SELECT 'moj-all-verified-judgments-review-002-chunk-127' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"d0086aeb-53a5-562f-844c-8c4d5801bb67","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -انتهاك حرمة منزل -سرقة جواالت من منزل -اشتراك يف سرقة -سرقة مال محترم من حرزه بالغ النصاب الشبهة منه- تستر -طلب إعادة حتقيق -اعتراف حتقيق ا -رجوع عن إقرار -طلب إقامة حد السرقة -درء حد السرقة -تعزير بالسجن واجللد.","document_number":"33462191","case_number":"33247078","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/22","year":"1434","subject":"سرقة -انتهاك حرمة منزل -سرقة جواالت من منزل -اشتراك يف سرقة -سرقة مال محترم من حرزه بالغ النصاب الشبهة منه- تستر -طلب إعادة حتقيق -اعتراف حتقيق ا -رجوع عن إقرار -طلب إقامة حد السرقة -درء حد السرقة -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 33462191 :‬تاريخه ‪1433/11/22:‬هـ‬\n                          ‫رقم الدعوى ‪33247078:‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34389112‬تاريخه‪1434/12/26 :‬ه‬\n\n\n\n      ‫ســرقة ‪ -‬انتهــاك حرمــة منــزل‪ -‬ســرقة جــواالت مــن منــزل ‪ -‬اشــتراك‬\n      ‫يف ســرقة ‪ -‬ســرقة مــال محتــرم مــن حــرزه بالــغ النصــاب الشــبهة منــه‪-‬‬\n      ‫تســتر‪ -‬طلــب إعــادة حتقيــق‪ -‬اعتــراف حتقيقـ ًا‪ -‬رجــوع عــن إقــرار‪ -‬طلب‬\n             ‫إقامــة حــد الســرقة‪ -‬درء حــد الســرقة‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n                ‫قول النبي صلى اهلل عليه وسلم ( ادرؤوا احلدود بالشبهات )‪.‬‬\n\n\n\n\n      ‫دعــوى املدعــي العــام ضــد املدعــى عليهمــا بانتهاكهمــا حرمــة منــزل‬\n      ‫وســرقة جــواالت داخلــه وتســترهما علــى املتهــم الثالــث وطلــب إقامــة حــد‬\n      ‫الســرقة علــى أحدهمــا الــذي أقــر بالتهمــة لــدى جهــة التحقيــق وتعزيــر‬\n      ‫الثانــي وهــو الــذي أنكــر التهمــة لــدى جهــة التحقيــق‪ ،‬مت القبــض علــى‬\n      ‫املدعــى عليهمــا بعــد بــاغ مفــاده تعــرض أحــد املنــازل للســرقة وكان من‬\n      ‫ضمــن املســروقات جــواالت فتــم االتصــال علــى أحــد اجلــواالت املســروقة‬\n      ‫وتبــن أنــه مت بيعــه علــى أحــد األشــخاص الــذي قــام بالداللة علــى املدعى‬\n      ‫عليهمــا‪ ،‬أنكــر املدعــى عليهمــا‪ ،‬وجــد إقــرار حتقيقـ ًا مــن أحــد املدعــى‬\n      ‫عليهمــا مبــا نســب إليــه‪ ،‬رجــع املدعــى عليــه املقــر حتقيق ـ ًا عــن إقــراره‬\n      ‫مدعيـ ًا أنــه صــدر منــه حتــت اإلكــراه‪،‬مت درء حــد الســرقة عــن املدعــى‬\n\n‫‪291‬‬\n\f‫عليــه املقــر حتقيقـ ًا لرجوعــه عــن اعترافه‪،‬حكمــت احملكمــة بتعزيــر‬\n‫املدعــى عليهمــا بالســجن واجللــد‪ ،‬مت تصديــق احلكــم مــن محكمــة‬\n                                                        ‫االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد ففــي‬\n‫هــذا اليــوم الثالثــاء املوافــق ‪1433/6/17‬ه ـ افتتحــت اجللســة الســاعة‬\n‫العاشــرة صباحــا لدينــا نحــن القضــاة ‪ .....‬و ‪ .....‬و ‪ ....‬وبنــاء علــى املعاملــة‬\n‫الــواردة مــن رئيــس هيئــة التحقيــق واالدعــاء العــام مبنطقــة تبــوك برقــم‬\n‫‪ 4443‬وتاريــخ ‪1433/3/27‬ه ـ واحملالــة مــن فضيلــة الرئيــس برقــم‬\n‫‪ 33247078‬وتاريــخ ‪1433/4/7‬ه ـ واخلاصــة بدعــوى املدعــي العــام ضــد‬\n‫كال مــن ‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).......‬مــن‬\n‫مواليــد عــام ‪1406‬ه ـ مــن ســكان تبــوك حــي ‪ ...‬تاريــخ القبــض عليــه‬\n‫‪1433/1/3‬هـ توجد ســابقة عليه اشــتباه ســكر جلده ‪60‬جلده مبوجب‬\n‫حكــم رقــم ‪ 138/3‬وتاريخــه ‪1426/8/14‬ه ـ مصــدره محكمــة تبــوك‬\n‫و‪ ......‬ســعودي مبوجــب الســجل املدنــي رقــم (‪ )....‬مــن مواليــد عــام‬\n‫‪1404‬ه ـ مــن ســكان تبــوك حــي ‪ .....‬وال توجــد ســوابق يف قضيــة انتهــاك‬\n‫حرمــة منــزل والســرقة عليــه فقــد حضــر املدعــي العــام وأدعــى قائــا‬\n‫بصفتــي مدعيــا عمــا بدائــرة االدعــاء العــام مبنطقــة تبــوك أدعــي علــى‬\n‫املذكوريــن أعــاه فإنــه بتاريــخ ‪1432/12/20‬ه ـ تقــدم املواطــن ‪......‬‬\n‫‪ 38‬عام ـ ًا ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬ببــاغ‬\n‫زوجــة جــاره املجنــي عليهــا ‪، ......‬تفيــد فيــه تعــرض منزلهــا للســرقة‬\n‫حيــث دخــل عليهــا شــخص وقــام بســرقة ســتة أجهــزة جــواالت دون‬\n\n                                                                                         ‫‪292‬‬\n\f      ‫تعرضهــا ألي أذى كمــا ورد محضــر الدوريــات األمنيــة رقــم(‪ )....‬بتاريــخ‬\n      ‫‪1432/12/20‬ه ـ املتضمــن تلقــي شــكوى املجنــي عليهــا ‪،.......‬بأنهــا‬\n      ‫تعرضــت للســرقة وقــد ســرق منهــا عــدد ًا مــن اجلــواالت وقامــت بالتنســيق‬\n      ‫معهــم بعــد اتصالهــا علــى أحــد جواالتهــا املســروقة واســتدراج مــن رد‬\n      ‫عليهــا أمــام ســوبر ماركــت ‪ ....‬بحــي ‪ ، .....‬وعنــد حضــور الشــخص‬\n      ‫الــذي معــه اجلــوال مت القبــض عليــه واتضــح أنــه يدعــى ‪ .......‬وباالنتقــال‬\n      ‫واملعاينــة ملنــزل املدعيــة الواقــع بحــي ‪ ......‬و اتضــح أن البــاب اخلارجــي‬\n      ‫متعــرض للكســر ويوجــد بعثــرة بداخــل املنــزل ولــم يعثــر علــى أي آثــار‬\n      ‫تفيــد التحقيــق‪ .‬وبســماع شــكوى املجنــي عليهــا ‪ ، .....‬أفــادت أنــه بتاريخ‬\n      ‫‪1432/12/20‬ه ـ ويف ســاعة متأخــرة مــن الليــل دخــل عليهــا شــخص‬\n      ‫أثنــاء نومهــا وقامــت بالصــراخ عنــد مشــاهدته فقــام بالهــرب وبتفقدهــا‬\n      ‫للمنــزل وجــدت بأنــه قــام بســرقة عــدد ســتة جــواالت اثنــن مــن نــوع ‪.....‬‬\n      ‫وأربعــة مــن نــوع ‪ ....‬وكذلــك مفتــاح البيــت وقامــت باالتصــال علــى‬\n      ‫جارهــا بالعمــارة ‪، ......‬كــون زوجهــا خــارج منطقــة تبــوك وذكــرت بــأن‬\n      ‫أوصــاف الســارق هــي (طويــل ومتــن ووجهــه دائــري ويرتدي بدله ســوداء‬\n      ‫اللــون حنطــي البشــرة ومغطــى الــرأس) وعندمــا حاولــت االتصــال بأحــد‬\n      ‫جواالتهــا والــذي يحمــل الرقــم (‪ ).......‬قــام أحدهــم بالــرد وأخبرتــه بــأن‬\n      ‫اجلــوال لهــا وترغــب يف شــرائه منــه وطلبــت مقابلتــه أمــام ســوبر ماركــت‬\n      ‫‪ .....‬ونســقت مــع دوريــات األمــن وعنــد حضــور الشــخص للموقــع ســلمها‬\n      ‫اجلــوال ومت القبــض عليــه وذكــرت بأنــه ليــس الشــخص الــذي دخــل‬\n      ‫عليهــا وال تتهمــه كونــه عندمــا أخبرتــه بــأن اجلــوال مســروق منهــا حضــر‬\n      ‫وســلمه لهــا‪ .‬وبســماع أقــوال املواطــن ‪30......‬عام ـ ًا ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ )......‬أفــاد بأنــه بتاريــخ ‪1432/12/20‬ه ـ‬\n\n\n‫‪293‬‬\n\f‫وأثنــاء وجــوده أمــام منزلــه قابلــه املدعــى عليــه‪.....‬و ‪........‬وشــخص ثالــث‬\n‫ال يعرفــه وعرضــوا عليــه شــراء أجهــزة جــواالت معهــم وكان عددهــا‬\n‫ســتة أجهــزة جــواالت (اثنــان منهــا ‪ ...‬وأربعــة ‪ )....‬فقــام بشــراء جوالــن‬\n‫منهــم مــن نــوع (‪ )....‬و(‪ )...‬مببلــغ وقــدره ســبعمائة وخمســن ريــال وبعدمــا‬\n‫ذهبــوا اتصلــت عليــه امــرأة علــى أحــد اجلوالــن وقالــت لــه إن اجلــوال‬\n‫الــذي معــه عائــد لهــا وأنــه مســروق وذهــب ملقابلتهــا إلرجــاع اجلــواالت‬\n‫وأخــذ املبلــغ الــذي دفعــه ومت القبــض عليــه أثنــاء حضــوره وذكــر بأنــه‬\n‫علــى اســتعداد بالتعــرف علــى مــن باعــه اجلوالــن ‪(.‬مت حفــظ االتهــام‬\n‫بحقــه لعــدم كفايــة األدلــة اســتناد ًا للمــادة (‪ )124‬مــن نظــام اإلجــراءات‬\n‫ـاء علــى مــا ورد بأقــوال املدعــو ‪ .......‬بأنــه اشــترى اجلوالــن‬\n                                                                  ‫اجلزائية)‪.‬وبنـ ً‬\n‫مــن ثالثــة أشــخاص ‪ ،‬وبالبحــث والتحــري اتضــح أن أحدهــم يدعــى ‪......‬‬\n‫ويلقــب (‪ )......‬وبعــرض صورتــه يف النهايــة الطرفيــة تعــرف عليــه وجــرى‬\n‫التعميــم عنــه ومت القبــض عليــه مــن قبــل وحــدة البحــث مبركــز شــرطة‬\n‫‪ .....‬بتاريــخ ‪1432/12/29‬ه ـ ‪ .‬كمــا مت القبــض علــى املدعــى عليــه ‪.....‬‬\n‫بعــد طلبــه احلضــور ملركــز الشــرطة بتاريــخ ‪1433/1/3‬ه ـ ‪.‬كمــا جــرى‬\n‫عــرض املدعــى عليــه ‪ ......‬علــى املدعيــة ضمــن مجموعــة أشــخاص‬\n‫وتعرفــت عليــه وأفــادت أنــه الشــخص الــذي دخــل منزلهــا ‪.‬كمــا جــرى‬\n‫عــرض املدعــى عليــه‪ .....‬علــى املدعــى عليــه ظاهــر ضمــن مجموعــة‬\n‫أشــخاص واســتطاع التعــرف عليــه وأنــه ضمــن األشــخاص الذيــن قامــوا‬\n‫ببيــع أجهــزة اجلــوال عليــه‪ .‬كمــا جــرى عــرض املدعــى عليــه‪ ....‬علــى‬\n‫املدعــى عليــه‪ ......‬ضمــن مجموعــة أشــخاص واســتطاع التعــرف عليــه‬\n‫وأفــاد أنــه كان مــن ضمــن األشــخاص الذيــن قامــوا ببيــع اجلــوال عليــه‪.‬‬\n‫وقــد جــرى فــرز أوراق للمتهــم الهــارب ‪.‬كمــا جــرى تســليم عــدد جهازيــن‬\n\n\n                                                                                      ‫‪294‬‬\n\f      ‫جــوال مــن نــوع ‪ ....‬موديــل (‪ )...‬و (‪ )...‬للمــرأة ‪، .........‬حســب احملضــر‬\n      ‫املــدون وبقــي أربعــة أجهــزة جــواالت لــم يتــم العثــور عليهــا ‪.‬كمــا مت إيداع‬\n      ‫املدعــى عليهمــا للســجن العــام مبوجــب مذكرتــي التوقيــف رقــم (‪)5-4‬‬\n      ‫بتاريخ ‪1433/1/19‬هـ ‪ .‬وباســتجواب املدعى عليه الثاني ‪،.........‬أنكر‬\n      ‫بدايــة األمــر وبعــد مواجهتــه باألدلــة والقرائــن أفــاد بأنــه بتاريــخ‬\n      ‫ال مــن‬‫‪1432/12/20‬ه ـ أقــدم علــى ســرقة منــزل املــرأة ‪ .......‬ومعــه ك ً‬\n      ‫املدعــى عليــه ‪، ......‬واملدعــى عليــه ‪، ......‬حيــث أفــاد بأنــه يف ذات اليــوم‬\n      ‫ال مــن‪ .......‬و ‪، ....‬عنــد املنــزل وطلبــا منــه‬‫وقبــل الفجــر حضــر لــه ك ً‬\n      ‫مرافقتهمــا للتمشــية وأثنــاء مرورهــم مبنــزل املجنــي عليهــا قــام‪ ......‬بدفــع‬\n      ‫البــاب لغــرض الســرقة وبقــي هــو ورفيقــه‪ ......‬يراقبــان املنــزل مــن اخلــارج‬\n      ‫وكان‪ .....‬بالقــرب مــن البــاب وبعــد عشــر دقائــق تقريب ـ ًا خــرج لهــم ‪....‬‬\n      ‫مســرع ًا ومعــه جوالــن ويقــول (املــرأة اســتيقظت مــن النــوم) والذوا‬\n      ‫بالفــرار وذهــب ملنزلــه ونــام وبعــد اســتيقاظه علــم بــأن ‪ ......‬مت القبــض‬\n      ‫عليــه ‪.‬ومبواجهــة املدعــى عليــه الثانــي‪ ...‬باملدعــو ‪،......‬عــدل املدعــى‬\n      ‫عليــه‪ ......‬عمــا جــاء بأقوالــه مــن مشــاركة املدعــو ‪ .....‬لهــم بالســرقة‬\n      ‫وقصــد مــن ذلــك إدخالــه يف القضيــة ‪.‬وباســتجواب املدعــى عليــه األول‬\n      ‫‪ .......‬أنكــر قيامــه بالســرقة أو االشــتراك مــع املدعــى عليــه الثانــي فيهــا‬\n      ‫‪.‬ومبواجهتــه باملدعــو ‪ .....‬أصــر كلٌ منهمــا علــى أقوالــه الســابقة وملــا‬\n      ‫أشــير إليــه أقــرر توجيــه االتهــام للمتهمــن ‪ ......‬و ‪ .....‬بانتهاكهمــا حلرمــة‬\n      ‫منــزل املدعيــة ‪.....‬وســرقة عــدد ســت أجهــزة جــواالت مــن داخلــه‬\n      ‫وتســترهما علــى املتهــم الثالــث الهــارب ‪ .‬وذلــك لألدلــة والقرائــن التاليــة‬\n      ‫‪ -1:‬مــا جــاء باعتــراف املدعــى عليــه‪ .......‬املــدون علــى الصفحــات (‪)15‬‬\n      ‫مــن دفتــر التحقيــق املرفــق لفــة (‪ -2. )2‬مــا ورد بأقــوال ‪ ......‬املنــوه عنــه‬\n\n\n‫‪295‬‬\n\f‫واملــدون علــى الصفحــة (‪ )14‬مــن دفتــر التحقيــق املرفــق لفــة (‪ -3. )3‬مــا‬\n‫جــاء مبحضــر العــرض والتعــرف املنــوه عنــه واملــدون علــى الصفحــة (‪)16‬‬\n‫مــن دفتــر التحقيــق املرفــق لفــة (‪ )1‬والصفحــة (‪ )13‬لفــة (‪ )2‬والصفحــة‬\n‫(‪ )15-13‬لفــة (‪ -4. )3‬مــا جــاء مبحضــر املعاينــة واملتضمــن تعــرض بــاب‬\n‫املنــزل للكســر واملنــوه عنــه املــدون علــى الصفحة (‪ )2‬مــن دفتر التحقيق‬\n‫املرفــق لفــة (‪ -4. )3‬مــا جــاء مبحضــر املواجهــة املــدون علــى الصفحــة‬\n‫(‪ )14‬مــن دفتــر التحقيــق املرفــق لفــة (‪ )1‬والصفحــة (‪ )16‬لفــة (‪-6. )3‬‬\n‫مــا جــاء باســتالم املجنــي عليهــا اجلوالــن املســروقة املنــوه عنــه واملــدون‬\n‫علــى الصفحــة (‪ )12‬مــن دفتــر التحقيــق لفــة (‪ . )3‬وانتهــى التحقيــق إلــى‬\n‫توجيــه االتهــام للمدعــى عليهمــا ‪ ..........‬و ‪، ...........‬بانتهاكهمــا حلرمــة‬\n‫منــزل املجنــي عليهــا ‪، ......‬وســرقة عــدد ســت أجهــزة جــواالت مــن داخله‬\n‫وتســترهما علــى املتهــم الثالــث الهــارب ‪.‬وحيــث أن مــا أقــدم عليــه‬\n‫املذكــوران فعــل محــرم ومعاقــب عليــه شــرع ًا وهــو انتهــاك حلرمــة منــزل‬\n‫وســرقة مــال محتــرم مــن حــرزه بلــغ النصــاب ال شــبهة لهمــا فيــه وهمــا‬\n‫مكلفــان غيــر مكرهــان لــذا أطلــب مايلــي ‪ -1 :‬إثبــات مــا أســند إليهمــا‬\n‫‪ -2.‬احلكــم علــى املدعــى عليــه الثانــي‪، .......‬بحــد الســرقة الــوارد يف‬\n‫اآليــة الكرميــة رقــم (‪ )38‬مــن ســورة املائــدة ‪ -3.‬احلكــم علــى املدعــى‬\n‫عليــه األول ‪ ،.......‬بعقوبــة تعزيريــة ‪( .‬علم ـ ًا بــأن احلــق اخلــاص ال زال‬\n‫قائم ـاً) هــذه دعــواي وأســألهما اجلــواب ‪ ،‬وبســؤال املدعــى عليهمــا عــن‬\n‫دعــوى املدعــي العــام أجــاب املدعــى عليــه األول ‪ ......‬قائــا إن مــا جــاء يف‬\n‫دعــوى املدعــي العــام ضــدي فغيــر صحيــح فلــم أنتهــك حرمــة منــزل‬\n‫املدعيــة ‪ .....‬ولــم أســرق اجلــواالت مــن منزلهــا املذكــور يف الدعــوى ولــم‬\n‫أشــترك يف ذلــك ولــم أتســتر علــى املتهــم الثالــث وال عالقــة لــي بهــذه‬\n\n\n                                                                                      ‫‪296‬‬\n\f      ‫الدعــوى ال مــن قريــب وال مــن بعيــد ولــم أقابــل املدعــى عليــه الثانــي ‪......‬‬\n      ‫يف يوم ‪1432/12/20‬هـ والصحيح أنني كنت بتاريخ ‪1432/12/20‬هـ‬\n      ‫مبنزلي بحي ‪ .....‬ولم أخرج منه إال عصر اليوم الثاني ‪1432/12/21‬هـ‬\n      ‫وقــد كان عنــدي ليلــة الواقعــة التــي اتهمنــي بهــا املدعــي العــام اثنــن مــن‬\n      ‫أبنــاء عمومتــي ‪ ........‬و ‪ .....‬ولــم نتفــرق إال بعــد الســاعة السادســة صباحــا‬\n      ‫وبتاريــخ ‪1433/1/3‬ه ـ حضــرت الدوريــات األمنيــة ملنــزل والدتــي بحــي‬\n      ‫‪ ....‬ومت طلبــي لقســم شــرطة ‪ .....‬وأبلغتنــي الوالــدة بذلــك وحضــرت لهــم‬\n      ‫ومت القبــض علــي هكــذا أجــاب وبســؤال املدعــى عليــه الثانــي ‪........‬‬\n      ‫قائــا إن مــا جــاء يف دعــوى املدعــي العــام ضــدي فغيــر صحيــح فلــم‬\n      ‫أنتهــك حرمــة منــزل املدعيــة ‪ ......‬ولــم أســرق اجلــواالت مــن منزلهــا‬\n      ‫املذكــور يف الدعــوى ولــم أشــترك يف ذلــك ولــم أتســتر علــى املتهــم‬\n      ‫الثالــث وال عالقــة لــي بهــذه الدعــوى ال مــن قريــب وال مــن بعيــد ولــم‬\n      ‫أقابــل املدعــى عليــه األول ‪ .......‬يف يــوم ‪1432/12/20‬ه ـ والصحيح أنني‬\n      ‫كنــت بتاريــخ ‪1432/12/20‬ه ـ مبنزلــي بحــي ‪ ....‬ولــم أخــرج منــه إال‬\n      ‫عصــر اليــوم الثانــي وبتاريــخ ‪1432/12/29‬ه ـ حضــرت الدوريــات‬\n      ‫األمنيــة ملنــزل والدتــي بحــي ‪ .....‬ومت طلبــي لقســم شــرطة ‪ .....‬ومت القبــض‬\n      ‫علــي هكــذا أجــاب وبســؤال املدعــي العــام عــن بينتــه أجــاب قائــا إنهــا‬\n      ‫مرصــودة ضمــن طيــات املعاملــة وأطلــب الرجــوع إليهــا وضبطهــا‬\n      ‫وعرضهــا علــى املدعــى عليهمــا ‪ -1‬مــا جــاء باعتــراف املدعــى عليــه ‪.......‬‬\n      ‫املــدون علــى الصفحــات (‪ )15‬مــن دفتــر التحقيــق املرفــق لفــة (‪ )2‬وهــذا‬\n      ‫نصــه و باســتجواب املدعــى عليــه الثانــي ‪،......‬أنكــر بدايــة األمــر وبعــد‬\n      ‫مواجهتــه باألدلــة والقرائــن أفــاد بأنــه بتاريــخ ‪1432/12/20‬ه ـ أقــدم‬\n      ‫ال مــن املدعى عليه ‪، .....‬واملدعى‬     ‫علــى ســرقة منــزل املــرأة ‪ ......‬ومعــه ك ً‬\n\n\n‫‪297‬‬\n\f‫ال‬\n ‫عليــه ‪،.......‬حيــث أفــاد بأنــه يف ذات اليــوم وقبــل الفجــر حضــر لــه ك ً‬\n‫مــن ‪ ......‬و‪ ...........‬عنــد املنــزل وطلبــا منــه مرافقتهمــا للتمشــية وأثنــاء‬\n‫مرورهــم مبنــزل املجنــي عليهــا قــام ‪......‬بدفــع البــاب لغــرض الســرقة‬\n‫وبقــي هــو ورفيقــه‪ .....‬يراقبــان املنــزل مــن اخلــارج وكان ‪ .....‬بالقــرب مــن‬\n‫البــاب وبعــد عشــر دقائــق تقريب ـ ًا خــرج لهــم‪ .....‬مســرع ًا ومعــه جوالــن‬\n‫ويقــول (املــرأة اســتيقظت مــن النــوم) والذوا بالفــرار وذهــب ملنزلــه ونــام‬\n‫وبعــد اســتيقاظه علــم بــأن‪ ......‬مت القبــض عليــه ‪ -2.‬مــا ورد بأقــوال ‪.....‬‬\n‫املنــوه عنــه واملــدون علــى الصفحــة (‪ )14‬مــن دفتــر التحقيــق املرفــق لفــة‬\n‫(‪ )3‬وهــذا نصــه وبســماع أقــوال املواطن‪،30........‬عامـ ًا ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )......‬أفــاد بأنــه بتاريــخ ‪1432/12/20‬ه ـ‬\n‫وأثنــاء وجــوده أمــام منزلــه قابلــه املدعــى عليــه ‪ .......‬و‪، ......‬وشــخص‬\n‫ثالــث ال يعرفــه وعرضــوا عليــه شــراء أجهــزة جــواالت معهــم وكان‬\n‫عددهــا ســتة أجهــزة جــواالت (اثنــان منهــا ‪ ....‬وأربعــة ‪ ) ....‬فقــام بشــراء‬\n‫جوالــن منهــم مــن نــوع (‪ ).....‬و (‪ ).....‬مببلــغ وقــدره ســبعمائة وخمســن‬\n‫ريــال وبعدمــا ذهبــوا اتصلــت عليــه امــرأة علــى أحــد اجلوالــن وقالــت لــه‬\n‫إن اجلــوال الــذي معــه عائــد لهــا وأنــه مســروق وذهــب ملقابلتهــا إلرجــاع‬\n‫اجلــواالت وأخــذ املبلــغ الــذي دفعــه ومت القبــض عليــه أثنــاء حضــوره‬\n‫وذكــر بأنــه علــى اســتعداد بالتعــرف علــى مــن باعــه اجلوالــن‪ -3‬مــا جــاء‬\n‫مبحضــر العــرض والتعــرف املنــوه عنــه واملــدون علــى الصفحــة (‪ )16‬مــن‬\n‫دفتــر التحقيــق املرفــق لفــة (‪ )1‬والصفحــة (‪ )13‬لفــة (‪ )2‬والصفحــة‬\n‫(‪ )15-13‬لفــة (‪ )3‬وهــذا نصــه جــرى عــرض املدعــى عليــه ‪، ......‬علــى‬\n‫املدعيــة ضمــن مجموعــة أشــخاص وتعرفــت عليــه وأفــادت أنــه هــو‬\n‫الشــخص الــذي دخــل منزلهــا ‪.‬كمــا جــرى عــرض املدعــى عليــه ‪......‬‬\n\n\n                                                                                       ‫‪298‬‬\n\f      ‫علــى املدعــي ‪ ......‬ضمــن مجموعــة أشــخاص واســتطاع التعــرف عليــه‬\n      ‫وأنــه ضمــن األشــخاص الذيــن قامــوا ببيــع أجهــزة اجلــوال عليــه ‪.‬كمــا‬\n      ‫جــرى عــرض املدعــى عليــه‪ ......‬علــى املدعــى ‪ ......‬ضمــن مجموعــة‬\n      ‫أشــخاص واســتطاع التعرف عليه وأفاد أنه كان من ضمن األشــخاص‬\n      ‫الذيــن قامــوا ببيــع اجلــوال عليــه ‪ -4.‬مــا جــاء مبحضــر املعاينــة واملتضمــن‬\n      ‫تعــرض بــاب املنــزل للكســر واملنــوه عنــه املــدون علــى الصفحــة (‪ )2‬مــن‬\n      ‫دفتــر التحقيــق املرفــق لفــة (‪)3‬وهــذا نصــه محضــر انتقــال ومعاينــة أوليــة‬\n      ‫بتاريــخ ‪1432/12/21‬ه ـ جــرى االنتقــال إلــى املنــزل واتضــح أنــه يقــع‬\n      ‫بحــي ‪ ....‬وبجــوار ‪ ......‬وكان هنــاك تكســير يف البــاب اخلارجــي ووجــود‬\n      ‫بعثــرة يف املنــزل وهــو عبــارة عــن دور أرضــي وملحــق جــرى رفــع االثــار‬\n      ‫مــن قبــل فنــي األدلــة وحفظــا للواقــع نظــم هــذا احملضــر أـ ه ـ ‪ -5‬مــا جــاء‬\n      ‫مبحضــر املواجهــة املــدون علــى الصفحــة (‪ )14‬مــن دفتــر التحقيــق املرفق‬\n      ‫لفــة (‪ )1‬والصفحــة (‪ )16‬لفــة (‪ )3‬وهــذا نصــه ومبواجهــة املدعــى عليــه‬\n      ‫الثانــي ‪ ......‬باملدعــو ‪،.....‬عــدل املدعــى عليــه‪ .......‬عمــا جــاء بأقوالــه مــن‬\n      ‫مشــاركة املدعــو ‪ .....‬لهــم بالســرقة وقصــد مــن ذلــك إدخالــه يف القضيــة‬\n      ‫‪ .‬ومبواجهــه املدعــو ‪ ......‬باملدعــو ‪ .....‬أصــر كلٌ منهمــا علــى أقوالــه‬\n      ‫الســابقة أ‪ .‬ه ـ ‪ -6‬مــا جــاء باســتالم املجنــي عليهــا اجلوالــن املســروقة‬\n      ‫املنــوه عنــه واملــدون علــى الصفحــة (‪ )12‬مــن دفتــر التحقيــق لفــة (‪)3‬‬\n      ‫وهــذا نصــه كمــا جــرى تســليم عــدد جهازيــن جــوال مــن نــوع ‪ .....‬موديــل‬\n      ‫(‪ ).....‬و (‪ )....‬للمــرأة ‪ .....‬حســب احملضــر املــدون وبقــي أربعــة أجهــزة‬\n      ‫جــواالت لــم يتــم العثــور عليهــا أ‪ .‬ه ـ ‪.‬وبعــرض أدلــة املدعــي العــام علــى‬\n      ‫املدعــى عليهمــا أجــاب املدعــى عليــه األول قائــا إن مــا جــاء يف األدلــة‬\n      ‫املوجهــة ضــدي فغيــر صحيــح وال أعلــم ملــاذا ذكــر ‪ ........‬أثنــاء التحقيــق‬\n\n\n‫‪299‬‬\n\f‫مشــاركتي لــه يف بيــع أجهــزة اجلــوال املســروقة وأمــا مــا جــاء بأقــوال ‪......‬‬\n‫وتعرفــه علــي فبينــي وبينــه عــداوة قدميــة بســبب مضاربــة معــه قبــل‬\n‫شــهرين مــن هــذه القضيــة هكــذا أجــاب كمــا أجــاب املدعــى عليــه‬\n‫الثانــي قائــا إن مــا جــاء يف األدلــة املوجهــة ضــدي فغيــر صحيــح وســبب‬\n‫اتهــام ‪ ....‬لــي كونــي صديــق ‪ ......‬ومــا جــاء مبحضــر تعــرف املدعيــة ‪......‬‬\n‫علــي فســببه مــازم التحقيــق الــذي ذكــر لهــا اســمي وقــال لهــا دققــي‬\n‫زي النــاس وقــد كانــت متــرددة بــن عــدة أشــخاص ثــم اتهمتنــي بهــذه‬\n‫التهمــه هكــذا أجــاب ورفعــت اجللســة للتأمــل و يف يــوم الثالثــاء املوافــق‬\n‫‪1433/07/08‬ه ـ افتتحــت اجللســة الســاعة ‪ 11.45‬وفيهــا حضــر املدعــي‬\n‫ا ‪ :‬مت‬  ‫العــام واملدعــى عليهمــا فســألنا املدعــي العــام عــن ‪ .....‬فأجــاب قائـ ً‬\n‫االتصــال عليــه عــدة مــرات ولــم يتجــاوب معنــا هكــذا أجــاب وملــا ظهــر‬\n‫لنــا مــن مجريــات التحقيــق وعــدم كفايــة األدلــة يف توجيــه االتهــام علــى‬\n‫املدعــى عليهمــا فقــط ولكــون بعــض املســروقات وجــدت مــع ‪......‬‬\n‫وحفــظ االتهــام بحقــه ملجــرد دعــواه بأنــه اشــتراها مــن املدعــى عليهمــا‬\n‫كاف يف حفــظ التهمــة علــى املذكــور ولكونــه قــد دعــي‬           ‫ٍ‬       ‫وهــذا غيــر‬\n‫إلــى احلضــور لــإدالء بإفادتــه يف احملكمــة ولــم يتجــاوب وألن املقصــود‬\n‫حتقيــق العدالــة والوصــول للحقيقة وملا جاء يف املادة اخلامســة والعشــرين‬\n‫بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة ‪ ،‬ولــذا فقــد أفهمنــا املدعــي‬\n‫العــام بــأن املعاملــة ســتعاد لهيئــة التحقيــق واالدعــاء العــام إلعــادة فتــح‬\n‫ملــف التحقيــق فيهــا وإحضــار ‪ .............‬وإعــادة التحقيــق معــه ثــم إعــادة‬\n‫املعاملــة لدينــا بعــد إكمــال مــا يلــزم ورفعــت اجللســة إلــى أن يكتــب‬\n‫ويــرد اجلــواب ويف يــوم االثنــن املوافــق ‪1433/11/22‬ه ـ افتتحــت اجللســة‬\n‫وفيهــا حضــر املدعــي العــام واملدعــى عليهمــا وقــد اشــترك معنــا فضيلــة‬\n\n\n                                                                                           ‫‪300‬‬\n\f      ‫القاضــي الشــيخ ‪ .......‬خلفــا لفضيلــة القاضــي الشــيخ ‪ ......‬كونــه انتقــل‬\n      ‫إلــى احملكمــة العامــة باخلــرج وبتــاوة مــا مت ضبطــه يف القضيــة صــادق‬\n      ‫األطــراف عليــه وقــد وردتنــا املعاملــة مــن رئيــس فــرع هيئــة التحقيــق‬\n      ‫واالدعــاء العــام مبنطقــة تبــوك برقــم ‪ 12553‬وتاريــخ ‪1433/8/25‬ه ـ‬\n      ‫ونــص احلاجــة منــه بنــاء علــى طلــب أصحــاب القضــاة إعــادة فتــح ملــف‬\n      ‫التحقيــق يف القضيــة والتحقيــق مــع املدعــو ‪ .....‬عليــه نفيدكــم بأنــه‬\n      ‫وردنــا خطــاب ســعادة مديــر مركز شــرطة اخلالدية رقــم ‪27/3835/28‬‬\n      ‫وتاريــخ ‪1433/8/19‬ه ـ املتضمــن بأنــه تعــذر إحضــار املدعــو ‪ ....‬يف‬\n      ‫الفتــرة احلاليــة وجــرى فــرز أوراق مســتقلة لــه للبحــث عنــه وجــرى التعميم‬\n      ‫عنــه برقــم ‪ 2119‬وتاريــخ ‪1433/8/18‬ه ـ ويف حالــة القبــض عليــه ســوف‬\n      ‫يتــم إعــادة التحقيــق معــه وإشــعاركم بذلــك أ‪.‬هــ‪ ،‬فســألنا املدعــى عليــه‬\n      ‫‪ .......‬عمــا جــاء باعترافــه حتقيقــا فأجــاب قائــا إنــه غيــر صحيــح وقــد‬\n      ‫أخــذ منــي حتــت اإلكــراه وال بينــة لــي علــى ذلــك هكــذا أجــاب فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وإنــكار املدعــى عليهمــا ملــا نســب‬\n      ‫إليهمــا ولكــون املدعــي العــام لــم يقــدم بينــة موصلــة تثبــت إدانــة املدعــى‬\n      ‫عليهمــا ملــا نســب إليهمــا وملــا جــاء باعتــراف املدعــى عليــه ‪ ......‬حتقيقــا‬\n      ‫املتضمــن أنــه يف تاريــخ ‪1432/12/21‬ه ـ كان هــو و ‪ ......‬و ‪ .......‬عنــد‬\n      ‫منــزل املجنــي عليهــا ‪ ......‬وأن ظاهــر دخــل املنــزل وأخــرج منــه بعــض‬\n      ‫اجلــواالت املســروقة ورجوعــه عــن هــذا االعتــراف ودفعــه بأنــه أخــذ منــه‬\n      ‫باإلكــراه ولعجــزه إقامــة بينــة علــى ذلــك وألن رجوعــه شــبهة واحلــدود‬\n      ‫تــدرأ بالشــبهات كمــا قــال املصطفــى صلــى اهلل عليــه وســلم وملــا جــاء‬\n      ‫مبحضــر العــرض والتعــرف املتضمــن تعــرف ‪ ......‬صاحبة املنزل املســروق‬\n      ‫علــى املدعــى عليــه ‪ .....‬وأنــه هــو الشــخص الــذي شــاهدته يف منزلهــا‬\n\n\n‫‪301‬‬\n\f‫وســرق جواالتهــا وملــا جــاء بإقــرار املدعــى عليــه ‪ ......‬بــأن املدعــى عليــه‬\n‫‪ .......‬كان معــه وقــت الســرقة وأنــه كان يقــف عنــد منــزل املجنــي عليها‬\n‫وتســتره علــى ذلــك وإن كان هــذا إقــرارا علــى الغيــر ومعلــوم أن اإلقــرار‬\n‫حجــة علــى صاحبــه إال أنــه يوجــه الشــبهة بحــق املدعى عليه ‪ .......‬بتســتره‬\n‫علــى الســرقة وانتهــاك حرمــة منــزل ‪ .......‬وأمــا مــا جــاء بإفــادة ‪.......‬‬\n‫واتهامــه للمدعــى عليهمــا وتعرفــه عليهمــا فهــذا غيــر مقبــول كونــه‬\n‫محــل تهمــة لوجــود املســروقات معــه وملــا تقــدم فقــد توجهــت الشــبهة‬\n‫بحــق املدعــى عليــه األول ‪ .....‬بالتســتر علــى ســرقة منــزل املجنــي عليهــا‬\n‫‪ .......‬كمــا توجهــت الشــبهة علــى املدعــى عليه ‪ ......‬بســرقة ســت جواالت‬\n‫مــن منــزل ‪ .......‬وانتهــاك حرمــة املنــزل وجلميــع مــا تقــدم فقــد قررنــا مــا‬\n‫يلــي ‪:‬أوال‪ :‬درء حــد الســرقة عــن املدعــى عليــه‪ ........‬ثانيــا‪ :‬تعزيــر املدعــى‬\n‫عليــه األول ‪ .........‬وذلــك بالســجن ملــدة ســنة حتســب مــن تاريــخ إيقافــه‬\n‫علــى ذمــة هــذه القضيــة وجلــده مائــة وخمســون جلــدة مفرقــه علــى ثــاث‬\n‫دفعــات كل دفعــة خمســون جلــدة وبــن كل دفعــة واألخــرى خمســة‬\n‫عشــر يومــا وتعزيــر املدعــى عليــه ‪ ........‬وذلــك بالســجن ملــدة ســنتني‬\n‫حتســب مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة وجلــده ثالثمائــة جلــدة‬\n‫مفرقــة علــى ســت دفعــات كل دفعــة خمســون جلــدة وبــن كل دفعــة‬\n‫واألخــرى خمســة عشــر يومــا وبذلــك حكمنــا وبعرضــه علــى املدعــي‬\n‫العــام واملدعــى عليهمــا قــررا عــدم قناعتهمــا باحلكــم وطلبــا متييــز‬\n‫احلكــم ووعــدا بتقــدمي الئحــة اعتراضيــة فأجيبــوا إلــى طلبهــم وجــرى‬\n‫تســليمهم نســخة مــن احلكــم يف هــذا اليــوم وأفهمــوا مبقتضــى تعليمــات‬\n‫التمييــز وحســبت عليهــم املــدة مــن تاريخــه وبــاهلل التوفيــق وصلــى اهلل‬\n‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف‬\n\n\n                                                                                        ‫‪302‬‬\n\f                                                                          ‫‪1433/11/22‬هـ‬\n      ‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‪ :‬ففــي‬\n      ‫هــذا اليــوم االحــد املوافــق ‪1434/06/04‬ه ـ ويف متــام الســاعة التاســعة‬\n      ‫وخمســة وأربعــون دقيقــة افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن‬\n      ‫محكمــة االســتئناف مبنطقــة تبــوك بخطــاب فضيلــة رئيســها املســاعد‬\n      ‫رقــم ‪ 34490035‬يف ‪1434/03/24‬ه ـ املرفــق بــه قــرار املالحظــة رقــم‬\n      ‫‪ 34168616‬وتاريــخ ‪1434/03/22‬ه ـ الصــادر مــن قضــاة الدائــرة‬\n      ‫اخلماســية لتدقيــق القضايــا اجلزائيــة ‪ ،‬ونــص احلاجــة منــه ‪ :‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه والئحتــه االعتراضيــة وأوراق املعاملــة لوحــظ مــا‬\n      ‫يلــي أو ًال ‪ :‬أن مــا حكــم بــه أصحــاب الفضيلــة جتــاه املدعــى عليــه األول‬\n      ‫‪ .......‬محــل نظــر ألنــه ال توجــد أدلــة ضــده أو قرائــن مبــا ينســب إليــه‬\n      ‫فليــس إقــرار ‪ ،‬ولــم تتعــرف عليــه املــرأة املدعيــة وإمنــا تعرفــت علــى الثانــي‬\n      ‫‪ .......‬وأفــادت بأنــه هــو مــن يدخــل إليهــا وحــده فقــط ‪ ،‬وال يوجــد مــا‬\n      ‫يدينــه إال ذكــره علــى لســان املتهــم ‪ ......‬وال يقبــل قولــه يف ذلــك ‪ ،‬ســيما‬\n      ‫وأنــه لــم ميثــل أمــام احملكمــة ويتجــاوب معهــا ‪ .‬ثاني ـ ًا ‪ :‬عبــر أصحــاب‬\n      ‫الفضيلــة بــدرء احلــد ال يكــون إال بعــد الثبــوت ‪ .‬ملالحظــة ذلــك ‪ ،‬وإحلــاق‬\n      ‫مــا ُيجــرى علــى الضبــط والقــرار وصورتــه حســب التعليمــات ‪ ،‬ومــن ثــم‬\n      ‫إعــادة املعاملــة ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬أ‪ .‬ه ـ عليــه جنيــب أصحــاب الفضيلــة وفقنــا اهلل وإياهــم‬\n      ‫فنقــول مســتعينني بــاهلل مســتمدين منــه العــون والســداد نحــن القاضيــن‬\n      ‫‪........‬و ‪ ......‬بــأن فضيلــة الشــيخ ‪ .......‬املشــارك معنــا يف نظــر هــذه‬\n      ‫القضيــة واحلكــم فيهــا قــد انتقــل عملــه الــى احملكمــة العامــة باخلــرج‬\n      ‫وبنــاء علــى التعليمــات فقــد قررنــا إعــادة كامــل املعاملــة بعــد إكمــال‬\n\n\n‫‪303‬‬\n\f                  ‫الــازم حملكمــة االســتئناف الطــاع أصحــاب الفضيلــة‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‪ :‬ففــي هــذا‬\n‫اليــوم األربعــاء املوافــق ‪1434/11/05‬ه ـ ويف متــام الســاعة العاشــرة‬\n‫والنصــف افتتحــت اجللســة وفيهــا حضــر املدعــي العــام واملدعــى عليهمــا‬\n‫وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف مبنطقــة تبــوك بخطــاب‬\n‫فضيلــة رئيســها املســاعد رقــم‪ 34830171‬وتاريــخ ‪1434/7/10‬ه ـ‬\n‫واملرفــق بهــا قــرار املالحظــة رقــم ‪ 34251502‬وتاريــخ ‪1434/06/26‬ه ـ‬\n‫الصــادر مــن الدائــرة اخلماســية ونــص احلاجــة منــه ‪:‬وباالطــاع علــى‬\n‫مــا أجــاب بــه أصحــاب الفضيلــة القضــاة علــى قــرار الدائــرة رقــم‬\n‫‪ 34168616‬وتاريــخ ‪1434/3/22‬ه ـ تقــرر الدائــرة اشــتراك فضيلــة‬\n‫‪ ......‬املنقــول أو القائــم بعملــه يف نظــر القضيــة بعاليــة بنــاء علــى املــادة‬\n‫التاســعة والثمانــون بعــد املائــة مــن نظــام املرافعــات الشــرعية ملالحظــة‬\n‫ذلــك واحلــاق مــا يجــري علــى الضبــط والقــرار وصورتــه حســب التعليمات‬\n‫ومــن ثــم اعــادة املعاملــة أ‪ .‬ه ـ وقــد اشــترك معنــا يف نظــر القضيــة فضيلــة‬\n‫الشــيخ ‪......‬خلفــا لفضيلــة الشــيخ ‪ .......‬يف املشــترك القضائــي ثــم جــرى‬\n‫تــاوة مــا مت ضبطــه يف القضيــة فصــادق األطــراف عليــه وعليــه جنيــب‬\n‫أصحــاب الفضيلــة وفقنــا اهلل وإياهــم للحــق وإصابتــه فنقــول مســتعينني‬\n‫بــاهلل مســتمدين منــه العــون والســداد جوابــا عــن املالحظــة األولــى ‪:‬أنــه‬\n‫قــد ذكرنــا يف تســبيب احلكــم أن املدعــى عليــه ‪ .....‬قــد توجهــت إليــه‬\n‫التهمــة بالتســتر علــى ســرقة بيــت املجنــي عليهــا ‪......‬بنــاء علــى مــا جــاء‬\n‫بإقــرار املدعــى عليــه ‪ .....‬بــأن املدعــى عليــه ‪ .......‬كان معــه عنــد منــزل‬\n‫املجنــي عليهــا وقــت الســرقة وهــذا اإلقــرار وإن كان علــى الغيــر اال أنــه‬\n‫يوجــه التهمــة بحــق املدعــى عليــه ‪ .....‬بالتســتر علــى جرميــة الســرقة وأمــا‬\n\n\n                                                                                        ‫‪304‬‬\n\f      ‫اجلــواب عــن املالحظــة الثانيــة ولوجاهــة مــا ذكــره أصحــاب الفضيلــة‬\n      ‫فإنــه لــم يثبــت لدينــا إدانــة املدعــى عليهمــا مبــا نســبه اليهمــا املدعــي‬\n      ‫العــام وإمنــا توجهــت الــى املدعــى عليــه األول ‪ .....‬بالتســتر علــى ســرقة‬\n      ‫بيــت املجنــي عليهــا ‪ ......‬كمــا توجهــت التهمــة بحــق املدعــى عليــه ‪......‬‬\n      ‫بســرقة ســت جــواالت مــن منــزل ‪ .....‬وانتهــاك حرمــة املنــزل ومــا قررنــا‬\n      ‫مــن عقوبــة تعزيريــة بحــق املدعــى عليهمــا نــرى أنــه كاف هــذا مــا لــزم‬\n      ‫جوابــا علــى مالحظــات أصحــاب الفضيلــة ولهــم منــا فائــق التقديــر‬\n      ‫واالحتــرام وقررنــا إعــادة كامــل املعاملــة حملكمــة االســتئناف بتبــوك‬\n      ‫بعــد إكمــال الــازم لتدقيــق احلكــم حســب املتبــع وبــاهلل التوفيــق‬\n                   ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ :‬اطلعن ــا نحــن قـض ــاة الدائ ــرة اخلماســية لتدقيــق‬\n      ‫القضايــا اجلزائيــة يف محكمــة االســتئناف مبنطقــة تبــوك علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بتبــوك برقــم‬\n      ‫‪34830171‬وتاريــخ ‪1434/11/9‬ه ـ ‪ ،‬املرفــق بهــا القــرار الصــادر مــن‬\n      ‫أصحــاب الفضيلــة القضــاة يف احملكمــة الشيخ‪،.......‬والشــيخ‪........‬‬\n      ‫والشــيخ ‪ .........‬برقــم ‪ 33462191‬وتاريــخ ‪1433/11/22‬ه ـ ‪ ،‬واخلاصــة‬\n      ‫بدعــوى املدعــي العــام ضــد ‪ .........‬ورفيقــه يف قضيــة ســرقة علــى النحــو‬\n      ‫املوضــح يف القــرار ‪ ،‬واملتضمــن حكــم أصحــاب الفضيلــة مبــا هــو‬\n      ‫مــدون ومفصــل فيــه‪ .‬وباالطــاع علــى مــا أجــاب بــه أصحــاب الفضيلــة‬\n      ‫القضــاة علــى قــرار الدائــرة رقــم ‪ 34251502‬وتاريــخ ‪1434/6/26‬ه ـ‬\n      ‫ورقــم‪ 34168616‬وتاريــخ ‪1434/3/22‬ه ـ قررنــا املصادقــة علــى احلكم‬\n      ‫بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                 ‫آلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪305‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":291,"source_page_end":305,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1579716183adf7f4ec4dfbd725e41fba95bc9c8f607c72d51a391387b027a3eb","normalized_text_hash":"3fc7b51bb14a46699bcdac4f226aa07ce0af7bbefa4e300f5fc25a503add87d0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p291-33462191"},{"id":"3dae3dad-11fc-5c14-8bd2-ffb2f4db8d98","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة بعض محتويات منزل -انتهاك حرمة منزل -حدث- سرقة مال محترم من حرز بالغ النصاب -رجوع عن إقرار مصدق شرعا-عدم وجود سوابق -درء حد السرقة -تعزير بالسجن واجللد.","document_number":"33217509","case_number":"33272554","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة املساعد بتبوك ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/27","year":"1434","subject":"سرقة -سرقة بعض محتويات منزل -انتهاك حرمة منزل -حدث- سرقة مال محترم من حرز بالغ النصاب -رجوع عن إقرار مصدق شرعا-عدم وجود سوابق -درء حد السرقة -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 33217509:‬تاريخه ‪1433/4/27:‬هـ‬\n                    ‫رقم الدعوى ‪33272554:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 3439716‬تاريخه‪1434/2/17 :‬ه‬\n\n\n\n‫ســرقة ‪ -‬ســرقة بعــض محتويــات منــزل ‪ -‬انتهــاك حرمــة منــزل ‪ -‬حدث‪-‬‬\n‫ســرقة مــال محتــرم مــن حــرز بالــغ النصــاب‪ -‬رجــوع عــن إقــرار مصــدق‬\n‫شــرعا‪-‬عدم وجــود ســوابق‪ -‬درء حــد الســرقة‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫‪ -‬قول النبي صلى اهلل عليه وسلم‪ ( :‬ادرؤوا احلدود بالشبهات )‪.‬‬\n\n\n\n\n‫دعــوى املدعــي العــام ضــد املدعــى عليهمــا باالشــتراك بانتهــاك حرمــة‬\n‫منزلــن وســرقة مبلــغ مالــي وجهــاز حاســب آلــي وســرقة كاميرتــن‬\n‫وجهــاز جــوال مــن مدرســة ابتدائيــة وجهــاز أم بــي ثــري وســرقة نظــارة‬\n‫شمســية وعــدة وســيديات وكســر درج ســيارة وســرقة مالبــس وأشــمغة‬\n‫مــن مغســلة مالبــس وطلــب املدعــي العــام إقامــة حــد الســرقة ‪،‬مت القبض‬\n‫علــى املدعــى عليهمــا بعــد بالغــات مفادهــا تعــرض مدرســة وســيارات‬\n‫ومســاكن للســرقة ومت جمــع املعلومــات وبالبحــث والتحــري مت القبــض‬\n‫علــى املدعــى عليهمــا وباســتجوابهما صادقــا علــى مــا نســب إليهمــا‬\n‫وصــدق إقرارهمــا شــرع ًا ‪،‬أنكــر املدعــى عليهمــا الدعــوى ‪،‬رجــع‬\n‫املدعــى عليهمــا عــن اإلقراريــن املنســوبني إليهمــا ‪ ،‬درء حــد الســرقة عــن‬\n‫املدعــى عليهمــا ‪ ،‬حكمــت احملكمــة بتعزيرهمــا بالســجن واجللــد ‪ ،‬مت‬\n\n                                                                                   ‫‪306‬‬\n\f                                     ‫تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعده‪..‬وبعــد بنــاء‬\n      ‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة املســاعد‬\n      ‫بتبــوك برقــم ‪ .......‬وتاريــخ ‪......‬املقيــدة باحملكمــة العامــة بتبــوك برقــم‬\n      ‫‪ .......‬وتاريــخ‪ ........‬واحملالــة إلــى احملكمــة مــن فــرع هيئــة التحقيــق‬\n      ‫واالدعــاء العــام مبنطقــة تبــوك برقــم ‪ ....‬يف‪.......‬ه ـ ففــي يــوم الثالثــاء‬\n      ‫املوافق‪.........‬فتحــت اجللســة الســاعة ‪ 10:00‬لدينــا نحــن القضــاة‬\n      ‫باحملكمــة العامــة بتبــوك ‪ ..........‬و‪ ...........‬و‪ ......‬وفيهــا حضــر املدعــي‬\n      ‫العــام ‪ ......‬حامــل الســجل املدنــي رقــم ‪ ......‬صــادر مــن تبــوك واملكلــف‬\n      ‫باإلدعــاء يف هــذه احملكمــة مبوجــب كتــاب مديــر فــرع هيئــة التحقيــق‬\n      ‫واإلدعــاء العــام مبنطقــة تبــوك رقــم‪ .....‬يف‪ .........‬ه ـ وقــدم كتابــه‬\n      ‫املتضمــن بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة‬\n      ‫مبنطقــة تبــوك أدعــي علــى احلاضريــن معــي ‪ ...... -1‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ......-2 ......‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ......‬فبتاريــخ ‪ ......‬تقــدم املواطن‪-،......‬يعمــل‬\n      ‫مــدرس‪ -‬ببــاغ لــدى مركــز شــرطة ‪ ....‬مفــاده تعــرض غرفــة مصــادر‬\n      ‫التعليــم ملدرســة ‪ ......‬للســرقة حيــث ســرق منهــا كاميرتــن فيديــو مــن‬\n      ‫نــوع ‪ ....‬ويدعــى علــى احلــدث ‪ .....‬بســرقتها ‪ .‬وباالنتقال واملعاينة للمدرســة‬\n      ‫تبــن أنهــا مدرســة ابتدائيــة تقــع بقريــة وهــي عبــارة عــن مبنــى يتكــون‬\n      ‫مــن دوريــن وكانــت الغرفــة بطــول ‪ 6،6‬م تقريب ـ ًا وتبــن أن اجلانــي دخــل‬\n\n‫‪307‬‬\n\f‫مــن أحــد النوافــذ ولــم يالحــظ أي شــي خــاف ذلــك ومت تصويــر املوقــع‬\n‫ورفــع البصمــات ‪ .‬وبتاريــخ ‪../../14‬ه ـ تقــدم املواطــن املجنــي عليــه‪/‬‬\n‫‪، ...................‬بشــكوى لــدى مركــز شــرطة ‪ ....‬مفادهــا أنــه بتاريــخ‬\n‫‪ ..........‬تعرضــت ســيارته نــوع ‪ .....‬حتمــل اللوحــة رقــم (‪ ) ... ....‬للســرقة‬\n‫حيــث ســرق منهــا جهــاز أم بــي ثــري ونظــارة شمســيه وأفــاد بــأن الســيارة‬\n‫كانــت مقفلــة واليدعــى علــى أحــد ًا بالســرقة ‪ .‬وتقــدم املواطــن املجنــي‬\n‫عليــه‪ ،....... .... /‬بشــكوى مفادهــا أنــه بتاريــخ ………‪.‬ه ـ تعرضــت‬\n‫ســيارته نــوع …‪ ..‬موديــل (‪ ).....‬حتمــل اللوحــة رقــم (…‪ )… .‬للســرقة‬\n‫حيــث ســرق منهــا مبلــغ (…) ريــال وســيديات وكســر درج الســيارة‬\n‫وســرقة مبلــغ (‪ )...‬ريــا ًال كمــا أفــاد بــأن الســيارة كانــت مقفلة واليدعى‬\n‫علــى أحــد ًا بالســرقة‪ .‬وتقــدم املواطــن املجنــي عليــه ‪ ............./‬بشــكوى‬\n‫مفادهــا أنــه بتاريخ‪........‬ه ـ تعرضــت ســيارته نــوع ‪ ......‬موديــل (‪)....‬‬\n‫للســرقة حيــث ســرق منهــا مجموعــة مفــكات ونظــارة واليدعــى علــى‬\n‫أحــد ًا بالســرقة ‪ .‬وبتاريــخ ‪ .........‬تقــدم املقيــم املجنــي عليــه‪......./‬‬\n‫بشــكوى مفادهــا تعــرض شــقته للســرقة حيــث وجــد حقيبــة جهــاز‬\n‫احلاســب اآللــي مفتوحــة ومت بعثــرة مــا بداخلهــا ووجــد آثــار أقــدام يف‬\n‫الصالــة وعصــا خشــبية أمــام غرفــة النــوم وكانــت فتحــة املكيــف‬\n‫مكســورة وأفــاد بأنــه مت ســرقة جهــاز جــوال (‪ ) ...‬ومبلــغ مالــي قــدره‬\n‫(‪ )...‬خمســمائة وخمســن ريــا ًال كانــت موجــودة داخــل محفظتــه وال‬\n‫يدعــى علــى أحــد ًا بالســرقة ‪ .‬وباالنتقــال واملعاينــة تبــن أنهــا تقــع يف‬\n‫عمــارة مكونــة مــن دوريــن وأن الشــقة رقــم (‪ )1‬الواقعــة بالــدور األرضــي‬\n‫هــي التــي تعرضــت للســرقة وتبــن دخــول اجلنــاة عــن طريــق نافــذة‬\n‫املكيــف التــي كانــت مغطــاة بلــوح خشــبي ولــم يوجــد آثــار بعثــرة داخــل‬\n\n\n                                                                                     ‫‪308‬‬\n\f      ‫الشــقة ‪ .‬وبتاريــخ ‪ .........‬تقــدم املقيــم املجنــي عليــه‪،............. /‬بشــكوى‬\n      ‫مفادهــا تعــرض شــقته للســرقة حيــث ســرق منهــا جهــاز حاســب آلــي‬\n      ‫محمــول نــوع (‪ )...‬وذاكــرة جــوال (فــاش ميمــوري) (‪ )4‬جيجــا وعنــد‬\n      ‫تفقــده لشــقته وجــد مفتــاح علــى غــاز املطبــخ وكان شــباك املطبــخ‬\n      ‫ا وأفــاد بــأن قيمــة‬ ‫مفتوح ـ ًا كمــا أفــاد بــأن بــاب الشــقة كان مقف ـ ً‬\n      ‫احلاســب اآللــي (‪ )1000‬ألــف ريــال واليدعــى علــى أحــد ًا بالســرقة ‪ .‬وقــد‬\n      ‫ورد محضــر التحــري والقبــض بتاريــخ ‪.......‬الصــادر مــن البحــث اجلنائــي‬\n      ‫بتبــوك املتضمــن أنــه مت جمــع معلومــات عــن األشــخاص املشــبوهني ومــن‬\n      ‫لهــم ســوابق يف قضايــا ســرقات وقــد توفــرت معلومــات عــن قيــام احلــدث‬\n      ‫‪ ........../‬واحلــدث ‪، ........... /‬واحلــدث‪ ،......../‬بســرقة تلــك املســروقات‬\n      ‫فتــم اســتدعاء احلــدث‪ ،......../‬مــن قبــل والــده ومت إيداعــه الــدار بتاريــخ‬\n      ‫ـاء علــى توجيــه فضيلــة قاضــي االحــداث‬          ‫‪............‬ومــازال موقوف ـ ًا بنـ ً‬\n      ‫أســتناد ًا للمــادة (‪ )13‬مــن نظــام االجــراءات اجلزائيــة‪ .‬وبســماع أقــوال‬\n      ‫احلــدث ‪، ........... /‬أفــاد بأنــه أخبــره كل مــن احلــدث ‪، ........ /‬‬\n      ‫واحلــدث‪ ،............../‬أن احلــدث‪ .........../‬واملتهــم الهــارب ‪، ........... /‬همــا‬\n      ‫من قاما بســرقة احلاســب اآللي من شــقة املقيم ‪ .... /‬وأنه قبل أســبوعني‬\n      ‫تقريب ـ ًا إلتقــى باملتهــم الهــارب ‪، .......... /‬عنــد املستشــفى وطلــب منــه‬\n      ‫الذهــاب معــه لســرقة مغســلة املالبــس فرفــض ذلــك فذهــب املتهــم‬\n      ‫الهــارب‪ ...../‬إلــى منــزل احلــدث‪ ........../‬كمــا أفــاد احلــدث ‪،........... /‬‬\n      ‫أنــه بعــد يومــن إلتقــى باملتهم الهــارب‪................. /‬واحلــدث‪ ......../‬وكانا‬\n      ‫راكبــن ســيارة ‪ .....‬بقيــادة املتهــم الهــارب ‪ ....... /‬وكان يرتــدي ثوب ـ ًا‬\n      ‫جديــد ًا وطلبــا منــه مرافقتهمــا للحديقــة فرفــض ذلــك كمــا أفــاد احلــدث‬\n      ‫‪ ،............ /‬بأن املتهم الهارب ‪..... /‬ذكر له بأنه قام هو واحلدث‪،......../‬‬\n\n\n‫‪309‬‬\n\f‫بســرقة مغســلة املالبــس التــي بعمــارة ‪ ..........‬حيــث قامــا بســرقة مالبــس‬\n‫وثــاث أشــمغة ‪.‬وباســتجواب احلــدث‪ ،......../‬أقــر بقيامــه بســرقة شــقة‬\n‫املقيــم ‪ .... /‬وشــاركه يف ذلــك احلــدث الهــارب‪، .......... /‬حيــث قامــا‬\n‫بدخــول الشــقة عــن طريــق فتحــة املكيــف وقــام بســرقة جهــاز جــوال‬\n‫(‪ )...‬وقــام احلــدث ‪ ... /‬بســرقة مبلــغ(‪ )550‬خمســمائة وخمســن ريــا ًال ثــم‬\n‫خرجــا مــن الشــقة عــن طريــق البــاب ثــم قامــا ببيــع جهــاز اجلــوال يف محــل‬\n‫اجلــواالت مببلــغ (‪ )320‬ثالثمائــة وعشــرين ريــا ًال وتقاســما املبلغ املســروق‬\n‫وكذلــك مبلــغ قيمــة اجلــوال كمــا أفــاد بأنــه اتفــق مــع احلــدث ‪........./‬‬\n‫‪،‬علــى ســرقة شــقة املقيــم ‪، ....... /‬حيــث قــام هــو باجللــوس يف احلــوش‬\n‫للمراقبــة بينمــا قــام احلــدث ‪ ،... /‬بدخــول الشــقة عــن طريــق تســلق‬\n‫املواســير والدخــول مــن النافــذة وجلــس عشــر دقائــق ثــم خــرج مــن نفــس‬\n‫النافــذة التــي دخــل منهــا ومعــه جهــاز احلاســب اآللــي احملمــول ثــم قــام هــو‬\n‫بأخــذ جهــاز احلاســب اآللــي احملمــول وأعطــى احملــدث ‪، .... /‬مبلــغ (‪)50‬‬\n‫خمســن ريــا ًال كمــا أفــاد احلــدث‪ ،.........../‬بأنــه عندمــا كان جالس ـ ًا‬\n‫بســطح منزلهــم شــاهد احلــدث‪ ،.......... /‬وهــو يقــوم بســرقة ســيارة‬\n‫جارهــم وهــي مــن نــوع ‪ .......‬وســرق منهــا جهــاز (أم بــي ثــري) ونظــارة‬\n‫شمســية ومبلــغ (‪ )60‬ســتني ريــا ًال وأخــذ هــو جهــاز (أم بــي ثــري) كمــا‬\n‫أفــاد احلــدث‪ ،.........../‬أنــه بتاريــخ ‪ ...........‬ه ـ وبعــد صــاة العشــاء حضــر‬\n‫لــه احلــدث ‪، ........ /‬وقــام بالركــوب معــه يف ســيارته وشــاهد معــه‬\n‫كامرتــن فيديــو وأخبــره احلــدث ‪، ... /‬بأنــه ســرقهما مــن مدرســة‬\n‫‪ ...........‬وقامــا ببيعهــا علــى املدعــو ‪، ................... /‬مببلــغ قــدره (‪)400‬‬\n‫أربعمائــة ريــال كــم أفــاد بأنــه شــاهد احلــدث ‪، ..../‬أثنــاء قيامــه بســرقة‬\n‫املالبــس مــن املغســلة وكاميرتــي الفيديــو مــن مدرســة ‪ ....‬اإلبتدائيــة‬\n\n\n                                                                                          ‫‪310‬‬\n\f      ‫وأنكر قيامه بســرقة بقية املســروقات وقد قام احلدث‪ ... /‬واحلدث‪...../‬‬\n      ‫‪،‬بالداللــة علــى منزلــي املقيمــن‪، ......../‬و‪، ........./‬وكيفيــة قيامهمــا‬\n      ‫بالســرقة‪( .‬وبالبحــث يف ســجالته لــدى دار املالحظــة اإلجتماعيــة بتبوك‬\n      ‫تبــن وجــود ســابقتني األولــى ســرقة ســيارة والثانيــة ســرقة)‪ .‬وباســتجواب‬\n      ‫احلــدث‪، ............ /‬أفــاد بأنــه اتفــق مــع احلــدث ‪ ،........./‬علــى ســرقة شــقة‬\n      ‫املقيــم ‪ ..../‬حيــث قــام احلــدث ‪، ....../‬بتســلق املواصيــر ودخــل عــن طريــق‬\n      ‫النافــذة وبعــد مضــي عشــر دقائــق خــرج ومعــه جهــاز احلاســب اآللــي‬\n      ‫احملمــول وقــام بإعطائــه احلــدث‪، .../‬ثــم قــام احلــدث ‪،......../‬بدخــول‬\n      ‫شــقة املقيــم ‪، ..../‬يف املوجــودة بالعمــارة التــي بهــا شــقة املقيــم‪، ..../‬عــن‬\n      ‫طريــق فتحــة املكيــف ثــم خــرج ومعــه مبلــغ قــدره (‪ )500‬خمســمائة‬\n      ‫ريــال وجهــاز جــوال نــوع (‪ )......‬بينمــا كان دور احلــدث‪، .../‬يقــوم‬\n      ‫باملراقبــة وأفــاد بأنهمــا قامــا ببيــع جهــاز اجلــوال علــى أحــد محــات بيــع‬\n      ‫اجلواالت كما أفاد بأنهما قاما بســرقة ســيارة نوع ‪ .......‬تعود ملكيتها‬\n      ‫للمواطــن‪ ...... /‬أثنــاء توقفهــا حيــث ســرقا منهــا مبلــغ (‪ )60‬ســتني ريــال‬\n      ‫وجهــاز (أم بــي ثــري) وســيديات كمــا أفــاد بأنهمــا قامــا بســرقة مغســلة‬\n      ‫مالبــس الواقعــة باملخطــط حيــث ســرقا منهــا ثــاث ثيــاب وثــاث أشــمغة‬\n      ‫كمــا أفــاد بأنهمــا قامــا بســرقة كاميرتــن فيديــو مــن مدرســة ‪.....‬‬\n      ‫االبتدائيــة والقــط وكرتــون عصيــر وقــام احلــدث ‪ ، ....../‬ببيعهــا علــى‬\n      ‫املواطــن‪ ،............ /‬مببلــغ (‪ )400‬أربعمائــة ريــال‪ .‬وبســماع أقــوال املقيم‪/‬‬\n      ‫‪ ،........‬بنجالديشــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪)..........‬‬\n      ‫أفــاد بأنــه يف شــهر (‪ )..‬مــن عــام ‪....‬ه ـ تعرضــت مغســلة املالبــس التــي‬\n      ‫يعمــل بهــا للســرقة حيــث ســرق منهــا بعــض املالبــس ال يعــرف عددهــا‬\n      ‫بالضبــط وال يعــرف اجلنــاة كمــا أفــاد بأنــه لــم يتقــدم ببــاغ بالواقعــة يف‬\n\n\n‫‪311‬‬\n\f‫حينــه‪ .‬وبســماع أقــوال املواطــن‪ ،.......... /‬أفــاد بــأن احلــدث ‪........ /‬‬\n‫‪،‬حضــر إليــه باملنــزل وعــرض عليــه شــراء كاميرتــن فيديــو األولــى‬\n‫مســتعملة والثانيــة جديــدة وذكــر لــه احلــدث‪، ... /‬بــأن الكاميرتــن‬\n‫تعــود ألهلــه وأنهــم محتاجــن للمــال فقــام املواطــن‪، ... /‬بشــراء‬\n‫الكاميرتــن مببلــغ (‪ )1000‬ألــف ريــال فقــام بإعطائــه مبلــغ (‪)200‬‬\n‫مائتــن ريــال والباقــي آخــر الشــهر كمــا أفــاد بأنــه عندمــا علــم بــأن‬\n‫احلــدث‪ ،... /‬قــام بســرقة الكاميرتــن مــن املدرســة قــام بتســليمها‬\n‫ملركــز الشــرطة ‪ .‬ومت عــرض الكاميرتــن علــى املواطــن ‪،........../‬‬\n‫وأفــاد بــأن الكاميرتــن همــا اللتــان ســرقتا مــن املدرســة وســلمتا لــه‪.‬‬\n‫ومت ‪ ..‬جهــاز احلاســب اآللــي احملمــول للمقيــم ‪ ،......../‬وهــو بحالــة ‪...‬‬\n‫وبلغــت قيمــة املســروقات (‪ )1170‬ألــف ومائــة وســبعون ريــال‪( .‬مت فــرز‬\n‫أوراق مســتقلة للحــدث الهــارب‪ ................/‬وأنتهــى التحقيــق الــى توجيــه‬\n‫االتهــام للحــدث ‪ ....................‬وللحــدث ‪ ،.......‬باالشــتراك بانتهــاك‬\n‫حرمــة منزلــي املقيمــن‪ ،...........‬و‪،.........‬وســرقة جهــاز (‪ )....‬ومبلــغ‬\n‫(‪ )550‬خمســمائة وخمســن ريــا ًال وجهــاز احلاســب اآللــي احملمــول نــوع‬\n‫(‪ )....‬وقيامــه بســرقة كاميرتــن نــوع ‪ ......‬مــن املدرســة االبتدائيــة ب‪......‬‬\n‫وســرقة جهــاز (إم بــي ثــري ) ونظــارة شمســية مــن ســيارة املواطــن‪،.........‬‬\n‫وســرقة عــدة ونظــاره شمســيه مــن ســيارة املواطــن‪ ،.........‬وســرقة‬\n‫ســيديات ومبلــغ (‪ )120‬مائــة وعشــرون ريــا ًال وكســر درج ســيارة‬\n‫املواطــن ‪، .....‬وســرقة مالبــس وأشــمغة مــن مغســلة مالبــس حيــث بلغــت‬\n‫قيمــة املســروقات (‪ )1170‬ألــف ومائــة وســبعني ريــال‪ .‬وذلــك لألدلــة‬\n                                                                ‫والقرائن التالية ‪:‬‬\n‫‪ -1‬اعترافهمــا املصــدق شــرعا املــدون علــى الصفحــة رقــم (‪ )....‬مــن‬\n\n\n                                                                                     ‫‪312‬‬\n\f      ‫دفتــر التحقيــق املرفــق لفــه رقــم (‪ )...‬ومــا جــاء باعترافهمــا املــدون علــى‬\n      ‫الصفحــة رقــم (‪ )...‬مــن دفتــر احلقيــق املرفــق لفــه رقــم (‪ ).......‬ومــا جــاء‬\n      ‫بأقــوال احلدث‪........‬املدونــة الصفحــة رقــم (‪ )....‬مــن دفتــر التحقيــق‬\n                                                                      ‫املرفــق لفــة رقــم (‪.)..‬‬\n      ‫‪ -2‬محاضــر االنتقــال واملعاينــة املنــوه عنهــا املدونــة علــى الصفحــة رقــم‬\n      ‫(‪ )..‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪ )..‬والصفحــة رقــم (‪ ).‬مــن دفتــر‬\n                                                            ‫التحقيــق املرفــق لفــة رقــم (‪.).‬‬\n      ‫‪ -3‬مــا جــاء بأقــوال عامــل املغســلة املــدون علــى الصفحــة رقــم (‪ )..‬مــن‬\n                                                   ‫دفتــر التحقيــق املرفــق لفــة رقــم(‪.)..‬‬\n      ‫‪ -4‬مــا جــاء بأقــوال احلــدث …………‪ ..‬املــدون علــى الصفحــة رقــم(‪).‬‬\n                                           ‫مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪.)....‬‬\n                      ‫‪ -5‬ما جاء يف تقرير البحث والتحري املرفق لفة رقم (‪.)....‬‬\n      ‫‪ -6‬مــا جــاء يف تناقــض أقــوال احلــدث ‪........‬مــع احلــدث اآلخــر…‪ .‬حيــث‬\n      ‫ذكــر احلــدث … بــأن ‪ ....‬هــو مــن قــام بتســلق منــزل املقيــم ‪ ...‬وســرقته‬\n      ‫وأن دوره كان املراقبــة فقــط وأنــه لــم يقــم بســرقة مغســلة املالبــس‬\n                                  ‫وســيارة جــاره‪ ......‬وأن ‪ ....‬هــو مــن قــام بذلــك يف‬\n      ‫حــن ذكــر احلــدث ‪...‬بــأن احلــدث ‪ ...‬هــو مــن قــام بتســلق منــزل املقيــم‪...‬‬\n      ‫وســرقته وأن دوره هــو املراقبــة وأنــه قــام مبشــاركة‪ ...‬يف ســرقة مغســلة‬\n      ‫املالبــس وســيارة ‪ .........‬املــدون علــى الصفحتــن رقــم (‪ )5-4‬مــن دفتــر‬\n                                                                                     ‫التحقيــق‪.‬‬\n      ‫‪ -7‬مــا جــاء مبحضــر التعــرف علــى بعــض املســروقات املــدون علــى‬\n              ‫الصفحــة رقــم (‪ )7‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪.)28‬‬\n      ‫‪ -8‬مــا جــاء مبحضــر الداللــة املنــوه عنــه املرفــق لفــة رقــم (‪)13-12‬‬\n\n\n‫‪313‬‬\n\f‫مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪.)32‬وحيــث أن ماقــام بــه احلدثــن‬\n‫املذكوريــن فعــل محــرم ومعاقــب عليــه شــرعا وهــو ســرقة مــال محتــرم‬\n‫مــن حــرزه بالــغ النصــاب ال شــبهة فيــه وهمــا مكلفــن غيــر مكرهــن‬\n                                                             ‫لــذا أطلــب مايلــي‪-:‬‬\n                                                        ‫‪-1‬إثبات ما أسند إليه ‪.‬‬\n‫‪-2‬احلكــم عليــه بحــد الســرقة الــواردة يف اآليــة الكرميــة رقــم (‪ )38‬مــن‬\n                                                                    ‫ســورة املائــدة ‪.‬‬\n                           ‫( علما بأن جميع احلقوق اخلاص انتهت بالتنازل )‪.‬‬\n‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليهمــا أجابــا بقولهمــا‬\n‫مــا ذكــره املدعــي العــام ال صحــة لــه جملــة وتفصيــا ونحــن أعترفنــا‬\n‫باالكــراه هكــذا أجابــا وبعــرض إجابتهــم علــى املدعــي العــام قــال‬\n‫الصحيــح مــا جــاء يف دعــواي وأطلــب الرجــوع إلــى األدلــة التــي ذكرتهــا‬\n‫يف املعاملــة عليــه رفعــت اجللســة للرجــوع إلــى أدلــة املدعــي العــام وصلــى‬\n                           ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n‫ويف جلســة أخــرى افتتحــت اجللســة وفيهــا حضــر املدعــي العــام واملدعــى‬\n‫عليهمــا وبالرجــوع إلــى أوراق املعاملــة وجدنــا أدلــة املدعــي العــام تتمثــل‬\n‫يف اآلتي‪-1:‬اعترافهمــا املصــدق شــرع ًا املــدون علــى الصفحــة رقــم(‪-4‬‬\n‫‪ )7‬مــن دفتــر التحقيــق املرفــق لفــه رقــم (‪ )21‬ومــا جــاء باعترافهمــا‬\n‫املــدون علــى الصفحــة رقــم (‪)5-4‬مــن دفتــر التحقيــق املرفــق لفــه رقم(‪)5‬‬\n‫ومــا جــاء بأقــوال احلــدث‪ .../‬املدونــة علــى الصفحــة رقــم(‪ )11‬مــن دفتــر‬\n‫التحقيــق املرفــق لفــه رقــم(‪. )53‬ونصــه إقــرار بتاريــخ ‪../12/4‬ه ـ أقــر أنا‬\n‫احلــدث ‪.............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪............‬‬\n‫أســكن مبحافظــة ‪ ...‬وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا‬\n\n\n                                                                                         ‫‪314‬‬\n\f      ‫وبطوعــي وأختيــاري وبــدون أجبــار أو اكــراه مــن أحــد بأنــه قبــل حوالــي‬\n      ‫ا أتفقــت انــا وصديقــي ‪ ............‬بــأن نذهب‬    ‫أســبوعني يف يــوم االربعــاء ليـ ً‬\n      ‫إلــى منــزل الدكتــور املصــري فذهبنــا حتــى وصلنــا الــى املنــزل ودخلنــا‬\n      ‫املنــزل عبــر فتحــة املكيــف بعــد كســر خشــب املكيــف وقمــت أنــا‬\n      ‫باحلصــول علــى جهــاز جــوال ‪ ......‬وقمــت بســرقته وقــام صديقــي باحلصول‬\n      ‫علــى مبلــغ مالــي وقــدره(‪ )550‬ريــال وقــام بســرقتها ووضعهــا يف جيبــه‬\n      ‫ومــن ثــم خرجنــا مــن املنــزل عــن طريــق البــاب وبالنســبة للمســروقات‬\n      ‫األخــرى أنــا لــم أقــم باالشــتراك بهــا والأعلــم عنهــا شــي علمـ ًا بــأن اجلهــاز‬\n      ‫اجلــوال الــذي قمــت بســرقته قمنــا ببيعــه أنــا وصديقــي‪ ...‬مببلــغ(‪)320‬‬\n      ‫ريــال وقــد تقاســمنا املبلــغ وهــذا أقــرار صريــح منــي مبــا حصــل وعليــه‬\n      ‫جــرى التوقيع‪.‬أ‪.‬ه ـ إقــرار بتاريخ‪.........‬ه ـ أقــر أنــا احلــدث ‪...............‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ..........‬أســكن محافظــة‬\n      ‫‪ ...‬وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا ولســت مجبــر ًا أو مكــره‬\n      ‫مــن أحــد بــل بطوعــي واختيــاري بأنــه قبــل حوالــي أســبوعني اتفقنــا أنــا‬\n      ‫وصديقــي ‪ ........‬بأننــا نقــوم بســرقة منــزل الدكتــور ‪ ......‬وقمنــا بدخــول‬\n      ‫املنــزل عــن طريــق فتحــة املكيــف الــذي قمنــا بكســره وعنــد دخولنــا‬\n      ‫قــام صديقــي ‪ ........‬بأخــذ اجلــوال ‪ .....‬وانــا قمــت بأخــذ املبلــغ ‪ 550‬ريــال‬\n      ‫وقمنــا باخلــروج مــن املنــزل عــن طريــق البــاب وقمنــا ببيع اجلوال وتقاســمنا‬\n      ‫املبلــغ وكذلــك قمنــا أنــا ‪ .......... ....... .......‬بســرقة منــزل الدكتــور‬\n      ‫‪ .........‬وذلــك عــن طريــق فتحــة املكيــف قمنــا نحــن الثالثــة بالدخــول‬\n      ‫داخــل املنــزل وســرقة الب تــوب واخلــروج مــع نفــس فتحــت املكيــف وان‬\n      ‫الــذي قــام بأخــذ االب تــوب هــو ‪ ...........‬وكذلــك قمنــا بســرقة ســيارة ‪....‬‬\n      ‫أنــا ‪ .......‬وقــام ‪ .. .....‬بكســر زجــاج املثلــث اخللفــي وفتــح البــاب وســرقة‬\n\n\n‫‪315‬‬\n\f‫مابــي داخلهــا مــن األغــراض وهــذا إقــرار صريــح منــي مبــا حصــل وعليــه‬\n‫جــرى التوقيع‪.‬أ‪.‬ه ـ س‪ /‬أنــت متهــم يف ســرقة مالبــس من مغســلة مبركز‬\n‫‪ ...‬ومعــك احلــدث ‪ .........‬ج‪ /‬أننــي لــم أقــم بــأي ســرقة مــن املغســلة س‪/‬مــن‬\n‫الــذي قــام بســرقة املغســلة ج‪ /‬اننــي ال أعلــم مــن قــام بســرقة املغســلة س‪/‬‬\n‫لقــد ذكــر احلــدث ‪ .....‬يف اعترافــه بأنــك كنــت معه أثناء ســرقة املغســلة‬\n‫وكذلــك ســرقة املدرســة فمــا قولــك بذلــك ج‪/‬نعــم أننــي كنــت معــه أم‬\n‫أثنــاء ســرقة املغســلة واملدرســة لــم أكــن معــه س‪ /‬لقــد أعتــرف املواطــن‬\n‫‪ ........‬بأنــه أشــترى الكاميــرات مــن احلــدث ‪ ...........‬فمــا قولــك يف ذلــك‬\n‫ج‪/‬نعــم لقــد أخبرنــي احلــدث ‪ .........‬بذلــك بأنــه بــاع الكاميــرات علــى‬\n‫املواطــن ‪ ..........‬س‪ /‬هــل تصــادق علــى اقوالــك ج‪/‬نعــم أ‪.‬ه ـ ‪-2‬محاضــر‬\n‫االنتقــال واملعاينــة املنــوه عنهــا املدونــة علــى الصفحــة رقــم (‪ )6‬مــن دفتــر‬\n‫التحقيــق املرفــق لفــه رقــم(‪ )1‬والصفحــة رقــم (‪ )1‬مــن دفتــر التحقيــق‬\n‫املرفــق لفــه رقــم (‪ )3‬ونصــه محضــر أنتقــال ومعاينــة يف‪ ..........‬ه ـ نعــم‬\n‫لقــد جــرى أنتقالنــا نحــن املدونة أســمائنا إلى مدرســة ‪ .....‬ملعاينة الســرقة‬\n‫وبالوقــوف علــى طبيعــة املوقــع وهــي عبــاره عــن مدرســة مــن دوريــن ومت‬\n‫اســتداللنا عــن موقــع الســرقة وهــي عبــارة عــن غرفــة مكتبــة املدرســة‬\n‫ومت معاينــة املوقــع جيــد ًا ومت العثــور علــى مدخــل اجلاني من أحد شــبابيك‬\n‫املكتبــه ولــم نالحــظ أي شــي خــاف ذلــك ومت تصويــر املوقــع ورفــع‬\n‫البصمــات وعلــى ذلــك نوقع‪.‬أ‪.‬ه ـ محضــر معاينــة‪ .‬مبعرفتــي انــا ضابــط‬\n‫خفــر لهــذا اليوم‪..........‬ه ـ مت معاينــة منــزل املدعــي وتبــن انــه يقــع يف حــي‬\n‫‪ .....‬وهــو عبــارة عــن عمــاره مكونــه مــن أربــع شــقق وهــو يســكن يف‬\n‫الشــقة رقــم (‪ )..‬يف الــدور االرضــي وتبــن دخــول اجلنــاة عــن طريــق نافــذة‬\n‫املكيــف التــي كانــت مغطــاه بلــوح خشــبي بعــد كســر اللــوح اخلشــبي‬\n\n\n                                                                                         ‫‪316‬‬\n\f      ‫ولــم يوجــد أي آثــار بعثــرة داخــل املنــزل وحفــظ للواقــع نظــم هــذا‬\n      ‫احملضر‪.‬أ‪.‬ه ـ ‪-3‬ماجــاء بأقــوال عامــل املغســلة املــدون علــى الصفحــة‬\n      ‫رقــم(‪ )2‬مــن دفتــر التحقيــق املرفــق لفــه رقــم(‪ )54‬نعــم أقــرر انــا‬\n      ‫املقيــم‪ ........../‬بنجالديشــي اجلنســية مبوجــب اإلقامــة رقــم‪............‬‬\n      ‫بأقــراري هــذا وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا وبطوعــي‬\n      ‫واختيــاري بأنــه يف شــهر‪ ..‬مــن العــام ‪....‬ه ـ والأعــرف اليــوم بالتحديــد‬\n      ‫تعرضــت املغســلة التــي أعمــل بهــا للســرقه والعبــث وفقــدت بعــض الثياب‬\n      ‫واملناديــل والأعــرف عددهــا بالضبــط ولــم أقــم بتقــدمي بــاغ بالواقعــة يف‬\n      ‫ال مــن‬‫حينهــا والأعــرف اجلنــاة وأننــي الأرغــب بإقامــة دعــوى ضــد ك ً‬\n      ‫‪.........‬واحلــدث ‪ ........‬وانــا متنــازل عــن حقــي اخلــاص وهــذا إقرارمنــي‬\n      ‫بذلــك وعليــه أوقع‪.‬أ‪.‬هــ‪ -4‬ماجــاء بأقــوال احلــدث‪ ........./‬املــدون علــى‬\n      ‫الصفحــة رقــم(‪ )3‬مــن دفتــر التحقيــق املرفــق لفــه رقم (‪ )5‬محضر ســماع‬\n      ‫أقــوال يف‪............‬نعــم أقــر انــا الغــام‪ ......./‬ســعودي اجلنســية بإقــراري‬\n      ‫ال مــن الغــام ‪ ......‬والغــام ‪ ........‬والغــام ‪.........‬‬\n                                                                ‫هــذا بأنــه أخبرنــي ك َ‬\n      ‫ال ‪ ........‬والغــام ‪ ......‬همــا الذيــن قامــا بســرقة جهــاز الالبتــوب‬ ‫بــأن ك ً‬\n      ‫مــن شــقة املقيــم ‪ ....‬وكذلــك انــه قبــل اســبوعني تقريب ـ ًا قابلنــي الغــام‬\n      ‫‪......‬عنــد املستشــفى باملخطــط وقــال لــي متشــي معــي نســرق مغســلة‬\n      ‫املالبــس فرفضــت وقــال لــي نــاد لــي ‪ ...‬معــك فرفضــت فذهــب للمدعــو‬\n      ‫‪ ......‬ودق عليــه البــاب وأنــا بعدهــا ذهبــت للمنــزل وبعــد يومــن قابلنــي‬\n      ‫‪ ........‬و ‪.......‬املذكــور وأخبرنــي ‪ .....‬بأنهــم هــو و‪ ....‬قــد ســرقوا مــن‬\n      ‫مغســلة املالبــس التــي بعمــارة ‪ ....‬ثيــاب وثبلثــة مناديــل وأننــي ال اعلــم عــن‬\n      ‫باقــي الســرقات أي شــي وهــذا مالــدي وعليــه أوقع‪.‬أ‪.‬ه ـ ‪ -5‬ماجــاء يف‬\n      ‫تقريــر البحــث والتحــري املرفــق لفــه رقــم(‪ )15‬محضــر بحــث وحتــري‬\n\n\n‫‪317‬‬\n\f‫وقبــض بتاريخ‪.........‬ه ـ نظــر ًا لتكــرار الســرقات يف حــي ‪ ......‬وحــي ‪......‬‬\n‫مبركــز ‪ ...‬فقــد جــرى تكليــف أفــراد مــن ذوي الكفــاءات واخلبــرة يف‬\n‫إجــراءات البحــث والتحــري ومت جمــع معلومــات عــن االشــخاص‬\n‫املشــبوهني داخــل تلــك االحيــاء ومــن لهــم ســوابق يف قضايــا الســرقات‬\n‫وقــد توفــرت معلومــات عــن قيــام بعــض االحــداث ببعــض تلــك الســرقات‬\n‫فقــد جــرى نشــر بعــض املصــادر بــن تلــك التجمعــات مــن الشــباب‬\n‫ال مــن ‪..........‬‬\n                ‫وتوفــرت معلومــات بــأن مــن يقــوم بتلــك الســرقات هــم ك ً‬\n‫و‪............‬و‪ ...........‬وقــد مت اســتدعاء أوليــاء أمورهــم وقــد مت احضــار‬\n‫املدعــو‪ .../‬عــن طريــق شــقيقه وبالنســبة للمدعو‪.../‬فقــد مت اســتدعاء‬\n‫والــده اكثــر مــن مــرة ومت إحضــاره ابنــه أمــا بالنســبة للمدعــو‪ ../‬فقــد مت‬\n‫االنتقــال ملنزلــه ولــم جنــده كــون والــده منفصــل عــن والدتــه منــذ ســنتني‬\n‫ال لســياره داخــل‬   ‫ويف هــذا اليــوم املوافــق ‪.....‬ه ـ مت مشــاهدته مســتق ً‬\n‫مركــز ‪ ...‬وعنــد محاولــة اســتيقافه الذا بالفــرار ومتــت متابعتــه حتــى مت‬\n‫القبــض عليــه وحفظـ ًا للواقــع جــرى اعــداد احملضــر ‪.‬أ‪ .‬ه ـ ‪ -6‬مــا جــاء يف‬\n‫تناقــض أقــوال احلــدث ‪...‬مــع احلــدث اآلخــر ‪ ...‬حيــث ذكــر احلــدث ‪..‬بــأن‬\n‫‪ ...‬هــو مــن قــام بتســلق منــزل املقيــم ‪ ...‬وســرقته وأن دوره كان املراقبــة‬\n‫فقــط وأنــه لــم يقــم بســرقة مغســلة املالبــس وســيارة جــاره ‪ ....‬وأن ‪ ...‬هــو‬\n‫مــن قــام بذلــك يف حــن ذكــر احلــدث ‪ ...‬بــأن احلــدث ‪..‬هــو مــن قــام بتســلق‬\n‫منــزل املقيــم ‪ ...‬وســرقه وأن دوره هــو املراقبــه وأنــه قــام مبشــاركة ‪..‬يف‬\n‫ســرقة مغســلة املالبــس وســيارة جــاره ‪ -7 ..‬ماجــاء مبحضــر التعــرف‬\n‫علــى بعــض املســروقات املــدون علــى الصفحــة رقــم (‪ )7‬مــن دفتــر‬\n‫التحقيــق املرفــق لفــه رقــم(‪ )28‬محضــر تعــرف أقــر أنــا املواطــن‪.......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي ‪1042027357‬بإقــراري هــذا‬\n\n\n                                                                                      ‫‪318‬‬\n\f      ‫وأنــا بكامــل قــواي العقليــه املعتبــرة شــرع ًا وبطوعــي واختيــاري بــأن‬\n      ‫الكاميــرات التــي عرضــت علــي وهــي مــن نــوع ‪ .....‬هــي نفــس‬\n      ‫الكاميــرات التــي ســرقت مــن املدرســة بتاريخ‪.....‬ه ـ هــذا إقــراري وعليــه‬\n      ‫أوقــع أ‪ .‬ه ـ ‪ -8‬مــا جــاء مبحضــر الداللــة املنــوه عنــه املرفــق صفحــة رقــم‬\n      ‫(‪ )13-12‬مــن دفتــر التحقيــق املرفــق لفــه رقــم(‪ )32‬محضــر تدليــل‬\n      ‫بتاريــخ ‪.....‬ه ـ ونصــه بتاريخــه أعــاه نحــن املوقعــن أدنــاه جــرى االنتقــال‬\n      ‫ال مــن احلــدث ‪ ............‬واحلــدث ‪ ...........‬رفــق منــدوب دار‬ ‫رفــق ك ً‬\n      ‫املالحظــة االجتماعيــة للتدليــل والتمثيــل عــن كيفيــة ســرقتهم للمنــزل‬\n      ‫والســيارة وعنــد الوصــول إلــى مركــز ‪ ...‬مت االنتقــال إلــى موقــع الســرقة‬\n      ‫وهــو عبــارة عــن عمــارة مكونــة مــن دوريــن والعمــارة لهــا مدخلــن وتبــن‬\n      ‫أن اجلنــاة قامــوا بالدخــول مــن البــاب الرئيســي للعمــاره والدخــول مــع‬\n      ‫بــاب حديــد صغيــر متجــه الــى ســيب صغيــر ومــن ثــم قــام احلــدث ‪....‬‬\n      ‫بالقفــز مــع فتحــت املكيــف والغيــر محصنــة بشــبك والدخــول الــى‬\n      ‫الغرفــة التــي يســكن بهــا شــخص مصــري يقيــم بهــا مبفــرده وســرقة‬\n      ‫جــوال ومبلــغ مالــي ومــن ثــم الرجوع مع فتحة املكيف والشــقة املســروقة‬\n      ‫عبــارة عــن ثالثــة غــرف ومطبــخ ودورة ميــاه يف الــدور االرضــي وأمــا‬\n      ‫زميلــه ‪.....‬قــام بتســلق ماســوره للصــرف الصحــي والصعــود الــى الــدور‬\n      ‫الثانــي والدخــول مــع شــبك املطبــخ الغيــر محصــن والدخــول الــى داخــل‬\n      ‫الشــقه وســرقة جهــاز الب تــوب مــن غرفــة النــوم ورميــه مــن الشــباك علــى‬\n      ‫كنــب موضــوع يف الســيب ومــن ثــم الرجــوع بنفــس الطريقــه والشــقه يف‬\n      ‫الــدور الثانــي مكونــة مــن ثــاث غــرف ومطبــخ ودورة ميــاه ولها مدخلني‬\n      ‫حيــث مت التدليــل مــن قبــل احلدثــن املذكوريــن دون إكــراه وال اجبــار‬\n      ‫ومت تصويــر املوقــع وأماكــن الدخــول واخلــروج وحفــظ للواقعــة نظــم‬\n\n\n‫‪319‬‬\n\f‫هــذا احملضر‪.‬أ‪.‬ه ـ وبعــرض األدلــة علــى املدعــى عليهمــا أجــاب املدعــى‬\n‫عليــه األول ‪ ...‬بقولــه مــن جهــة اعتــرايف املصــدق شــرع ًا فنعــم انــا أعترفت‬\n‫امــام احملمكــة إلن احملقــق قــال لــي إذا اعترفــت ســنقوم بإخراجــك مــن‬\n‫الســجن ورغبــة منــي يف اخلــروج مــن الســجن اعترفــت مــع أن مااعترفــت‬\n‫بــه غيــر صحيــح ومحضــر االنتقــال واملعاينــة ال أعلــم عنــه شــيئ ًا وكذلــك‬\n‫أقــوال عامــل املغســلة أمــا أقــوال احلــدث ‪..‬ان ‪ .......‬فنعــم هــو قــال الــكالم‬\n‫هــذا وأعتــرف بــه إلنــه كان يرغــب اخلــروج مــن الســجن ويضعنــي أنــا‬\n‫فيــه ويتخلــص هــو مــن القضيــة أمــا تقريــر البحــث والتحــري فهــو غيــر‬\n‫صحيــح ومــن جهــة تناقــض أقوالــي مــع أقــوال ‪..‬فاحملقــق هــو الــذي كان‬\n‫ميلــي علينــا الــكالم ويطلــب منــا أن نقولــه ومــن جهــة تعــرف ‪ .......‬علــى‬\n‫املســروقات فــا أعلــم عنــه شــيئا ومــن جهــة محضــر الداللــة والتمثيــل‬\n‫فنعــم أنــا قمــت بتمثيــل الســرقة ولكــن قمــت بهــا بنــاء علــى طلــب احملقق‬\n‫وإال فأنــا بــريء منهــا هكــذا اجــاب كمــا أجــاب املدعــى عليــه الثانــي‬\n‫‪..‬بقولــه بــأن احملقــق ضحــك علــي وقــال لــي إذا اعترفــت أمــام احملكمــة‬\n‫فســوف نخرجــك مــن الســجن وصدقتــه مــع أنــي بــريء منهــا ومــن جهــة‬\n‫اعتــرايف حتقيقــا بــأن ‪ ...‬أخبرنــي ببيــع الكاميــرات فهــذا صحيــح وأنــا‬\n‫لــم أعلــم مــن أيــن أتــى بهــا وهــي كاميــره واحدةومحضــر االنتقــال‬\n‫واملعاينــة ال علــم لــي بــه ومــن جهــة أقــوال عامــل املغســلة فــا علــم لــي بهــا‬\n‫أيضـ ًا وتقريــر البحــث والتحــري غيــر صحيــح ومــن جهــة تناقــض أقوالــي‬\n‫مــع احلــدث املدعــى عليــه الثانــي ‪ ...‬فأنــا أقــول مايطلــب منــي احملقــق‬\n‫قولــه ومــن جهــة تعــرف‪ .......‬علــى املســروقات فــا علــم لــي بــه ومحضــر‬\n‫الداللــة والتمثيــل فنعــم أنــا قمــت بتمثيــل الســرقة ولكــن قمــت بهــا بنــاء‬\n‫علــى طلــب احملقــق وهددنــي بأنــي إذا لــم أقــم بهــا فســوف يضربنــي‬\n\n\n                                                                                            ‫‪320‬‬\n\f      ‫هكــذا أجــاب وبســؤال املدعــي العــام عــن ســوابق املدعــى عليهمــا قــال‬\n      ‫ال يظهــر مــن املعاملــة والئحــة اإلدعــاء العــام وجــود ســوابق عليهمــا فبنــاء‬\n      ‫علــى ماتقــدم مــن دعــوى املدعــي العــام وإجابــة املدعــى عليهمــا‬\n      ‫ا وملــا قدمــه‬  ‫بإنكارهمــا بصحــة ماجــاء يف الدعــوى جملــة وتفصي ـ ً‬\n      ‫املدعــي العــام مــن أدلــة وقرائــن ضــد املدعــى عليهمــا ومنهــا اعتــراف‬\n      ‫املدعــى عليهمــا املصــدق شــرع ًا بســرقة منــزل الدكتــور املقيــم وســرقة‬\n      ‫جــوال ‪ ....‬ومبلــغ خمســمائة ريــال وإلعتــراف املدعــى عليــه ‪..‬حتقيقـ ًا بــأن‬\n      ‫‪ ...‬أخبــره ببيــع كاميــرات ومصادقــة ‪..‬علــى ذلــك وملــا جــاء يف محضــر‬\n      ‫االنتقــال واملعاينــة وأقــوال عامــل املغســلة وأقــوال احلــدث ‪..‬أن ‪ .......‬مــن أن‬\n      ‫‪ ...‬طلــب منــه الذهــاب معــه لســرقة مغســلة املالبــس وملــا تضمنــه تقريــر‬\n      ‫البحــث والتحــري وتناقــض أقــوال احلدثــن وماجــاء يف محضــر الداللــة‬\n      ‫والتمثيــل مــن قيــام املدعــى عليهمــا بتمثيــل الســرقة ممــا يجعــل الشــبهة‬\n      ‫متوجــه يف حــق املدعــى عليهمــا بالقيــام بالســرقة املذكــوره يف دعــوى‬\n      ‫املدعــي العــام ونظــر ًا لرجــوع املدعــى عليهمــا عــن االعتــراف بالســرقة‬\n      ‫وهــذا االعتــراف يف حقهمــا شــبهة يــدرء بــه احلــد عنهمــا لقــول النبــي‬\n      ‫صلــى اهلل عليــه وســلم(ادرؤ احلــدود بالشــبهات مــا اســتطعتم ) ونظــر ًا‬\n      ‫النتشــار الســرقة يف هــذا الزمــان واملــكان وهــي مــن الكبائــر احملرمــة‬\n      ‫يف الشــريعة األســامية إذ فيهــا اإلعتــداء علــى حرمــة املــال وهــي ممــا‬\n      ‫جــاء الديــن بحفظهــا وصيانتهــا وملــا تقــدم ذكــره فقــد حكمنــا مبــا يلــي‬\n      ‫اوالً‪ :‬توجــه الشــبهه القويــة للمدعــى عليهمــا بقيامهمــا مبــا نســب إليهمــا‬\n      ‫يف الدعــوى ثانيـاً‪:‬درء حــد الســرقة عــن املدعــى عليهمــا ثالثاً‪:‬ســجن كل‬\n      ‫واحــد مــن املدعــى عليهمــا أربــع ســنوات وجلــد كل واحــد خمســن‬\n      ‫جلــده تتكررثمــان مــرات بــن كل مــرة والتــي تليهــا خمســة عشــر يومـ ًا‬\n\n\n‫‪321‬‬\n\f‫تعزيــر ُا وبإعــان احلكــم قــرر املدعــي العــام واملدعــى عليهمــا عــدم‬\n‫قناعتهــم باحلكــم مــع تقــدمي لوائــح اعتراضيــة فأفهمــوا بــأن عليهــم‬\n‫مراجعــة احملكمــة يــوم الســبت املوافــق ‪........‬ه ـ الســتالم نســخة مــن‬\n‫احلكــم لتقــدمي اعتراضهــم وأن لــكل واحــد منهمــا ثالثــن يوم ـ ًا مــن‬\n‫اســتالمه وعنــد تأخرهــم عــن ذلــك يســقط حقهــم يف اإلعتــراض وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n‫يف ‪1433/4/27‬ه ـ احلمــد هلل وحــده وبعــد فقــد جــرى رفــع احلكــم‬\n‫وصــورة ضبطــه وكافــة أوراق املعاملــة إلــى محكمــة االســتئناف‬\n‫مبنطقــة اجلــوف فعــاد احلكــم بالقــرار رقــم ‪ .......‬يف‪........‬ه ـ متضمنـ ًا أن‬\n‫احلكــم التعزيــري الصــادر بحــق املدعــى عليهمــا كثيــر لكونهمــا وقــت‬\n‫الســرقة أحــداث واليوجــد لهمــا ســوابق إلعــادة النظــر وتخفيــف العقوبــة‬\n‫وجنيــب أصحــاب الفضيلة_ســلمهم اهلل_أن قضايــا الســرقة مــن‬\n‫القضايــا التــي يعانــي منهــا أهالــي منطقــة تبــوك مــن خــال مايعــرض‬\n‫علينــا مــن قضايــا ممــا يتطلــب معــه األمــر احلــزم يف العقوبــة والصالبــة‬\n‫فيهــا كمــا إن املدعــى عليهمــا وإن كانــا وقــت اجلرميــة أحــداث إال أنهمــا‬\n‫يف ســن البلــوغ ومبــا أن أصحــاب الفضيلــة رأو باإلجمــاع التخفيــف يف‬\n‫العقوبــة فقــد رجعنــا عمــا حكمنــا بــه فيمــا يتعلق بســجن املدعى عليهما‬\n‫وحكمنــا بســجن كل واحــد منهمــا ثــاث ســنوات اعتبــار ًا مــن تاريــخ‬\n‫إيقافهــم وأمرنــا بإعــادة رفــع احلكــم حملكمــة االســتئناف مبنطقــة‬\n‫اجلــوف لتدقيقــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                 ‫وصحبه وسلم‪.‬حرر يف ‪.......‬هـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد أطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫اخلماســية األولــى يف محكمــة االســتئناف باجلــوف علــى املعاملــة الــواردة‬\n\n\n                                                                                     ‫‪322‬‬\n\f      ‫مــن فضيلــة رئيــس احملكمــة العامــة بتبــوك برقــم ……‪ ..‬وتاريــخ ‪......‬ه ـ‬\n      ‫املرفــق بهــا القــرار الصــادر مــن أصحــاب الفضيلــة الشــيخ ‪ ......‬والشــيخ‬\n      ‫‪ ..........‬والشــيخ ‪ ..........‬برقــم ‪ 33217509‬وتاريــخ ‪1433/4/27‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد كل مــن ‪ ....... ....‬و ‪ ............‬يف قضيــة‬\n      ‫ســرقة وقــد تضمــن القــرار حكــم أصحــاب الفضيلــة مبــا هــو مــدون‬\n      ‫ومفصــل فيــه وباإلطــاع علــى مــا أجــاب بــه أصحــاب الفضيلــة القضــاة‬\n      ‫وأحلقــوه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا الســابق رقــم ‪ ....‬تقــرر‬\n      ‫املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                         ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪323‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":306,"source_page_end":323,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d2ab3dfc49be8d92e91e349545faf9f7414dcc2231f4a7f104e4462a474db14e","normalized_text_hash":"fd224d64383e8a9a89ee8c83cf557082616ee1bdeab3d0eefd29b92bccc771d4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p306-33217509"},{"id":"7faca029-7bf5-5ce6-aba2-3564767942eb","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -خطف مبلغ مالي -شهادة -رفض طلب مهلة إلحضار بينة لكثرة االستمهاالت -تعزير -قرينة -شبهة -احلكم بالتعزير بالسجن واجللد والغرامة.","document_number":"33426193","case_number":"33347398","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/15","year":"1434","subject":"سرقة -خطف مبلغ مالي -شهادة -رفض طلب مهلة إلحضار بينة لكثرة االستمهاالت -تعزير -قرينة -شبهة -احلكم بالتعزير بالسجن واجللد والغرامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 33426193:‬تاريخه ‪1433/10/15:‬ه‬\n                    ‫رقم الدعوى‪33347398:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 3440457‬تاريخه‪1434/2/18 :‬ه‬\n\n\n\n‫ســرقة ‪ -‬خطــف مبلــغ مالــي ‪ -‬شــهادة ‪ -‬رفــض طلــب مهلــة إلحضــار‬\n‫بينــة لكثــرة االســتمهاالت ‪ -‬تعزيــر ‪ -‬قرينــة ‪ -‬شــبهة ‪ -‬احلكــم بالتعزيــر‬\n                                              ‫بالســجن واجللــد والغرامــة‪.‬‬\n\n\n\n\n                    ‫‪-‬قوله تعالى ( وال تعتدوا إن اهلل ال يحب املعتدين )‬\n                     ‫‪-‬قوله تعالى ( وال تأكلوا أموالكم بينكم بالباطل)‬\n‫‪-‬قولــه صلــى اهلل عليــه وســلم ( كل املســلم علــى املســلم حــرام دمــه‬\n                                                          ‫ومالــه وعرضــه )‬\n‫‪-‬قولــه صلــى اهلل عليــه وســلم (ال يحــل مــال امــرئ مســلم إال عــن طيــب‬\n                                                                ‫نفــس منــه )‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليهمــا بخطــف مبلــغ مالــي مــن أحــد‬\n‫املقيمــن‪ ،‬طلــب املدعــي العــام تعزيرهمــا ‪،‬أنكــر املدعــى عليهمــا‬\n‫مــا جــاء بدعــوى املدعــى العام‪،‬طلــب القاضــي مــن املدعــي العــام بينتــه‬\n‫علــى دعــواه عــدة مــرات ولــم يحضرهــا‪،‬مت االطــاع علــى طيــات املعاملــة‬\n‫فوجــد مــن ضمنهــا شــهادة ألحــد األشــخاص ضــد املدعــى عليهمــا تثبــت‬\n‫صحــة مــا جــاء بدعــوى املدعــى العام‪،‬حكمــت احملكمــة بتعزيــر‬\n\n                                                                                  ‫‪324‬‬\n\f      ‫املدعــى عليهمــا بالســجن واجللــد مــع تغرميهمــا مبلغـ ًا ماليـ ًا وإبعادهما عن‬\n      ‫البــاد بعــد انتهــاء محكوميتيهمــا‪ ،‬قنــع املدعــى عليهمــا باحلكــم بينمــا‬\n      ‫املدعــي العــام اعتــرض عليه‪،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ .....‬القاضــي باحملكمــة اجلزئيــة‬\n      ‫مبحافظــة جــدة حــا ًال بنــاء علــى املعاملــة الــواردة لنــا بشــرح مســاعد‬\n      ‫رئيــس احملكمــة اجلزئيــة مبحافظــة جدة واملقيــدة برقم‪...‬يف‪......‬واملتعلقة‬\n      ‫بدعــوى املدعــي العــام ضــد املدعــى عليهمــا ‪ .....‬و ‪ ....‬ومبوجبهــا ففــي‬\n      ‫هــذا اليــوم الثالثــاء املوافــق ‪ ......‬ويف متــام الســاعة الواحــدة ظهــر ًا حضــر‬\n      ‫املدعــي العــام بدائــرة التحقيــق واالدعــاء العــام ‪ ......‬املكلــف بالعمــل‬\n      ‫لــدى احملكمــة مبوجــب خطــاب رقــم ‪....‬يف ‪ .....‬وحضــر حلضــوره املدعــى‬\n      ‫عليهمــا ‪ .....‬إثيوبــي اجلنســية مبوجــب االقامــة رقــم ‪ ..... ،..........‬إثيوبــي‬\n      ‫اجلنســية مبوجــب البطاقــة البديلــة رقــم ‪......‬وقــد أذنــت للمدعــي العــام‬\n      ‫بتحريــر دعــواه فأبــرز الئحــة جــاء فيهــا وقــد انتهــى وقــد أســفر التحقيــق‬\n      ‫عــن توجيــه االتهــام إليهمــا بخطــف مبلــغ مالــي قــدره (‪ )40،200‬أربعــون‬\n      ‫ألف ـ ًا ومائتــي ريــال مــن أحــد املقيمــن أثنــاء دخولــه ملقــر عملــه ‪ ،‬وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة‪ -1-:‬مــا جــاء يف أقــوال املدعــى عليهمــا املنــوه‬\n      ‫عنهــا املدونــة صفحــة (‪ ) ....‬مبلــف إجــراءات االســتدالل املرفــق لفــة (‪)....‬‬\n      ‫وصفحــة (‪ )....‬مبلــف إجــراءات االســتدالل املرفــق لفــة (‪ -2. )..‬مــا جــاء‬\n      ‫يف محضــر القبــض املنــوه عنــه املــدون صفحــة (‪ )....‬مبلــف إجــراءات‬\n      ‫االســتدالل املرفــق لفــة (‪-3. )....‬مــا جــاء يف شــهادة الشــاهد‪،..../‬‬\n      ‫املنــوه عنهــا املدونــة صفحــة (‪ )....‬مبلــف إجــراءات االســتدالل املرفــق‬\n\n‫‪325‬‬\n\f‫لفــة (‪ -4.)....‬مــا جــاء يف محضــر عــرض املدعــى عليهمــا علــى املجنــي‬\n‫عليــه املنــوه عنــه املــدون صفحــة (‪ )...‬مبلــف إجــراءات االســتدالل املرفــق‬\n‫لفــة (‪ -5.)...‬ضبــط مبلــغ مالــي قــدره (‪ )28.904‬ريــال بحــوزة املدعــى‬\n‫عليــه الثانــي وهــو مقيــم بطريقــة غيــر نظاميــة وليــس لديــه مصــدر دخــل‬\n‫ثابــت وضبــط جهــازي جــوال بحوزتــه وثالثــة جــواالت بحــوزة املــرأة‪،..../‬‬\n‫تؤكــد صحــة مــا نســب إليهمــا‪ -6.‬إقــرار األول بشــرائه ســيارة مــن نــوع‬\n‫‪ .......‬مببلــغ (‪ )30.000‬ثالثــن ألــف ريــال وبيعهــا وإرســال قيمتهــا لبــاده‬\n‫وهــو بــدون عمــل وليــس لــه مصــدر دخــل‪ ....‬قويــة تؤكــد صحــة مــا نســب‬\n‫إليهمــا‪ -7.‬تســجيل رقــم اجلــوال اخلــاص باملدعــى عليــه األول بعقــد إيجــار‬\n‫الســيارة املســتخدمة يف إرتــكاب اجلرميــة وإنــكاره مبعرفــة رقــم الهاتــف‬\n‫املذكــور ‪ ...‬تؤكــد أنــه مــن قــام باســتئجار الســيارة واســتخدامها يف‬\n‫ارتــكاب اجلرمية‪.‬وباإلطــاع علــى احلالــة اجلنائيــة للمدعــى عليهما‪/‬لــم‬\n‫يعثــر لهمــا علــى حــاالت جنائيــة مســجلة‪.‬وحيث إن مــا أقــدم عليــه املدعــى‬\n‫عليهمــا وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا فعــل محــرم ومعاقــب‬\n‫عليــه شــرع ًا لــذا اطلــب إثبــات مــا اســند إليهمــا واحلكــم مبعاقبتهمــا‬\n‫بعقوبــة تعزيريــة رادعــه لقــاء ذلــك ‪ ((.‬علم ـ ًا أن احلــق اخلــاص مــا زال‬\n‫قائمـ ًا ))‪.‬هــذه دعــواي أطالبهمــا بهــا وأســألهما اجلــواب وبعــرض مــا جــاء‬\n‫ا إن مــاورد بدعــوى‬   ‫يف دعــوى املدعــي العــام عليهمــا أجــاب األول قائ ـ ً‬\n‫املدعــي العــام مــن حيــث خطــف مبلــغ مالــي وقــدره أربعــون ألــف ومائتــي‬\n‫ريــال مــن املدعــي فغيــر صحيــح وعلــى املدعــي العــام إثبــات صحــة مــا‬\n‫يدعيــه هكــذا أجاب‪،‬وأجــاب الثانــي قائــا‪ :‬إن مــاورد بدعــوى املدعــي‬\n‫العــام مــن حيــث اشــتراكي مــع املدعــى عليــه األول يف خطــف مبلــغ‬\n‫مالــي وقــدره أربعــون ألــف ومائتــي ريــال مــن املدعــي فغيــر صحيــح وعلــى‬\n\n\n                                                                                    ‫‪326‬‬\n\f      ‫املدعــي العــام إثبــات صحــة مــا يدعيــه هكــذا أجــاب فجــرى ســؤال‬\n      ‫املدعــي العــام هــل لديــك بينــة تشــهد طبــق دعــواك أجــاب قائــا نعــم‬\n      ‫لــدي واطلــب إمهالــي إلحضارهــا وعليــه وإلمهالــه إلحضــار بينتــه تأجلــت‬\n      ‫اجللســة إلــى يــوم األربعــاء املوافــق ‪......‬الســاعة احلاديــة عشــرة وأربعــن‬\n      ‫دقيقــة صباحــا واهلل املوفــق وصلــى اهلل علــى محمــد وعلــى الــه وصحبــه‬\n      ‫وســلم حــرر يف ‪ .....‬احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األحــد املوافــق‬\n      ‫‪ ....‬ويف متــام الســاعة الواحــدة والنصــف ظهــرا افتتحــت اجللســة وفيهــا‬\n      ‫حضــر الطرفــان فجــرى ســؤال املدعــي العــام عمــا اســتمهل مــن أجلــه‬\n      ‫فأجــاب قائــا لــم أمتكــن مــن إحضــار بينتــي وأطلــب إمهالــي مــرة أخــرى‬\n      ‫إلحضارهــا فجــرى إفهامــه برفــض طلبــه لكثــرة اســتمهاالته وجــرى‬\n      ‫االطــاع علــى األوراق فوجــد بطياتهــا شــهادة املدعــو ‪ ....‬بدفتــر التحقيــق‬\n      ‫صفحــة رقــم أثنــا عشــر لفــة رقــم ثالثــة وأربعــن هــذا نصهــا (الســاعة‬\n      ‫الثانيــة والربــع ظهــرا كنــت واقفــا عنــد البــاب اخلارجــي للشــركة‬\n      ‫التــي اعمــل بهــا ألدخــن عندمــا قــدم زميلــي ‪ ....‬وركــن ســيارته بجــراج‬\n      ‫الشــركة واجتــه إلــى صعــود املدخــل الرئيســي مــن جهــة الطريــق‬\n      ‫العــام وعنــد وصولــه إلــى الدرجــة األولــى مــن الســلم وكنــت أحييــه‬\n      ‫وإذا بشــخص طولــه حوالــي مائــة وســتون ســم ممتلــئ قليــا حنطــي‬\n      ‫اللــون لــه عيــون قريبــة مــن األســيوية يلبــس قبعــه صــوف وقميــص لــون‬\n      ‫ترابــي أو أحمــر عمــره حوالــي العشــرين تقــدم مــن خلفــه وســحب كيــس‬\n      ‫البالســتيك (النقــود) الــذي بيــده والتفــت عائــدا علــى الشــارع عندهــا‬\n      ‫ركضــت أنــا و‪ ....‬باجتاهــه ولكــن ســيارة ‪ ....‬اللــون غامــق زجــاج‬\n      ‫لــون اســود قــد خففــت ســرعتها وفتــح بابهــا اخللفــي اليمــن واســتطاع‬\n      ‫أحلرامــي ان يقفــز بالســيارة قبــل ان اســتطيع اإلمســاك بــه مبتريــن او‬\n\n\n‫‪327‬‬\n\f‫ثالثــة رقــم الســيارة‪ ....‬توقفــت و‪ ...‬عــن الركــض خلــف الســيارة حيــث‬\n‫احــد املــارة بســيارته الفــورد توقــف واقلنــا لنالحــق ســيارة الســارقني‬\n‫الحظــت بــأن الســائق لــه مالمــح أفريقيــة غامــق البشــرة وأكبــر مــن‬\n‫الــذي قــام بالســرقة انطلقنــا بســيارة فاعــل اخليــر محاولــن اللحــاق‬\n‫بهــم واســتطعنا أن نــرى الســيارة غــرب شــارع أم القــرى بإجتــاه مركــز‬\n‫حــرس احلــدود ولكننــا لــم نســتطع العثــور عليهــم وبالتالــي قــام فاعــل‬\n‫اخليــر ‪ .....‬باالتصــال بالشــرطة وإعالمهــم باألمــر وبالتالــي توقفنــا‬\n‫عــن البحــث عنــد قاعــة رهــام بشــارع األربعــن حيــث التقينــا بدوريــات‬\n‫ـاء علــى دعــوى املدعــي العــام‬\n                                ‫الشــرطة وبذلــك أشــهد انتهــى وعليــه فبنـ ً‬\n‫املرصــودة بعاليــه وإجابــة املدعــى عليهمــا وحيــث عجــز املدعــي العــام عن‬\n‫إثبــات دعــواه واســتنادا إلــى الشــهادة املرصــودة بدفتــر التحقيــق واملشــار‬\n‫إليهــا آنفــا ونظــرا إلــى محضــر القبــض ومحضــر عــرض املدعــى عليهمــا‬\n‫علــى املدعــي واملرفقــة يف طيــات املعاملــة وحيــث تعــرف املجنــي عليــه‬\n‫علــى املدعــى عليــه االول ونظــرا لوجــود مبلــغ قــدره ثمانيــة وعشــرون‬\n‫ألفــا تســعمائة وأربعــة ريــاالت بحــوزة املدعــى عليــه الثانــي وحيــث إنــه‬\n‫يقيــم يف البــاد بطريقــة غيــر نظاميــة وليــس لــه مصــدر دخــل ثابــت ممــا‬\n‫يــورث الشــبهة علــى أنــه حصــل علــى املبلــغ بطريــق غيــر مشــروع ونظــرا‬\n‫إلقــرار األول املشــار إليــه باملعاملــة مــن أنــه بــاع ســيارة مببلــغ ثالثــن‬\n‫ألــف ريــال وأرســل قيمتهــا إلــى بــاده وليــس لديــه مصــدر ثابــت للدخــل‬\n‫أو عمــل مينحــه هــذا املبلــغ وحيــث إن رقــم جــوال املدعــى عليــه األول‬\n‫مســجال يف عقــد ايجــار الســيارة املســتخدمة يف ارتــكاب اجلرميــة ونظــرا‬\n‫إلنــكاره رقــم هاتفــه ممــا يــدل علــى كذبــه ومراوغتــه وحيــث أحــل‬\n‫اهلل الطيبــات وحــرم علينــا اخلبائــث وحيــث إن يف فعــل املدعــى عليهمــا‬\n\n\n                                                                                      ‫‪328‬‬\n\f      ‫ترويــع لآلمنــن وأخــذ ألموالهــم وغصبهــا بغيــر وجــه حــق واســتنادا إلــى‬\n      ‫قولــه تعالــى (وال تعتــدوا إن اهلل ال يحــب املعتديــن) اآليــة ولقولــه تعالــى‬\n      ‫وال تأكلــوا أموالكــم بينكــم بالباطــل آاليــة وقــال النبــي صلــى اهلل‬\n      ‫عليــه وســلم (كل املســلم علــى املســلم حــرام دمــه ومالــه وعرضــه) وقــال‬\n      ‫عليــه الصــاة والســام(كل جســد نبــت مــن الســحت فالنــار أولــى بــه )‬\n      ‫ولقولــه (ال يحــل مــال امــرئ مســلم إال عــن طيــب نفــس منــه) لــذا فقــد‬\n      ‫ثبــت لــدي توجــه الشــبهة القويــة يف حــق املدعــى عليهمــا بخطــف مبلــغ‬\n      ‫قــدره أربعــون ألفــا ومئتــا ريــال مــن أحــد املقيمــن وحكمــت عليهمــا‬\n      ‫مبــا يلــي‪:‬ـ أوالً‪ :‬ســجن كل واحــد منهمــا ثــاث ســنوات تعزيــرا اعتبــار ًا‬\n      ‫مــن تاريــخ دخولــه الســجن علــى ذمــة هــذه القضيــة ثانيــا‪ :‬جلــد كل‬\n      ‫واحــد منهمــا ســبعني جلــدة تعزيــر ًا مفرقــة علــى جميــع بدنــه علنـ ًا دفعــة‬\n      ‫واحــدة مكــررة عشــر مــرات ومــا بــن كل فتــرة والتــي تليهــا مــا ال‬\n      ‫يقــل عــن عشــرة أيــام ثالثــا ‪:‬غرامــة ماليــة تعزيــر ًا قدرهــا خمســة عشــر‬\n      ‫ألــف ريــال لــكل واحــد منهمــا معاملــة لهمــا بنقيــض قصدهمــا رابعــا‪:‬‬\n      ‫إبعادهمــا عــن اململكــة اتقــاء لشــرهما عقــب تنفيــذ محكوميتهمــا‬\n      ‫وبــه حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام عــدم‬\n      ‫القناعــة باحلكــم مســتعدا بتقــدمي الئحتــه االعتراضيــة فأجبتــه لطلبــه‬\n      ‫وأفهمتــه بتعليمــات التمييــز ففهــم وقــرر املدعــى عليهمــا قناعتهمــا‬\n      ‫باحلكــم وأفهمــت املدعــي العــام بــأن عليــه إبــاغ املدعــي باحلــق اخلــاص‬\n      ‫برفــع دعــواه أمــام احملكمــة املختصــة إذا رغــب ففهــم وعليــه فقــد أمرت‬\n      ‫بتنظيــم هــذا القــرار مبوجبــه وبعثــه وصــورة ضبطــه والئحــة املدعي العام‬\n      ‫إلــى محكمــة االســتئناف لتدقيقــه حســب املتبــع واهلل املوفــق حــرر يف‬\n      ‫‪......‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n\n\n‫‪329‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‬\n‫‪ -:‬فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة املســاعد مبحافظــة جــدة برقــم ‪...‬‬\n‫وتاريــخ ‪ .....‬هـ ـ املرفــق بهــا القــرار الشــرعي رقم ‪ ....‬وتاريــخ ‪ ...‬ه ـ الصادر‬\n‫مــن فضيلــة الشــيخ ‪ ....‬القاضــي يف احملكمــة اجلزائيــة مبحافظــة جــدة‪،‬‬\n‫املتضمــن دعــوى املدعــي العــام ضــد ‪ .....‬ورفيقــه أثيوبيــن اجلنســية‬\n‫املتهمــن بقضيــة ســرقة ‪ /‬نشــل احملكــوم فيــه مبــا دون باطنــه‪ .‬وبدراســة‬\n‫احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا املوافقــة علــى‬\n‫احلكــم لقناعــة املدعــى عليهمــا ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                             ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                        ‫‪330‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":324,"source_page_end":330,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2e15b86761f148c6ce5940870336d35c4259cf7d37aebb13a1b58c344f2b5021","normalized_text_hash":"6f6662ca562ee2af436b02c1a24ecc49222c6665c24e8f03c1004c8316e9587a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p324-33426193"},{"id":"a8fd714b-9a7c-5b3a-8a65-47ec9e724e75","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -انتهاك حرمة منزل -سرقة منزل اجلار -سرقة بعض محتويات املنزل -سرقة حرز بعد هتكه -بيع مسروقات -طلب إقامة حد السرقة -درء حد السرقة -تعزير بالسجن واجللد -1قوله صلى اهلل عليه وسلم ( واهلل اليؤمن واهلل ال يؤمن قيل من يارسول اهلل قال الذي ال يأمن جاره بوائقه).","document_number":"33323065","case_number":"33367340","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باخلبر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/07/01","year":"1434","subject":"سرقة -انتهاك حرمة منزل -سرقة منزل اجلار -سرقة بعض محتويات املنزل -سرقة حرز بعد هتكه -بيع مسروقات -طلب إقامة حد السرقة -درء حد السرقة -تعزير بالسجن واجللد -1قوله صلى اهلل عليه وسلم ( واهلل اليؤمن واهلل ال يؤمن قيل من يارسول اهلل قال الذي ال يأمن جاره بوائقه).","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33323065 :‬تاريخه ‪1433/07/01 :‬هـ‬\n                           ‫رقم القضية ‪33367340:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                   ‫‪ 34176303‬تاريخه ‪1434/4/1:‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬انتهــاك حرمــة منــزل‪ -‬ســرقة منــزل اجلــار ‪ -‬ســرقة بعــض‬\n      ‫محتويــات املنــزل ‪ -‬ســرقة حــرز بعــد هتكــه‪ -‬بيــع مســروقات‪ -‬طلــب‬\n         ‫إقامــة حــد الســرقة‪ -‬درء حــد الســرقة‪ -‬تعزيــر بالســجن واجللــد‬\n\n\n\n\n      ‫‪-1‬قولــه صلــى اهلل عليــه وســلم ( واهلل اليؤمــن واهلل ال يؤمــن قيــل مــن‬\n                                ‫يارســول اهلل قــال الــذي ال يأمــن جــاره بوائقــه)‪.‬‬\n      ‫‪-2‬قولــه صلــى اهلل عليــه وســلم (ال يدخــل اجلنةمــن ال يأمــن جــاره‬\n                                                                           ‫بوائقــه )‪.‬‬\n            ‫‪-3‬قال ابن قدامه ( احلرز ماعد حرزا يف العرف )املغني ‪.12/427‬‬\n      ‫‪-4‬قــال القــرايف يف الذخيــرة ( ضابــط احلــرز مــا اليعــد الواضــع فيــه‬\n                                                                ‫مفرطــا ) ‪.12/166‬‬\n\n\n\n\n      ‫دعــوى املدعــي العــام ضــد املدعــى عليــه بانتهــاك حرمــة منــزل جــاره‬\n      ‫وســرقة مصوغــات ذهبيــة وجهــاز حاســب آلــي محمــول وأجهــزة هواتــف‬\n      ‫محمولــة‪ ،‬وســرقة حــرز بعــد هتكــه وبيعــه واالســتيالء علــى ثمنــه‪،‬‬\n      ‫وطلــب إقامــة حــد الســرقة‪،‬مت القبــض علــى املدعــى عليــه بعــد بــاغ‬\n      ‫مفــاده تعــرض أحــد املنــازل للســرقة وأن املبلــغ يتهــم جــاره وبعــد البحــث‬\n\n‫‪331‬‬\n\f‫والتحــري قبــض علــى املتهــم وأقــر بالســرقة املنســوبة إليــه‪ ،‬أقــر املدعــى‬\n‫عليــه بالدعــوى وقــرر أن املنــزل لــم يكــن بــه أحــد وكانــت إحــدى‬\n‫النوافــذ مفتــوح شــباكها مــن الداخــل والشــبك احلديــدي املركــب مــن‬\n‫اخلــارج غيــر مثبــت مبســامير مــن األســفل ومثبــت مــن األعلــى‪ ،‬وقــد‬\n‫تنــازل املدعــي اخلــاص عــن حقــه‪ ،‬تقريــر ناظــري القضيــة عــدم توفــر‬\n‫كامــل شــروط الســرقة إذ اختــل فيهــا شــرط احلــرز حيــث إن صاحــب‬\n‫احلــق اخلــاص قــد حصــل منــه نــوع تفريــط يف حفــظ مالــه إذ لــم يحصــن‬\n‫بيتــه جيــداً‪ ،‬درء حــد الســرقة عــن املدعــى عليــه‪ ،‬وتعزيــر املدعــى عليــه‬\n       ‫بالســجن واجللــد‪،‬مت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده أمــا بعــد فلدينــا كال مــن ‪ ......‬و ‪ .......‬و‪ ........‬القائــم‬\n‫بعمــل املكتــب التاســع مبوجــب التكليــف رقــم ‪ 331021193‬فـ ـ ــي‬\n‫‪1433/06/1‬ه ـ القضــاة يف احملكمــة العامــة باخلبــر‪ ،‬وبنــاء علــى‬\n‫املعاملــة احملالــة للمكتــب الرابــع مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫يف اخلبر‪/‬املســاعد برقــم ‪ 33367340‬وتاريــخ ‪ 1433/05/29‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331009441‬وتاريــخ ‪ 1433/05/29‬ه ـ ففــي يــوم‬\n‫االثنــن املوافــق‪ 1433/06/16‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ ......‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ،......‬وادعــى علــى احلاضــر معــه ‪ .......‬ســعودي مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ، .......‬قائــا يف دعــواه عليــه ‪ :‬إنــه باالطــاع علــى‬\n‫محضــر البــاغ املعــد مــن قبــل رجــال الضبــط اجلنائــي تبــن أنــه يف يــوم‬\n‫اخلميــس املوافــق ‪1433/1/13‬ه ـ تقــدم املواطــن‪ ...... /‬ببــاغ يفيــد فيــه‬\n\n                                                                                       ‫‪332‬‬\n\f      ‫عــن تعــرض شــقته للســرقة فســرق منهــا شــنطة حتتــوي علــى مصوغــات‬\n      ‫ذهبيــة وجهــاز حاســب آلــي وأجهــزة هواتــف محمولــة ويشــك يف جــاره‬\n      ‫املجــاور لــه يف الســكن وباالطــاع علــى محضــر بحــث وحتــري وقبــض‬\n      ‫املعــد مــن قبــل رجــال الضبــط اجلنائــي تبــن أنــه يف يــوم اخلميــس املوافــق‬\n      ‫‪1433/3/1‬ه ـ وبالتنســيق مــع املبلــغ هاتفيــا الــذي أفــاد أن مــن ضمــن‬\n      ‫املســروقات جهــاز‪ ......‬يحمــل الرقــم التسلســلي (‪ )............‬ومبخاطبــة‬\n      ‫مــزودي اخلدمــة لإلفــادة عمــا إذا اســتخدمت أي شــريحة علــى هــذا‬\n      ‫اجلهــاز وأفــادت الشــركة أن الشــريحة رقـ ـ ـ ــم (‪ )............‬اســتخدمت‬\n      ‫علــى اجلهــاز املســروق وتبــن أن مســتخدم اجلهــاز امــرأة وأفــادت أنهــا‬\n      ‫اشــترت اجلهــاز مــن محــل (‪ ....‬للجــواالت) وبالتواصــل مــع صاحــب احملــل‬\n      ‫املواطــن (‪ .....‬وأفــاد أن اجلهــاز اشــتراه مــن شــخص يســتقل ســيارة نــوع‬\n      ‫‪ ......‬وذكــر أوصافــه التــي تنطبــق علــى املتهــم املذكــور‪ ،‬وبالبحــث‬\n      ‫والتحــري عــن املتهــم املذكــور تبــن قيامــه ببيــع اجلهــاز املســروق مــن‬\n      ‫منــزل املبلــغ بتاريــخ ‪1433/2/27‬ه ـ علــى محــل (‪ .....‬للجــواالت) ‪،‬‬\n      ‫وقيامــه ببيــع تعاليــق وسالســل وخــامت ذهــب علــى محــل ‪ .......‬للذهــب‬\n      ‫واملجوهــرات بالثقبــة بتاريــخ ‪1433/1/11‬ه ـ بقيمــة خمســة آالف‬\n      ‫وخمســمائة ريــال ‪ ،‬وبعــرض صــورة املتهــم املذكــور علــى املقيــم‪..... /‬‬\n      ‫صاحــب محــل اجلــواالت تعــرف عليــه ‪ ،‬وباســتدعاء املتهــم املذكــور‬\n      ‫ومناقشــته شــفهيا عــن اجلــوال أقــر بأنــه وجــده مرميــا يف العمــارة التــي‬\n      ‫يســكن بهــا وتصــرف ببيعــه ‪ ،‬وأثبــت محضــر انتقــال واملعـ ـ ـ ـ ـ ـ ـ ــاينة أنــه‬\n      ‫مبعاينــة الشــقة تبــن أنهــا بالــدور األرضــي مواجهــة للشــارع وبدخــول‬\n      ‫غرفــة النــوم التــي ســرق منهــا الذهــب وجهــاز حاســب آلــي محمــول‬\n      ‫وجــدت الغرفــة مبعثــرة وشــوهد مجلــس النســاء أن بــه شــباك حرامــي‬\n\n\n‫‪333‬‬\n\f‫ولوحــظ أن البلــوط قــد ف ـ ـ ـ ـ ـ ــك ورفــع الشــباك ومنهــا دخــول اجلانــي إلــى‬\n‫الشــقة ‪،‬واثبــت محضــر العــرض بأنــه بعــرض صــور املتهــم امل ـ ـ ــذكور‬\n‫علــى املقيــم‪ ..... /‬صاحــب محــل اجلــواالت تعــرف علــى صورتــه وأفــاد أن‬\n‫املتهــم املذكــور قــام ببيعــه جهــاز هاتــف جــوال نــوع بــاك بيــري موديــل‬\n‫(‪ )............‬ي ـ ـ ـ ــوم الس ـ ـ ـ ــبت بتاريخ ‪1433/2/27‬هـ ‪ .‬وأثبـ ـ ـ ــتت ف ـ ـ ـ ـ ــاتورة‬\n‫شراء الصادرة من محل ‪ .....‬للذهب واملجوهرات بتاريخ ‪1433/1/11‬هـ‬\n‫قيــام املتهــم املذكــور ببيــع تعاليــق وسالســل وخــامت ذهــب وزنهــا (‪)32,7‬‬\n‫جــرام عيــار (‪ )21‬مببلــغ قــدره خمســة آالف وخمســمائة ريــال ‪،‬‬\n‫وباســتجواب املتهــم ( ‪ )......‬أفــاد أنــه قــام بدخــول منــزل جــاره عــن طريــق‬\n‫خلــع مســامير شــباك أحـ ـ ـ ـ ـ ـ ـ ــد النوافــذ ملنزلــه والدخول منهــا إلى املنزل‬\n‫وســرقة عشــر قطــع مــن الذهــب وجهازيــن هاتفــن محمولــن نــوع نوكيا‬\n‫واألخــر أيبــاد وجهــاز حاســب آلــي محمــول ثــم اجتــه لســوق الذهــب وبــاع‬\n‫الذهــب املســروق علــى دفعتــن بقيمــة أربعــة آالف ريــال ويف يــوم الســبت‬\n‫املوافــق ‪1433/2/27‬ه ـ قــام ببيــع جهــاز هاتــف جــوال ن ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ــوع بــاك‬\n‫بيــري وبقيــة املســروقات ال يع ـ ـ ـ ـ ـ ـ ـ ــرف عنهــا فقــد أخ ـ ـ ـ ــذت مــن‬\n‫السيـ ـ ـ ـ ـ ـ ــارة أثنــاء نزولــه مل ـ ـ ـ ـ ـ ــحل الذهــب ونفــى مــا س ـ ـ ـ ـ ــوى ذلك‪ ،‬وبناء‬\n‫ع ـ ـ ـ ــلى مــا ذكــر أقــرر اتهــام املواطــن ‪ ...... /‬بانتهــاك حرمــة منــزل‬\n‫املدعــي وســرقة مصوغــات ذهبيــه وجهــاز حاســب آلــي محمــول وأجهــزه‬\n‫هواتــف محمولــة منــه حــرز بعــد هتكــه ‪ ,‬وبيعهــا واالســتيالء علــى ثمنهــا‬\n‫وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬اعترافــه املنــوه عنــه املــدون علــى‬\n‫الصفحات رقم (‪ )15 - 9‬مبلف التحقيق‪ -2 .‬محضر البحث والتحري‬\n‫والقبــض املنــوه عنــه املــدون علــى اللفتــن رقــم (‪ -3، )12,12‬محضــر‬\n‫االنتقــال واملعاينــة املنــوه عنــه املــدون علــى الصفحتــن رقــم (‪ )3,2‬مــن‬\n\n\n                                                                                                        ‫‪334‬‬\n\f      ‫ملــف التحقيــق رقــم (‪ )1‬لفــه رقــم (‪ -4 ،)1‬محضــر العــرض املنــوه عنــه‬\n      ‫املــدون علــى اللفــة رقــم (‪ -5، )11‬فاتــورة الشــراء املنــوه عنهــا املرفقــة‬\n      ‫علــى اللفــة رقــم ( ‪ ، )10‬وبالبحــث عمــا إذا كان لــه ســوابق عثــر لــه‬\n      ‫علــى ســابقتني األولــى شــرب مســكر ومخــدرات وقيــادة ســيارة وهــو‬\n      ‫بحالــة ســكر و الثانيــة تكســير زجــاج ســيارة وســرقة وحيــث أن مــا‬\n      ‫أقــدم عليــه املذكــور ـ وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ـ فعــل محــرم‬\n      ‫ومعاقــب عليــه شــرع ًا ممــا يتعــن معــه إحالتــه للمحكمــة العامــة باخلبــر‬\n      ‫اســتناد ًا للمادتــن ( ‪ )126‬و ( ‪ )129‬مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫إلثبــات مــا أســند إليــه واحلكــم عليــه بحــد الســرقة الــوارد يف اآليــة‬\n      ‫الكرميــة رقــم (‪ )38‬مــن ســورة املائــدة ‪ (،‬علم ـ ًا بــأن احلــق اخلــاص قــد‬\n      ‫انتهــى بالتنــازل)‪ .‬وباســتجواب املدعــى عليــة قــرر قائــا مــا ذكــره‬\n      ‫املدعــى العــام مــن قيامــي بالســرقة للمذكــورات فصحيــح وطريقــة‬\n      ‫الســرقة أننــي دخلــت منــزل جــاري اليــوم املذكــور وليــس فيــه أحــد‬\n      ‫وكان فيــه أحــد النوافــذ مفتــوح شــباكها مــن الداخــل وكان الشــبك‬\n      ‫احلديــدي املركــب مــن اخلــارج غيــر مثبــت مبســامير مــن األســفل وإمنــا‬\n      ‫هــو مثبــت مــن األعلــى فقــط فقمــت بخلعــه بيــدي ودخلــت وســرقت‬\n      ‫املجوهــرات مــن شــنطة كانــت علــى التســريحة وســرقت األجهــزة مــن‬\n      ‫الصالــة ثــم بعــت الذهــب وجهــاز البــاك بيــري فلمــا اشــتكاني جــاري‬\n      ‫للشــرطة ومت اســتدعائي أقــررت بالســرقة وأعـ ـ ـ ـ ـ ـ ــدت لــه املســروقات‬\n      ‫املتبقيــة وقيمــة مــا بعــت مــن الذهــب وجهــاز البــاك بيــري وتصاحلــت معــه‬\n      ‫وتنــازل عــن مطالبتــي وأنــا تائــب ونــادم علــى فعلتــي علمــا أن الســوابق‬\n      ‫التــي علــي صحيحــة فجــرى تصفــح أوراق املعاملــة ووجــد فيهــا إقــرار‬\n      ‫املدعــى عليــه يف ص‪ 15‬مــن دفتــر التحقيــق لفــة رقــم(‪ )1‬وهــذا نــص‬\n\n\n‫‪335‬‬\n\f‫احلاجــة منــه (أقــر أنــا املدعــو ‪ .....‬ســعودي اجلنســية مبوجــب ســجل مدنــي‬\n‫رقــم (‪ ).......‬أنــي قمــت بدخــول منــزل جــاري املدعــو ‪ .....‬عــن طريــق نافــذة‬\n‫املنــزل وقمــت بأخــذ مجموعــة مــن الذهــب وجوالــن األول مــن نــوع‬\n‫نوكيــا والثانــي آيبــاد وفــور انتهائــي مــن الســرقة والتــي كان مــن‬\n‫ضمنهــا جهــاز كمبيوتــر البتــوب محمــول توجهــت مــن ليلتــي إلــى محــل‬\n‫الذهــب وقمــت ببيــع الذهــب علــى دفعتــن بقيمــة أربعــة آالف ريــال‬\n‫ســعودي وقمــت أيضــا يف يــوم الســبت املاضــي املوافــق ‪1433/2/27‬ه ـ‬\n‫ببيــع جهــاز بــاك بيــري وأمــا بقيــة املســروقات وهــي كمبيوتــر محمــول‬\n‫وبعــض األغــراض ال أعرفهــا فقــد أخــذت مــن الســيارة أثنــاء نزولــي‬\n‫حملــات الذهــب وأن اعتــرايف هــذا مــن غيــر إجبــار مــن أحــد أو إكــراه‬\n‫أو ضغــوط أدليــت بــه وأنــا بكامــل قــواي الشــرعية وإرادتــي الطوعيــة)‬\n‫انتهــى نــص احلاجــة منــه فجــرى عرضــه عليــه فأجــاب قائــا مــا ورد فيــه‬\n‫صحيــح جملــة وتفصيــا كمــا جــرى االطــاع علــى تقرير األدلــة اجلنائية‬\n‫للقضيــة وقــد تضمــن أن املتهــم قــد جــرى اســتجوابه ومواجهتــه باألدلــة‬\n‫والقرائن فأقر مبا نســب إليه من تهم وأفاد بأنه بتاريخ ‪1433/1/13‬هـ‬\n‫أقــدم علــى دخــول منــزل جــاره عــن طريــق خلــع مســامير شــباك أحــد‬\n‫النوافــذ ملنــزل جــاره انتهــى مضمونــه كمــا يف اللفــة (‪ )57‬مــن املعاملــة‬\n‫فجــرى عرضــه علــى املدعــى عليــه فأجــاب قائــا مــا ورد فيــه غيــر‬\n‫صحيــح فلــم أقــم بخلــع املســامير وإمنــا هــي يف األصــل غيــر مركبــة إذ إن‬\n‫العمــارة جديــدة هكــذا أجــاب فجــرى ســؤال املدعــي العــام هــل لديــه‬\n‫بينــة علــى أن املدعــى عليــه قــد خلــع مســامير نافــذة جــاره فقــال ال بينــة‬\n‫لــدي علــى ذلــك هكــذا أجــاب ‪ ،‬وقــد جــرى ســؤال كل واحــد مــن‬\n‫الطرفــن هــل لديهمــا مــا يريــدان إضافتــه علــى مــا ســبق فقــال كل‬\n\n\n                                                                                       ‫‪336‬‬\n\f      ‫واحــد منهمــا ليــس لدينــا ســوى مــا جــرى تقدميــه يف اجللســات الســابقة‬\n      ‫فجــرى االطــاع علــى أوراق املعاملــة ولــم جنــد فيهــا بينــة للمدعــي العــام‬\n      ‫ســوى مــا تقــدم ذكــره فبنــاء علــى مــا تقــدم وبعــد ســماع الدعــوى‬\n      ‫واإلجابــة ومبــا أن املدعــي العــام قــد ادعــى بــأن املدعــى عليــه قــد ســرق‬\n      ‫مــن جــاره ذهبــا وأجهــزة جــوال وحاســب آلــي عــن طريــق دخولــه مــن‬\n      ‫إحــدى نوافــذ بيتــه بعــد فــك مســاميرها وقــد صــادق املدعــى عليــه علــى‬\n      ‫ذلــك كلــه مــا عــدا أنــه هــو الــذي فــك املســامير فدفــع بأنهــا مفكوكــة‬\n      ‫مــن األصــل وأنــه دخــل البيــت مــن طريــق النافــذة بعــد رفــع الشــبك‬\n      ‫احلديــدي ولــم يقــدم املدعــي العــام بينــة موصلــة علــى دعــواه مــن أن‬\n      ‫املدعــى عليــه هــو الــذي فــك مســامير نافــذة جــاره وأمــا مــا جــاء يف تقريــر‬\n      ‫األدلــة اجلنائيــة مــن اتهــام املدعــى عليــه بأنــه هــو الــذي فــك املســامير‬\n      ‫فإنهــم اســتنتجوه مــن إقــرار املدعــى عليــه ولــم يــرد يف اإلقــرار مــا يفيــد‬\n      ‫ذلــك ومبــا أن املدعــي العــام قــد طلــب إقامــة حــد الســرقة علــى املدعــى‬\n      ‫عليــه وحيــث لــم تتوفــر كامــل شــروط إقامــة حــد الســرقة إذ اختــل فيهــا‬\n      ‫شــرط احلــرز واحلــرز معتبــر مبــا يتعــارف النــاس عليــه قــال ابــن قدامــة‬\n      ‫رحمــه اهلل‪( :‬احلــرز مــا عــد حــرزا يف العرف)[املغنــي ‪]427/12‬وقــال‬\n      ‫القــرايف رحمــه اهلل يف الذخيــرة‪( :‬ضابــط احلــرز مــا ال يعــد الواضــع فيــه‬\n      ‫مفرطــا)[‪ ]166/12‬وصاحــب احلــق اخلــاص يف هــذه القضيــة قــد حصــل‬\n      ‫منــه نــوع تفريــط يف حفــظ مالــه إذ لــم يحصــن بيتــه جيــدا فاختــل شــرط‬\n      ‫احلــرز ومبــا أن مــا أقــدم عليــه املدعــى عليــه جــرم عظيــم وفيــه إخــال‬\n      ‫باألمــن مــع أن املدعــى عليــه رجــل أمــن وممــن أوكل إليــه حفــظ األمــن‬\n      ‫وهــذا يقتضــي تشــديد العقوبــة يف حقــه ال ســيما وأن لــه ســوابق مماثلــة‬\n      ‫إضافــة إلــى أنــه قــد حصــل منــه انتهــاك حلرمــة بيــت جــاره وقــد قــال النبي‬\n\n\n‫‪337‬‬\n\f‫صلــى اهلل عليــه وســلم‪[ :‬واهلل ال يؤمــن واهلل ال يؤمــن واهلل ال يؤمــن]‬\n‫قيــل‪ :‬مــن يــا رســول اهلل؟ قال‪[:‬الــذي ال يأمــن جــاره بوائقــه]رواه البخــاري‬\n‫وقــال‪[:‬ال يدخــل اجلنــة مــن ال يأمــن جــاره بوائقــه]رواه مســلم فنفــي اإلميــان‬\n‫ودخــول اجلنــة عمــن فعــل مثــل هــذا الفعــل يــدل علــى عظــم ذنبــه ومبــا أن‬\n‫املدعــى عليــه قــد أظهــر النــدم والتوبــة على ما بدر منه وأعاد املســروقات‬\n‫لصاحبهــا فقــد قررنــا تخفيــف العقوبــة عنــه ولــكل مــا ســبق فقــد‬\n‫حكمنــا باإلجمــاع مبــا يلــي أوال صرفنــا النظــر عــن طلــب املدعــي العــام‬\n‫إقامــة حــد الســرقة علــى املدعــى عليــه ‪ ....‬لعــدم توفــر شــروط إقامــة احلــد‬\n‫كمــا ذكــر بعاليــه ثانيــا‪ :‬قررنــا تعزيــر املدعــى عليــه بســجنه ملــدة ثالث‬\n‫ســنوات حتتســب منهــا مــدة توقيفــه الســابقة علــى ذمــة هــذه القضيــة‬\n‫وجلــده ثالثمائــة جلــدة علــى دفعــات كل دفعــة خمســون جلــدة وبني كل‬\n‫دفعــة والتــي تليهــا خمســة عشــر يومــا وبــه حكمنــا وبعرضــه علــى‬\n‫الطرفــن قــرر كل واحــد منهمــا اعتراضــه علــى احلكــم وطلبــا رفعــه‬\n‫إلــى محكمــة االســتئناف بالئحــة اعتراضية فأفهمــا مبقتضى تعليمات‬\n‫االســتئناف وبــاهلل التوفيــق حــرر يف ‪1433/7/1‬ه ـ وصلــى اهلل علــى‬\n                                         ‫نبينا محمد وعلى آله وصحبه وسلم‪.‬‬\n‫احلمــد هلل وحــده أمــا بعــد ففــي يــوم األحــد املوافــق‪1434/01/18‬‬\n‫ه ـ افتتحــت اجللســة الســاعة التاســعة والربــع وقــد عــادت املعاملــة مــن‬\n‫محكمــة االســتئناف باملنطقــة الشــرقية مبوجــب خطــاب رئيســها رقــم‬\n‫‪ 331726723‬يف ‪1434/1/10‬ه ـ واملرفــق بــه قــرار الدائــرة اجلزائيــة‬\n‫اخلماســية األولــى رقــم ‪ 33480389‬يف ‪1433/12/27‬ه ـ ونــص احلاجــة‬\n‫منــه (وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة لوحــظ أنــه لــم يتــم إرفــاق الالئحــة االعتراضيــة للمدعــي‬\n\n\n                                                                                        ‫‪338‬‬\n\f      ‫العــام وال بــد مــن ذلــك فعلــى أصحــاب الفضيلــة مالحظــة مــا ذكــر‬\n      ‫وإكمــال مــا يلــزم ومــن ثــم إعــادة املعاملــة إلكمــال الزمهــا) انتهــى عليــه‬\n      ‫فنقــول جوابــا علــى ذلــك إن املدعــي العــام قــد اســتلم نســخة احلكــم‬\n      ‫يف‪1433/7/1‬ه ـ ومضــت املــدة ولــم يقــدم الئحتــه االعتراضيــة فلــذا‬\n      ‫ســقط حقــه يف االعتــراض وقــد ســقطت اإلشــارة إلــى ذلــك يف الضبــط‬\n      ‫يف وقتــه ســهوا علمــا أن فضيلــة املشــارك الثالــث الشــيخ ‪ ....‬قــد انتقــل‬\n      ‫إلــى محكمــة االســتئناف يف اجلــوف وأمرنــا بالتهميــش بذلــك علــى‬\n      ‫القــرار ثــم إعــادة كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق‬\n      ‫احلكــم بعــد اإلجــراء األخيــر وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/18‬ه ـ املتضمــن‬\n      ‫املصادقــة علــى احلكــم بعــد اإليضــاح األخيــر قاضــي اســتئناف د ‪......‬‬\n      ‫قاضــي اســتئناف ‪ ......‬قاضــي اســتئناف ‪ .......‬رئيــس اســتئناف ‪.........‬‬\n      ‫رئيــس الدائــرة ‪)........‬وحــرر لئــا يخفــى يف ‪1434/4/15‬ه ـ وصلــى اهلل‬\n                                                             ‫وســلم علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n      ‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة اخلبــر‬\n      ‫املســاعد برقــم ‪ 34/117393‬وتاريــخ ‪1434/1/24‬ه ـ واملقيــدة لــدى‬\n      ‫احملكمــة برقــم ‪/34/285161‬خ‪ 1‬وتاريــخ ‪1434/2/4‬ه ـ املرفــق بهــا‬\n      ‫القــرار الشــرعي ذو الرقــم ‪ 33323065‬والتاريــخ ‪1433/7/1‬ه ـ الصــادر‬\n      ‫مــن أصحــاب الفضيلــة القضــاة باحملكمــة الشــيخ‪ ......./‬والشــيخ‪......./‬‬\n      ‫والشــيخ‪ ......./‬اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد‪ ....../‬يف قضيــة‬\n      ‫ســرقة وقــد تضمــن القــرار حكــم أصحــاب الفضيلــة مبــا هــو مــدون‬\n\n\n‫‪339‬‬\n\f‫ومفصــل فيــه ‪ .‬وحيــث ســبق دراســة القــرار وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه أصحــاب‬\n‫الفضيلــة علــى قرارنــا رقــم ‪ 33480389‬وتاريــخ ‪1433/12/27‬ه ـ قررنــا‬\n‫املصادقــة علــى احلكــم بعــد اإليضــاح األخيــر‪ .‬واهلل املوفــق وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪ 1434/4/1‬هـ ـ ـ ـ ‪.‬‬\n\n\n\n\n                                                                                ‫‪340‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":331,"source_page_end":340,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c504a3eaa84da0f613a1ed0899e081f4329788909414bdd8adf0cedb8de08260","normalized_text_hash":"46a9699979cc5832a1b6d075c5658547a4bd653db80a1da0954ae0dbdffe4cc1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p331-33323065"},{"id":"6631547c-6c1d-5ca0-9500-1e03c31c862d","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -حدث -سرقة بعض محتويات سيارة -كسر زجاج سيارة- اشتراك يف سرقة -تخطيط للسرقة -انطباق بصمات -مطالبة بحد السرقة -اعتراف مصدق شرع ا -إنكار الدعوى -درء حد السرقة -رد دعوى -تعزير بالسجن واجللد.","document_number":"33388499","case_number":"33417918","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/21","year":"1434","subject":"سرقة -حدث -سرقة بعض محتويات سيارة -كسر زجاج سيارة- اشتراك يف سرقة -تخطيط للسرقة -انطباق بصمات -مطالبة بحد السرقة -اعتراف مصدق شرع ا -إنكار الدعوى -درء حد السرقة -رد دعوى -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"         ‫رقم الصك‪ 33388499:‬تاريخه ‪1433/8/21:‬هـ‬\n                          ‫رقم الدعوى ‪33417918:‬‬\n             ‫رقم قرار التصديق من محكمة االستئناف‬\n                    ‫‪ 3416470:‬تاريخه ‪1434/1/19:‬ه‬\n\n\n\n      ‫ســرقة‪ -‬حــدث‪ -‬ســرقة بعــض محتويــات ســيارة ‪ -‬كســر زجــاج ســيارة‪-‬‬\n      ‫اشــتراك يف ســرقة‪ -‬تخطيــط للســرقة ‪ -‬انطبــاق بصمــات‪ -‬مطالبــة‬\n      ‫بحــد الســرقة‪ -‬اعتــراف مصــدق شــرع ًا‪ -‬إنــكار الدعــوى ‪ -‬درء حــد‬\n                            ‫الســرقة‪ -‬رد دعــوى ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫قولــه صلــى اهلل عليــه وســلم ( إن دمائكــم وأموالكــم وأعراضكــم عليكــم‬\n                                                                         ‫حــرام )‪.‬‬\n\n\n\n\n      ‫دعــوى املدعــي العــام ضــد ثالثــة أشــخاص أحدهمــا عمــره ‪ 18‬عامــا‬\n      ‫والثانــي حــدث عمــره ‪ 17‬عامــا والثالــث حــدث عمــره ‪ 11‬عامــا إذ‬\n      ‫تشــاركوا يف التخطيــط وتكســير عــدد مــن الســيارات وســرقة مــا‬\n      ‫بداخلهــا مــن مبالــغ ماليــة وعينيــة وطلــب املدعــى العام إقامة حد الســرقة‬\n      ‫علــى املدعــى عليهمــا البالغــن وتعزيــر الثالــث بعقوبــة تناســب عمــره‬\n      ‫وإلــزام املدعــى عليــه الثانــي بإعــادة املبالــغ التــي ال يعلــم أصحابهــا إلــى‬\n      ‫بيــت املــال‪ ،‬مت القبــض علــى املدعــى عليهــم بعــد ورود بالغــات بســرقة‬\n      ‫عــدد مــن الســيارات وســرقة مــا بداخلهــا وبعــد البحــث والتحــري قبــض‬\n      ‫علــى املدعــى عليهــم وقــد اعتــرف أحــد املدعــى عليهــم حتقيق ـ ًا كمــا‬\n\n‫‪341‬‬\n\f‫انطبقــت بصمــات املدعــى عليهــم علــى بعــض البصمــات املرفوعــة مــن‬\n‫محــل اجلرميــة‪ ،‬أنكــر املدعــى عليهــم للدعــوى‪ ،‬وجــد اعتــراف للمدعــى‬\n‫عليــه الثانــي مصــدق شــرعاً‪ ،‬وجــود تقاريــر فنيــة ملضاهــاة بصمــات‬\n‫مرفوعــة مــن مســرح اجلرميــة لعــدد مــن الســرقات املثبتــة‪ ،‬انطبقــت‬\n‫بصمــات األول والثانــي‪ ،‬وجــدت شــهادات مدونــة يف ضبــط القضيــة‪،‬مت‬\n‫درء حــد الســرقة عنهما‪،‬حكمــت احملكمــة بتعزيــر املدعــى عليهمــا‬\n‫األول والثانــي بالســجن واجللــد‪ ،‬رد دعــوى املدعــي العــام بخصــوص‬\n          ‫احلــدث الثالــث‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلدينــا نحــن ‪ .....‬و ‪ ....‬و ‪ ......‬القضــاة باحملكمــة‬\n‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33417918‬وتاريــخ‬\n‫‪1433/6/22‬ه ـ واملقيــدة باحملكمــة برقــم ‪ 331169581‬وتاريــخ‬\n‫‪1433/6/22‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1433/07/23‬ه ـ أفتحــت‬\n‫اجللســة الســاعة ‪ 11 : 01‬وفيهــا حضــر املدعــي العــام ‪ ......‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬وادعــى قائــا بصفتــي مدعي ًا‬\n‫عامـ ًا بدائــرة االدعــاء العــام مبكــة املكرمــة ادعــي على كل مــن (‪)......‬‬\n‫البالــغ مــن العمر‪18‬عامــا بوركينــا فاســو اجلنســية مبوجــب إقامــة‬\n‫نظاميــة رقــم (‪ )....‬موقــوف بالســجن العــام مبكــة املكرمــة واحلــدث‬\n‫‪ .........‬البالــغ مــن العمر‪17‬عامــا مالــي اجلنســية مبوجــب رخصــة إقامــة‬\n‫والــده رقــم (‪ ).....‬موقــوف منــذ ‪1433/2/5‬هـ بــدار املالحظة االجتماعية‬\n‫بجــدة والغــام ‪ .......‬البالــغ مــن العمــر ‪11‬عامــا مالــي اجلنســية مبوجــب‬\n\n                                                                                     ‫‪342‬‬\n\f      ‫بطاقــة بديلــة رقــم‪ 2019‬بتاريــخ‪1433/1/ 19‬ه ـ موقــوف منــذ‬\n      ‫‪1433/2/5‬ه ـ بــدار املالحظــة ب‪ ....‬بأمــر قاضــي األحــداث حيث بتاريخ‬\n      ‫‪ 1431/9/19‬تبلــغ مركــز شــرطة ‪ ......‬عــن ســرقة ســيارة نــوع ‪ ....‬حتمــل‬\n      ‫اللوحــة ذات احلــروف واألرقــام (‪ ).... ...‬بعــد أن كســر اجلانــي زجــاج بــاب‬\n      ‫مســاعد الســائق وبتاريــخ ‪1431/10/29‬ه ـ تبلــغ مركــز شــرطة ‪ ...‬عــن‬\n      ‫ســرقة ســيارة نــوع ‪ .....‬حتمــل اللوحــة ذات احلــروف واألرقــام (‪).... ...‬‬\n      ‫وســرق منهــا جــوال أبــو كشــاف وثــاث بطائــق صــراف وبطاقــة أحــوال‬\n      ‫ورخصــة قيــادة وبتاريــخ ‪1432/4/17‬ه ـ ابلــغ ‪ ....../‬مركــز شــرطة ‪.....‬‬\n      ‫عــن تعــرض ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة ذات احلــروف واألرقــام (‪...‬‬\n      ‫‪ )....‬لكســر الزجــاج وكذلــك تبلــغ املركــز ذاتــه مــن‪ ....../‬عــن تعــرض‬\n      ‫ســيارته مــن نــوع ‪ .......‬حتمــل ذات الرقــم (‪ )....‬وقبــض علــى املدعــى عليــه‬\n      ‫الثانــي ‪ ....../‬داخــل الســيارة يفتــش بهــا وبتاريــخ ‪1432/11/8‬ه ـ ابلــغ‪/‬‬\n      ‫‪ ......‬مركــز شــرطة ‪......‬عــن تعــرض ســيارته مــن نــوع ‪ ......‬حتمــل اللوحــة‬\n      ‫ذات األرقــام واحلــروف (‪ ).... ...‬لكســر زجــاج الســائق وســرقة جهــاز أي‬\n      ‫بــاد وثالثمائــة ريــاال وبتاريــخ ‪1432/11/12‬ه ـ ‪ ،‬ابلــغ ‪ ....../‬عــن تعــرض‬\n      ‫ســيارته مــن نــوع ‪ .........‬حتمــل اللوحــة ذات احلــروف واألرقــام (‪) .... ...‬‬\n      ‫لكســر يف الزجــاج اخللفــي وســرقة ثــاث مائــة ريــال وابلــغ ‪ ......‬عــن‬\n      ‫تعــرض ســيارته مــن نــوع ‪ .....‬حتمــل اللوحــة ذات احلــروف واألرقــام(‪).... ...‬‬\n      ‫لكســر زجــاج املثلــث اخللفــي األميــن وســرقة كمبيــاالت رســمية‬\n      ‫وباالنتقــال واملعاينــة بتاريــخ ‪1432/9/19‬ه ـ ملعاينــة ســيارة مــن نــوع ‪.....‬‬\n      ‫حتمــل اللوحــة ذات احلــروف واألرقــام (‪ ).... ...‬اتضــح إن الزجــاج األمامــي‬\n      ‫األميــن للســائق تعــرض للكســر وجــرى رفــع اآلثــار وبتاريــخ‬\n      ‫‪1431/10/20‬ه ـ جــرى االنتقــال ومعاينــة ســيارة مــن نــوع ‪ ....‬حتمــل‬\n\n\n‫‪343‬‬\n\f‫اللوحــة ذات احلــروف واألرقــام (‪ )...‬واتضــح إنهــا تعرضــت لكســر‬\n‫الزجــاج األميــن األمامــي للســائق وجــرى رفــع البصمــات وبتاريــخ‬\n‫‪1432/4/17‬ه ـ جــرى معاينــة ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة ذات‬\n‫احلــروف واألرقــام (‪ ).... ...‬واتضــح إنهــا تعرضــت لكســر زجــاج بــاب‬\n‫الســائق وكذلــك جــرى معاينــة ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم‬\n‫(‪ ).... ...‬واتضــح أن زجــاج البــاب اخللفــي األميــن قــد تعــرض للكســر‬\n‫وبتاريــخ ‪1432/1/28‬ه ـ جــرى االنتقــال إلــى حــي ‪ ....‬بجــوار مســجد ‪.....‬‬\n‫ومعاينــة الســيارة نــوع ‪ .....‬تابــع لشــركة الكهربــاء رقــم اللوحــة (‪).... ...‬‬\n‫وقــد وجــد الزجــاج األمامــي للســائق مكســور ووجــد يف املوقــع نفســه‬\n‫ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم(‪ ).... ...‬وقــد كســر زجــاج املثلــث‬\n‫اخللفــي األيســر وبتاريــخ ‪1432/11/8‬ه ـ جــرى معاينــة ســيارة مــن نــوع‬\n‫‪ ......‬حتمــل اللوحــة ذات احلــروف واألرقــام (‪ ).... ...‬واتضــح أن زجــاج‬\n‫الســائق تعــرض للكســر وبتاريــخ ‪1432/11/14‬ه ـ جــرى معاينــة ســيارة‬\n‫مــن نــوع ‪ .....‬حتمــل اللوحــة ذات األرقــام واحلــروف(‪ ).... ...‬واتضــح إنهــا‬\n‫تعرضــت لكســر مثلــث الزجــاج اخللفــي األميــن وبتاريــخ ‪1433/1/18‬ه ـ‬\n‫قبــض علــى املدعــى عليــه األول ‪ ...../‬واملدعــى عليــه الثالــث ‪ ....../‬مــن‬\n‫قبــل الدوريــة األمنيــة يف موقــع ســرقة مــن داخــل ســيارة ‪ ....../‬وذكــرا‬\n‫إنهمــا يعرفــان مــن ســرق وجــرى االنتقــال برفقتهمــا إلــى حــي ‪ .....‬فارشــد‬\n‫علــى املدعــى عليــه الثانــي ‪ ......./‬وقبــض عليــه وبتفتيشــه وجــد معــه‬\n‫محفظــة صغيــرة ســوداء بداخلهــا هويــة وطنيــه باســم‪ ........./‬وكــرت‬\n‫عائلتــه ورخصتــه وبطاقــة الصــراف اآللــي اخلاصــة بــه ملصــرف ‪............‬‬\n‫وبســماع أقــوال‪ ....../‬صاحــب البطاقــة التــي ضبطــت مــع الثالــث أفــاد‬\n‫بأنــه أدى صــاة الظهــر مبســجد ‪ .....‬وعنــد خروجــه مــن املســجد وجــد‬\n\n\n                                                                                       ‫‪344‬‬\n\f      ‫ثالثــة أشــخاص بجــوار ســيارته وزجــاج بــاب الســائق مكســور فقبــض‬\n      ‫علــى اثنــن منهــم وهــرب الثالــث وقــد ســرق مــن الســيارة (‪ )2000‬ريــاال‬\n      ‫وهويتــه الوطنيــة وبطاقــة الصــراف اخلاصة به ملصــرف ‪ ............‬والبطاقة‬\n      ‫اخلاصــة لعملــه وباســتجواب املدعــى عليــه الثانــي احلــدث‪ ......./‬اعتــرف‬\n      ‫بأنــه يف وقــت صــاة الظهــر كان برفقــة املدعــى عليــه األول ‪...../‬‬\n      ‫واملدعــى عليــه الثالــث ‪ ....../‬عنــد مســجد ‪ ............‬فكســر األول ‪....../‬‬\n      ‫زجــاج بــاب الســائق بحجــر وفتــح البــاب واخــذ منهــا محفظــة ســوداء‬\n      ‫بداخلهــا (‪ )2000‬ألفــي ريــال فاخــذ األلفــن وأعطــاه احملفظــة وبهــا عــدد‬\n      ‫مــن البطاقــات وكان الثالــث ‪ ..... /‬يراقــب خــروج النــاس مــن صــاة‬\n      ‫الظهــر فأعطــاه إشــارة بانتهــاء الصــاة فهــرب وحضــر صاحــب الســيارة‬\n      ‫فقبــض علــى الثالــث‪ ...../‬وعلــى األول ‪ .....‬وهــرب هــو فقبــض عليــه مــن‬\n      ‫قبــل البحــث اجلنائــي يف عصــر اليــوم نفســه وأضــاف انــه ســبق أن ســرق‬\n      ‫(‪ )250‬مائتــن وخمســن ريــاال مــن إحــدى الســيارات و(‪ )150‬مــن ســيارة‬\n      ‫أخــرى ولفــة أســاك مــن عمــارة حتــت اإلنشــاء وانــه كذلــك كســر‬\n      ‫زجــاج إحــدى الســيارات لغــرض ســرقتها وقبــض عليــه مــن قبــل صاحبهــا‬\n      ‫وســلم لــدار املالحظــة فأطلقــوا ســراحه وباســتجواب املدعــى عليــه‬\n      ‫الثالث‪ .....‬ذكر بأنه قبض عليه بجوار مســجد ‪ ......‬الن معه شــخصني‬\n      ‫كســرا زجــاج ســيارة وســرق منهــا وهمــا األول‪ ......../‬والثانــي ‪......‬‬\n      ‫وأضــاف ان الثانــي‪ .... /‬هــو مــن كســر زجــاج الســيارة بحجــر ثــم ســرق‬\n      ‫احملفظــة ومبضاهــاة بصمــات املدعــى عليهــم علــى احلــوادث اجلنائيــة‬\n      ‫املقيــدة ضــد مجهــول ثبــت انطبــاق املدعــى عليــه األول ‪ ....../‬علــى‬\n      ‫حادثتــي ســرقة مــن داخــل ســيارتني األولــى بتاريخ‪1433/1/23‬ه ـ ورد‬\n      ‫التقريــر الفنــي رقــم ‪ 23‬لعــام ‪1433‬ه ـ مثبتــا انطبــاق بصمــات األول‪.....‬‬\n\n\n‫‪345‬‬\n\f‫علــى حادثــة ســرقة ســيارة مــن نــوع ‪ .....‬لوحــة رقــم (‪ ).... ...‬والثانيــة بتاريــخ‬\n‫‪1433/1/23‬ه ـ ورد التقريــر الفنــي رقــم ‪24‬لعــام ‪1433‬ه ـ مثبتــا انطباق‬\n‫بصمــات االول ‪....../‬علــى حــادث ســرقة ســيارة مــن نــوع ‪ ....‬لوحــة رقــم (‪...‬‬\n‫‪ )....‬وثبــت انطبــاق بصمــات الثانــي ‪ .....‬علــى اربــع حــوادث ســرقة مــن‬\n‫داخــل ســيارات علــى النحــو االتــي‪ :‬االولــى بتاريــخ ‪1432/11/16‬ه ـ ورد‬\n‫التقريــر الفنــي رقــم ‪ 419‬لعــام ‪1432‬ه ـ مثبتــا انطبــاق بصمــات الثانــي‬\n‫‪ ..../‬علــى حــادث ســرقة ســيارة مــن نــوع ‪ ......‬لوحــة رقــم (‪ ).... ...‬والثانيــة‬\n‫بتاريخ‪1432/11/18‬ه ـ ورد التقريــر الفنــي رقــم (‪ )420‬لعام‪1432‬ه ـ‬\n‫مثبتــا انطبــاق بصمــات الثانــي ‪.../‬علــى ســيارة مــن نــوع ‪ ......‬لوحــة رقــم(‪...‬‬\n‫‪ )....‬والثالثــة بتاريــخ ‪1432/9/6‬ه ـ ورد التقريــر الفنــي رقم(‪)332‬لعــام‬\n‫‪1432‬ه ـ مثبتــا انطبــاق بصمــات الثانــي ‪ .../‬علــى حادثــة ســرقة مــن نــوع‬\n‫ســيارة ‪ ....‬لوحــة رقــم (‪ ).... ...‬والرابعــة بتاريــخ ‪1432/9/6‬ه ـ ورد التقرير‬\n‫الفنــي رقــم (‪ )7‬لعــام ‪1432‬ه ـ مثبتــا انطبــاق بصمــات الثانــي ‪ .../‬علــى‬\n‫حادثــة ســرقة مــن ســيارة نــوع ‪ ....‬لوحــة رقــم (‪ ).... ...‬واســفر التحقيــق عــن‬\n‫توجيــه االتهــام للمدعــى عليهــم باالشــتراك يف التخطيــط وتكســير‬\n‫عــدد مــن الســيارات وســرقة مــا بداخلهــا مــن مبالــغ ماليــة وعينيــة وذلــك‬\n‫وفقــا لقــرار االتهــام رقــم (‪ /47‬لعام‪1433‬ه ـ واملؤيــد بقــرار جلنــة ادارة‬\n‫الهيئــة رقــم(‪/944‬م) لعام‪1433‬ه ـ لألدلــة والقرائــن التاليــة‪_1 :‬ماجــاء‬\n‫باعتــراف املدعــى عليــه الثانــي املــدون صفحــة (‪)6‬لفة(‪)41‬وصفحة(‪)15‬‬\n‫لفة(‪)33‬واملــدون صفحة(‪)13‬واملصــادق شــرعا ولفة(‪)105‬ولفــة(‪)98‬‬\n‫وصفحــة (‪)16،15،14‬مــن ملــف لفــة (‪-2)42‬ماجــاء يف محضــر القبــض‬\n‫علــى املدعــى عليــه الثانــي املرفــق لفة(‪)45‬ومحضــر الدوريــة بالقبــض‬\n‫علــى االول والثالــث واملرفــق لفــه(‪ -3)44‬مــا جــاء يف محاضــر االنتقــال‬\n\n\n                                                                                            ‫‪346‬‬\n\f      ‫واملعاينــة املدونــة بدفاتــر االســتدالل املرفقــة صفحــة (‪ )2‬ملــف (‪)1‬‬\n      ‫وصفحــة (‪ )2‬ملــف (‪ )10‬وصفحــة (‪ )2‬ملــف (‪ )32‬وصفحــة (‪)56‬‬\n      ‫وصفحــة (‪ )3‬ملــف (‪ )23‬صفحــة (‪ )3‬ملــف (‪ -4 )33‬التقاريــر الفنــي‬\n      ‫ملضاهــاة البصمــات املرفوعــة مــن مســرح اجلرميــة لعــدد مــن الســرقات‬\n      ‫املثبتــة النطبــاق بصمــات االول لســرقتني لفــة (‪ )18-8‬والثانــي ألربــع‬\n      ‫ســرقات املرفقــة لفــة (‪ -5)62-75-51-49-29‬مــا جــاء يف اقوال ‪......../‬‬\n      ‫مــن قبضــه علــى املدعــى عليهمــا االول والثالــث بجــوار ســيارته املتعرضــة‬\n      ‫للســرقة املــدون صفحــه (‪ )2‬لفــه (‪ -6 )42‬محضــر القبــض لفــه (‪-7)45‬‬\n      ‫تقاريــر الدوريــات األمنيــة لفة(‪-8)72-57-44-35-28-13‬تســلم‬\n      ‫املبلــغ‪ ......./‬للمســروقات صفحــة (‪ )14‬ملــف لفــه (‪ )33‬و (‪ )13‬ملــف لفــة‬\n      ‫(‪ )42‬وبالبحــث عــن ســوابقهم لــم يعثــر لهــم عــن ســوابق مســجلة وحيــث‬\n      ‫ان مــا قــام بــه املدعــى عليهــم فعــل محــرم ومعاقــب عليــه شــرعا لــذا‬\n      ‫اطلــب اثبــات ادانتهــم مبــا اســند اليهــم واحلكــم علــى االول والثانــي بحــد‬\n      ‫الســرقة الــوارد يف اآليــة الكرميــة رقم(‪)38‬مــن ســورة املائــدة واحلكــم‬\n      ‫علــى الغــام املدعــى عليــه الثالــث بعقوبــة تعزيريــه تناســب عمــره‬\n      ‫واحلكــم علــى الثانــي بإعــادة املبالــغ التــي ســرقها وال يعلــم اصحابهــا‬\n      ‫لصالــح بيــت املــال وقدرهــا (‪ )350‬ثالثــة مائــة وخمســون ريــاال وثمــن‬\n      ‫االســاك التــي ذكــر بانــه ســرقها مــن عمــارة حتــت االنشــاء (علمــا بــان‬\n      ‫احلــق اخلــاص مــازال قائمــا هــذه دعــواي وبعــرض دعــوى املدعــي العــام‬\n      ‫علــى املدعــى عليهــم أجابــوا بقولهــم مــا ذكــره املدعــي العــام يف دعــواه‬\n      ‫غيــر صحيــح جملــه وتفصيــا ونحــن لــم نقــم بســرقة أي ســيارة مــن التــي‬\n      ‫ذكرهــا املدعــي العــام ومت القبــض علينــا بــدون أي وجــه حــق هكــذا‬\n      ‫أجابــوا وبعــرض ذلــك علــى املدعــي العــام قــال الصحيــح مــا ذكرتــه يف‬\n\n\n‫‪347‬‬\n\f‫دعــواي وبينتــي اعتــراف املدعــى عليــه الثانــي املصــدق شــرعا وجــود‬\n‫بصمــات املدعــى عليــه االول والثانــي املذكــورة يف االدلــة والقرائــن‬\n‫وبالرجــوع الــى اعتــراف املدعــى عليــه الثانــي ‪ ....‬وجــد كمــا ذكــر‬\n‫املدعــي العــام كمــا وجــدت البصمــات املذكــورة وبعــرض االعتــراف‬\n‫علــى املدعــى عليــه الثانــي قــال انــه مت ضربــي واجبــاري علــى ان اوقــع‬\n‫وانــا عمــري ثالثــة عشــر عامــا تقريبــا وليــس كمــا ذكــره املدعــي العــام‬\n‫بــان عمــري ســبعة عشــر عامــا وبســؤال املدعــي العــام هــل لديــه بينــه قــال‬\n‫نعــم وقــد احضرتهــا واطلــب ســماع مــا لديهمــا وعليــه فقــد حضــر‪....‬‬\n‫ســعودي مبوجــب ســجل مدنــي رقــم (‪ ).....‬يف‪1393/7/1‬ه ـ ‪ ......‬ســعودي‬\n‫مبوجــب ســجل مدنــي رقــم (‪ ).....‬يف ‪1422/5/17‬ه ـ وبســؤالهم عــن‬\n‫الشــهادة التــي حضــرا ألدائهــا شــهد كل واحــد منهمــا مبفــرده قائــا‬\n‫اشــهد انــه يف شــهر محــرم مــن هــذا العــام جاءنــا بــاغ عــن طريــق‬\n‫العمليــات بوجــود ســرقة ســيارة يف حــي ‪ ......‬وبالذهــاب الــى موقع احلادث‬\n‫وجــد شــخص وســيارته مكســورة احــدى الزجاجــات وال نذكــر نــوع‬\n‫الســيارة واي زجــاج مكســور وبســؤاله مــن قــام بســرقتها اشــار الــى‬\n‫شــخص وهــو املدعــى عليــه االول وقــال هــذا ايضــا ويقصــد املدعــى عليــه‬\n‫الثالــث واخبرنــا املدعــى عليهمــا ان الــذي قــام بالســرقة هــو املدعــى‬\n‫عليــه الثانــي ‪ ...‬ومت طلــب البصمــات هكــذا شــهدا وبســؤال املدعــي‬\n‫العــام هــل لديــه مزيــد بينــه قــال بينتــي مــا جــاء يف اوراق املعاملــة مــن‬\n‫االدلــة والقرائــن فجــرى الرجــوع اليهــا فوجــدت كمــا ذكــر املدعــي‬\n‫العــام فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة وحيــث أنكــر املدعــى‬\n‫عليهــم مــا جــاء يف دعــوى املدعــي العــام ولضعــف األدلــة والقرائــن‬\n‫املقدمــة مــن املدعــي العــام يف حــق املدعــى عليــه الثالــث ولصغــر ســن‬\n\n\n                                                                                      ‫‪348‬‬\n\f      ‫املدعــى عليهــم والن امــوال املســلم محترمــة لقولــه صلــى اهلل عليــه وســلم‬\n      ‫(إن دمائكــم واموالكــم واعراضكــم عليكــم حــرام ) ولتوجه التهمه‬\n      ‫يف حــق املدعــى عليــه االول والثانــي لذلــك كلــه فلــم يثبــت لدينــا مــا‬\n      ‫يوجــب اقامــة حــد الســرقة علــى املدعــى عليهــم ودرانــا عنهــم احلــد‬\n      ‫وحكمنــا بتعزيرهــم وذلــك بســجن املدعــى عليــه االول ‪ .......‬ســتة اشــهر‬\n      ‫مــن تاريــخ ايقافــه وجلــده مائــة جلــده مفرقــة علــى دفعتــن يف كل دفعــه‬\n      ‫خمســون مــرة بــن كل مــرة والتــي تليهــا عشــرة ايــام وســجن املدعــى‬\n      ‫عليــه الثانــي ثمانيــة اشــهر مــن تاريــخ ايقافــه وجلــده مائــة جلــده مفرقــه‬\n      ‫علــى مرتــن يف كل مــرة خمســون جلــده بــن كل مــرة والتــي تليهــا‬\n      ‫عشــرة ايــام وحكمنــا بــرد دعــوى املدعــي العــام فيمــا يخــص املدعــى‬\n      ‫عليــه الثالــث وبعــرض احلكــم علــى املدعــى عليهــم قــرروا القناعــة‬\n      ‫وبعــرض احلكــم علــى املدعــي العــام قرر عدم القناعة وطلب االســتئناف‬\n      ‫واجيــب لطلبــه وافهــم بتعليمــات االعتــراض وبــاهلل التوفيــق وصلــى اهلل‬\n          ‫على سيدنا محمد وعلى اله وصحبه وسلم حرر يف ‪1433/7/23‬هـ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1433/11/21‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 12.30‬وبعــد رفــع كامــل اوراق املعاملــة‬\n      ‫الــى محكمــة االســتئناف عــادت وبرفقهــا القــرار رقــم ‪33439423‬‬\n      ‫يف‪1433/10/25‬ه ـ وهــذا نصــه بعــد املقدمــة وبدراســة احلكــم وصــورة‬\n      ‫ضبطــه والئحتــه االعتراضيــة تقــرر اعادتهــا ألصحــاب الفضيلــة حــكام‬\n      ‫القضيــة ملالحظــة أن العقوبــة قليلــة ســجنا وجلــدا يف حــق املدعــى عليهــم‬\n      ‫مبــا فيهــم الثالــث ملالحظــة ذلــك ‪ .‬وبــاهلل التوفيــق قاضــي اســتئناف‬\n      ‫د‪ ......‬ختــم وتوقيــع قاضــي اســتئناف ‪ ......‬ختــم وتوقيــع قاضــي اســتئناف‬\n      ‫‪ ......‬ختــم وتوقيــع قاضــي اســتئناف ‪ ......‬ختــم وتوقيــع رئيــس اســتئناف‬\n\n\n‫‪349‬‬\n\f‫‪ .....‬ختــم وتوقيــع عليــه جنيــب اصحــاب الفضيلــة وفقنــا اهلل واياهــم ان‬\n‫املدعــي العــام لــم يقــدم ادلــه او قرائــن توجــب زيــادة يف الســجن واجللــد‬\n‫علــى مــا حكمنــا بــه وامــا املدعــى عليــه الثالــث فســبب رد الدعــوى‬\n‫هــو عــدم وجــود مــا يدينــه عليــه فلــم يظهــر لدينــا ســوى مــا حكمنــا‬\n‫بــه وامرنــا برفــع كامــل االوراق املعاملــة الــى محكمــة االســتئناف‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n‫‪ 1433/11/21‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي‬\n‫بعــده ‪ ،‬وبعــد ‪ -:‬فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلماســية‬\n‫الثانيــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة‬\n‫برقــم ‪ 33/2029196‬وتاريــخ ‪1433/12/20‬ه ـ املرفــق بهــا القــرار رقــم‬\n‫‪ 33388499‬وتاريــخ ‪1433/8/21‬ه ـ الصــادر مــن أصحــاب الفضيلــة‬\n‫القضــاة باحملكمــة العامــة مبكــة املكرمــة الشــيخ‪ ...... /‬والشــيخ‪......‬‬\n‫والشــيخ ‪ .......‬املتضمــن دعــوى املدعــي العــام ضــد‪ ...... /‬بوركينــا‬\n‫فاســو اجلنســية ورفاقه‪،‬املتهمــن يف االشــتراك يف التخطيــط وتكســير‬\n‫عــدد مــن الســيارات وســرقة مــا بداخلهــا مــن مبالــغ ماليــة ‪ ،‬احملكــوم‬\n‫فيــه مبــا دون باطنــه‪ .‬املالحــظ عليــه بقــرار محكمــة االســتئناف رقــم‬\n‫‪ 33439423‬وتاريــخ ‪1433/10/25‬ه ـ وبدراســة احلكــم وصــورة ضبطه‬\n‫والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم بعــد‬\n‫اإليضــاح األخيــر‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                          ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                    ‫‪350‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":341,"source_page_end":350,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"34414c7edf6a46fb9b96fbcae634651304a3fd67753d5e97f2df64e34a45220a","normalized_text_hash":"456218419da8fca4d33d511e5455e41d3ab1a6bf10697ed4ac8ad188e8fc9d41","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p341-33388499"},{"id":"081704cc-ead8-57d3-8e12-cb0b9744e5f2","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة منزل -سرقة مجوهرات من داخل املنزل -سرقة من حرز -مقاومة الفرقة القابضة ومحاولة الهرب منها -مطالبة بإقامة حد السرقة -احلكم بإقامة حد السرقة -الرجوع عن احلكم بإقامة حد السرقة -رجوع املدعى عليه عن االعتراف على زعم ضغط احملقق وتأثير املرض النفسي -درء حد السرقة -التعزير بالسجن واجللد.","document_number":"33476192","case_number":"33423216","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باخلرج/املساعد ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/12/22","year":"1434","subject":"سرقة -سرقة منزل -سرقة مجوهرات من داخل املنزل -سرقة من حرز -مقاومة الفرقة القابضة ومحاولة الهرب منها -مطالبة بإقامة حد السرقة -احلكم بإقامة حد السرقة -الرجوع عن احلكم بإقامة حد السرقة -رجوع املدعى عليه عن االعتراف على زعم ضغط احملقق وتأثير املرض النفسي -درء حد السرقة -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 33476192:‬تاريخه ‪1434/12/22:‬هـ‬\n                         ‫رقم الدعوى ‪33423216:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34226366‬تاريخه‪1434/5/28 :‬ه‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة منــزل ‪ -‬ســرقة مجوهــرات مــن داخــل املنــزل ‪-‬ســرقة مــن‬\n      ‫حــرز ‪ -‬مقاومــة الفرقــة القابضــة ومحاولــة الهــرب منهــا ‪ -‬مطالبــة‬\n      ‫بإقامــة حــد الســرقة ‪ -‬احلكــم بإقامــة حــد الســرقة‪ -‬الرجــوع عــن احلكم‬\n      ‫بإقامــة حــد الســرقة‪ -‬رجــوع املدعــى عليــه عــن االعتــراف علــى زعــم‬\n      ‫ضغــط احملقــق وتأثيــر املــرض النفســي ‪ -‬درء حــد الســرقة‪ -‬التعزيــر‬\n                                                             ‫بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫‪-1‬قولــه تعالــى (والســارق والســارقة فاقطعــوا أيديهمــا جــزاء مبــا‬\n                                 ‫كســبا نــكا ًال مــن اهلل واهلل عزيــز حكيــم)‪.‬‬\n                                                    ‫‪-2‬احلدود تدرأ بالشبهات‪.‬‬\n\n\n\n      ‫دعــوى املدعــي العــام ضــد املدعــى عليه بســرقة مجموعة مــن املجوهرات‬\n      ‫مــن حرزهــا بعــد دخولــه إلــى أحــد املنــازل بالقفــز ومقاومــة الفرقــة‬\n      ‫القابضــة ومحاولــة الهــرب مــن الفرقــة‪ ،‬وطلــب املدعــى العــام إقامــة حــد‬\n      ‫الســرقة وتعزيــر املدعــى عليــه لقــاء مقاومتــه الفرقــة القابضــة ومحاولتــه‬\n      ‫الهــرب منهــا‪ ،‬مت القبــض علــى املدعــى عليــه بعد بالغ مفــاده تعرض أحد‬\n      ‫املنــازل لســرقة املجوهــرات املوجــودة بداخلــه‪ ،‬وبعــد البحــث والتحــري‬\n\n\n‫‪351‬‬\n\f‫ورد بــاغ مفــاده وجــود شــخص يف أســواق يحــاول بيــع بعــض املجوهــرات‬\n‫بــدون إثبــات وبعــد وصــول الدوريــات حــاول املدعى عليه الهــرب ومقاومة‬\n‫الفرقــة القابضــة إال أن الفرقــة متكنــت مــن القبــض عليــه وباســتجوابه‬\n‫أقــر بالســرقة املنســوبة إليــه‪ ،‬أقــر املدعــى عليــه بالدعــوى ثــم رجــع عــن‬\n‫اعترافــه املصــدق شــرعاً‪ ،‬تبــن وجــود ســوابق علــى املدعــى عليــه‪ ،‬صــدر‬\n‫احلكــم مــن ناظــري القضيــة بإقامــة حــد الســرقة لوجــود املــال املســروق‬\n‫واملــال محــرز يف بيــت مغلــق واملنــزل حــرز ملــا يف داخلــه واملــال املســروق‬\n‫بالــغ النصــاب واملدعــى عليــه عاقــل مكلــف مؤاخــذ بإقــراره‪ ،‬مت تقــدمي‬\n‫الالئحــة االعتراضيــة علــى احلكــم وذكــر املدعــى عليــه يف الئحتــه أنــه‬\n‫تراجــع عــن أقوالــه‪ ،‬أفــاد املدعــى عليــه أن إقــراره صــدر باإلكــراه مــن‬\n‫احملققــن وحتــت تأثيــر املــرض النفســي‪ ،‬مت الرجــوع عــن احلكــم بإقامة‬\n‫حــد الســرقة‪ ،‬تعزيــر املدعــى عليــه بالســجن واجللــد‪ ،‬تصديــق احلكــم‬\n                                                     ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدينا نحن القضاة ‪ ........‬والقاضي ‪ .......‬والقاضي‬\n‫‪ ......‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫باخلرج‪/‬املســاعد برقــم ‪ 33423216‬وتاريــخ ‪ 1433/06/24‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331187899‬وتاريــخ ‪ 1433/06/24‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1433/07/08‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعي‬\n‫العــام ‪ .....‬وأدعــى علــى احلاضــر معــه ‪ ........‬ســعودي مبوجــب الســجل‬\n‫املدنــي رقــم (‪ ).......‬قائــا ‪ :‬فقــد تقــدم املواطــن‪ ،....../‬ببــاغ لشــرطة‬\n‫محافظــة اخلرج‪/‬مخفــر شــرطة الناصفــة ‪ ،‬مفــاده بأنــه خــرج مــن منزلــه‬\n\n                                                                                         ‫‪352‬‬\n\f      ‫الواقــع مبحافظــة اخلــرج حــي ‪ ، ......‬يــوم األربعــاء املوافــق ‪1433/1/5‬ه ـ‬\n      ‫ـاء وبعــد عودتــه ملنزلــه وجــد نافــذة (فتحــة)‬     ‫الســاعة (‪ )2‬الثانيــة مسـ ً‬\n      ‫مكيــف املطبــخ مكســورة وقــد ســرق مــن غرفــة نومــه مجوهــرات‬\n      ‫مختلفــة األنــواع تقــدر قيمتهــا ب ــ(‪ )45000‬خمســة وأربعــن ألــف ريــال‬\n      ‫وأنــه ال يتهــم أحــد ًا بعينــه‪ ،‬وباالنتقــال ملنــزل املبلــغ ودخولــه اتضــح بــأن‬\n      ‫الدخــول حصــل عــن طريــق فتحــة املكيــف بعــد أن دفــع الســارق اللــوح‬\n      ‫املغلقــة بــه‪ ،‬وأن املســروقات ُأخــذت مــن درج تســريحة غرفــة النــوم‪.‬‬\n      ‫ويف يــوم األحــد املوافــق ‪1433/2/21‬ه ـ تلقــت العمليــات بالغ ـ ًا مفــاده‬\n      ‫وجــود شــخص مبجمــع أســواق ‪ ...‬مبدينــة الريــاض وبحوزتــه كميــة مــن‬\n      ‫الذهــب يحــاول بيعهــا دون إثبــات هويــة ‪ ،‬ممــا يوحــي ذلــك بســرقتها‪،‬‬\n      ‫وبوجــود فرقتــي (‪ )19‬و(‪ )20‬األمنيــة باملوقــع التقتــا باملبلــغ املواطــن‪.....‬‬\n      ‫والــذي أفــاد بــأن املدعــى عليــه حضــر لــه وبحوزتــه كميــة مــن الذهــب‬\n      ‫حــاول بيعهــا دون إثبــات هويــة وأنــه عــرض عليــه بيــع تلــك املجوهــرات‬\n      ‫دون إثبــات مقابــل (‪ )2000‬ريــال مــن قيمتهــا وأنــه منــذ صــاة املغــرب‬\n      ‫وهــو يحــاول بيــع املجوهــرات‪ .‬وبدخــول الفرقــة للمحــل شــاهدت املدعــى‬\n      ‫عليــه وبحوزتــه ذهــب وبطلــب إثباتــه حــاول الهــرب علــى األقــدام فيمــا‬\n      ‫قــاوم الفرقــة واعتــدى عليهــا فتــم القبــض عليــه ووجــد بحوزتــه مــن‬\n      ‫املجوهــرات الذهبيــة مــا وزنــه (‪ )86‬ســتة وثمانــون جرامـ ًا تقــدر قيمتهــا‬\n      ‫بــ(‪ )22700‬اثنــن وعشــرين ألف ـ ًا وســبعمائة ريــال‪ .‬وبتفتيــش ســيارته‬\n      ‫نــوع فــورد حتمــل اللوحــة رقــم (‪ ).... ...‬وجــد بهــا (‪ )2‬ســاعتان واحــدة‬\n      ‫رجاليــة والثانيــة نســائية قيمتهمــا تقــدر (‪ )2500‬ألفــن وخمســمائة ريــال‬\n      ‫وتعليقتــن ذهبيــة وفضيــة وخرصــان مــن الفضــة ‪ ،‬وجهــاز آيبــاد ‪ ،‬وقلــم‬\n                      ‫ماركــة ‪ ،‬وثالثــة أجهــزة نقالــة ‪ ،‬وبطاقــات صــراف آلــي‪.‬‬\n\n\n‫‪353‬‬\n\f‫وبســماع أقــوال ‪ ....... :‬أفــاد بأنــه ســمع مــن أصحــاب احملــات املجــاورة‬\n‫لــه وجــود شــخص يتنقــل بينهــا طلب ـ ًا يف بيــع مــا بحوزتــه مــن ذهــب دون‬\n‫إثبــات وأنــه طلــب مــن أصحــاب احملــات يف حالــة حضــوره لهــم توجيهــه‬\n‫حمللــه لوضــع كمــن لــه فحضــر إليــه ومعــه الذهــب واألملــاس وبطلــب‬\n‫إثباتــه أفــاد بعــدم وجــوده معــه وأن مــا بحوزتــه مــن ذهــب خــاص وعائــد‬\n‫لوالدتــه‪ ،‬وأضــاف (املبلــغ ) بــأن املدعــى عليــه قــدم لــه عمولــة وذلــك‬\n‫يف حالــة عــدم طلــب إثباتــه منــه وأنــه بعــد ذلــك أبلــغ اجلهــات األمنيــة‬\n‫وبحضورهــم وطلبهــم إثباتــه حــاول الهــرب وقاومهــم ورفــض امتثــال‬\n‫أمرهــم‪ .‬وباســتجواب املدعــى عليــه أقــر بأنــه يف يــوم ‪1433/1/5‬ه ـ‬\n‫ـاء دخــل منــزل املبلــغ ‪ ..... /‬الواقــع‬ ‫الســاعة (‪ )12‬الثانيــة عشــرة مسـ ً‬\n‫مبحافظــة اخلرج‪/‬حــي الــورود مــن فتحــة مكيــف املطبــخ وأنــه اجتــه‬\n‫لغرفــة النــوم وأخــذ مــن درج تســريحتها مجموعــة مــن املجوهــرات وخــرج‬\n‫مــن حيــث دخــل وصــدق اعترافــه شــرعاً‪ .‬وبعــرض املجوهــرات املســروقة‬\n‫علــى املبلــغ وزوجتــه أفــادا بأنهــا هــي مجوهراتهمــا إال أنهمــا فقــدا منهــا‬\n‫حلــق وخــوامت بهــا فصــوص املاســية وقــد تســلم صاحبهــا مــن املدعــى‬\n‫عليــه بــد ًال عنهــا (‪ )2000‬ريــال فيمــا قــرر بأنــه لــم يبــق لــه شــيء مفقــود‬\n‫مــن مجوهراتــه‪ .‬وقــد انتهــى التحقيــق معــه إلــى توجيــه االتهــام لــه بســرقة‬\n‫مجموعــة مــن املجوهــرات مــن حرزهــا بعــد دخولــه عــن طريــق القفــز إلــى‬\n‫أحــد املنــازل ومقاومتــه للفرقــة القابضــة ومحاولتــه الهــرب مــن الفرقــة‬\n‫وفــق قــرار االتهــام رقــم (‪ )132‬لعــام ‪1433‬ه ـ املراجــع مــن جلنــة إدارة هيئة‬\n‫التحقيــق واالدعــاء العــام بقرارهــا رقــم (‪/939‬ر) لعــام ‪1433‬ه ـ وذلــك‬\n                                                         ‫لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ .1‬إقــراره املصــدق شــرع ًا املــدون علــى الصفحــة رقــم (‪ )8‬مــن دفتــر‬\n\n\n                                                                                          ‫‪354‬‬\n\f                                                                      ‫التحقيــق لفــه (‪. )9‬‬\n                          ‫‪ .2‬محضر القبض املنوه عنه املرفق على اللفة رقم (‪. )3‬‬\n      ‫‪ .3‬محضــر االنتقــال واملعاينــة مــن ‪ .......‬املنــوه عنــه املــدون علــى الصفحــة‬\n                                         ‫رقــم (‪ )3‬مــن دفتــر التحقيــق لفــه رقــم (‪. )9‬‬\n      ‫‪ .4‬شــهادة املبلــغ ‪ .....‬عنهــا املدونــة علــى الصفحــة رقــم(‪ 1‬ـ ـ ‪ )3‬مــن دفتــر‬\n                                                                   ‫التحقيــق لفــة رقــم (‪)1‬‬\n      ‫‪ .5‬محضــر تعــرف صاحــب املســروقات عليهــا واســتالمها املنــوه عنــه‬\n      ‫املــدون علــى الصفحتــن رقــم (‪ ) 11 ، 5‬مــن دفتــر التحقيــق املرفــق علــى‬\n                                                                           ‫اللفــة رقــم (‪. )9‬‬\n      ‫وبالبحــث عــن مــا إذا كان لــه ســوابق ُعثــر لــه علــى ثــاث ســوابق األولــى‬\n      ‫دخــول منــازل لغــرض ســيء والثانيــة ســرقة أمــوال مقترنــة بســرقة ذهــب‬\n                                 ‫والتهديــد وحــرق منــزل والثالثــة ســرقة مســاكن‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه‪ -‬وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا وهــو ســرقة مــال محتــرم‬\n      ‫بالــغ النصــاب مــن حــرزه بعــد هتكــه ‪ ،‬وال شــبهة لــه فيــه ‪ ،‬وطالــب بــه‬\n       ‫صاحبــه أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه مبــا يلــي‪:‬‬\n           ‫‪ .1‬بحد السرقة الوارد يف اآلية الكرمية رقم(‪ )38‬من سورة املائدة ‪.‬‬\n      ‫‪ .2‬بعقوبــة تعزيريــة زاجــرة لــه ورادعــة لغيــره لقــاء مقاومتــه للفرقــة‬\n      ‫القابضــة ومحاولتــه الهــرب منها‪(.‬علم ـ ًا بــأن احلــق اخلــاص منت ـهٍ)‪ .‬وبــاهلل‬\n      ‫التوفيــق ‪ .‬ا ‪ -‬ه ـ وبســؤال املدعــى عليــه عــن دعــوى املدعــي العــام أجــاب‬\n      ‫بقولــة ‪ :‬انــه ومــن غيــر إرادة منــي وأنــا أســير علــى أقدامــي داخــل احلــي‬\n      ‫الــذي أســكنه مــع والــدي وزوجتــي دخلــت منــزل أحــد املواطنــن يف حــي‬\n      ‫الــورود يف محافظــة اخلــرج الســاعة الثانيــة عشــر ليــا وذلــك مــن غيــر‬\n\n\n‫‪355‬‬\n\f‫غــرض ومــن غيــر قصــد أي شــيء حيــث دخلــت عمــارة حتــت االنشــاء‬\n‫مجــاورة للمنــزل وقفــزت داخــل ســور منــزل املواطــن ووجــدت فتحــة‬\n‫مكيــف شــباك مفتوحــة فوجــدت مثــل الطاولــة الصغيــرة وصعــدت‬\n‫عليهــا ثــم دخلــت مــع فتحــة املكيــف داخــل املطبــخ ثــم جتولــت داخــل‬\n‫املنــزل حتــى وجــدت غرفــة نــوم مفتوحــة البــاب ووجــدت داخــل الــدرج‬\n‫(كمدينــة ) علبــة فيهــا عــدد مــن املجوهــرات عبــارة عــن ذهــب وســاعتني‬\n‫فأخذتهــا وعــدت مــن حيــث دخلــت أي مــن خــال الفتحــة التــي دخلــت‬\n‫معهــا وأخــذت املجوهــرات معــي وقمــت بدفنهــا قــرب منــزل والــدي‬\n‫وندمــت أشــد النــدم وهممــت بإعادتهــا لصاحــب املنــزل ولكنــي متــردد‬\n‫وخائــف ثــم تركتهــا يف مكانهــا وبعــد الســرقة بأســبوعني ‪ .‬والن لــي‬\n‫موعــد يف مستشــفى ( ‪ ) .......‬لألمــراض النفســية حيــث اتصلــت بــي‬\n‫املستشــفى وأخبرونــي باملوعــد وملعرفتــي ان املستشــفى يريــد مبلغــا مــن‬\n‫املــال بحثــت عــن أبــي آلخــذ منــه املــال فلــم أجــده فأخــذت الذهــب معــي‬\n‫للريــاض فحاولــت بيعــه فتــم القبــض علــي ومــا وجــد معــي يف ســوق ‪......‬‬\n‫مــن ذهــب هــو الذهــب الــذي ســرقته مــن املنــزل يف حــي الــورود ‪ .‬ومت‬\n‫ارجاعــه ملالكــه ولــم أقــاوم الفرقــة القابضــة وال أعلــم أنهــم رجــال أمــن‬\n‫ألنهــم يلبســون الثيــاب املدنيــة وذكــرت يف بدايــة التحقيــق أن الذهــب‬\n‫لوالدتــي وبعــد أن صليــت االســتخارة وعــدت الــى رشــدي اعترفــت‬\n‫أنــي ســارق للذهــب مــن املنــزل املذكــور وأنــا مريــض نفســي واعالــج‬\n‫عــن املــرض وصحيــح أنــه يوجــد علــي ســابقة دخــول منــزل لغــرض ســيئ‬\n‫قبــل زواجــي والســابقة الثانيــة متهــم فيهــا ولــم تثبــت التهمــة ومت احلكــم‬\n‫علــي بعشــر ســنوات أمضيــت منهــا خمــس ســنني وشــملني العفــو بحفــظ‬\n‫القــرآن وبعــد تســعة أشــهر مــن خروجــي مــن الســجن وقعــت يف هــذه‬\n\n\n                                                                                     ‫‪356‬‬\n\f      ‫القضيــة وال صحــة ملــا جــاء يف ذكــر الســوابق انــي حرقــت املنــزل ‪ .‬وأنــا‬\n      ‫تائــب هلل جــل وعــا ولــن أعــود لشــيء مــن املعاصــي ‪.‬هكــذا أجــاب ‪.‬‬\n      ‫وباالطــاع علــى أوراق املعاملــة وجــد مــن بينهــا صحيفــة الســوابق املبينــة‬\n      ‫أن للمدعــى عليــه ثــاث ســوابق وهــي مطابقــة للســوابق املذكــورة يف‬\n      ‫دعــوى املدعــي العــام أعــاه ولالطــاع علــى بقيــة أوراق املعاملــة والتأمــل‬\n      ‫رفعــت اجللســة وعليــه حصــل التوقيــع ‪ .‬احلمــد هلل وحــده وبعــد ففــي هــذا‬\n      ‫اليــوم الثالثــاء املوافــق ‪1433/11/21‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n      ‫املدعــي العــام وحضــر حلضــوره املدعــى عليــه ‪ ........‬وجــرى ســؤال هــل جد‬\n      ‫عنــده جديــد قــال ال جديــد عنــدي وجــرى االطــاع علــى أوراق املعاملــة‬\n      ‫ومــن بينهــا دفتــر التحقيــق املرفــق لفــة رقــم (‪ )1‬ص ‪ 1‬املتضمــن بــاغ يف‬\n      ‫يــوم األحــد ‪1433/11/21‬ه ـ عــن شــخص يريــد بيــع كميــة مــن الذهــب‬\n      ‫يف محــات بيــع الذهــب يف أســواق طيبــة ومــن غيــر اثبــات هويــة وذكــر‬\n      ‫أن الذهــب لوالدتــه فابلــغ الدوريــات االمنيــة وأنــه بعــد حضــور الدوريــة‬\n      ‫األمنيــة وطلبهــا اثباتــه قــام بالهــرب ورفــض االنصيــاع ‪ .‬وجــاء علــى اللفــة‬\n      ‫رقــم ‪ 3‬تقريــر حــادث علــى مطبوعــات قيــادة الدوريــات األمنيــة ويتضمــن‬\n      ‫أنــه مت القبــض علــى ‪ ..........‬ومعــه اثبــات هويتــه ومعــه مجوهــرات وزن‬\n      ‫‪ 86‬جرامــا مــن الذهــب ويوجــد يف ســيارته عــدد ســاعتني املــاس ‪ ..‬الــخ‬\n      ‫‪ .‬ومــن ضمــن أوراق املعاملــة دفتــر التحقيــق لفــة رقــم ‪ 9‬جــاء علــى ص‬\n      ‫‪ 8‬ويتضمــن اعتــراف املدعــى عليــه وهــذا نصــه ( نعــم أنــا ‪ .....‬ســعودي‬\n      ‫ســجل مدنــي رقــم (‪)......‬أقــر بطوعــي واختيــاري وبــدون اكــراه مــن‬\n      ‫أحــد أقــر بانــي يف يــوم االربعــاء املوافــق ‪1433/1/5‬ه ـ وعنــد الســاعة‬\n      ‫الثانيــة عشــر ليــا قمــت بدخــول منــزل املدعــو ‪ ............‬الواقــع بحــي ‪...‬‬\n      ‫عــن طريــق دريشــة مكيــف املطبــخ واجتهــت إلــى غرفــة النــوم وقمــت‬\n\n\n‫‪357‬‬\n\f‫بأخــذ مجموعــه مجوهــرات مــن درج التســريحة وخرجــت مــن نفــس‬\n‫املــكان الــذي دخلــت معــه ولــم أخــذ شــيئا آخــر غيــر ذلــك هــذا اقــرار‬\n‫منــي وعليــه جــرى التوقيــع ‪ .‬أ ـ ه ـ ‪ .‬ومصــادق عليــه شــرعا مبــا نصــه ‪:‬‬\n‫حضــر لدينــا املذكــور أعــاه وبتــاوة اقــراره عليــه املــدون ص ‪ 8‬مــن‬\n‫هــذا امللــف صــادق عليــه حرفيــا وأقــاد أن ســبب دخولــه للمنــزل هــي حالــة‬\n‫نفســية‪ .‬ومــن ضمــن أوراق املعاملــة االفــادة الطبيــة الصــادرة مــن مكتــب‬\n‫أ ‪ .‬د ‪ ............‬الطبيــة رقــم بــدون تاريــخ ‪1433/2/25 :‬ه ـ وجــاء نصهــا‪:‬‬\n‫املذكــور أعــاه راجعنــا يف مركــز ‪ .....‬ألول مــرة بتاريــخ ‪2011/6/22‬م‬\n‫حيــث كان يعانــي مــن اضطــراب وجدانــي ( ثنائــي القطــب ) وهــذه‬\n‫احلالــة تــؤدي الــى تدهــور شــخصية الفــرد ويكــون هنــاك طــرق شــاذة‬\n‫وغريبــة يف التفكيــر والســلوك واملشــاعر وميكــن أن يــرى مــن حولــه‬\n‫بصــورة غيــر ســوية وتهيمــن عليــه أفــكار غيــر واقعيــة وتبــدو أحيانــا‬\n‫تصرفاتــه متضاربــة ومتنافــرة ورمبــا ينقطــع عــن أهلــه ومعارفــة لدرجــة‬\n‫أن يبــدو عليــه وكانــه معــزول عــن الدنيــا وكانــت آخــر مراجعــة لــه‬\n‫بتاريــخ ‪2011/7/31‬م ‪ .‬ومــن ضمــن أوراق املعاملــة تقريــر بحث الســوابق‬\n‫املبــن وجــود عــدة ســوابق علــى املدعــى عليــه ومــن بينهــا الســابقة التــي‬\n‫حكــم فيهــا مبوجــب القــرار الصــادر برقــم ‪/11/4/24‬ض تاريــخ‬\n‫احلكــم ‪1427/6/27‬ه ـ ونــوع اجلرميــة ســرقة مســاكن كمــا جــرى‬\n‫االطــاع علــى صــورة القــرار املشــار إليــه يف صحيفــة الســوابق الصــادر‬\n‫مــن هــذه احملكمــة برقــم ‪/11/4/24‬ض يف ‪1427/6/27‬ه ـ واملتضمــن‬\n‫إقامــة دعــوى مــن املدعــي العــام ضــد املدعــى عليــه هنــا ‪ .....‬ويطالــب‬\n‫املدعــي العــام بإقامــة حــد احلرابــة علــى املدعــى عليــه التهــام املدعــى‬\n‫عليــه بدخــول املنــازل علــى ســبيل الغلبــة والقــوة والتهديــد بوجــود ســاح‬\n\n\n                                                                                    ‫‪358‬‬\n\f      ‫معــه ومعاونــون آخــرون وانتهــى حكــم أصحــاب الفضيلــة ( وحيــث لــم‬\n      ‫يثبــت مــا يوجــب إقامــة حــد احلرابــة علــى املدعــى عليــه فقــد صرفنــا‬\n      ‫النظــر عــن طلــب املدعــي العــام بإقامــة حــد احلرابــة وقــرر أصحــاب‬\n      ‫الفضيلــة تعزيــره بالســجن ســبع ســنني مــن تاريــخ توقيفــه وجلــده ألفــي‬\n      ‫جلــدة ) واحلكــم مصــادق عليــه مــن محكمــة االســتئناف بالقــرار رقــم‬\n      ‫‪/367‬خ‪/‬أ يف ‪1428/3/13‬ه ـ ثــم جــرى ســؤال املدعــى عليــه عمــا جــاء‬\n      ‫يف القــرار الســابق فقــال أننــي تائــب نــادم علــى مــا مضــى وأنــا ابــن اليــوم‬\n      ‫وســبب عودتــي للســرقة يف هــذه القضيــة أننــي لــم أشــعر بنفســي ومــا‬\n      ‫فعلتــه مــن غيــر إرادة منــي ‪ .‬فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي‬\n      ‫العــام وإلقــرار املدعــى عليــه أنــه دخــل أحــد العمائــر املجــاورة للمنــزل‬\n      ‫املســروق يف محافظــة اخلــرج ومــن ثــم قفــز داخــل ســور املنــزل املســروق‬\n      ‫وبحــث عــن مدخــل لداخــل املنــزل ووجــد فتحــة مكيــف وأحضــر مــا‬\n      ‫يرتفــع عليــه ليدخــل مــن خــال هــذه الفتحــة ودخــل داخــل املنــزل وجتــول‬\n      ‫يف البيــت املســروق ودخــل غرفــة النــوم وفتــح ( درج الكمدينــة) ووجــد‬\n      ‫فيــه علبــة فيهــا الذهــب والســاعتان فأخذهــا وخــرج مــن حيــث دخــل‬\n      ‫وأخفــى املســروقات ملــدة اســبوعني ثــم أخذهــا معــه ملدينــة الريــاض‬\n      ‫وذهــب لســوق الذهــب يف اســواق ‪ ........‬وعــرض الذهــب علــى أصحــاب‬\n      ‫احملــات وحــاول بيعــه وتتوجــه التهمــة عليــه مبقاومــة الفرقــة ولــو كان‬\n      ‫املدعــى عليــه مريــض مرضــا مســقط ًا لكمــال أهليتــه ملــا صــدرت منــه‬\n      ‫هــذه األفعــال وألن األصــل اســتصحاب حــال الصحــة عنــد املدعــى عليــه‬\n      ‫ولوجــود ســابقة علــى املدعــى عليــه مت احلكــم عليــه فيهــا بحكــم بليــغ‬\n      ‫ولــم يرتــدع‪ .‬وحيــث وجــد املــال املســروق بحــوزة املدعــى عليــه وألن املــال‬\n      ‫محــرز يف بيــت مغلــق عليــه وانتهــك املدعــى عليــه هــذا احلــرز بالتســلق‬\n\n\n‫‪359‬‬\n\f‫للســور اخلارجــي ومــن ثــم الدخــول داخــل املنــزل وألن املنــزل حــرز ملــا يف‬\n‫داخلــه وألن املــال املســروق مــال محتــرم وبالــغ للنصــاب واملدعــى عليــه‬\n‫عاقــل مكلــف مؤاخــذ بإقــراره وألن املدعــى عليــه بــاق علــى اقــراره وقــد‬\n‫صــدر منــه اإلقــرار وهــو بكامــل أهليتــه املعتبرة ولقوله تعالى( والســارق‬\n‫والســارقة فاقطعــوا أيديهمــا جــزاء ًا مبــا كســبا نــكاال مــن اهلل واهلل‬\n‫عزيــز حكيــم) لذلــك كلــه فقــد حكمنــا بإقامــة حــد الســرقة علــى‬\n‫املدعــى عليــه ‪ ............‬وذلــك بــأن تقطــع يــده اليمنــى مــن مفصــل الكــف‬\n‫مــادام بــاق علــى إقــراره ويكــون تعزيــره عــن تهمــة مقاومــة الفرقــة داخــل‬\n‫يف إقامــة احلــد عليــه وبــه حكمنــا وبعرضــه علــى املدعــى عليــه لــم يقنــع‬\n‫وطلــب رفعــه حملكمــة االســتئناف بالئحــة اعتراضيــة وجــرى إفهامــه‬\n‫أنــه يتــم طلبــه مــن الســجن ويســلم نســخة مــن القــرار خــال مــدة أقصاها‬\n‫ثالثــون يومــا مــن تاريخــه وأنــه إن لــم يتقــدم باالعتــراض يف تلــك املــدة‬\n‫يســقط حقــه يف االعتــراض ولــم يرغــب املدعــي العــام يف االعتــراض‬\n            ‫وصلــى وســلم علــى نبينــا محمــد ‪ .‬حــرر يف ‪1433/12/21‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده ففــي يــوم الســبت املوافــق‪ 1433/12/25‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــر املدعــى عليــه ‪ .......‬وجــرى تســليمه نســخة مــن‬\n‫القــرار وذلــك لتقــدمي الئحتــه االعتراضيــة خــال ثالثــن يومــا مــن تاريخه‬\n‫وإن لــم يتقــدم يف تلــك املــدة فإنــه يســقط حقــه يف االعتــراض ‪ ،‬ففــي يــوم‬\n‫الثالثــاء املوافــق ‪ 1434/3/3‬ه ـ افتتحــت اجللســة بنــاء علــى الالئحــة‬\n‫االعتراضيــة املقدمــة مــن املدعــى عليــه ‪ ....... /‬برقــم ‪34174980‬‬\n‫وتاريــخ ‪1434/1/20‬ه ـ وفيهــا حضــر املدعــى عليــه ‪ ............‬وجــاء علــى‬\n‫الصفحــة األخيــرة يف الئحتــه قولــه ( ومبــا أننــي قــد أخطــأت يف فهــم‬\n‫مــا عــرض علــي مــن أســئلة ســواء مــن احملقــق أو فضيلــة القضــاة لــذا‬\n\n\n                                                                                     ‫‪360‬‬\n\f      ‫فأننــي أتراجــع عــن كل مــا جــاء بأقوالــي ) ثــم جــرى ســؤال املدعــى عليه‬\n      ‫عــن مــا جــاء يف الئحتــه فقــال أننــي أقــرر رجوعــي عــن اعترافاتــي لــدى‬\n      ‫احملققــن ولديكــم وأنهــا قــد صــدرت منــي بنــاء علــى ضغــط احملقــق‬\n      ‫وتأثيــر املــرض النفســي علــي ومــن غيــر أدراك ‪ .‬لــذا فأنــه ال صحــة ملــا‬\n      ‫جــاء يف دعــوى املدعــي العــام أننــي دخلــت املنــزل وســرقت منــه الذهــب‬\n      ‫هكــذا قــرر ‪ .‬وبعرضــه علــى املدعــي العــام قــال الصحيــح مــا جــاء يف‬\n      ‫الدعــوى ويف إقــراره لــدى جهــة التحقيــق ولديكــم ‪ ،‬فســألناه البينــة‬\n      ‫فقــال ليــس لــدي بينــه ســوى إقــراره لــدى جهــات التحقيــق ولديكــم ‪،‬‬\n      ‫وبنــاء عليــه وحيــث رجــع املدعــى عليــه عــن إقــراره وذكــر أنــه مصــاب‬\n      ‫مبــرض نفســي وأن لهــا أثــر يف إقــراره وأنــه لــم يــدرك مــا أقــر بــه وألن‬\n      ‫احلــدود تــدرأ بالشــبهات لذلــك كلــه فقــد رجعنــا عــن مــا حكمنــا‬\n      ‫بــه مــن قطــع اليــد اليمنــى للمدعــى عليــه ولتوجــه التهمــة القويــة علــى‬\n      ‫املدعــى عليــه بإقــراره لــدى جهــات التحقيــق ولدينــا ولوجــود ســابقة مــن‬\n      ‫جنــس هــذه القضيــة قررنــا تعزيــر املدعــى عليــه بــأن يســجن ثمــان ســنني‬\n      ‫مــن تاريــخ القبــض عليــه وأن يجلــد ألــف جلــدة مفرقــة علــى عشــرين‬\n      ‫دفعــه كل دفعــه خمســن جلــدة بــن كل دفعــه وأخــرى خمســة أيــام ‪،‬‬\n      ‫وبــه حكمنــا وبعرضــه علــى املدعــى عليــه قنــع بــه وبعرضــه علــى املدعــي‬\n      ‫العــام طلــب رفعــه حملكمــة االســتئناف بالئحــة اعتراض وجــرى أفهامه‬\n      ‫أنــه يتــم تســليمة نســخة مــن احلكــم لتقــدمي الئحــة اعتــراض عليهــا يف‬\n      ‫مــدة أقصاهــا ثالثــون يومـ ًا ‪ ،‬واهلل املوفــق للصــواب ‪ .‬وصلــى اهلل وســلم‬\n                                      ‫علــى نبينــا محمــد ‪ .‬حــرر يف ‪ 1434/3/3‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فقــد‬\n      ‫اطلعنــا نحــن قضــاة الدائــرة اخلماســية األولــى مبحكمــة االســتئناف‬\n\n\n‫‪361‬‬\n\f‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة باخلــرج املكلــف الشــيخ‪ ........ /‬برقــم ‪ 331187899‬وتاريــخ‬\n‫‪1434/4/22‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلتــه والقضــاة‬\n‫املشــاركني لــه باحملكمــة الشــيخ‪ ...... /‬والشــيخ ‪ ..... /‬املســجل برقــم‬\n‫‪ 33476192‬وتاريــخ ‪1433/12/22‬ه ـ اخلــاص بدعــوى املدعــي العــام‬\n‫ضــد‪ ...... /‬يف قضيــة ســرقة ‪ ،‬وقــد تضمــن القــرار حكــم أصحــاب‬\n‫الفضيلــة علــى النحــو املفصــل فيــه ‪ ،‬وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة نقــرر باألكثريــة املصادقــة علــى احلكــم األخيــر مــع‬\n‫تنبيــه أصحــاب الفضيلــة إلــى مصادقــة رئيــس احملكمــة علــى صحــة‬\n‫أختــام وتواقيــع القضــاة قبــل بعــث املعاملــة جلهــة التنفيــذ والتوقيــع‬\n‫ال علــى الالئحــة االعتراضيــة مبــا يفيــد االطــاع عليهــا ‪ .‬واهلل‬\n                                                                   ‫مســتقب ً‬\n                                                                     ‫املوفــق ‪.‬‬\n\n\n\n\n                                                                                  ‫‪362‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":351,"source_page_end":362,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2bb84ff98e99b10366557988c0293840427c3b4220f1c42fc10acdc4d256a092","normalized_text_hash":"59989ddc9c243c6249847417b67428dccb97a211316ba23c87c4da8b178bd15c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p351-33476192"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"d0086aeb-53a5-562f-844c-8c4d5801bb67","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -انتهاك حرمة منزل -سرقة جواالت من منزل -اشتراك يف سرقة -سرقة مال محترم من حرزه بالغ النصاب الشبهة منه- تستر -طلب إعادة حتقيق -اعتراف حتقيق ا -رجوع عن إقرار -طلب إقامة حد السرقة -درء حد السرقة -تعزير بالسجن واجللد.","document_number":"33462191","case_number":"33247078","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/22","year":"1434","subject":"سرقة -انتهاك حرمة منزل -سرقة جواالت من منزل -اشتراك يف سرقة -سرقة مال محترم من حرزه بالغ النصاب الشبهة منه- تستر -طلب إعادة حتقيق -اعتراف حتقيق ا -رجوع عن إقرار -طلب إقامة حد السرقة -درء حد السرقة -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 33462191 :‬تاريخه ‪1433/11/22:‬هـ‬\n                          ‫رقم الدعوى ‪33247078:‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34389112‬تاريخه‪1434/12/26 :‬ه‬\n\n\n\n      ‫ســرقة ‪ -‬انتهــاك حرمــة منــزل‪ -‬ســرقة جــواالت مــن منــزل ‪ -‬اشــتراك‬\n      ‫يف ســرقة ‪ -‬ســرقة مــال محتــرم مــن حــرزه بالــغ النصــاب الشــبهة منــه‪-‬‬\n      ‫تســتر‪ -‬طلــب إعــادة حتقيــق‪ -‬اعتــراف حتقيقـ ًا‪ -‬رجــوع عــن إقــرار‪ -‬طلب‬\n             ‫إقامــة حــد الســرقة‪ -‬درء حــد الســرقة‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n                ‫قول النبي صلى اهلل عليه وسلم ( ادرؤوا احلدود بالشبهات )‪.‬‬\n\n\n\n\n      ‫دعــوى املدعــي العــام ضــد املدعــى عليهمــا بانتهاكهمــا حرمــة منــزل‬\n      ‫وســرقة جــواالت داخلــه وتســترهما علــى املتهــم الثالــث وطلــب إقامــة حــد‬\n      ‫الســرقة علــى أحدهمــا الــذي أقــر بالتهمــة لــدى جهــة التحقيــق وتعزيــر‬\n      ‫الثانــي وهــو الــذي أنكــر التهمــة لــدى جهــة التحقيــق‪ ،‬مت القبــض علــى‬\n      ‫املدعــى عليهمــا بعــد بــاغ مفــاده تعــرض أحــد املنــازل للســرقة وكان من‬\n      ‫ضمــن املســروقات جــواالت فتــم االتصــال علــى أحــد اجلــواالت املســروقة‬\n      ‫وتبــن أنــه مت بيعــه علــى أحــد األشــخاص الــذي قــام بالداللة علــى املدعى‬\n      ‫عليهمــا‪ ،‬أنكــر املدعــى عليهمــا‪ ،‬وجــد إقــرار حتقيقـ ًا مــن أحــد املدعــى‬\n      ‫عليهمــا مبــا نســب إليــه‪ ،‬رجــع املدعــى عليــه املقــر حتقيق ـ ًا عــن إقــراره‬\n      ‫مدعيـ ًا أنــه صــدر منــه حتــت اإلكــراه‪،‬مت درء حــد الســرقة عــن املدعــى‬\n\n‫‪291‬‬\n\f‫عليــه املقــر حتقيقـ ًا لرجوعــه عــن اعترافه‪،‬حكمــت احملكمــة بتعزيــر‬\n‫املدعــى عليهمــا بالســجن واجللــد‪ ،‬مت تصديــق احلكــم مــن محكمــة‬\n                                                        ‫االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد ففــي‬\n‫هــذا اليــوم الثالثــاء املوافــق ‪1433/6/17‬ه ـ افتتحــت اجللســة الســاعة‬\n‫العاشــرة صباحــا لدينــا نحــن القضــاة ‪ .....‬و ‪ .....‬و ‪ ....‬وبنــاء علــى املعاملــة‬\n‫الــواردة مــن رئيــس هيئــة التحقيــق واالدعــاء العــام مبنطقــة تبــوك برقــم‬\n‫‪ 4443‬وتاريــخ ‪1433/3/27‬ه ـ واحملالــة مــن فضيلــة الرئيــس برقــم‬\n‫‪ 33247078‬وتاريــخ ‪1433/4/7‬ه ـ واخلاصــة بدعــوى املدعــي العــام ضــد‬\n‫كال مــن ‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).......‬مــن‬\n‫مواليــد عــام ‪1406‬ه ـ مــن ســكان تبــوك حــي ‪ ...‬تاريــخ القبــض عليــه‬\n‫‪1433/1/3‬هـ توجد ســابقة عليه اشــتباه ســكر جلده ‪60‬جلده مبوجب‬\n‫حكــم رقــم ‪ 138/3‬وتاريخــه ‪1426/8/14‬ه ـ مصــدره محكمــة تبــوك‬\n‫و‪ ......‬ســعودي مبوجــب الســجل املدنــي رقــم (‪ )....‬مــن مواليــد عــام‬\n‫‪1404‬ه ـ مــن ســكان تبــوك حــي ‪ .....‬وال توجــد ســوابق يف قضيــة انتهــاك‬\n‫حرمــة منــزل والســرقة عليــه فقــد حضــر املدعــي العــام وأدعــى قائــا‬\n‫بصفتــي مدعيــا عمــا بدائــرة االدعــاء العــام مبنطقــة تبــوك أدعــي علــى‬\n‫املذكوريــن أعــاه فإنــه بتاريــخ ‪1432/12/20‬ه ـ تقــدم املواطــن ‪......‬‬\n‫‪ 38‬عام ـ ًا ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬ببــاغ‬\n‫زوجــة جــاره املجنــي عليهــا ‪، ......‬تفيــد فيــه تعــرض منزلهــا للســرقة‬\n‫حيــث دخــل عليهــا شــخص وقــام بســرقة ســتة أجهــزة جــواالت دون‬\n\n                                                                                         ‫‪292‬‬\n\f      ‫تعرضهــا ألي أذى كمــا ورد محضــر الدوريــات األمنيــة رقــم(‪ )....‬بتاريــخ‬\n      ‫‪1432/12/20‬ه ـ املتضمــن تلقــي شــكوى املجنــي عليهــا ‪،.......‬بأنهــا‬\n      ‫تعرضــت للســرقة وقــد ســرق منهــا عــدد ًا مــن اجلــواالت وقامــت بالتنســيق‬\n      ‫معهــم بعــد اتصالهــا علــى أحــد جواالتهــا املســروقة واســتدراج مــن رد‬\n      ‫عليهــا أمــام ســوبر ماركــت ‪ ....‬بحــي ‪ ، .....‬وعنــد حضــور الشــخص‬\n      ‫الــذي معــه اجلــوال مت القبــض عليــه واتضــح أنــه يدعــى ‪ .......‬وباالنتقــال‬\n      ‫واملعاينــة ملنــزل املدعيــة الواقــع بحــي ‪ ......‬و اتضــح أن البــاب اخلارجــي‬\n      ‫متعــرض للكســر ويوجــد بعثــرة بداخــل املنــزل ولــم يعثــر علــى أي آثــار‬\n      ‫تفيــد التحقيــق‪ .‬وبســماع شــكوى املجنــي عليهــا ‪ ، .....‬أفــادت أنــه بتاريخ‬\n      ‫‪1432/12/20‬ه ـ ويف ســاعة متأخــرة مــن الليــل دخــل عليهــا شــخص‬\n      ‫أثنــاء نومهــا وقامــت بالصــراخ عنــد مشــاهدته فقــام بالهــرب وبتفقدهــا‬\n      ‫للمنــزل وجــدت بأنــه قــام بســرقة عــدد ســتة جــواالت اثنــن مــن نــوع ‪.....‬‬\n      ‫وأربعــة مــن نــوع ‪ ....‬وكذلــك مفتــاح البيــت وقامــت باالتصــال علــى‬\n      ‫جارهــا بالعمــارة ‪، ......‬كــون زوجهــا خــارج منطقــة تبــوك وذكــرت بــأن‬\n      ‫أوصــاف الســارق هــي (طويــل ومتــن ووجهــه دائــري ويرتدي بدله ســوداء‬\n      ‫اللــون حنطــي البشــرة ومغطــى الــرأس) وعندمــا حاولــت االتصــال بأحــد‬\n      ‫جواالتهــا والــذي يحمــل الرقــم (‪ ).......‬قــام أحدهــم بالــرد وأخبرتــه بــأن‬\n      ‫اجلــوال لهــا وترغــب يف شــرائه منــه وطلبــت مقابلتــه أمــام ســوبر ماركــت‬\n      ‫‪ .....‬ونســقت مــع دوريــات األمــن وعنــد حضــور الشــخص للموقــع ســلمها‬\n      ‫اجلــوال ومت القبــض عليــه وذكــرت بأنــه ليــس الشــخص الــذي دخــل‬\n      ‫عليهــا وال تتهمــه كونــه عندمــا أخبرتــه بــأن اجلــوال مســروق منهــا حضــر‬\n      ‫وســلمه لهــا‪ .‬وبســماع أقــوال املواطــن ‪30......‬عام ـ ًا ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ )......‬أفــاد بأنــه بتاريــخ ‪1432/12/20‬ه ـ‬\n\n\n‫‪293‬‬\n\f‫وأثنــاء وجــوده أمــام منزلــه قابلــه املدعــى عليــه‪.....‬و ‪........‬وشــخص ثالــث‬\n‫ال يعرفــه وعرضــوا عليــه شــراء أجهــزة جــواالت معهــم وكان عددهــا‬\n‫ســتة أجهــزة جــواالت (اثنــان منهــا ‪ ...‬وأربعــة ‪ )....‬فقــام بشــراء جوالــن‬\n‫منهــم مــن نــوع (‪ )....‬و(‪ )...‬مببلــغ وقــدره ســبعمائة وخمســن ريــال وبعدمــا‬\n‫ذهبــوا اتصلــت عليــه امــرأة علــى أحــد اجلوالــن وقالــت لــه إن اجلــوال‬\n‫الــذي معــه عائــد لهــا وأنــه مســروق وذهــب ملقابلتهــا إلرجــاع اجلــواالت‬\n‫وأخــذ املبلــغ الــذي دفعــه ومت القبــض عليــه أثنــاء حضــوره وذكــر بأنــه‬\n‫علــى اســتعداد بالتعــرف علــى مــن باعــه اجلوالــن ‪(.‬مت حفــظ االتهــام‬\n‫بحقــه لعــدم كفايــة األدلــة اســتناد ًا للمــادة (‪ )124‬مــن نظــام اإلجــراءات‬\n‫ـاء علــى مــا ورد بأقــوال املدعــو ‪ .......‬بأنــه اشــترى اجلوالــن‬\n                                                                  ‫اجلزائية)‪.‬وبنـ ً‬\n‫مــن ثالثــة أشــخاص ‪ ،‬وبالبحــث والتحــري اتضــح أن أحدهــم يدعــى ‪......‬‬\n‫ويلقــب (‪ )......‬وبعــرض صورتــه يف النهايــة الطرفيــة تعــرف عليــه وجــرى‬\n‫التعميــم عنــه ومت القبــض عليــه مــن قبــل وحــدة البحــث مبركــز شــرطة‬\n‫‪ .....‬بتاريــخ ‪1432/12/29‬ه ـ ‪ .‬كمــا مت القبــض علــى املدعــى عليــه ‪.....‬‬\n‫بعــد طلبــه احلضــور ملركــز الشــرطة بتاريــخ ‪1433/1/3‬ه ـ ‪.‬كمــا جــرى‬\n‫عــرض املدعــى عليــه ‪ ......‬علــى املدعيــة ضمــن مجموعــة أشــخاص‬\n‫وتعرفــت عليــه وأفــادت أنــه الشــخص الــذي دخــل منزلهــا ‪.‬كمــا جــرى‬\n‫عــرض املدعــى عليــه‪ .....‬علــى املدعــى عليــه ظاهــر ضمــن مجموعــة‬\n‫أشــخاص واســتطاع التعــرف عليــه وأنــه ضمــن األشــخاص الذيــن قامــوا‬\n‫ببيــع أجهــزة اجلــوال عليــه‪ .‬كمــا جــرى عــرض املدعــى عليــه‪ ....‬علــى‬\n‫املدعــى عليــه‪ ......‬ضمــن مجموعــة أشــخاص واســتطاع التعــرف عليــه‬\n‫وأفــاد أنــه كان مــن ضمــن األشــخاص الذيــن قامــوا ببيــع اجلــوال عليــه‪.‬‬\n‫وقــد جــرى فــرز أوراق للمتهــم الهــارب ‪.‬كمــا جــرى تســليم عــدد جهازيــن‬\n\n\n                                                                                      ‫‪294‬‬\n\f      ‫جــوال مــن نــوع ‪ ....‬موديــل (‪ )...‬و (‪ )...‬للمــرأة ‪، .........‬حســب احملضــر‬\n      ‫املــدون وبقــي أربعــة أجهــزة جــواالت لــم يتــم العثــور عليهــا ‪.‬كمــا مت إيداع‬\n      ‫املدعــى عليهمــا للســجن العــام مبوجــب مذكرتــي التوقيــف رقــم (‪)5-4‬‬\n      ‫بتاريخ ‪1433/1/19‬هـ ‪ .‬وباســتجواب املدعى عليه الثاني ‪،.........‬أنكر‬\n      ‫بدايــة األمــر وبعــد مواجهتــه باألدلــة والقرائــن أفــاد بأنــه بتاريــخ‬\n      ‫ال مــن‬‫‪1432/12/20‬ه ـ أقــدم علــى ســرقة منــزل املــرأة ‪ .......‬ومعــه ك ً‬\n      ‫املدعــى عليــه ‪، ......‬واملدعــى عليــه ‪، ......‬حيــث أفــاد بأنــه يف ذات اليــوم‬\n      ‫ال مــن‪ .......‬و ‪، ....‬عنــد املنــزل وطلبــا منــه‬‫وقبــل الفجــر حضــر لــه ك ً‬\n      ‫مرافقتهمــا للتمشــية وأثنــاء مرورهــم مبنــزل املجنــي عليهــا قــام‪ ......‬بدفــع‬\n      ‫البــاب لغــرض الســرقة وبقــي هــو ورفيقــه‪ ......‬يراقبــان املنــزل مــن اخلــارج‬\n      ‫وكان‪ .....‬بالقــرب مــن البــاب وبعــد عشــر دقائــق تقريب ـ ًا خــرج لهــم ‪....‬‬\n      ‫مســرع ًا ومعــه جوالــن ويقــول (املــرأة اســتيقظت مــن النــوم) والذوا‬\n      ‫بالفــرار وذهــب ملنزلــه ونــام وبعــد اســتيقاظه علــم بــأن ‪ ......‬مت القبــض‬\n      ‫عليــه ‪.‬ومبواجهــة املدعــى عليــه الثانــي‪ ...‬باملدعــو ‪،......‬عــدل املدعــى‬\n      ‫عليــه‪ ......‬عمــا جــاء بأقوالــه مــن مشــاركة املدعــو ‪ .....‬لهــم بالســرقة‬\n      ‫وقصــد مــن ذلــك إدخالــه يف القضيــة ‪.‬وباســتجواب املدعــى عليــه األول‬\n      ‫‪ .......‬أنكــر قيامــه بالســرقة أو االشــتراك مــع املدعــى عليــه الثانــي فيهــا‬\n      ‫‪.‬ومبواجهتــه باملدعــو ‪ .....‬أصــر كلٌ منهمــا علــى أقوالــه الســابقة وملــا‬\n      ‫أشــير إليــه أقــرر توجيــه االتهــام للمتهمــن ‪ ......‬و ‪ .....‬بانتهاكهمــا حلرمــة‬\n      ‫منــزل املدعيــة ‪.....‬وســرقة عــدد ســت أجهــزة جــواالت مــن داخلــه‬\n      ‫وتســترهما علــى املتهــم الثالــث الهــارب ‪ .‬وذلــك لألدلــة والقرائــن التاليــة‬\n      ‫‪ -1:‬مــا جــاء باعتــراف املدعــى عليــه‪ .......‬املــدون علــى الصفحــات (‪)15‬‬\n      ‫مــن دفتــر التحقيــق املرفــق لفــة (‪ -2. )2‬مــا ورد بأقــوال ‪ ......‬املنــوه عنــه‬\n\n\n‫‪295‬‬\n\f‫واملــدون علــى الصفحــة (‪ )14‬مــن دفتــر التحقيــق املرفــق لفــة (‪ -3. )3‬مــا‬\n‫جــاء مبحضــر العــرض والتعــرف املنــوه عنــه واملــدون علــى الصفحــة (‪)16‬‬\n‫مــن دفتــر التحقيــق املرفــق لفــة (‪ )1‬والصفحــة (‪ )13‬لفــة (‪ )2‬والصفحــة‬\n‫(‪ )15-13‬لفــة (‪ -4. )3‬مــا جــاء مبحضــر املعاينــة واملتضمــن تعــرض بــاب‬\n‫املنــزل للكســر واملنــوه عنــه املــدون علــى الصفحة (‪ )2‬مــن دفتر التحقيق‬\n‫املرفــق لفــة (‪ -4. )3‬مــا جــاء مبحضــر املواجهــة املــدون علــى الصفحــة‬\n‫(‪ )14‬مــن دفتــر التحقيــق املرفــق لفــة (‪ )1‬والصفحــة (‪ )16‬لفــة (‪-6. )3‬‬\n‫مــا جــاء باســتالم املجنــي عليهــا اجلوالــن املســروقة املنــوه عنــه واملــدون‬\n‫علــى الصفحــة (‪ )12‬مــن دفتــر التحقيــق لفــة (‪ . )3‬وانتهــى التحقيــق إلــى‬\n‫توجيــه االتهــام للمدعــى عليهمــا ‪ ..........‬و ‪، ...........‬بانتهاكهمــا حلرمــة‬\n‫منــزل املجنــي عليهــا ‪، ......‬وســرقة عــدد ســت أجهــزة جــواالت مــن داخله‬\n‫وتســترهما علــى املتهــم الثالــث الهــارب ‪.‬وحيــث أن مــا أقــدم عليــه‬\n‫املذكــوران فعــل محــرم ومعاقــب عليــه شــرع ًا وهــو انتهــاك حلرمــة منــزل‬\n‫وســرقة مــال محتــرم مــن حــرزه بلــغ النصــاب ال شــبهة لهمــا فيــه وهمــا‬\n‫مكلفــان غيــر مكرهــان لــذا أطلــب مايلــي ‪ -1 :‬إثبــات مــا أســند إليهمــا‬\n‫‪ -2.‬احلكــم علــى املدعــى عليــه الثانــي‪، .......‬بحــد الســرقة الــوارد يف‬\n‫اآليــة الكرميــة رقــم (‪ )38‬مــن ســورة املائــدة ‪ -3.‬احلكــم علــى املدعــى‬\n‫عليــه األول ‪ ،.......‬بعقوبــة تعزيريــة ‪( .‬علم ـ ًا بــأن احلــق اخلــاص ال زال‬\n‫قائم ـاً) هــذه دعــواي وأســألهما اجلــواب ‪ ،‬وبســؤال املدعــى عليهمــا عــن‬\n‫دعــوى املدعــي العــام أجــاب املدعــى عليــه األول ‪ ......‬قائــا إن مــا جــاء يف‬\n‫دعــوى املدعــي العــام ضــدي فغيــر صحيــح فلــم أنتهــك حرمــة منــزل‬\n‫املدعيــة ‪ .....‬ولــم أســرق اجلــواالت مــن منزلهــا املذكــور يف الدعــوى ولــم‬\n‫أشــترك يف ذلــك ولــم أتســتر علــى املتهــم الثالــث وال عالقــة لــي بهــذه‬\n\n\n                                                                                      ‫‪296‬‬\n\f      ‫الدعــوى ال مــن قريــب وال مــن بعيــد ولــم أقابــل املدعــى عليــه الثانــي ‪......‬‬\n      ‫يف يوم ‪1432/12/20‬هـ والصحيح أنني كنت بتاريخ ‪1432/12/20‬هـ‬\n      ‫مبنزلي بحي ‪ .....‬ولم أخرج منه إال عصر اليوم الثاني ‪1432/12/21‬هـ‬\n      ‫وقــد كان عنــدي ليلــة الواقعــة التــي اتهمنــي بهــا املدعــي العــام اثنــن مــن‬\n      ‫أبنــاء عمومتــي ‪ ........‬و ‪ .....‬ولــم نتفــرق إال بعــد الســاعة السادســة صباحــا‬\n      ‫وبتاريــخ ‪1433/1/3‬ه ـ حضــرت الدوريــات األمنيــة ملنــزل والدتــي بحــي‬\n      ‫‪ ....‬ومت طلبــي لقســم شــرطة ‪ .....‬وأبلغتنــي الوالــدة بذلــك وحضــرت لهــم‬\n      ‫ومت القبــض علــي هكــذا أجــاب وبســؤال املدعــى عليــه الثانــي ‪........‬‬\n      ‫قائــا إن مــا جــاء يف دعــوى املدعــي العــام ضــدي فغيــر صحيــح فلــم‬\n      ‫أنتهــك حرمــة منــزل املدعيــة ‪ ......‬ولــم أســرق اجلــواالت مــن منزلهــا‬\n      ‫املذكــور يف الدعــوى ولــم أشــترك يف ذلــك ولــم أتســتر علــى املتهــم‬\n      ‫الثالــث وال عالقــة لــي بهــذه الدعــوى ال مــن قريــب وال مــن بعيــد ولــم‬\n      ‫أقابــل املدعــى عليــه األول ‪ .......‬يف يــوم ‪1432/12/20‬ه ـ والصحيح أنني‬\n      ‫كنــت بتاريــخ ‪1432/12/20‬ه ـ مبنزلــي بحــي ‪ ....‬ولــم أخــرج منــه إال‬\n      ‫عصــر اليــوم الثانــي وبتاريــخ ‪1432/12/29‬ه ـ حضــرت الدوريــات‬\n      ‫األمنيــة ملنــزل والدتــي بحــي ‪ .....‬ومت طلبــي لقســم شــرطة ‪ .....‬ومت القبــض‬\n      ‫علــي هكــذا أجــاب وبســؤال املدعــي العــام عــن بينتــه أجــاب قائــا إنهــا‬\n      ‫مرصــودة ضمــن طيــات املعاملــة وأطلــب الرجــوع إليهــا وضبطهــا‬\n      ‫وعرضهــا علــى املدعــى عليهمــا ‪ -1‬مــا جــاء باعتــراف املدعــى عليــه ‪.......‬‬\n      ‫املــدون علــى الصفحــات (‪ )15‬مــن دفتــر التحقيــق املرفــق لفــة (‪ )2‬وهــذا‬\n      ‫نصــه و باســتجواب املدعــى عليــه الثانــي ‪،......‬أنكــر بدايــة األمــر وبعــد‬\n      ‫مواجهتــه باألدلــة والقرائــن أفــاد بأنــه بتاريــخ ‪1432/12/20‬ه ـ أقــدم‬\n      ‫ال مــن املدعى عليه ‪، .....‬واملدعى‬     ‫علــى ســرقة منــزل املــرأة ‪ ......‬ومعــه ك ً‬\n\n\n‫‪297‬‬\n\f‫ال‬\n ‫عليــه ‪،.......‬حيــث أفــاد بأنــه يف ذات اليــوم وقبــل الفجــر حضــر لــه ك ً‬\n‫مــن ‪ ......‬و‪ ...........‬عنــد املنــزل وطلبــا منــه مرافقتهمــا للتمشــية وأثنــاء‬\n‫مرورهــم مبنــزل املجنــي عليهــا قــام ‪......‬بدفــع البــاب لغــرض الســرقة‬\n‫وبقــي هــو ورفيقــه‪ .....‬يراقبــان املنــزل مــن اخلــارج وكان ‪ .....‬بالقــرب مــن‬\n‫البــاب وبعــد عشــر دقائــق تقريب ـ ًا خــرج لهــم‪ .....‬مســرع ًا ومعــه جوالــن‬\n‫ويقــول (املــرأة اســتيقظت مــن النــوم) والذوا بالفــرار وذهــب ملنزلــه ونــام‬\n‫وبعــد اســتيقاظه علــم بــأن‪ ......‬مت القبــض عليــه ‪ -2.‬مــا ورد بأقــوال ‪.....‬‬\n‫املنــوه عنــه واملــدون علــى الصفحــة (‪ )14‬مــن دفتــر التحقيــق املرفــق لفــة‬\n‫(‪ )3‬وهــذا نصــه وبســماع أقــوال املواطن‪،30........‬عامـ ًا ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )......‬أفــاد بأنــه بتاريــخ ‪1432/12/20‬ه ـ‬\n‫وأثنــاء وجــوده أمــام منزلــه قابلــه املدعــى عليــه ‪ .......‬و‪، ......‬وشــخص‬\n‫ثالــث ال يعرفــه وعرضــوا عليــه شــراء أجهــزة جــواالت معهــم وكان‬\n‫عددهــا ســتة أجهــزة جــواالت (اثنــان منهــا ‪ ....‬وأربعــة ‪ ) ....‬فقــام بشــراء‬\n‫جوالــن منهــم مــن نــوع (‪ ).....‬و (‪ ).....‬مببلــغ وقــدره ســبعمائة وخمســن‬\n‫ريــال وبعدمــا ذهبــوا اتصلــت عليــه امــرأة علــى أحــد اجلوالــن وقالــت لــه‬\n‫إن اجلــوال الــذي معــه عائــد لهــا وأنــه مســروق وذهــب ملقابلتهــا إلرجــاع‬\n‫اجلــواالت وأخــذ املبلــغ الــذي دفعــه ومت القبــض عليــه أثنــاء حضــوره‬\n‫وذكــر بأنــه علــى اســتعداد بالتعــرف علــى مــن باعــه اجلوالــن‪ -3‬مــا جــاء‬\n‫مبحضــر العــرض والتعــرف املنــوه عنــه واملــدون علــى الصفحــة (‪ )16‬مــن‬\n‫دفتــر التحقيــق املرفــق لفــة (‪ )1‬والصفحــة (‪ )13‬لفــة (‪ )2‬والصفحــة‬\n‫(‪ )15-13‬لفــة (‪ )3‬وهــذا نصــه جــرى عــرض املدعــى عليــه ‪، ......‬علــى‬\n‫املدعيــة ضمــن مجموعــة أشــخاص وتعرفــت عليــه وأفــادت أنــه هــو‬\n‫الشــخص الــذي دخــل منزلهــا ‪.‬كمــا جــرى عــرض املدعــى عليــه ‪......‬‬\n\n\n                                                                                       ‫‪298‬‬\n\f      ‫علــى املدعــي ‪ ......‬ضمــن مجموعــة أشــخاص واســتطاع التعــرف عليــه‬\n      ‫وأنــه ضمــن األشــخاص الذيــن قامــوا ببيــع أجهــزة اجلــوال عليــه ‪.‬كمــا‬\n      ‫جــرى عــرض املدعــى عليــه‪ ......‬علــى املدعــى ‪ ......‬ضمــن مجموعــة‬\n      ‫أشــخاص واســتطاع التعرف عليه وأفاد أنه كان من ضمن األشــخاص‬\n      ‫الذيــن قامــوا ببيــع اجلــوال عليــه ‪ -4.‬مــا جــاء مبحضــر املعاينــة واملتضمــن‬\n      ‫تعــرض بــاب املنــزل للكســر واملنــوه عنــه املــدون علــى الصفحــة (‪ )2‬مــن‬\n      ‫دفتــر التحقيــق املرفــق لفــة (‪)3‬وهــذا نصــه محضــر انتقــال ومعاينــة أوليــة‬\n      ‫بتاريــخ ‪1432/12/21‬ه ـ جــرى االنتقــال إلــى املنــزل واتضــح أنــه يقــع‬\n      ‫بحــي ‪ ....‬وبجــوار ‪ ......‬وكان هنــاك تكســير يف البــاب اخلارجــي ووجــود‬\n      ‫بعثــرة يف املنــزل وهــو عبــارة عــن دور أرضــي وملحــق جــرى رفــع االثــار‬\n      ‫مــن قبــل فنــي األدلــة وحفظــا للواقــع نظــم هــذا احملضــر أـ ه ـ ‪ -5‬مــا جــاء‬\n      ‫مبحضــر املواجهــة املــدون علــى الصفحــة (‪ )14‬مــن دفتــر التحقيــق املرفق‬\n      ‫لفــة (‪ )1‬والصفحــة (‪ )16‬لفــة (‪ )3‬وهــذا نصــه ومبواجهــة املدعــى عليــه‬\n      ‫الثانــي ‪ ......‬باملدعــو ‪،.....‬عــدل املدعــى عليــه‪ .......‬عمــا جــاء بأقوالــه مــن‬\n      ‫مشــاركة املدعــو ‪ .....‬لهــم بالســرقة وقصــد مــن ذلــك إدخالــه يف القضيــة‬\n      ‫‪ .‬ومبواجهــه املدعــو ‪ ......‬باملدعــو ‪ .....‬أصــر كلٌ منهمــا علــى أقوالــه‬\n      ‫الســابقة أ‪ .‬ه ـ ‪ -6‬مــا جــاء باســتالم املجنــي عليهــا اجلوالــن املســروقة‬\n      ‫املنــوه عنــه واملــدون علــى الصفحــة (‪ )12‬مــن دفتــر التحقيــق لفــة (‪)3‬‬\n      ‫وهــذا نصــه كمــا جــرى تســليم عــدد جهازيــن جــوال مــن نــوع ‪ .....‬موديــل‬\n      ‫(‪ ).....‬و (‪ )....‬للمــرأة ‪ .....‬حســب احملضــر املــدون وبقــي أربعــة أجهــزة‬\n      ‫جــواالت لــم يتــم العثــور عليهــا أ‪ .‬ه ـ ‪.‬وبعــرض أدلــة املدعــي العــام علــى‬\n      ‫املدعــى عليهمــا أجــاب املدعــى عليــه األول قائــا إن مــا جــاء يف األدلــة‬\n      ‫املوجهــة ضــدي فغيــر صحيــح وال أعلــم ملــاذا ذكــر ‪ ........‬أثنــاء التحقيــق‬\n\n\n‫‪299‬‬\n\f‫مشــاركتي لــه يف بيــع أجهــزة اجلــوال املســروقة وأمــا مــا جــاء بأقــوال ‪......‬‬\n‫وتعرفــه علــي فبينــي وبينــه عــداوة قدميــة بســبب مضاربــة معــه قبــل‬\n‫شــهرين مــن هــذه القضيــة هكــذا أجــاب كمــا أجــاب املدعــى عليــه‬\n‫الثانــي قائــا إن مــا جــاء يف األدلــة املوجهــة ضــدي فغيــر صحيــح وســبب‬\n‫اتهــام ‪ ....‬لــي كونــي صديــق ‪ ......‬ومــا جــاء مبحضــر تعــرف املدعيــة ‪......‬‬\n‫علــي فســببه مــازم التحقيــق الــذي ذكــر لهــا اســمي وقــال لهــا دققــي‬\n‫زي النــاس وقــد كانــت متــرددة بــن عــدة أشــخاص ثــم اتهمتنــي بهــذه‬\n‫التهمــه هكــذا أجــاب ورفعــت اجللســة للتأمــل و يف يــوم الثالثــاء املوافــق‬\n‫‪1433/07/08‬ه ـ افتتحــت اجللســة الســاعة ‪ 11.45‬وفيهــا حضــر املدعــي‬\n‫ا ‪ :‬مت‬  ‫العــام واملدعــى عليهمــا فســألنا املدعــي العــام عــن ‪ .....‬فأجــاب قائـ ً‬\n‫االتصــال عليــه عــدة مــرات ولــم يتجــاوب معنــا هكــذا أجــاب وملــا ظهــر‬\n‫لنــا مــن مجريــات التحقيــق وعــدم كفايــة األدلــة يف توجيــه االتهــام علــى‬\n‫املدعــى عليهمــا فقــط ولكــون بعــض املســروقات وجــدت مــع ‪......‬‬\n‫وحفــظ االتهــام بحقــه ملجــرد دعــواه بأنــه اشــتراها مــن املدعــى عليهمــا‬\n‫كاف يف حفــظ التهمــة علــى املذكــور ولكونــه قــد دعــي‬           ‫ٍ‬       ‫وهــذا غيــر‬\n‫إلــى احلضــور لــإدالء بإفادتــه يف احملكمــة ولــم يتجــاوب وألن املقصــود‬\n‫حتقيــق العدالــة والوصــول للحقيقة وملا جاء يف املادة اخلامســة والعشــرين‬\n‫بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة ‪ ،‬ولــذا فقــد أفهمنــا املدعــي‬\n‫العــام بــأن املعاملــة ســتعاد لهيئــة التحقيــق واالدعــاء العــام إلعــادة فتــح‬\n‫ملــف التحقيــق فيهــا وإحضــار ‪ .............‬وإعــادة التحقيــق معــه ثــم إعــادة‬\n‫املعاملــة لدينــا بعــد إكمــال مــا يلــزم ورفعــت اجللســة إلــى أن يكتــب‬\n‫ويــرد اجلــواب ويف يــوم االثنــن املوافــق ‪1433/11/22‬ه ـ افتتحــت اجللســة‬\n‫وفيهــا حضــر املدعــي العــام واملدعــى عليهمــا وقــد اشــترك معنــا فضيلــة‬\n\n\n                                                                                           ‫‪300‬‬\n\f      ‫القاضــي الشــيخ ‪ .......‬خلفــا لفضيلــة القاضــي الشــيخ ‪ ......‬كونــه انتقــل‬\n      ‫إلــى احملكمــة العامــة باخلــرج وبتــاوة مــا مت ضبطــه يف القضيــة صــادق‬\n      ‫األطــراف عليــه وقــد وردتنــا املعاملــة مــن رئيــس فــرع هيئــة التحقيــق‬\n      ‫واالدعــاء العــام مبنطقــة تبــوك برقــم ‪ 12553‬وتاريــخ ‪1433/8/25‬ه ـ‬\n      ‫ونــص احلاجــة منــه بنــاء علــى طلــب أصحــاب القضــاة إعــادة فتــح ملــف‬\n      ‫التحقيــق يف القضيــة والتحقيــق مــع املدعــو ‪ .....‬عليــه نفيدكــم بأنــه‬\n      ‫وردنــا خطــاب ســعادة مديــر مركز شــرطة اخلالدية رقــم ‪27/3835/28‬‬\n      ‫وتاريــخ ‪1433/8/19‬ه ـ املتضمــن بأنــه تعــذر إحضــار املدعــو ‪ ....‬يف‬\n      ‫الفتــرة احلاليــة وجــرى فــرز أوراق مســتقلة لــه للبحــث عنــه وجــرى التعميم‬\n      ‫عنــه برقــم ‪ 2119‬وتاريــخ ‪1433/8/18‬ه ـ ويف حالــة القبــض عليــه ســوف‬\n      ‫يتــم إعــادة التحقيــق معــه وإشــعاركم بذلــك أ‪.‬هــ‪ ،‬فســألنا املدعــى عليــه‬\n      ‫‪ .......‬عمــا جــاء باعترافــه حتقيقــا فأجــاب قائــا إنــه غيــر صحيــح وقــد‬\n      ‫أخــذ منــي حتــت اإلكــراه وال بينــة لــي علــى ذلــك هكــذا أجــاب فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وإنــكار املدعــى عليهمــا ملــا نســب‬\n      ‫إليهمــا ولكــون املدعــي العــام لــم يقــدم بينــة موصلــة تثبــت إدانــة املدعــى‬\n      ‫عليهمــا ملــا نســب إليهمــا وملــا جــاء باعتــراف املدعــى عليــه ‪ ......‬حتقيقــا‬\n      ‫املتضمــن أنــه يف تاريــخ ‪1432/12/21‬ه ـ كان هــو و ‪ ......‬و ‪ .......‬عنــد‬\n      ‫منــزل املجنــي عليهــا ‪ ......‬وأن ظاهــر دخــل املنــزل وأخــرج منــه بعــض‬\n      ‫اجلــواالت املســروقة ورجوعــه عــن هــذا االعتــراف ودفعــه بأنــه أخــذ منــه‬\n      ‫باإلكــراه ولعجــزه إقامــة بينــة علــى ذلــك وألن رجوعــه شــبهة واحلــدود‬\n      ‫تــدرأ بالشــبهات كمــا قــال املصطفــى صلــى اهلل عليــه وســلم وملــا جــاء‬\n      ‫مبحضــر العــرض والتعــرف املتضمــن تعــرف ‪ ......‬صاحبة املنزل املســروق‬\n      ‫علــى املدعــى عليــه ‪ .....‬وأنــه هــو الشــخص الــذي شــاهدته يف منزلهــا‬\n\n\n‫‪301‬‬\n\f‫وســرق جواالتهــا وملــا جــاء بإقــرار املدعــى عليــه ‪ ......‬بــأن املدعــى عليــه‬\n‫‪ .......‬كان معــه وقــت الســرقة وأنــه كان يقــف عنــد منــزل املجنــي عليها‬\n‫وتســتره علــى ذلــك وإن كان هــذا إقــرارا علــى الغيــر ومعلــوم أن اإلقــرار‬\n‫حجــة علــى صاحبــه إال أنــه يوجــه الشــبهة بحــق املدعى عليه ‪ .......‬بتســتره‬\n‫علــى الســرقة وانتهــاك حرمــة منــزل ‪ .......‬وأمــا مــا جــاء بإفــادة ‪.......‬‬\n‫واتهامــه للمدعــى عليهمــا وتعرفــه عليهمــا فهــذا غيــر مقبــول كونــه‬\n‫محــل تهمــة لوجــود املســروقات معــه وملــا تقــدم فقــد توجهــت الشــبهة‬\n‫بحــق املدعــى عليــه األول ‪ .....‬بالتســتر علــى ســرقة منــزل املجنــي عليهــا‬\n‫‪ .......‬كمــا توجهــت الشــبهة علــى املدعــى عليه ‪ ......‬بســرقة ســت جواالت‬\n‫مــن منــزل ‪ .......‬وانتهــاك حرمــة املنــزل وجلميــع مــا تقــدم فقــد قررنــا مــا‬\n‫يلــي ‪:‬أوال‪ :‬درء حــد الســرقة عــن املدعــى عليــه‪ ........‬ثانيــا‪ :‬تعزيــر املدعــى‬\n‫عليــه األول ‪ .........‬وذلــك بالســجن ملــدة ســنة حتســب مــن تاريــخ إيقافــه‬\n‫علــى ذمــة هــذه القضيــة وجلــده مائــة وخمســون جلــدة مفرقــه علــى ثــاث‬\n‫دفعــات كل دفعــة خمســون جلــدة وبــن كل دفعــة واألخــرى خمســة‬\n‫عشــر يومــا وتعزيــر املدعــى عليــه ‪ ........‬وذلــك بالســجن ملــدة ســنتني‬\n‫حتســب مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة وجلــده ثالثمائــة جلــدة‬\n‫مفرقــة علــى ســت دفعــات كل دفعــة خمســون جلــدة وبــن كل دفعــة‬\n‫واألخــرى خمســة عشــر يومــا وبذلــك حكمنــا وبعرضــه علــى املدعــي‬\n‫العــام واملدعــى عليهمــا قــررا عــدم قناعتهمــا باحلكــم وطلبــا متييــز‬\n‫احلكــم ووعــدا بتقــدمي الئحــة اعتراضيــة فأجيبــوا إلــى طلبهــم وجــرى‬\n‫تســليمهم نســخة مــن احلكــم يف هــذا اليــوم وأفهمــوا مبقتضــى تعليمــات‬\n‫التمييــز وحســبت عليهــم املــدة مــن تاريخــه وبــاهلل التوفيــق وصلــى اهلل‬\n‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف‬\n\n\n                                                                                        ‫‪302‬‬\n\f                                                                          ‫‪1433/11/22‬هـ‬\n      ‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‪ :‬ففــي‬\n      ‫هــذا اليــوم االحــد املوافــق ‪1434/06/04‬ه ـ ويف متــام الســاعة التاســعة‬\n      ‫وخمســة وأربعــون دقيقــة افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن‬\n      ‫محكمــة االســتئناف مبنطقــة تبــوك بخطــاب فضيلــة رئيســها املســاعد‬\n      ‫رقــم ‪ 34490035‬يف ‪1434/03/24‬ه ـ املرفــق بــه قــرار املالحظــة رقــم‬\n      ‫‪ 34168616‬وتاريــخ ‪1434/03/22‬ه ـ الصــادر مــن قضــاة الدائــرة‬\n      ‫اخلماســية لتدقيــق القضايــا اجلزائيــة ‪ ،‬ونــص احلاجــة منــه ‪ :‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه والئحتــه االعتراضيــة وأوراق املعاملــة لوحــظ مــا‬\n      ‫يلــي أو ًال ‪ :‬أن مــا حكــم بــه أصحــاب الفضيلــة جتــاه املدعــى عليــه األول‬\n      ‫‪ .......‬محــل نظــر ألنــه ال توجــد أدلــة ضــده أو قرائــن مبــا ينســب إليــه‬\n      ‫فليــس إقــرار ‪ ،‬ولــم تتعــرف عليــه املــرأة املدعيــة وإمنــا تعرفــت علــى الثانــي‬\n      ‫‪ .......‬وأفــادت بأنــه هــو مــن يدخــل إليهــا وحــده فقــط ‪ ،‬وال يوجــد مــا‬\n      ‫يدينــه إال ذكــره علــى لســان املتهــم ‪ ......‬وال يقبــل قولــه يف ذلــك ‪ ،‬ســيما‬\n      ‫وأنــه لــم ميثــل أمــام احملكمــة ويتجــاوب معهــا ‪ .‬ثاني ـ ًا ‪ :‬عبــر أصحــاب‬\n      ‫الفضيلــة بــدرء احلــد ال يكــون إال بعــد الثبــوت ‪ .‬ملالحظــة ذلــك ‪ ،‬وإحلــاق‬\n      ‫مــا ُيجــرى علــى الضبــط والقــرار وصورتــه حســب التعليمــات ‪ ،‬ومــن ثــم‬\n      ‫إعــادة املعاملــة ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬أ‪ .‬ه ـ عليــه جنيــب أصحــاب الفضيلــة وفقنــا اهلل وإياهــم‬\n      ‫فنقــول مســتعينني بــاهلل مســتمدين منــه العــون والســداد نحــن القاضيــن‬\n      ‫‪........‬و ‪ ......‬بــأن فضيلــة الشــيخ ‪ .......‬املشــارك معنــا يف نظــر هــذه‬\n      ‫القضيــة واحلكــم فيهــا قــد انتقــل عملــه الــى احملكمــة العامــة باخلــرج‬\n      ‫وبنــاء علــى التعليمــات فقــد قررنــا إعــادة كامــل املعاملــة بعــد إكمــال‬\n\n\n‫‪303‬‬\n\f                  ‫الــازم حملكمــة االســتئناف الطــاع أصحــاب الفضيلــة‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‪ :‬ففــي هــذا‬\n‫اليــوم األربعــاء املوافــق ‪1434/11/05‬ه ـ ويف متــام الســاعة العاشــرة‬\n‫والنصــف افتتحــت اجللســة وفيهــا حضــر املدعــي العــام واملدعــى عليهمــا‬\n‫وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف مبنطقــة تبــوك بخطــاب‬\n‫فضيلــة رئيســها املســاعد رقــم‪ 34830171‬وتاريــخ ‪1434/7/10‬ه ـ‬\n‫واملرفــق بهــا قــرار املالحظــة رقــم ‪ 34251502‬وتاريــخ ‪1434/06/26‬ه ـ‬\n‫الصــادر مــن الدائــرة اخلماســية ونــص احلاجــة منــه ‪:‬وباالطــاع علــى‬\n‫مــا أجــاب بــه أصحــاب الفضيلــة القضــاة علــى قــرار الدائــرة رقــم‬\n‫‪ 34168616‬وتاريــخ ‪1434/3/22‬ه ـ تقــرر الدائــرة اشــتراك فضيلــة‬\n‫‪ ......‬املنقــول أو القائــم بعملــه يف نظــر القضيــة بعاليــة بنــاء علــى املــادة‬\n‫التاســعة والثمانــون بعــد املائــة مــن نظــام املرافعــات الشــرعية ملالحظــة‬\n‫ذلــك واحلــاق مــا يجــري علــى الضبــط والقــرار وصورتــه حســب التعليمات‬\n‫ومــن ثــم اعــادة املعاملــة أ‪ .‬ه ـ وقــد اشــترك معنــا يف نظــر القضيــة فضيلــة‬\n‫الشــيخ ‪......‬خلفــا لفضيلــة الشــيخ ‪ .......‬يف املشــترك القضائــي ثــم جــرى‬\n‫تــاوة مــا مت ضبطــه يف القضيــة فصــادق األطــراف عليــه وعليــه جنيــب‬\n‫أصحــاب الفضيلــة وفقنــا اهلل وإياهــم للحــق وإصابتــه فنقــول مســتعينني‬\n‫بــاهلل مســتمدين منــه العــون والســداد جوابــا عــن املالحظــة األولــى ‪:‬أنــه‬\n‫قــد ذكرنــا يف تســبيب احلكــم أن املدعــى عليــه ‪ .....‬قــد توجهــت إليــه‬\n‫التهمــة بالتســتر علــى ســرقة بيــت املجنــي عليهــا ‪......‬بنــاء علــى مــا جــاء‬\n‫بإقــرار املدعــى عليــه ‪ .....‬بــأن املدعــى عليــه ‪ .......‬كان معــه عنــد منــزل‬\n‫املجنــي عليهــا وقــت الســرقة وهــذا اإلقــرار وإن كان علــى الغيــر اال أنــه‬\n‫يوجــه التهمــة بحــق املدعــى عليــه ‪ .....‬بالتســتر علــى جرميــة الســرقة وأمــا‬\n\n\n                                                                                        ‫‪304‬‬\n\f      ‫اجلــواب عــن املالحظــة الثانيــة ولوجاهــة مــا ذكــره أصحــاب الفضيلــة‬\n      ‫فإنــه لــم يثبــت لدينــا إدانــة املدعــى عليهمــا مبــا نســبه اليهمــا املدعــي‬\n      ‫العــام وإمنــا توجهــت الــى املدعــى عليــه األول ‪ .....‬بالتســتر علــى ســرقة‬\n      ‫بيــت املجنــي عليهــا ‪ ......‬كمــا توجهــت التهمــة بحــق املدعــى عليــه ‪......‬‬\n      ‫بســرقة ســت جــواالت مــن منــزل ‪ .....‬وانتهــاك حرمــة املنــزل ومــا قررنــا‬\n      ‫مــن عقوبــة تعزيريــة بحــق املدعــى عليهمــا نــرى أنــه كاف هــذا مــا لــزم‬\n      ‫جوابــا علــى مالحظــات أصحــاب الفضيلــة ولهــم منــا فائــق التقديــر‬\n      ‫واالحتــرام وقررنــا إعــادة كامــل املعاملــة حملكمــة االســتئناف بتبــوك‬\n      ‫بعــد إكمــال الــازم لتدقيــق احلكــم حســب املتبــع وبــاهلل التوفيــق‬\n                   ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ :‬اطلعن ــا نحــن قـض ــاة الدائ ــرة اخلماســية لتدقيــق‬\n      ‫القضايــا اجلزائيــة يف محكمــة االســتئناف مبنطقــة تبــوك علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بتبــوك برقــم‬\n      ‫‪34830171‬وتاريــخ ‪1434/11/9‬ه ـ ‪ ،‬املرفــق بهــا القــرار الصــادر مــن‬\n      ‫أصحــاب الفضيلــة القضــاة يف احملكمــة الشيخ‪،.......‬والشــيخ‪........‬‬\n      ‫والشــيخ ‪ .........‬برقــم ‪ 33462191‬وتاريــخ ‪1433/11/22‬ه ـ ‪ ،‬واخلاصــة‬\n      ‫بدعــوى املدعــي العــام ضــد ‪ .........‬ورفيقــه يف قضيــة ســرقة علــى النحــو‬\n      ‫املوضــح يف القــرار ‪ ،‬واملتضمــن حكــم أصحــاب الفضيلــة مبــا هــو‬\n      ‫مــدون ومفصــل فيــه‪ .‬وباالطــاع علــى مــا أجــاب بــه أصحــاب الفضيلــة‬\n      ‫القضــاة علــى قــرار الدائــرة رقــم ‪ 34251502‬وتاريــخ ‪1434/6/26‬ه ـ‬\n      ‫ورقــم‪ 34168616‬وتاريــخ ‪1434/3/22‬ه ـ قررنــا املصادقــة علــى احلكم‬\n      ‫بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                 ‫آلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪305‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":291,"source_page_end":305,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1579716183adf7f4ec4dfbd725e41fba95bc9c8f607c72d51a391387b027a3eb","normalized_text_hash":"3fc7b51bb14a46699bcdac4f226aa07ce0af7bbefa4e300f5fc25a503add87d0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p291-33462191"},{"id":"3dae3dad-11fc-5c14-8bd2-ffb2f4db8d98","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة بعض محتويات منزل -انتهاك حرمة منزل -حدث- سرقة مال محترم من حرز بالغ النصاب -رجوع عن إقرار مصدق شرعا-عدم وجود سوابق -درء حد السرقة -تعزير بالسجن واجللد.","document_number":"33217509","case_number":"33272554","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة املساعد بتبوك ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/27","year":"1434","subject":"سرقة -سرقة بعض محتويات منزل -انتهاك حرمة منزل -حدث- سرقة مال محترم من حرز بالغ النصاب -رجوع عن إقرار مصدق شرعا-عدم وجود سوابق -درء حد السرقة -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 33217509:‬تاريخه ‪1433/4/27:‬هـ‬\n                    ‫رقم الدعوى ‪33272554:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 3439716‬تاريخه‪1434/2/17 :‬ه‬\n\n\n\n‫ســرقة ‪ -‬ســرقة بعــض محتويــات منــزل ‪ -‬انتهــاك حرمــة منــزل ‪ -‬حدث‪-‬‬\n‫ســرقة مــال محتــرم مــن حــرز بالــغ النصــاب‪ -‬رجــوع عــن إقــرار مصــدق‬\n‫شــرعا‪-‬عدم وجــود ســوابق‪ -‬درء حــد الســرقة‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫‪ -‬قول النبي صلى اهلل عليه وسلم‪ ( :‬ادرؤوا احلدود بالشبهات )‪.‬‬\n\n\n\n\n‫دعــوى املدعــي العــام ضــد املدعــى عليهمــا باالشــتراك بانتهــاك حرمــة‬\n‫منزلــن وســرقة مبلــغ مالــي وجهــاز حاســب آلــي وســرقة كاميرتــن‬\n‫وجهــاز جــوال مــن مدرســة ابتدائيــة وجهــاز أم بــي ثــري وســرقة نظــارة‬\n‫شمســية وعــدة وســيديات وكســر درج ســيارة وســرقة مالبــس وأشــمغة‬\n‫مــن مغســلة مالبــس وطلــب املدعــي العــام إقامــة حــد الســرقة ‪،‬مت القبض‬\n‫علــى املدعــى عليهمــا بعــد بالغــات مفادهــا تعــرض مدرســة وســيارات‬\n‫ومســاكن للســرقة ومت جمــع املعلومــات وبالبحــث والتحــري مت القبــض‬\n‫علــى املدعــى عليهمــا وباســتجوابهما صادقــا علــى مــا نســب إليهمــا‬\n‫وصــدق إقرارهمــا شــرع ًا ‪،‬أنكــر املدعــى عليهمــا الدعــوى ‪،‬رجــع‬\n‫املدعــى عليهمــا عــن اإلقراريــن املنســوبني إليهمــا ‪ ،‬درء حــد الســرقة عــن‬\n‫املدعــى عليهمــا ‪ ،‬حكمــت احملكمــة بتعزيرهمــا بالســجن واجللــد ‪ ،‬مت‬\n\n                                                                                   ‫‪306‬‬\n\f                                     ‫تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعده‪..‬وبعــد بنــاء‬\n      ‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة املســاعد‬\n      ‫بتبــوك برقــم ‪ .......‬وتاريــخ ‪......‬املقيــدة باحملكمــة العامــة بتبــوك برقــم‬\n      ‫‪ .......‬وتاريــخ‪ ........‬واحملالــة إلــى احملكمــة مــن فــرع هيئــة التحقيــق‬\n      ‫واالدعــاء العــام مبنطقــة تبــوك برقــم ‪ ....‬يف‪.......‬ه ـ ففــي يــوم الثالثــاء‬\n      ‫املوافق‪.........‬فتحــت اجللســة الســاعة ‪ 10:00‬لدينــا نحــن القضــاة‬\n      ‫باحملكمــة العامــة بتبــوك ‪ ..........‬و‪ ...........‬و‪ ......‬وفيهــا حضــر املدعــي‬\n      ‫العــام ‪ ......‬حامــل الســجل املدنــي رقــم ‪ ......‬صــادر مــن تبــوك واملكلــف‬\n      ‫باإلدعــاء يف هــذه احملكمــة مبوجــب كتــاب مديــر فــرع هيئــة التحقيــق‬\n      ‫واإلدعــاء العــام مبنطقــة تبــوك رقــم‪ .....‬يف‪ .........‬ه ـ وقــدم كتابــه‬\n      ‫املتضمــن بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة‬\n      ‫مبنطقــة تبــوك أدعــي علــى احلاضريــن معــي ‪ ...... -1‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ......-2 ......‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ......‬فبتاريــخ ‪ ......‬تقــدم املواطن‪-،......‬يعمــل‬\n      ‫مــدرس‪ -‬ببــاغ لــدى مركــز شــرطة ‪ ....‬مفــاده تعــرض غرفــة مصــادر‬\n      ‫التعليــم ملدرســة ‪ ......‬للســرقة حيــث ســرق منهــا كاميرتــن فيديــو مــن‬\n      ‫نــوع ‪ ....‬ويدعــى علــى احلــدث ‪ .....‬بســرقتها ‪ .‬وباالنتقال واملعاينة للمدرســة‬\n      ‫تبــن أنهــا مدرســة ابتدائيــة تقــع بقريــة وهــي عبــارة عــن مبنــى يتكــون‬\n      ‫مــن دوريــن وكانــت الغرفــة بطــول ‪ 6،6‬م تقريب ـ ًا وتبــن أن اجلانــي دخــل‬\n\n‫‪307‬‬\n\f‫مــن أحــد النوافــذ ولــم يالحــظ أي شــي خــاف ذلــك ومت تصويــر املوقــع‬\n‫ورفــع البصمــات ‪ .‬وبتاريــخ ‪../../14‬ه ـ تقــدم املواطــن املجنــي عليــه‪/‬‬\n‫‪، ...................‬بشــكوى لــدى مركــز شــرطة ‪ ....‬مفادهــا أنــه بتاريــخ‬\n‫‪ ..........‬تعرضــت ســيارته نــوع ‪ .....‬حتمــل اللوحــة رقــم (‪ ) ... ....‬للســرقة‬\n‫حيــث ســرق منهــا جهــاز أم بــي ثــري ونظــارة شمســيه وأفــاد بــأن الســيارة‬\n‫كانــت مقفلــة واليدعــى علــى أحــد ًا بالســرقة ‪ .‬وتقــدم املواطــن املجنــي‬\n‫عليــه‪ ،....... .... /‬بشــكوى مفادهــا أنــه بتاريــخ ………‪.‬ه ـ تعرضــت‬\n‫ســيارته نــوع …‪ ..‬موديــل (‪ ).....‬حتمــل اللوحــة رقــم (…‪ )… .‬للســرقة‬\n‫حيــث ســرق منهــا مبلــغ (…) ريــال وســيديات وكســر درج الســيارة‬\n‫وســرقة مبلــغ (‪ )...‬ريــا ًال كمــا أفــاد بــأن الســيارة كانــت مقفلة واليدعى‬\n‫علــى أحــد ًا بالســرقة‪ .‬وتقــدم املواطــن املجنــي عليــه ‪ ............./‬بشــكوى‬\n‫مفادهــا أنــه بتاريخ‪........‬ه ـ تعرضــت ســيارته نــوع ‪ ......‬موديــل (‪)....‬‬\n‫للســرقة حيــث ســرق منهــا مجموعــة مفــكات ونظــارة واليدعــى علــى‬\n‫أحــد ًا بالســرقة ‪ .‬وبتاريــخ ‪ .........‬تقــدم املقيــم املجنــي عليــه‪......./‬‬\n‫بشــكوى مفادهــا تعــرض شــقته للســرقة حيــث وجــد حقيبــة جهــاز‬\n‫احلاســب اآللــي مفتوحــة ومت بعثــرة مــا بداخلهــا ووجــد آثــار أقــدام يف‬\n‫الصالــة وعصــا خشــبية أمــام غرفــة النــوم وكانــت فتحــة املكيــف‬\n‫مكســورة وأفــاد بأنــه مت ســرقة جهــاز جــوال (‪ ) ...‬ومبلــغ مالــي قــدره‬\n‫(‪ )...‬خمســمائة وخمســن ريــا ًال كانــت موجــودة داخــل محفظتــه وال‬\n‫يدعــى علــى أحــد ًا بالســرقة ‪ .‬وباالنتقــال واملعاينــة تبــن أنهــا تقــع يف‬\n‫عمــارة مكونــة مــن دوريــن وأن الشــقة رقــم (‪ )1‬الواقعــة بالــدور األرضــي‬\n‫هــي التــي تعرضــت للســرقة وتبــن دخــول اجلنــاة عــن طريــق نافــذة‬\n‫املكيــف التــي كانــت مغطــاة بلــوح خشــبي ولــم يوجــد آثــار بعثــرة داخــل‬\n\n\n                                                                                     ‫‪308‬‬\n\f      ‫الشــقة ‪ .‬وبتاريــخ ‪ .........‬تقــدم املقيــم املجنــي عليــه‪،............. /‬بشــكوى‬\n      ‫مفادهــا تعــرض شــقته للســرقة حيــث ســرق منهــا جهــاز حاســب آلــي‬\n      ‫محمــول نــوع (‪ )...‬وذاكــرة جــوال (فــاش ميمــوري) (‪ )4‬جيجــا وعنــد‬\n      ‫تفقــده لشــقته وجــد مفتــاح علــى غــاز املطبــخ وكان شــباك املطبــخ‬\n      ‫ا وأفــاد بــأن قيمــة‬ ‫مفتوح ـ ًا كمــا أفــاد بــأن بــاب الشــقة كان مقف ـ ً‬\n      ‫احلاســب اآللــي (‪ )1000‬ألــف ريــال واليدعــى علــى أحــد ًا بالســرقة ‪ .‬وقــد‬\n      ‫ورد محضــر التحــري والقبــض بتاريــخ ‪.......‬الصــادر مــن البحــث اجلنائــي‬\n      ‫بتبــوك املتضمــن أنــه مت جمــع معلومــات عــن األشــخاص املشــبوهني ومــن‬\n      ‫لهــم ســوابق يف قضايــا ســرقات وقــد توفــرت معلومــات عــن قيــام احلــدث‬\n      ‫‪ ........../‬واحلــدث ‪، ........... /‬واحلــدث‪ ،......../‬بســرقة تلــك املســروقات‬\n      ‫فتــم اســتدعاء احلــدث‪ ،......../‬مــن قبــل والــده ومت إيداعــه الــدار بتاريــخ‬\n      ‫ـاء علــى توجيــه فضيلــة قاضــي االحــداث‬          ‫‪............‬ومــازال موقوف ـ ًا بنـ ً‬\n      ‫أســتناد ًا للمــادة (‪ )13‬مــن نظــام االجــراءات اجلزائيــة‪ .‬وبســماع أقــوال‬\n      ‫احلــدث ‪، ........... /‬أفــاد بأنــه أخبــره كل مــن احلــدث ‪، ........ /‬‬\n      ‫واحلــدث‪ ،............../‬أن احلــدث‪ .........../‬واملتهــم الهــارب ‪، ........... /‬همــا‬\n      ‫من قاما بســرقة احلاســب اآللي من شــقة املقيم ‪ .... /‬وأنه قبل أســبوعني‬\n      ‫تقريب ـ ًا إلتقــى باملتهــم الهــارب ‪، .......... /‬عنــد املستشــفى وطلــب منــه‬\n      ‫الذهــاب معــه لســرقة مغســلة املالبــس فرفــض ذلــك فذهــب املتهــم‬\n      ‫الهــارب‪ ...../‬إلــى منــزل احلــدث‪ ........../‬كمــا أفــاد احلــدث ‪،........... /‬‬\n      ‫أنــه بعــد يومــن إلتقــى باملتهم الهــارب‪................. /‬واحلــدث‪ ......../‬وكانا‬\n      ‫راكبــن ســيارة ‪ .....‬بقيــادة املتهــم الهــارب ‪ ....... /‬وكان يرتــدي ثوب ـ ًا‬\n      ‫جديــد ًا وطلبــا منــه مرافقتهمــا للحديقــة فرفــض ذلــك كمــا أفــاد احلــدث‬\n      ‫‪ ،............ /‬بأن املتهم الهارب ‪..... /‬ذكر له بأنه قام هو واحلدث‪،......../‬‬\n\n\n‫‪309‬‬\n\f‫بســرقة مغســلة املالبــس التــي بعمــارة ‪ ..........‬حيــث قامــا بســرقة مالبــس‬\n‫وثــاث أشــمغة ‪.‬وباســتجواب احلــدث‪ ،......../‬أقــر بقيامــه بســرقة شــقة‬\n‫املقيــم ‪ .... /‬وشــاركه يف ذلــك احلــدث الهــارب‪، .......... /‬حيــث قامــا‬\n‫بدخــول الشــقة عــن طريــق فتحــة املكيــف وقــام بســرقة جهــاز جــوال‬\n‫(‪ )...‬وقــام احلــدث ‪ ... /‬بســرقة مبلــغ(‪ )550‬خمســمائة وخمســن ريــا ًال ثــم‬\n‫خرجــا مــن الشــقة عــن طريــق البــاب ثــم قامــا ببيــع جهــاز اجلــوال يف محــل‬\n‫اجلــواالت مببلــغ (‪ )320‬ثالثمائــة وعشــرين ريــا ًال وتقاســما املبلغ املســروق‬\n‫وكذلــك مبلــغ قيمــة اجلــوال كمــا أفــاد بأنــه اتفــق مــع احلــدث ‪........./‬‬\n‫‪،‬علــى ســرقة شــقة املقيــم ‪، ....... /‬حيــث قــام هــو باجللــوس يف احلــوش‬\n‫للمراقبــة بينمــا قــام احلــدث ‪ ،... /‬بدخــول الشــقة عــن طريــق تســلق‬\n‫املواســير والدخــول مــن النافــذة وجلــس عشــر دقائــق ثــم خــرج مــن نفــس‬\n‫النافــذة التــي دخــل منهــا ومعــه جهــاز احلاســب اآللــي احملمــول ثــم قــام هــو‬\n‫بأخــذ جهــاز احلاســب اآللــي احملمــول وأعطــى احملــدث ‪، .... /‬مبلــغ (‪)50‬‬\n‫خمســن ريــا ًال كمــا أفــاد احلــدث‪ ،.........../‬بأنــه عندمــا كان جالس ـ ًا‬\n‫بســطح منزلهــم شــاهد احلــدث‪ ،.......... /‬وهــو يقــوم بســرقة ســيارة‬\n‫جارهــم وهــي مــن نــوع ‪ .......‬وســرق منهــا جهــاز (أم بــي ثــري) ونظــارة‬\n‫شمســية ومبلــغ (‪ )60‬ســتني ريــا ًال وأخــذ هــو جهــاز (أم بــي ثــري) كمــا‬\n‫أفــاد احلــدث‪ ،.........../‬أنــه بتاريــخ ‪ ...........‬ه ـ وبعــد صــاة العشــاء حضــر‬\n‫لــه احلــدث ‪، ........ /‬وقــام بالركــوب معــه يف ســيارته وشــاهد معــه‬\n‫كامرتــن فيديــو وأخبــره احلــدث ‪، ... /‬بأنــه ســرقهما مــن مدرســة‬\n‫‪ ...........‬وقامــا ببيعهــا علــى املدعــو ‪، ................... /‬مببلــغ قــدره (‪)400‬‬\n‫أربعمائــة ريــال كــم أفــاد بأنــه شــاهد احلــدث ‪، ..../‬أثنــاء قيامــه بســرقة‬\n‫املالبــس مــن املغســلة وكاميرتــي الفيديــو مــن مدرســة ‪ ....‬اإلبتدائيــة‬\n\n\n                                                                                          ‫‪310‬‬\n\f      ‫وأنكر قيامه بســرقة بقية املســروقات وقد قام احلدث‪ ... /‬واحلدث‪...../‬‬\n      ‫‪،‬بالداللــة علــى منزلــي املقيمــن‪، ......../‬و‪، ........./‬وكيفيــة قيامهمــا‬\n      ‫بالســرقة‪( .‬وبالبحــث يف ســجالته لــدى دار املالحظــة اإلجتماعيــة بتبوك‬\n      ‫تبــن وجــود ســابقتني األولــى ســرقة ســيارة والثانيــة ســرقة)‪ .‬وباســتجواب‬\n      ‫احلــدث‪، ............ /‬أفــاد بأنــه اتفــق مــع احلــدث ‪ ،........./‬علــى ســرقة شــقة‬\n      ‫املقيــم ‪ ..../‬حيــث قــام احلــدث ‪، ....../‬بتســلق املواصيــر ودخــل عــن طريــق‬\n      ‫النافــذة وبعــد مضــي عشــر دقائــق خــرج ومعــه جهــاز احلاســب اآللــي‬\n      ‫احملمــول وقــام بإعطائــه احلــدث‪، .../‬ثــم قــام احلــدث ‪،......../‬بدخــول‬\n      ‫شــقة املقيــم ‪، ..../‬يف املوجــودة بالعمــارة التــي بهــا شــقة املقيــم‪، ..../‬عــن‬\n      ‫طريــق فتحــة املكيــف ثــم خــرج ومعــه مبلــغ قــدره (‪ )500‬خمســمائة‬\n      ‫ريــال وجهــاز جــوال نــوع (‪ )......‬بينمــا كان دور احلــدث‪، .../‬يقــوم‬\n      ‫باملراقبــة وأفــاد بأنهمــا قامــا ببيــع جهــاز اجلــوال علــى أحــد محــات بيــع‬\n      ‫اجلواالت كما أفاد بأنهما قاما بســرقة ســيارة نوع ‪ .......‬تعود ملكيتها‬\n      ‫للمواطــن‪ ...... /‬أثنــاء توقفهــا حيــث ســرقا منهــا مبلــغ (‪ )60‬ســتني ريــال‬\n      ‫وجهــاز (أم بــي ثــري) وســيديات كمــا أفــاد بأنهمــا قامــا بســرقة مغســلة‬\n      ‫مالبــس الواقعــة باملخطــط حيــث ســرقا منهــا ثــاث ثيــاب وثــاث أشــمغة‬\n      ‫كمــا أفــاد بأنهمــا قامــا بســرقة كاميرتــن فيديــو مــن مدرســة ‪.....‬‬\n      ‫االبتدائيــة والقــط وكرتــون عصيــر وقــام احلــدث ‪ ، ....../‬ببيعهــا علــى‬\n      ‫املواطــن‪ ،............ /‬مببلــغ (‪ )400‬أربعمائــة ريــال‪ .‬وبســماع أقــوال املقيم‪/‬‬\n      ‫‪ ،........‬بنجالديشــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪)..........‬‬\n      ‫أفــاد بأنــه يف شــهر (‪ )..‬مــن عــام ‪....‬ه ـ تعرضــت مغســلة املالبــس التــي‬\n      ‫يعمــل بهــا للســرقة حيــث ســرق منهــا بعــض املالبــس ال يعــرف عددهــا‬\n      ‫بالضبــط وال يعــرف اجلنــاة كمــا أفــاد بأنــه لــم يتقــدم ببــاغ بالواقعــة يف‬\n\n\n‫‪311‬‬\n\f‫حينــه‪ .‬وبســماع أقــوال املواطــن‪ ،.......... /‬أفــاد بــأن احلــدث ‪........ /‬‬\n‫‪،‬حضــر إليــه باملنــزل وعــرض عليــه شــراء كاميرتــن فيديــو األولــى‬\n‫مســتعملة والثانيــة جديــدة وذكــر لــه احلــدث‪، ... /‬بــأن الكاميرتــن‬\n‫تعــود ألهلــه وأنهــم محتاجــن للمــال فقــام املواطــن‪، ... /‬بشــراء‬\n‫الكاميرتــن مببلــغ (‪ )1000‬ألــف ريــال فقــام بإعطائــه مبلــغ (‪)200‬‬\n‫مائتــن ريــال والباقــي آخــر الشــهر كمــا أفــاد بأنــه عندمــا علــم بــأن‬\n‫احلــدث‪ ،... /‬قــام بســرقة الكاميرتــن مــن املدرســة قــام بتســليمها‬\n‫ملركــز الشــرطة ‪ .‬ومت عــرض الكاميرتــن علــى املواطــن ‪،........../‬‬\n‫وأفــاد بــأن الكاميرتــن همــا اللتــان ســرقتا مــن املدرســة وســلمتا لــه‪.‬‬\n‫ومت ‪ ..‬جهــاز احلاســب اآللــي احملمــول للمقيــم ‪ ،......../‬وهــو بحالــة ‪...‬‬\n‫وبلغــت قيمــة املســروقات (‪ )1170‬ألــف ومائــة وســبعون ريــال‪( .‬مت فــرز‬\n‫أوراق مســتقلة للحــدث الهــارب‪ ................/‬وأنتهــى التحقيــق الــى توجيــه‬\n‫االتهــام للحــدث ‪ ....................‬وللحــدث ‪ ،.......‬باالشــتراك بانتهــاك‬\n‫حرمــة منزلــي املقيمــن‪ ،...........‬و‪،.........‬وســرقة جهــاز (‪ )....‬ومبلــغ‬\n‫(‪ )550‬خمســمائة وخمســن ريــا ًال وجهــاز احلاســب اآللــي احملمــول نــوع‬\n‫(‪ )....‬وقيامــه بســرقة كاميرتــن نــوع ‪ ......‬مــن املدرســة االبتدائيــة ب‪......‬‬\n‫وســرقة جهــاز (إم بــي ثــري ) ونظــارة شمســية مــن ســيارة املواطــن‪،.........‬‬\n‫وســرقة عــدة ونظــاره شمســيه مــن ســيارة املواطــن‪ ،.........‬وســرقة‬\n‫ســيديات ومبلــغ (‪ )120‬مائــة وعشــرون ريــا ًال وكســر درج ســيارة‬\n‫املواطــن ‪، .....‬وســرقة مالبــس وأشــمغة مــن مغســلة مالبــس حيــث بلغــت‬\n‫قيمــة املســروقات (‪ )1170‬ألــف ومائــة وســبعني ريــال‪ .‬وذلــك لألدلــة‬\n                                                                ‫والقرائن التالية ‪:‬‬\n‫‪ -1‬اعترافهمــا املصــدق شــرعا املــدون علــى الصفحــة رقــم (‪ )....‬مــن‬\n\n\n                                                                                     ‫‪312‬‬\n\f      ‫دفتــر التحقيــق املرفــق لفــه رقــم (‪ )...‬ومــا جــاء باعترافهمــا املــدون علــى‬\n      ‫الصفحــة رقــم (‪ )...‬مــن دفتــر احلقيــق املرفــق لفــه رقــم (‪ ).......‬ومــا جــاء‬\n      ‫بأقــوال احلدث‪........‬املدونــة الصفحــة رقــم (‪ )....‬مــن دفتــر التحقيــق‬\n                                                                      ‫املرفــق لفــة رقــم (‪.)..‬‬\n      ‫‪ -2‬محاضــر االنتقــال واملعاينــة املنــوه عنهــا املدونــة علــى الصفحــة رقــم‬\n      ‫(‪ )..‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪ )..‬والصفحــة رقــم (‪ ).‬مــن دفتــر‬\n                                                            ‫التحقيــق املرفــق لفــة رقــم (‪.).‬‬\n      ‫‪ -3‬مــا جــاء بأقــوال عامــل املغســلة املــدون علــى الصفحــة رقــم (‪ )..‬مــن‬\n                                                   ‫دفتــر التحقيــق املرفــق لفــة رقــم(‪.)..‬‬\n      ‫‪ -4‬مــا جــاء بأقــوال احلــدث …………‪ ..‬املــدون علــى الصفحــة رقــم(‪).‬‬\n                                           ‫مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪.)....‬‬\n                      ‫‪ -5‬ما جاء يف تقرير البحث والتحري املرفق لفة رقم (‪.)....‬‬\n      ‫‪ -6‬مــا جــاء يف تناقــض أقــوال احلــدث ‪........‬مــع احلــدث اآلخــر…‪ .‬حيــث‬\n      ‫ذكــر احلــدث … بــأن ‪ ....‬هــو مــن قــام بتســلق منــزل املقيــم ‪ ...‬وســرقته‬\n      ‫وأن دوره كان املراقبــة فقــط وأنــه لــم يقــم بســرقة مغســلة املالبــس‬\n                                  ‫وســيارة جــاره‪ ......‬وأن ‪ ....‬هــو مــن قــام بذلــك يف‬\n      ‫حــن ذكــر احلــدث ‪...‬بــأن احلــدث ‪ ...‬هــو مــن قــام بتســلق منــزل املقيــم‪...‬‬\n      ‫وســرقته وأن دوره هــو املراقبــة وأنــه قــام مبشــاركة‪ ...‬يف ســرقة مغســلة‬\n      ‫املالبــس وســيارة ‪ .........‬املــدون علــى الصفحتــن رقــم (‪ )5-4‬مــن دفتــر‬\n                                                                                     ‫التحقيــق‪.‬‬\n      ‫‪ -7‬مــا جــاء مبحضــر التعــرف علــى بعــض املســروقات املــدون علــى‬\n              ‫الصفحــة رقــم (‪ )7‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪.)28‬‬\n      ‫‪ -8‬مــا جــاء مبحضــر الداللــة املنــوه عنــه املرفــق لفــة رقــم (‪)13-12‬‬\n\n\n‫‪313‬‬\n\f‫مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪.)32‬وحيــث أن ماقــام بــه احلدثــن‬\n‫املذكوريــن فعــل محــرم ومعاقــب عليــه شــرعا وهــو ســرقة مــال محتــرم‬\n‫مــن حــرزه بالــغ النصــاب ال شــبهة فيــه وهمــا مكلفــن غيــر مكرهــن‬\n                                                             ‫لــذا أطلــب مايلــي‪-:‬‬\n                                                        ‫‪-1‬إثبات ما أسند إليه ‪.‬‬\n‫‪-2‬احلكــم عليــه بحــد الســرقة الــواردة يف اآليــة الكرميــة رقــم (‪ )38‬مــن‬\n                                                                    ‫ســورة املائــدة ‪.‬‬\n                           ‫( علما بأن جميع احلقوق اخلاص انتهت بالتنازل )‪.‬‬\n‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليهمــا أجابــا بقولهمــا‬\n‫مــا ذكــره املدعــي العــام ال صحــة لــه جملــة وتفصيــا ونحــن أعترفنــا‬\n‫باالكــراه هكــذا أجابــا وبعــرض إجابتهــم علــى املدعــي العــام قــال‬\n‫الصحيــح مــا جــاء يف دعــواي وأطلــب الرجــوع إلــى األدلــة التــي ذكرتهــا‬\n‫يف املعاملــة عليــه رفعــت اجللســة للرجــوع إلــى أدلــة املدعــي العــام وصلــى‬\n                           ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n‫ويف جلســة أخــرى افتتحــت اجللســة وفيهــا حضــر املدعــي العــام واملدعــى‬\n‫عليهمــا وبالرجــوع إلــى أوراق املعاملــة وجدنــا أدلــة املدعــي العــام تتمثــل‬\n‫يف اآلتي‪-1:‬اعترافهمــا املصــدق شــرع ًا املــدون علــى الصفحــة رقــم(‪-4‬‬\n‫‪ )7‬مــن دفتــر التحقيــق املرفــق لفــه رقــم (‪ )21‬ومــا جــاء باعترافهمــا‬\n‫املــدون علــى الصفحــة رقــم (‪)5-4‬مــن دفتــر التحقيــق املرفــق لفــه رقم(‪)5‬‬\n‫ومــا جــاء بأقــوال احلــدث‪ .../‬املدونــة علــى الصفحــة رقــم(‪ )11‬مــن دفتــر‬\n‫التحقيــق املرفــق لفــه رقــم(‪. )53‬ونصــه إقــرار بتاريــخ ‪../12/4‬ه ـ أقــر أنا‬\n‫احلــدث ‪.............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪............‬‬\n‫أســكن مبحافظــة ‪ ...‬وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا‬\n\n\n                                                                                         ‫‪314‬‬\n\f      ‫وبطوعــي وأختيــاري وبــدون أجبــار أو اكــراه مــن أحــد بأنــه قبــل حوالــي‬\n      ‫ا أتفقــت انــا وصديقــي ‪ ............‬بــأن نذهب‬    ‫أســبوعني يف يــوم االربعــاء ليـ ً‬\n      ‫إلــى منــزل الدكتــور املصــري فذهبنــا حتــى وصلنــا الــى املنــزل ودخلنــا‬\n      ‫املنــزل عبــر فتحــة املكيــف بعــد كســر خشــب املكيــف وقمــت أنــا‬\n      ‫باحلصــول علــى جهــاز جــوال ‪ ......‬وقمــت بســرقته وقــام صديقــي باحلصول‬\n      ‫علــى مبلــغ مالــي وقــدره(‪ )550‬ريــال وقــام بســرقتها ووضعهــا يف جيبــه‬\n      ‫ومــن ثــم خرجنــا مــن املنــزل عــن طريــق البــاب وبالنســبة للمســروقات‬\n      ‫األخــرى أنــا لــم أقــم باالشــتراك بهــا والأعلــم عنهــا شــي علمـ ًا بــأن اجلهــاز‬\n      ‫اجلــوال الــذي قمــت بســرقته قمنــا ببيعــه أنــا وصديقــي‪ ...‬مببلــغ(‪)320‬‬\n      ‫ريــال وقــد تقاســمنا املبلــغ وهــذا أقــرار صريــح منــي مبــا حصــل وعليــه‬\n      ‫جــرى التوقيع‪.‬أ‪.‬ه ـ إقــرار بتاريخ‪.........‬ه ـ أقــر أنــا احلــدث ‪...............‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ..........‬أســكن محافظــة‬\n      ‫‪ ...‬وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا ولســت مجبــر ًا أو مكــره‬\n      ‫مــن أحــد بــل بطوعــي واختيــاري بأنــه قبــل حوالــي أســبوعني اتفقنــا أنــا‬\n      ‫وصديقــي ‪ ........‬بأننــا نقــوم بســرقة منــزل الدكتــور ‪ ......‬وقمنــا بدخــول‬\n      ‫املنــزل عــن طريــق فتحــة املكيــف الــذي قمنــا بكســره وعنــد دخولنــا‬\n      ‫قــام صديقــي ‪ ........‬بأخــذ اجلــوال ‪ .....‬وانــا قمــت بأخــذ املبلــغ ‪ 550‬ريــال‬\n      ‫وقمنــا باخلــروج مــن املنــزل عــن طريــق البــاب وقمنــا ببيع اجلوال وتقاســمنا‬\n      ‫املبلــغ وكذلــك قمنــا أنــا ‪ .......... ....... .......‬بســرقة منــزل الدكتــور‬\n      ‫‪ .........‬وذلــك عــن طريــق فتحــة املكيــف قمنــا نحــن الثالثــة بالدخــول‬\n      ‫داخــل املنــزل وســرقة الب تــوب واخلــروج مــع نفــس فتحــت املكيــف وان‬\n      ‫الــذي قــام بأخــذ االب تــوب هــو ‪ ...........‬وكذلــك قمنــا بســرقة ســيارة ‪....‬‬\n      ‫أنــا ‪ .......‬وقــام ‪ .. .....‬بكســر زجــاج املثلــث اخللفــي وفتــح البــاب وســرقة‬\n\n\n‫‪315‬‬\n\f‫مابــي داخلهــا مــن األغــراض وهــذا إقــرار صريــح منــي مبــا حصــل وعليــه‬\n‫جــرى التوقيع‪.‬أ‪.‬ه ـ س‪ /‬أنــت متهــم يف ســرقة مالبــس من مغســلة مبركز‬\n‫‪ ...‬ومعــك احلــدث ‪ .........‬ج‪ /‬أننــي لــم أقــم بــأي ســرقة مــن املغســلة س‪/‬مــن‬\n‫الــذي قــام بســرقة املغســلة ج‪ /‬اننــي ال أعلــم مــن قــام بســرقة املغســلة س‪/‬‬\n‫لقــد ذكــر احلــدث ‪ .....‬يف اعترافــه بأنــك كنــت معه أثناء ســرقة املغســلة‬\n‫وكذلــك ســرقة املدرســة فمــا قولــك بذلــك ج‪/‬نعــم أننــي كنــت معــه أم‬\n‫أثنــاء ســرقة املغســلة واملدرســة لــم أكــن معــه س‪ /‬لقــد أعتــرف املواطــن‬\n‫‪ ........‬بأنــه أشــترى الكاميــرات مــن احلــدث ‪ ...........‬فمــا قولــك يف ذلــك‬\n‫ج‪/‬نعــم لقــد أخبرنــي احلــدث ‪ .........‬بذلــك بأنــه بــاع الكاميــرات علــى‬\n‫املواطــن ‪ ..........‬س‪ /‬هــل تصــادق علــى اقوالــك ج‪/‬نعــم أ‪.‬ه ـ ‪-2‬محاضــر‬\n‫االنتقــال واملعاينــة املنــوه عنهــا املدونــة علــى الصفحــة رقــم (‪ )6‬مــن دفتــر‬\n‫التحقيــق املرفــق لفــه رقــم(‪ )1‬والصفحــة رقــم (‪ )1‬مــن دفتــر التحقيــق‬\n‫املرفــق لفــه رقــم (‪ )3‬ونصــه محضــر أنتقــال ومعاينــة يف‪ ..........‬ه ـ نعــم‬\n‫لقــد جــرى أنتقالنــا نحــن املدونة أســمائنا إلى مدرســة ‪ .....‬ملعاينة الســرقة‬\n‫وبالوقــوف علــى طبيعــة املوقــع وهــي عبــاره عــن مدرســة مــن دوريــن ومت‬\n‫اســتداللنا عــن موقــع الســرقة وهــي عبــارة عــن غرفــة مكتبــة املدرســة‬\n‫ومت معاينــة املوقــع جيــد ًا ومت العثــور علــى مدخــل اجلاني من أحد شــبابيك‬\n‫املكتبــه ولــم نالحــظ أي شــي خــاف ذلــك ومت تصويــر املوقــع ورفــع‬\n‫البصمــات وعلــى ذلــك نوقع‪.‬أ‪.‬ه ـ محضــر معاينــة‪ .‬مبعرفتــي انــا ضابــط‬\n‫خفــر لهــذا اليوم‪..........‬ه ـ مت معاينــة منــزل املدعــي وتبــن انــه يقــع يف حــي‬\n‫‪ .....‬وهــو عبــارة عــن عمــاره مكونــه مــن أربــع شــقق وهــو يســكن يف‬\n‫الشــقة رقــم (‪ )..‬يف الــدور االرضــي وتبــن دخــول اجلنــاة عــن طريــق نافــذة‬\n‫املكيــف التــي كانــت مغطــاه بلــوح خشــبي بعــد كســر اللــوح اخلشــبي‬\n\n\n                                                                                         ‫‪316‬‬\n\f      ‫ولــم يوجــد أي آثــار بعثــرة داخــل املنــزل وحفــظ للواقــع نظــم هــذا‬\n      ‫احملضر‪.‬أ‪.‬ه ـ ‪-3‬ماجــاء بأقــوال عامــل املغســلة املــدون علــى الصفحــة‬\n      ‫رقــم(‪ )2‬مــن دفتــر التحقيــق املرفــق لفــه رقــم(‪ )54‬نعــم أقــرر انــا‬\n      ‫املقيــم‪ ........../‬بنجالديشــي اجلنســية مبوجــب اإلقامــة رقــم‪............‬‬\n      ‫بأقــراري هــذا وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا وبطوعــي‬\n      ‫واختيــاري بأنــه يف شــهر‪ ..‬مــن العــام ‪....‬ه ـ والأعــرف اليــوم بالتحديــد‬\n      ‫تعرضــت املغســلة التــي أعمــل بهــا للســرقه والعبــث وفقــدت بعــض الثياب‬\n      ‫واملناديــل والأعــرف عددهــا بالضبــط ولــم أقــم بتقــدمي بــاغ بالواقعــة يف‬\n      ‫ال مــن‬‫حينهــا والأعــرف اجلنــاة وأننــي الأرغــب بإقامــة دعــوى ضــد ك ً‬\n      ‫‪.........‬واحلــدث ‪ ........‬وانــا متنــازل عــن حقــي اخلــاص وهــذا إقرارمنــي‬\n      ‫بذلــك وعليــه أوقع‪.‬أ‪.‬هــ‪ -4‬ماجــاء بأقــوال احلــدث‪ ........./‬املــدون علــى‬\n      ‫الصفحــة رقــم(‪ )3‬مــن دفتــر التحقيــق املرفــق لفــه رقم (‪ )5‬محضر ســماع‬\n      ‫أقــوال يف‪............‬نعــم أقــر انــا الغــام‪ ......./‬ســعودي اجلنســية بإقــراري‬\n      ‫ال مــن الغــام ‪ ......‬والغــام ‪ ........‬والغــام ‪.........‬‬\n                                                                ‫هــذا بأنــه أخبرنــي ك َ‬\n      ‫ال ‪ ........‬والغــام ‪ ......‬همــا الذيــن قامــا بســرقة جهــاز الالبتــوب‬ ‫بــأن ك ً‬\n      ‫مــن شــقة املقيــم ‪ ....‬وكذلــك انــه قبــل اســبوعني تقريب ـ ًا قابلنــي الغــام‬\n      ‫‪......‬عنــد املستشــفى باملخطــط وقــال لــي متشــي معــي نســرق مغســلة‬\n      ‫املالبــس فرفضــت وقــال لــي نــاد لــي ‪ ...‬معــك فرفضــت فذهــب للمدعــو‬\n      ‫‪ ......‬ودق عليــه البــاب وأنــا بعدهــا ذهبــت للمنــزل وبعــد يومــن قابلنــي‬\n      ‫‪ ........‬و ‪.......‬املذكــور وأخبرنــي ‪ .....‬بأنهــم هــو و‪ ....‬قــد ســرقوا مــن‬\n      ‫مغســلة املالبــس التــي بعمــارة ‪ ....‬ثيــاب وثبلثــة مناديــل وأننــي ال اعلــم عــن‬\n      ‫باقــي الســرقات أي شــي وهــذا مالــدي وعليــه أوقع‪.‬أ‪.‬ه ـ ‪ -5‬ماجــاء يف‬\n      ‫تقريــر البحــث والتحــري املرفــق لفــه رقــم(‪ )15‬محضــر بحــث وحتــري‬\n\n\n‫‪317‬‬\n\f‫وقبــض بتاريخ‪.........‬ه ـ نظــر ًا لتكــرار الســرقات يف حــي ‪ ......‬وحــي ‪......‬‬\n‫مبركــز ‪ ...‬فقــد جــرى تكليــف أفــراد مــن ذوي الكفــاءات واخلبــرة يف‬\n‫إجــراءات البحــث والتحــري ومت جمــع معلومــات عــن االشــخاص‬\n‫املشــبوهني داخــل تلــك االحيــاء ومــن لهــم ســوابق يف قضايــا الســرقات‬\n‫وقــد توفــرت معلومــات عــن قيــام بعــض االحــداث ببعــض تلــك الســرقات‬\n‫فقــد جــرى نشــر بعــض املصــادر بــن تلــك التجمعــات مــن الشــباب‬\n‫ال مــن ‪..........‬‬\n                ‫وتوفــرت معلومــات بــأن مــن يقــوم بتلــك الســرقات هــم ك ً‬\n‫و‪............‬و‪ ...........‬وقــد مت اســتدعاء أوليــاء أمورهــم وقــد مت احضــار‬\n‫املدعــو‪ .../‬عــن طريــق شــقيقه وبالنســبة للمدعو‪.../‬فقــد مت اســتدعاء‬\n‫والــده اكثــر مــن مــرة ومت إحضــاره ابنــه أمــا بالنســبة للمدعــو‪ ../‬فقــد مت‬\n‫االنتقــال ملنزلــه ولــم جنــده كــون والــده منفصــل عــن والدتــه منــذ ســنتني‬\n‫ال لســياره داخــل‬   ‫ويف هــذا اليــوم املوافــق ‪.....‬ه ـ مت مشــاهدته مســتق ً‬\n‫مركــز ‪ ...‬وعنــد محاولــة اســتيقافه الذا بالفــرار ومتــت متابعتــه حتــى مت‬\n‫القبــض عليــه وحفظـ ًا للواقــع جــرى اعــداد احملضــر ‪.‬أ‪ .‬ه ـ ‪ -6‬مــا جــاء يف‬\n‫تناقــض أقــوال احلــدث ‪...‬مــع احلــدث اآلخــر ‪ ...‬حيــث ذكــر احلــدث ‪..‬بــأن‬\n‫‪ ...‬هــو مــن قــام بتســلق منــزل املقيــم ‪ ...‬وســرقته وأن دوره كان املراقبــة‬\n‫فقــط وأنــه لــم يقــم بســرقة مغســلة املالبــس وســيارة جــاره ‪ ....‬وأن ‪ ...‬هــو‬\n‫مــن قــام بذلــك يف حــن ذكــر احلــدث ‪ ...‬بــأن احلــدث ‪..‬هــو مــن قــام بتســلق‬\n‫منــزل املقيــم ‪ ...‬وســرقه وأن دوره هــو املراقبــه وأنــه قــام مبشــاركة ‪..‬يف‬\n‫ســرقة مغســلة املالبــس وســيارة جــاره ‪ -7 ..‬ماجــاء مبحضــر التعــرف‬\n‫علــى بعــض املســروقات املــدون علــى الصفحــة رقــم (‪ )7‬مــن دفتــر‬\n‫التحقيــق املرفــق لفــه رقــم(‪ )28‬محضــر تعــرف أقــر أنــا املواطــن‪.......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي ‪1042027357‬بإقــراري هــذا‬\n\n\n                                                                                      ‫‪318‬‬\n\f      ‫وأنــا بكامــل قــواي العقليــه املعتبــرة شــرع ًا وبطوعــي واختيــاري بــأن‬\n      ‫الكاميــرات التــي عرضــت علــي وهــي مــن نــوع ‪ .....‬هــي نفــس‬\n      ‫الكاميــرات التــي ســرقت مــن املدرســة بتاريخ‪.....‬ه ـ هــذا إقــراري وعليــه‬\n      ‫أوقــع أ‪ .‬ه ـ ‪ -8‬مــا جــاء مبحضــر الداللــة املنــوه عنــه املرفــق صفحــة رقــم‬\n      ‫(‪ )13-12‬مــن دفتــر التحقيــق املرفــق لفــه رقــم(‪ )32‬محضــر تدليــل‬\n      ‫بتاريــخ ‪.....‬ه ـ ونصــه بتاريخــه أعــاه نحــن املوقعــن أدنــاه جــرى االنتقــال‬\n      ‫ال مــن احلــدث ‪ ............‬واحلــدث ‪ ...........‬رفــق منــدوب دار‬ ‫رفــق ك ً‬\n      ‫املالحظــة االجتماعيــة للتدليــل والتمثيــل عــن كيفيــة ســرقتهم للمنــزل‬\n      ‫والســيارة وعنــد الوصــول إلــى مركــز ‪ ...‬مت االنتقــال إلــى موقــع الســرقة‬\n      ‫وهــو عبــارة عــن عمــارة مكونــة مــن دوريــن والعمــارة لهــا مدخلــن وتبــن‬\n      ‫أن اجلنــاة قامــوا بالدخــول مــن البــاب الرئيســي للعمــاره والدخــول مــع‬\n      ‫بــاب حديــد صغيــر متجــه الــى ســيب صغيــر ومــن ثــم قــام احلــدث ‪....‬‬\n      ‫بالقفــز مــع فتحــت املكيــف والغيــر محصنــة بشــبك والدخــول الــى‬\n      ‫الغرفــة التــي يســكن بهــا شــخص مصــري يقيــم بهــا مبفــرده وســرقة‬\n      ‫جــوال ومبلــغ مالــي ومــن ثــم الرجوع مع فتحة املكيف والشــقة املســروقة‬\n      ‫عبــارة عــن ثالثــة غــرف ومطبــخ ودورة ميــاه يف الــدور االرضــي وأمــا‬\n      ‫زميلــه ‪.....‬قــام بتســلق ماســوره للصــرف الصحــي والصعــود الــى الــدور‬\n      ‫الثانــي والدخــول مــع شــبك املطبــخ الغيــر محصــن والدخــول الــى داخــل‬\n      ‫الشــقه وســرقة جهــاز الب تــوب مــن غرفــة النــوم ورميــه مــن الشــباك علــى‬\n      ‫كنــب موضــوع يف الســيب ومــن ثــم الرجــوع بنفــس الطريقــه والشــقه يف‬\n      ‫الــدور الثانــي مكونــة مــن ثــاث غــرف ومطبــخ ودورة ميــاه ولها مدخلني‬\n      ‫حيــث مت التدليــل مــن قبــل احلدثــن املذكوريــن دون إكــراه وال اجبــار‬\n      ‫ومت تصويــر املوقــع وأماكــن الدخــول واخلــروج وحفــظ للواقعــة نظــم‬\n\n\n‫‪319‬‬\n\f‫هــذا احملضر‪.‬أ‪.‬ه ـ وبعــرض األدلــة علــى املدعــى عليهمــا أجــاب املدعــى‬\n‫عليــه األول ‪ ...‬بقولــه مــن جهــة اعتــرايف املصــدق شــرع ًا فنعــم انــا أعترفت‬\n‫امــام احملمكــة إلن احملقــق قــال لــي إذا اعترفــت ســنقوم بإخراجــك مــن‬\n‫الســجن ورغبــة منــي يف اخلــروج مــن الســجن اعترفــت مــع أن مااعترفــت‬\n‫بــه غيــر صحيــح ومحضــر االنتقــال واملعاينــة ال أعلــم عنــه شــيئ ًا وكذلــك‬\n‫أقــوال عامــل املغســلة أمــا أقــوال احلــدث ‪..‬ان ‪ .......‬فنعــم هــو قــال الــكالم‬\n‫هــذا وأعتــرف بــه إلنــه كان يرغــب اخلــروج مــن الســجن ويضعنــي أنــا‬\n‫فيــه ويتخلــص هــو مــن القضيــة أمــا تقريــر البحــث والتحــري فهــو غيــر‬\n‫صحيــح ومــن جهــة تناقــض أقوالــي مــع أقــوال ‪..‬فاحملقــق هــو الــذي كان‬\n‫ميلــي علينــا الــكالم ويطلــب منــا أن نقولــه ومــن جهــة تعــرف ‪ .......‬علــى‬\n‫املســروقات فــا أعلــم عنــه شــيئا ومــن جهــة محضــر الداللــة والتمثيــل‬\n‫فنعــم أنــا قمــت بتمثيــل الســرقة ولكــن قمــت بهــا بنــاء علــى طلــب احملقق‬\n‫وإال فأنــا بــريء منهــا هكــذا اجــاب كمــا أجــاب املدعــى عليــه الثانــي‬\n‫‪..‬بقولــه بــأن احملقــق ضحــك علــي وقــال لــي إذا اعترفــت أمــام احملكمــة‬\n‫فســوف نخرجــك مــن الســجن وصدقتــه مــع أنــي بــريء منهــا ومــن جهــة‬\n‫اعتــرايف حتقيقــا بــأن ‪ ...‬أخبرنــي ببيــع الكاميــرات فهــذا صحيــح وأنــا‬\n‫لــم أعلــم مــن أيــن أتــى بهــا وهــي كاميــره واحدةومحضــر االنتقــال‬\n‫واملعاينــة ال علــم لــي بــه ومــن جهــة أقــوال عامــل املغســلة فــا علــم لــي بهــا‬\n‫أيضـ ًا وتقريــر البحــث والتحــري غيــر صحيــح ومــن جهــة تناقــض أقوالــي‬\n‫مــع احلــدث املدعــى عليــه الثانــي ‪ ...‬فأنــا أقــول مايطلــب منــي احملقــق‬\n‫قولــه ومــن جهــة تعــرف‪ .......‬علــى املســروقات فــا علــم لــي بــه ومحضــر‬\n‫الداللــة والتمثيــل فنعــم أنــا قمــت بتمثيــل الســرقة ولكــن قمــت بهــا بنــاء‬\n‫علــى طلــب احملقــق وهددنــي بأنــي إذا لــم أقــم بهــا فســوف يضربنــي‬\n\n\n                                                                                            ‫‪320‬‬\n\f      ‫هكــذا أجــاب وبســؤال املدعــي العــام عــن ســوابق املدعــى عليهمــا قــال‬\n      ‫ال يظهــر مــن املعاملــة والئحــة اإلدعــاء العــام وجــود ســوابق عليهمــا فبنــاء‬\n      ‫علــى ماتقــدم مــن دعــوى املدعــي العــام وإجابــة املدعــى عليهمــا‬\n      ‫ا وملــا قدمــه‬  ‫بإنكارهمــا بصحــة ماجــاء يف الدعــوى جملــة وتفصي ـ ً‬\n      ‫املدعــي العــام مــن أدلــة وقرائــن ضــد املدعــى عليهمــا ومنهــا اعتــراف‬\n      ‫املدعــى عليهمــا املصــدق شــرع ًا بســرقة منــزل الدكتــور املقيــم وســرقة‬\n      ‫جــوال ‪ ....‬ومبلــغ خمســمائة ريــال وإلعتــراف املدعــى عليــه ‪..‬حتقيقـ ًا بــأن‬\n      ‫‪ ...‬أخبــره ببيــع كاميــرات ومصادقــة ‪..‬علــى ذلــك وملــا جــاء يف محضــر‬\n      ‫االنتقــال واملعاينــة وأقــوال عامــل املغســلة وأقــوال احلــدث ‪..‬أن ‪ .......‬مــن أن‬\n      ‫‪ ...‬طلــب منــه الذهــاب معــه لســرقة مغســلة املالبــس وملــا تضمنــه تقريــر‬\n      ‫البحــث والتحــري وتناقــض أقــوال احلدثــن وماجــاء يف محضــر الداللــة‬\n      ‫والتمثيــل مــن قيــام املدعــى عليهمــا بتمثيــل الســرقة ممــا يجعــل الشــبهة‬\n      ‫متوجــه يف حــق املدعــى عليهمــا بالقيــام بالســرقة املذكــوره يف دعــوى‬\n      ‫املدعــي العــام ونظــر ًا لرجــوع املدعــى عليهمــا عــن االعتــراف بالســرقة‬\n      ‫وهــذا االعتــراف يف حقهمــا شــبهة يــدرء بــه احلــد عنهمــا لقــول النبــي‬\n      ‫صلــى اهلل عليــه وســلم(ادرؤ احلــدود بالشــبهات مــا اســتطعتم ) ونظــر ًا‬\n      ‫النتشــار الســرقة يف هــذا الزمــان واملــكان وهــي مــن الكبائــر احملرمــة‬\n      ‫يف الشــريعة األســامية إذ فيهــا اإلعتــداء علــى حرمــة املــال وهــي ممــا‬\n      ‫جــاء الديــن بحفظهــا وصيانتهــا وملــا تقــدم ذكــره فقــد حكمنــا مبــا يلــي‬\n      ‫اوالً‪ :‬توجــه الشــبهه القويــة للمدعــى عليهمــا بقيامهمــا مبــا نســب إليهمــا‬\n      ‫يف الدعــوى ثانيـاً‪:‬درء حــد الســرقة عــن املدعــى عليهمــا ثالثاً‪:‬ســجن كل‬\n      ‫واحــد مــن املدعــى عليهمــا أربــع ســنوات وجلــد كل واحــد خمســن‬\n      ‫جلــده تتكررثمــان مــرات بــن كل مــرة والتــي تليهــا خمســة عشــر يومـ ًا‬\n\n\n‫‪321‬‬\n\f‫تعزيــر ُا وبإعــان احلكــم قــرر املدعــي العــام واملدعــى عليهمــا عــدم‬\n‫قناعتهــم باحلكــم مــع تقــدمي لوائــح اعتراضيــة فأفهمــوا بــأن عليهــم‬\n‫مراجعــة احملكمــة يــوم الســبت املوافــق ‪........‬ه ـ الســتالم نســخة مــن‬\n‫احلكــم لتقــدمي اعتراضهــم وأن لــكل واحــد منهمــا ثالثــن يوم ـ ًا مــن‬\n‫اســتالمه وعنــد تأخرهــم عــن ذلــك يســقط حقهــم يف اإلعتــراض وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n‫يف ‪1433/4/27‬ه ـ احلمــد هلل وحــده وبعــد فقــد جــرى رفــع احلكــم‬\n‫وصــورة ضبطــه وكافــة أوراق املعاملــة إلــى محكمــة االســتئناف‬\n‫مبنطقــة اجلــوف فعــاد احلكــم بالقــرار رقــم ‪ .......‬يف‪........‬ه ـ متضمنـ ًا أن‬\n‫احلكــم التعزيــري الصــادر بحــق املدعــى عليهمــا كثيــر لكونهمــا وقــت‬\n‫الســرقة أحــداث واليوجــد لهمــا ســوابق إلعــادة النظــر وتخفيــف العقوبــة‬\n‫وجنيــب أصحــاب الفضيلة_ســلمهم اهلل_أن قضايــا الســرقة مــن‬\n‫القضايــا التــي يعانــي منهــا أهالــي منطقــة تبــوك مــن خــال مايعــرض‬\n‫علينــا مــن قضايــا ممــا يتطلــب معــه األمــر احلــزم يف العقوبــة والصالبــة‬\n‫فيهــا كمــا إن املدعــى عليهمــا وإن كانــا وقــت اجلرميــة أحــداث إال أنهمــا‬\n‫يف ســن البلــوغ ومبــا أن أصحــاب الفضيلــة رأو باإلجمــاع التخفيــف يف‬\n‫العقوبــة فقــد رجعنــا عمــا حكمنــا بــه فيمــا يتعلق بســجن املدعى عليهما‬\n‫وحكمنــا بســجن كل واحــد منهمــا ثــاث ســنوات اعتبــار ًا مــن تاريــخ‬\n‫إيقافهــم وأمرنــا بإعــادة رفــع احلكــم حملكمــة االســتئناف مبنطقــة‬\n‫اجلــوف لتدقيقــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                 ‫وصحبه وسلم‪.‬حرر يف ‪.......‬هـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد أطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫اخلماســية األولــى يف محكمــة االســتئناف باجلــوف علــى املعاملــة الــواردة‬\n\n\n                                                                                     ‫‪322‬‬\n\f      ‫مــن فضيلــة رئيــس احملكمــة العامــة بتبــوك برقــم ……‪ ..‬وتاريــخ ‪......‬ه ـ‬\n      ‫املرفــق بهــا القــرار الصــادر مــن أصحــاب الفضيلــة الشــيخ ‪ ......‬والشــيخ‬\n      ‫‪ ..........‬والشــيخ ‪ ..........‬برقــم ‪ 33217509‬وتاريــخ ‪1433/4/27‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد كل مــن ‪ ....... ....‬و ‪ ............‬يف قضيــة‬\n      ‫ســرقة وقــد تضمــن القــرار حكــم أصحــاب الفضيلــة مبــا هــو مــدون‬\n      ‫ومفصــل فيــه وباإلطــاع علــى مــا أجــاب بــه أصحــاب الفضيلــة القضــاة‬\n      ‫وأحلقــوه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا الســابق رقــم ‪ ....‬تقــرر‬\n      ‫املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                         ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪323‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":306,"source_page_end":323,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d2ab3dfc49be8d92e91e349545faf9f7414dcc2231f4a7f104e4462a474db14e","normalized_text_hash":"fd224d64383e8a9a89ee8c83cf557082616ee1bdeab3d0eefd29b92bccc771d4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p306-33217509"},{"id":"7faca029-7bf5-5ce6-aba2-3564767942eb","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -خطف مبلغ مالي -شهادة -رفض طلب مهلة إلحضار بينة لكثرة االستمهاالت -تعزير -قرينة -شبهة -احلكم بالتعزير بالسجن واجللد والغرامة.","document_number":"33426193","case_number":"33347398","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/15","year":"1434","subject":"سرقة -خطف مبلغ مالي -شهادة -رفض طلب مهلة إلحضار بينة لكثرة االستمهاالت -تعزير -قرينة -شبهة -احلكم بالتعزير بالسجن واجللد والغرامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 33426193:‬تاريخه ‪1433/10/15:‬ه‬\n                    ‫رقم الدعوى‪33347398:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 3440457‬تاريخه‪1434/2/18 :‬ه‬\n\n\n\n‫ســرقة ‪ -‬خطــف مبلــغ مالــي ‪ -‬شــهادة ‪ -‬رفــض طلــب مهلــة إلحضــار‬\n‫بينــة لكثــرة االســتمهاالت ‪ -‬تعزيــر ‪ -‬قرينــة ‪ -‬شــبهة ‪ -‬احلكــم بالتعزيــر‬\n                                              ‫بالســجن واجللــد والغرامــة‪.‬‬\n\n\n\n\n                    ‫‪-‬قوله تعالى ( وال تعتدوا إن اهلل ال يحب املعتدين )‬\n                     ‫‪-‬قوله تعالى ( وال تأكلوا أموالكم بينكم بالباطل)‬\n‫‪-‬قولــه صلــى اهلل عليــه وســلم ( كل املســلم علــى املســلم حــرام دمــه‬\n                                                          ‫ومالــه وعرضــه )‬\n‫‪-‬قولــه صلــى اهلل عليــه وســلم (ال يحــل مــال امــرئ مســلم إال عــن طيــب‬\n                                                                ‫نفــس منــه )‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليهمــا بخطــف مبلــغ مالــي مــن أحــد‬\n‫املقيمــن‪ ،‬طلــب املدعــي العــام تعزيرهمــا ‪،‬أنكــر املدعــى عليهمــا‬\n‫مــا جــاء بدعــوى املدعــى العام‪،‬طلــب القاضــي مــن املدعــي العــام بينتــه‬\n‫علــى دعــواه عــدة مــرات ولــم يحضرهــا‪،‬مت االطــاع علــى طيــات املعاملــة‬\n‫فوجــد مــن ضمنهــا شــهادة ألحــد األشــخاص ضــد املدعــى عليهمــا تثبــت‬\n‫صحــة مــا جــاء بدعــوى املدعــى العام‪،‬حكمــت احملكمــة بتعزيــر‬\n\n                                                                                  ‫‪324‬‬\n\f      ‫املدعــى عليهمــا بالســجن واجللــد مــع تغرميهمــا مبلغـ ًا ماليـ ًا وإبعادهما عن‬\n      ‫البــاد بعــد انتهــاء محكوميتيهمــا‪ ،‬قنــع املدعــى عليهمــا باحلكــم بينمــا‬\n      ‫املدعــي العــام اعتــرض عليه‪،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ .....‬القاضــي باحملكمــة اجلزئيــة‬\n      ‫مبحافظــة جــدة حــا ًال بنــاء علــى املعاملــة الــواردة لنــا بشــرح مســاعد‬\n      ‫رئيــس احملكمــة اجلزئيــة مبحافظــة جدة واملقيــدة برقم‪...‬يف‪......‬واملتعلقة‬\n      ‫بدعــوى املدعــي العــام ضــد املدعــى عليهمــا ‪ .....‬و ‪ ....‬ومبوجبهــا ففــي‬\n      ‫هــذا اليــوم الثالثــاء املوافــق ‪ ......‬ويف متــام الســاعة الواحــدة ظهــر ًا حضــر‬\n      ‫املدعــي العــام بدائــرة التحقيــق واالدعــاء العــام ‪ ......‬املكلــف بالعمــل‬\n      ‫لــدى احملكمــة مبوجــب خطــاب رقــم ‪....‬يف ‪ .....‬وحضــر حلضــوره املدعــى‬\n      ‫عليهمــا ‪ .....‬إثيوبــي اجلنســية مبوجــب االقامــة رقــم ‪ ..... ،..........‬إثيوبــي‬\n      ‫اجلنســية مبوجــب البطاقــة البديلــة رقــم ‪......‬وقــد أذنــت للمدعــي العــام‬\n      ‫بتحريــر دعــواه فأبــرز الئحــة جــاء فيهــا وقــد انتهــى وقــد أســفر التحقيــق‬\n      ‫عــن توجيــه االتهــام إليهمــا بخطــف مبلــغ مالــي قــدره (‪ )40،200‬أربعــون‬\n      ‫ألف ـ ًا ومائتــي ريــال مــن أحــد املقيمــن أثنــاء دخولــه ملقــر عملــه ‪ ،‬وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة‪ -1-:‬مــا جــاء يف أقــوال املدعــى عليهمــا املنــوه‬\n      ‫عنهــا املدونــة صفحــة (‪ ) ....‬مبلــف إجــراءات االســتدالل املرفــق لفــة (‪)....‬‬\n      ‫وصفحــة (‪ )....‬مبلــف إجــراءات االســتدالل املرفــق لفــة (‪ -2. )..‬مــا جــاء‬\n      ‫يف محضــر القبــض املنــوه عنــه املــدون صفحــة (‪ )....‬مبلــف إجــراءات‬\n      ‫االســتدالل املرفــق لفــة (‪-3. )....‬مــا جــاء يف شــهادة الشــاهد‪،..../‬‬\n      ‫املنــوه عنهــا املدونــة صفحــة (‪ )....‬مبلــف إجــراءات االســتدالل املرفــق‬\n\n‫‪325‬‬\n\f‫لفــة (‪ -4.)....‬مــا جــاء يف محضــر عــرض املدعــى عليهمــا علــى املجنــي‬\n‫عليــه املنــوه عنــه املــدون صفحــة (‪ )...‬مبلــف إجــراءات االســتدالل املرفــق‬\n‫لفــة (‪ -5.)...‬ضبــط مبلــغ مالــي قــدره (‪ )28.904‬ريــال بحــوزة املدعــى‬\n‫عليــه الثانــي وهــو مقيــم بطريقــة غيــر نظاميــة وليــس لديــه مصــدر دخــل‬\n‫ثابــت وضبــط جهــازي جــوال بحوزتــه وثالثــة جــواالت بحــوزة املــرأة‪،..../‬‬\n‫تؤكــد صحــة مــا نســب إليهمــا‪ -6.‬إقــرار األول بشــرائه ســيارة مــن نــوع‬\n‫‪ .......‬مببلــغ (‪ )30.000‬ثالثــن ألــف ريــال وبيعهــا وإرســال قيمتهــا لبــاده‬\n‫وهــو بــدون عمــل وليــس لــه مصــدر دخــل‪ ....‬قويــة تؤكــد صحــة مــا نســب‬\n‫إليهمــا‪ -7.‬تســجيل رقــم اجلــوال اخلــاص باملدعــى عليــه األول بعقــد إيجــار‬\n‫الســيارة املســتخدمة يف إرتــكاب اجلرميــة وإنــكاره مبعرفــة رقــم الهاتــف‬\n‫املذكــور ‪ ...‬تؤكــد أنــه مــن قــام باســتئجار الســيارة واســتخدامها يف‬\n‫ارتــكاب اجلرمية‪.‬وباإلطــاع علــى احلالــة اجلنائيــة للمدعــى عليهما‪/‬لــم‬\n‫يعثــر لهمــا علــى حــاالت جنائيــة مســجلة‪.‬وحيث إن مــا أقــدم عليــه املدعــى‬\n‫عليهمــا وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا فعــل محــرم ومعاقــب‬\n‫عليــه شــرع ًا لــذا اطلــب إثبــات مــا اســند إليهمــا واحلكــم مبعاقبتهمــا‬\n‫بعقوبــة تعزيريــة رادعــه لقــاء ذلــك ‪ ((.‬علم ـ ًا أن احلــق اخلــاص مــا زال‬\n‫قائمـ ًا ))‪.‬هــذه دعــواي أطالبهمــا بهــا وأســألهما اجلــواب وبعــرض مــا جــاء‬\n‫ا إن مــاورد بدعــوى‬   ‫يف دعــوى املدعــي العــام عليهمــا أجــاب األول قائ ـ ً‬\n‫املدعــي العــام مــن حيــث خطــف مبلــغ مالــي وقــدره أربعــون ألــف ومائتــي‬\n‫ريــال مــن املدعــي فغيــر صحيــح وعلــى املدعــي العــام إثبــات صحــة مــا‬\n‫يدعيــه هكــذا أجاب‪،‬وأجــاب الثانــي قائــا‪ :‬إن مــاورد بدعــوى املدعــي‬\n‫العــام مــن حيــث اشــتراكي مــع املدعــى عليــه األول يف خطــف مبلــغ‬\n‫مالــي وقــدره أربعــون ألــف ومائتــي ريــال مــن املدعــي فغيــر صحيــح وعلــى‬\n\n\n                                                                                    ‫‪326‬‬\n\f      ‫املدعــي العــام إثبــات صحــة مــا يدعيــه هكــذا أجــاب فجــرى ســؤال‬\n      ‫املدعــي العــام هــل لديــك بينــة تشــهد طبــق دعــواك أجــاب قائــا نعــم‬\n      ‫لــدي واطلــب إمهالــي إلحضارهــا وعليــه وإلمهالــه إلحضــار بينتــه تأجلــت‬\n      ‫اجللســة إلــى يــوم األربعــاء املوافــق ‪......‬الســاعة احلاديــة عشــرة وأربعــن‬\n      ‫دقيقــة صباحــا واهلل املوفــق وصلــى اهلل علــى محمــد وعلــى الــه وصحبــه‬\n      ‫وســلم حــرر يف ‪ .....‬احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األحــد املوافــق‬\n      ‫‪ ....‬ويف متــام الســاعة الواحــدة والنصــف ظهــرا افتتحــت اجللســة وفيهــا‬\n      ‫حضــر الطرفــان فجــرى ســؤال املدعــي العــام عمــا اســتمهل مــن أجلــه‬\n      ‫فأجــاب قائــا لــم أمتكــن مــن إحضــار بينتــي وأطلــب إمهالــي مــرة أخــرى‬\n      ‫إلحضارهــا فجــرى إفهامــه برفــض طلبــه لكثــرة اســتمهاالته وجــرى‬\n      ‫االطــاع علــى األوراق فوجــد بطياتهــا شــهادة املدعــو ‪ ....‬بدفتــر التحقيــق‬\n      ‫صفحــة رقــم أثنــا عشــر لفــة رقــم ثالثــة وأربعــن هــذا نصهــا (الســاعة‬\n      ‫الثانيــة والربــع ظهــرا كنــت واقفــا عنــد البــاب اخلارجــي للشــركة‬\n      ‫التــي اعمــل بهــا ألدخــن عندمــا قــدم زميلــي ‪ ....‬وركــن ســيارته بجــراج‬\n      ‫الشــركة واجتــه إلــى صعــود املدخــل الرئيســي مــن جهــة الطريــق‬\n      ‫العــام وعنــد وصولــه إلــى الدرجــة األولــى مــن الســلم وكنــت أحييــه‬\n      ‫وإذا بشــخص طولــه حوالــي مائــة وســتون ســم ممتلــئ قليــا حنطــي‬\n      ‫اللــون لــه عيــون قريبــة مــن األســيوية يلبــس قبعــه صــوف وقميــص لــون‬\n      ‫ترابــي أو أحمــر عمــره حوالــي العشــرين تقــدم مــن خلفــه وســحب كيــس‬\n      ‫البالســتيك (النقــود) الــذي بيــده والتفــت عائــدا علــى الشــارع عندهــا‬\n      ‫ركضــت أنــا و‪ ....‬باجتاهــه ولكــن ســيارة ‪ ....‬اللــون غامــق زجــاج‬\n      ‫لــون اســود قــد خففــت ســرعتها وفتــح بابهــا اخللفــي اليمــن واســتطاع‬\n      ‫أحلرامــي ان يقفــز بالســيارة قبــل ان اســتطيع اإلمســاك بــه مبتريــن او‬\n\n\n‫‪327‬‬\n\f‫ثالثــة رقــم الســيارة‪ ....‬توقفــت و‪ ...‬عــن الركــض خلــف الســيارة حيــث‬\n‫احــد املــارة بســيارته الفــورد توقــف واقلنــا لنالحــق ســيارة الســارقني‬\n‫الحظــت بــأن الســائق لــه مالمــح أفريقيــة غامــق البشــرة وأكبــر مــن‬\n‫الــذي قــام بالســرقة انطلقنــا بســيارة فاعــل اخليــر محاولــن اللحــاق‬\n‫بهــم واســتطعنا أن نــرى الســيارة غــرب شــارع أم القــرى بإجتــاه مركــز‬\n‫حــرس احلــدود ولكننــا لــم نســتطع العثــور عليهــم وبالتالــي قــام فاعــل‬\n‫اخليــر ‪ .....‬باالتصــال بالشــرطة وإعالمهــم باألمــر وبالتالــي توقفنــا‬\n‫عــن البحــث عنــد قاعــة رهــام بشــارع األربعــن حيــث التقينــا بدوريــات‬\n‫ـاء علــى دعــوى املدعــي العــام‬\n                                ‫الشــرطة وبذلــك أشــهد انتهــى وعليــه فبنـ ً‬\n‫املرصــودة بعاليــه وإجابــة املدعــى عليهمــا وحيــث عجــز املدعــي العــام عن‬\n‫إثبــات دعــواه واســتنادا إلــى الشــهادة املرصــودة بدفتــر التحقيــق واملشــار‬\n‫إليهــا آنفــا ونظــرا إلــى محضــر القبــض ومحضــر عــرض املدعــى عليهمــا‬\n‫علــى املدعــي واملرفقــة يف طيــات املعاملــة وحيــث تعــرف املجنــي عليــه‬\n‫علــى املدعــى عليــه االول ونظــرا لوجــود مبلــغ قــدره ثمانيــة وعشــرون‬\n‫ألفــا تســعمائة وأربعــة ريــاالت بحــوزة املدعــى عليــه الثانــي وحيــث إنــه‬\n‫يقيــم يف البــاد بطريقــة غيــر نظاميــة وليــس لــه مصــدر دخــل ثابــت ممــا‬\n‫يــورث الشــبهة علــى أنــه حصــل علــى املبلــغ بطريــق غيــر مشــروع ونظــرا‬\n‫إلقــرار األول املشــار إليــه باملعاملــة مــن أنــه بــاع ســيارة مببلــغ ثالثــن‬\n‫ألــف ريــال وأرســل قيمتهــا إلــى بــاده وليــس لديــه مصــدر ثابــت للدخــل‬\n‫أو عمــل مينحــه هــذا املبلــغ وحيــث إن رقــم جــوال املدعــى عليــه األول‬\n‫مســجال يف عقــد ايجــار الســيارة املســتخدمة يف ارتــكاب اجلرميــة ونظــرا‬\n‫إلنــكاره رقــم هاتفــه ممــا يــدل علــى كذبــه ومراوغتــه وحيــث أحــل‬\n‫اهلل الطيبــات وحــرم علينــا اخلبائــث وحيــث إن يف فعــل املدعــى عليهمــا‬\n\n\n                                                                                      ‫‪328‬‬\n\f      ‫ترويــع لآلمنــن وأخــذ ألموالهــم وغصبهــا بغيــر وجــه حــق واســتنادا إلــى‬\n      ‫قولــه تعالــى (وال تعتــدوا إن اهلل ال يحــب املعتديــن) اآليــة ولقولــه تعالــى‬\n      ‫وال تأكلــوا أموالكــم بينكــم بالباطــل آاليــة وقــال النبــي صلــى اهلل‬\n      ‫عليــه وســلم (كل املســلم علــى املســلم حــرام دمــه ومالــه وعرضــه) وقــال‬\n      ‫عليــه الصــاة والســام(كل جســد نبــت مــن الســحت فالنــار أولــى بــه )‬\n      ‫ولقولــه (ال يحــل مــال امــرئ مســلم إال عــن طيــب نفــس منــه) لــذا فقــد‬\n      ‫ثبــت لــدي توجــه الشــبهة القويــة يف حــق املدعــى عليهمــا بخطــف مبلــغ‬\n      ‫قــدره أربعــون ألفــا ومئتــا ريــال مــن أحــد املقيمــن وحكمــت عليهمــا‬\n      ‫مبــا يلــي‪:‬ـ أوالً‪ :‬ســجن كل واحــد منهمــا ثــاث ســنوات تعزيــرا اعتبــار ًا‬\n      ‫مــن تاريــخ دخولــه الســجن علــى ذمــة هــذه القضيــة ثانيــا‪ :‬جلــد كل‬\n      ‫واحــد منهمــا ســبعني جلــدة تعزيــر ًا مفرقــة علــى جميــع بدنــه علنـ ًا دفعــة‬\n      ‫واحــدة مكــررة عشــر مــرات ومــا بــن كل فتــرة والتــي تليهــا مــا ال‬\n      ‫يقــل عــن عشــرة أيــام ثالثــا ‪:‬غرامــة ماليــة تعزيــر ًا قدرهــا خمســة عشــر‬\n      ‫ألــف ريــال لــكل واحــد منهمــا معاملــة لهمــا بنقيــض قصدهمــا رابعــا‪:‬‬\n      ‫إبعادهمــا عــن اململكــة اتقــاء لشــرهما عقــب تنفيــذ محكوميتهمــا‬\n      ‫وبــه حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام عــدم‬\n      ‫القناعــة باحلكــم مســتعدا بتقــدمي الئحتــه االعتراضيــة فأجبتــه لطلبــه‬\n      ‫وأفهمتــه بتعليمــات التمييــز ففهــم وقــرر املدعــى عليهمــا قناعتهمــا‬\n      ‫باحلكــم وأفهمــت املدعــي العــام بــأن عليــه إبــاغ املدعــي باحلــق اخلــاص‬\n      ‫برفــع دعــواه أمــام احملكمــة املختصــة إذا رغــب ففهــم وعليــه فقــد أمرت‬\n      ‫بتنظيــم هــذا القــرار مبوجبــه وبعثــه وصــورة ضبطــه والئحــة املدعي العام‬\n      ‫إلــى محكمــة االســتئناف لتدقيقــه حســب املتبــع واهلل املوفــق حــرر يف‬\n      ‫‪......‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n\n\n‫‪329‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‬\n‫‪ -:‬فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة املســاعد مبحافظــة جــدة برقــم ‪...‬‬\n‫وتاريــخ ‪ .....‬هـ ـ املرفــق بهــا القــرار الشــرعي رقم ‪ ....‬وتاريــخ ‪ ...‬ه ـ الصادر‬\n‫مــن فضيلــة الشــيخ ‪ ....‬القاضــي يف احملكمــة اجلزائيــة مبحافظــة جــدة‪،‬‬\n‫املتضمــن دعــوى املدعــي العــام ضــد ‪ .....‬ورفيقــه أثيوبيــن اجلنســية‬\n‫املتهمــن بقضيــة ســرقة ‪ /‬نشــل احملكــوم فيــه مبــا دون باطنــه‪ .‬وبدراســة‬\n‫احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا املوافقــة علــى‬\n‫احلكــم لقناعــة املدعــى عليهمــا ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                             ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                        ‫‪330‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":324,"source_page_end":330,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2e15b86761f148c6ce5940870336d35c4259cf7d37aebb13a1b58c344f2b5021","normalized_text_hash":"6f6662ca562ee2af436b02c1a24ecc49222c6665c24e8f03c1004c8316e9587a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p324-33426193"},{"id":"a8fd714b-9a7c-5b3a-8a65-47ec9e724e75","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -انتهاك حرمة منزل -سرقة منزل اجلار -سرقة بعض محتويات املنزل -سرقة حرز بعد هتكه -بيع مسروقات -طلب إقامة حد السرقة -درء حد السرقة -تعزير بالسجن واجللد -1قوله صلى اهلل عليه وسلم ( واهلل اليؤمن واهلل ال يؤمن قيل من يارسول اهلل قال الذي ال يأمن جاره بوائقه).","document_number":"33323065","case_number":"33367340","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باخلبر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/07/01","year":"1434","subject":"سرقة -انتهاك حرمة منزل -سرقة منزل اجلار -سرقة بعض محتويات املنزل -سرقة حرز بعد هتكه -بيع مسروقات -طلب إقامة حد السرقة -درء حد السرقة -تعزير بالسجن واجللد -1قوله صلى اهلل عليه وسلم ( واهلل اليؤمن واهلل ال يؤمن قيل من يارسول اهلل قال الذي ال يأمن جاره بوائقه).","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33323065 :‬تاريخه ‪1433/07/01 :‬هـ‬\n                           ‫رقم القضية ‪33367340:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                   ‫‪ 34176303‬تاريخه ‪1434/4/1:‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬انتهــاك حرمــة منــزل‪ -‬ســرقة منــزل اجلــار ‪ -‬ســرقة بعــض‬\n      ‫محتويــات املنــزل ‪ -‬ســرقة حــرز بعــد هتكــه‪ -‬بيــع مســروقات‪ -‬طلــب‬\n         ‫إقامــة حــد الســرقة‪ -‬درء حــد الســرقة‪ -‬تعزيــر بالســجن واجللــد‬\n\n\n\n\n      ‫‪-1‬قولــه صلــى اهلل عليــه وســلم ( واهلل اليؤمــن واهلل ال يؤمــن قيــل مــن‬\n                                ‫يارســول اهلل قــال الــذي ال يأمــن جــاره بوائقــه)‪.‬‬\n      ‫‪-2‬قولــه صلــى اهلل عليــه وســلم (ال يدخــل اجلنةمــن ال يأمــن جــاره‬\n                                                                           ‫بوائقــه )‪.‬‬\n            ‫‪-3‬قال ابن قدامه ( احلرز ماعد حرزا يف العرف )املغني ‪.12/427‬‬\n      ‫‪-4‬قــال القــرايف يف الذخيــرة ( ضابــط احلــرز مــا اليعــد الواضــع فيــه‬\n                                                                ‫مفرطــا ) ‪.12/166‬‬\n\n\n\n\n      ‫دعــوى املدعــي العــام ضــد املدعــى عليــه بانتهــاك حرمــة منــزل جــاره‬\n      ‫وســرقة مصوغــات ذهبيــة وجهــاز حاســب آلــي محمــول وأجهــزة هواتــف‬\n      ‫محمولــة‪ ،‬وســرقة حــرز بعــد هتكــه وبيعــه واالســتيالء علــى ثمنــه‪،‬‬\n      ‫وطلــب إقامــة حــد الســرقة‪،‬مت القبــض علــى املدعــى عليــه بعــد بــاغ‬\n      ‫مفــاده تعــرض أحــد املنــازل للســرقة وأن املبلــغ يتهــم جــاره وبعــد البحــث‬\n\n‫‪331‬‬\n\f‫والتحــري قبــض علــى املتهــم وأقــر بالســرقة املنســوبة إليــه‪ ،‬أقــر املدعــى‬\n‫عليــه بالدعــوى وقــرر أن املنــزل لــم يكــن بــه أحــد وكانــت إحــدى‬\n‫النوافــذ مفتــوح شــباكها مــن الداخــل والشــبك احلديــدي املركــب مــن‬\n‫اخلــارج غيــر مثبــت مبســامير مــن األســفل ومثبــت مــن األعلــى‪ ،‬وقــد‬\n‫تنــازل املدعــي اخلــاص عــن حقــه‪ ،‬تقريــر ناظــري القضيــة عــدم توفــر‬\n‫كامــل شــروط الســرقة إذ اختــل فيهــا شــرط احلــرز حيــث إن صاحــب‬\n‫احلــق اخلــاص قــد حصــل منــه نــوع تفريــط يف حفــظ مالــه إذ لــم يحصــن‬\n‫بيتــه جيــداً‪ ،‬درء حــد الســرقة عــن املدعــى عليــه‪ ،‬وتعزيــر املدعــى عليــه‬\n       ‫بالســجن واجللــد‪،‬مت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده أمــا بعــد فلدينــا كال مــن ‪ ......‬و ‪ .......‬و‪ ........‬القائــم‬\n‫بعمــل املكتــب التاســع مبوجــب التكليــف رقــم ‪ 331021193‬فـ ـ ــي‬\n‫‪1433/06/1‬ه ـ القضــاة يف احملكمــة العامــة باخلبــر‪ ،‬وبنــاء علــى‬\n‫املعاملــة احملالــة للمكتــب الرابــع مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫يف اخلبر‪/‬املســاعد برقــم ‪ 33367340‬وتاريــخ ‪ 1433/05/29‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331009441‬وتاريــخ ‪ 1433/05/29‬ه ـ ففــي يــوم‬\n‫االثنــن املوافــق‪ 1433/06/16‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ ......‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ،......‬وادعــى علــى احلاضــر معــه ‪ .......‬ســعودي مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ، .......‬قائــا يف دعــواه عليــه ‪ :‬إنــه باالطــاع علــى‬\n‫محضــر البــاغ املعــد مــن قبــل رجــال الضبــط اجلنائــي تبــن أنــه يف يــوم‬\n‫اخلميــس املوافــق ‪1433/1/13‬ه ـ تقــدم املواطــن‪ ...... /‬ببــاغ يفيــد فيــه‬\n\n                                                                                       ‫‪332‬‬\n\f      ‫عــن تعــرض شــقته للســرقة فســرق منهــا شــنطة حتتــوي علــى مصوغــات‬\n      ‫ذهبيــة وجهــاز حاســب آلــي وأجهــزة هواتــف محمولــة ويشــك يف جــاره‬\n      ‫املجــاور لــه يف الســكن وباالطــاع علــى محضــر بحــث وحتــري وقبــض‬\n      ‫املعــد مــن قبــل رجــال الضبــط اجلنائــي تبــن أنــه يف يــوم اخلميــس املوافــق‬\n      ‫‪1433/3/1‬ه ـ وبالتنســيق مــع املبلــغ هاتفيــا الــذي أفــاد أن مــن ضمــن‬\n      ‫املســروقات جهــاز‪ ......‬يحمــل الرقــم التسلســلي (‪ )............‬ومبخاطبــة‬\n      ‫مــزودي اخلدمــة لإلفــادة عمــا إذا اســتخدمت أي شــريحة علــى هــذا‬\n      ‫اجلهــاز وأفــادت الشــركة أن الشــريحة رقـ ـ ـ ــم (‪ )............‬اســتخدمت‬\n      ‫علــى اجلهــاز املســروق وتبــن أن مســتخدم اجلهــاز امــرأة وأفــادت أنهــا‬\n      ‫اشــترت اجلهــاز مــن محــل (‪ ....‬للجــواالت) وبالتواصــل مــع صاحــب احملــل‬\n      ‫املواطــن (‪ .....‬وأفــاد أن اجلهــاز اشــتراه مــن شــخص يســتقل ســيارة نــوع‬\n      ‫‪ ......‬وذكــر أوصافــه التــي تنطبــق علــى املتهــم املذكــور‪ ،‬وبالبحــث‬\n      ‫والتحــري عــن املتهــم املذكــور تبــن قيامــه ببيــع اجلهــاز املســروق مــن‬\n      ‫منــزل املبلــغ بتاريــخ ‪1433/2/27‬ه ـ علــى محــل (‪ .....‬للجــواالت) ‪،‬‬\n      ‫وقيامــه ببيــع تعاليــق وسالســل وخــامت ذهــب علــى محــل ‪ .......‬للذهــب‬\n      ‫واملجوهــرات بالثقبــة بتاريــخ ‪1433/1/11‬ه ـ بقيمــة خمســة آالف‬\n      ‫وخمســمائة ريــال ‪ ،‬وبعــرض صــورة املتهــم املذكــور علــى املقيــم‪..... /‬‬\n      ‫صاحــب محــل اجلــواالت تعــرف عليــه ‪ ،‬وباســتدعاء املتهــم املذكــور‬\n      ‫ومناقشــته شــفهيا عــن اجلــوال أقــر بأنــه وجــده مرميــا يف العمــارة التــي‬\n      ‫يســكن بهــا وتصــرف ببيعــه ‪ ،‬وأثبــت محضــر انتقــال واملعـ ـ ـ ـ ـ ـ ـ ــاينة أنــه‬\n      ‫مبعاينــة الشــقة تبــن أنهــا بالــدور األرضــي مواجهــة للشــارع وبدخــول‬\n      ‫غرفــة النــوم التــي ســرق منهــا الذهــب وجهــاز حاســب آلــي محمــول‬\n      ‫وجــدت الغرفــة مبعثــرة وشــوهد مجلــس النســاء أن بــه شــباك حرامــي‬\n\n\n‫‪333‬‬\n\f‫ولوحــظ أن البلــوط قــد ف ـ ـ ـ ـ ـ ــك ورفــع الشــباك ومنهــا دخــول اجلانــي إلــى‬\n‫الشــقة ‪،‬واثبــت محضــر العــرض بأنــه بعــرض صــور املتهــم امل ـ ـ ــذكور‬\n‫علــى املقيــم‪ ..... /‬صاحــب محــل اجلــواالت تعــرف علــى صورتــه وأفــاد أن‬\n‫املتهــم املذكــور قــام ببيعــه جهــاز هاتــف جــوال نــوع بــاك بيــري موديــل‬\n‫(‪ )............‬ي ـ ـ ـ ــوم الس ـ ـ ـ ــبت بتاريخ ‪1433/2/27‬هـ ‪ .‬وأثبـ ـ ـ ــتت ف ـ ـ ـ ـ ــاتورة‬\n‫شراء الصادرة من محل ‪ .....‬للذهب واملجوهرات بتاريخ ‪1433/1/11‬هـ‬\n‫قيــام املتهــم املذكــور ببيــع تعاليــق وسالســل وخــامت ذهــب وزنهــا (‪)32,7‬‬\n‫جــرام عيــار (‪ )21‬مببلــغ قــدره خمســة آالف وخمســمائة ريــال ‪،‬‬\n‫وباســتجواب املتهــم ( ‪ )......‬أفــاد أنــه قــام بدخــول منــزل جــاره عــن طريــق‬\n‫خلــع مســامير شــباك أحـ ـ ـ ـ ـ ـ ـ ــد النوافــذ ملنزلــه والدخول منهــا إلى املنزل‬\n‫وســرقة عشــر قطــع مــن الذهــب وجهازيــن هاتفــن محمولــن نــوع نوكيا‬\n‫واألخــر أيبــاد وجهــاز حاســب آلــي محمــول ثــم اجتــه لســوق الذهــب وبــاع‬\n‫الذهــب املســروق علــى دفعتــن بقيمــة أربعــة آالف ريــال ويف يــوم الســبت‬\n‫املوافــق ‪1433/2/27‬ه ـ قــام ببيــع جهــاز هاتــف جــوال ن ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ــوع بــاك‬\n‫بيــري وبقيــة املســروقات ال يع ـ ـ ـ ـ ـ ـ ـ ــرف عنهــا فقــد أخ ـ ـ ـ ــذت مــن‬\n‫السيـ ـ ـ ـ ـ ـ ــارة أثنــاء نزولــه مل ـ ـ ـ ـ ـ ــحل الذهــب ونفــى مــا س ـ ـ ـ ـ ــوى ذلك‪ ،‬وبناء‬\n‫ع ـ ـ ـ ــلى مــا ذكــر أقــرر اتهــام املواطــن ‪ ...... /‬بانتهــاك حرمــة منــزل‬\n‫املدعــي وســرقة مصوغــات ذهبيــه وجهــاز حاســب آلــي محمــول وأجهــزه‬\n‫هواتــف محمولــة منــه حــرز بعــد هتكــه ‪ ,‬وبيعهــا واالســتيالء علــى ثمنهــا‬\n‫وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬اعترافــه املنــوه عنــه املــدون علــى‬\n‫الصفحات رقم (‪ )15 - 9‬مبلف التحقيق‪ -2 .‬محضر البحث والتحري‬\n‫والقبــض املنــوه عنــه املــدون علــى اللفتــن رقــم (‪ -3، )12,12‬محضــر‬\n‫االنتقــال واملعاينــة املنــوه عنــه املــدون علــى الصفحتــن رقــم (‪ )3,2‬مــن‬\n\n\n                                                                                                        ‫‪334‬‬\n\f      ‫ملــف التحقيــق رقــم (‪ )1‬لفــه رقــم (‪ -4 ،)1‬محضــر العــرض املنــوه عنــه‬\n      ‫املــدون علــى اللفــة رقــم (‪ -5، )11‬فاتــورة الشــراء املنــوه عنهــا املرفقــة‬\n      ‫علــى اللفــة رقــم ( ‪ ، )10‬وبالبحــث عمــا إذا كان لــه ســوابق عثــر لــه‬\n      ‫علــى ســابقتني األولــى شــرب مســكر ومخــدرات وقيــادة ســيارة وهــو‬\n      ‫بحالــة ســكر و الثانيــة تكســير زجــاج ســيارة وســرقة وحيــث أن مــا‬\n      ‫أقــدم عليــه املذكــور ـ وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ـ فعــل محــرم‬\n      ‫ومعاقــب عليــه شــرع ًا ممــا يتعــن معــه إحالتــه للمحكمــة العامــة باخلبــر‬\n      ‫اســتناد ًا للمادتــن ( ‪ )126‬و ( ‪ )129‬مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫إلثبــات مــا أســند إليــه واحلكــم عليــه بحــد الســرقة الــوارد يف اآليــة‬\n      ‫الكرميــة رقــم (‪ )38‬مــن ســورة املائــدة ‪ (،‬علم ـ ًا بــأن احلــق اخلــاص قــد‬\n      ‫انتهــى بالتنــازل)‪ .‬وباســتجواب املدعــى عليــة قــرر قائــا مــا ذكــره‬\n      ‫املدعــى العــام مــن قيامــي بالســرقة للمذكــورات فصحيــح وطريقــة‬\n      ‫الســرقة أننــي دخلــت منــزل جــاري اليــوم املذكــور وليــس فيــه أحــد‬\n      ‫وكان فيــه أحــد النوافــذ مفتــوح شــباكها مــن الداخــل وكان الشــبك‬\n      ‫احلديــدي املركــب مــن اخلــارج غيــر مثبــت مبســامير مــن األســفل وإمنــا‬\n      ‫هــو مثبــت مــن األعلــى فقــط فقمــت بخلعــه بيــدي ودخلــت وســرقت‬\n      ‫املجوهــرات مــن شــنطة كانــت علــى التســريحة وســرقت األجهــزة مــن‬\n      ‫الصالــة ثــم بعــت الذهــب وجهــاز البــاك بيــري فلمــا اشــتكاني جــاري‬\n      ‫للشــرطة ومت اســتدعائي أقــررت بالســرقة وأعـ ـ ـ ـ ـ ـ ــدت لــه املســروقات‬\n      ‫املتبقيــة وقيمــة مــا بعــت مــن الذهــب وجهــاز البــاك بيــري وتصاحلــت معــه‬\n      ‫وتنــازل عــن مطالبتــي وأنــا تائــب ونــادم علــى فعلتــي علمــا أن الســوابق‬\n      ‫التــي علــي صحيحــة فجــرى تصفــح أوراق املعاملــة ووجــد فيهــا إقــرار‬\n      ‫املدعــى عليــه يف ص‪ 15‬مــن دفتــر التحقيــق لفــة رقــم(‪ )1‬وهــذا نــص‬\n\n\n‫‪335‬‬\n\f‫احلاجــة منــه (أقــر أنــا املدعــو ‪ .....‬ســعودي اجلنســية مبوجــب ســجل مدنــي‬\n‫رقــم (‪ ).......‬أنــي قمــت بدخــول منــزل جــاري املدعــو ‪ .....‬عــن طريــق نافــذة‬\n‫املنــزل وقمــت بأخــذ مجموعــة مــن الذهــب وجوالــن األول مــن نــوع‬\n‫نوكيــا والثانــي آيبــاد وفــور انتهائــي مــن الســرقة والتــي كان مــن‬\n‫ضمنهــا جهــاز كمبيوتــر البتــوب محمــول توجهــت مــن ليلتــي إلــى محــل‬\n‫الذهــب وقمــت ببيــع الذهــب علــى دفعتــن بقيمــة أربعــة آالف ريــال‬\n‫ســعودي وقمــت أيضــا يف يــوم الســبت املاضــي املوافــق ‪1433/2/27‬ه ـ‬\n‫ببيــع جهــاز بــاك بيــري وأمــا بقيــة املســروقات وهــي كمبيوتــر محمــول‬\n‫وبعــض األغــراض ال أعرفهــا فقــد أخــذت مــن الســيارة أثنــاء نزولــي‬\n‫حملــات الذهــب وأن اعتــرايف هــذا مــن غيــر إجبــار مــن أحــد أو إكــراه‬\n‫أو ضغــوط أدليــت بــه وأنــا بكامــل قــواي الشــرعية وإرادتــي الطوعيــة)‬\n‫انتهــى نــص احلاجــة منــه فجــرى عرضــه عليــه فأجــاب قائــا مــا ورد فيــه‬\n‫صحيــح جملــة وتفصيــا كمــا جــرى االطــاع علــى تقرير األدلــة اجلنائية‬\n‫للقضيــة وقــد تضمــن أن املتهــم قــد جــرى اســتجوابه ومواجهتــه باألدلــة‬\n‫والقرائن فأقر مبا نســب إليه من تهم وأفاد بأنه بتاريخ ‪1433/1/13‬هـ‬\n‫أقــدم علــى دخــول منــزل جــاره عــن طريــق خلــع مســامير شــباك أحــد‬\n‫النوافــذ ملنــزل جــاره انتهــى مضمونــه كمــا يف اللفــة (‪ )57‬مــن املعاملــة‬\n‫فجــرى عرضــه علــى املدعــى عليــه فأجــاب قائــا مــا ورد فيــه غيــر‬\n‫صحيــح فلــم أقــم بخلــع املســامير وإمنــا هــي يف األصــل غيــر مركبــة إذ إن‬\n‫العمــارة جديــدة هكــذا أجــاب فجــرى ســؤال املدعــي العــام هــل لديــه‬\n‫بينــة علــى أن املدعــى عليــه قــد خلــع مســامير نافــذة جــاره فقــال ال بينــة‬\n‫لــدي علــى ذلــك هكــذا أجــاب ‪ ،‬وقــد جــرى ســؤال كل واحــد مــن‬\n‫الطرفــن هــل لديهمــا مــا يريــدان إضافتــه علــى مــا ســبق فقــال كل‬\n\n\n                                                                                       ‫‪336‬‬\n\f      ‫واحــد منهمــا ليــس لدينــا ســوى مــا جــرى تقدميــه يف اجللســات الســابقة‬\n      ‫فجــرى االطــاع علــى أوراق املعاملــة ولــم جنــد فيهــا بينــة للمدعــي العــام‬\n      ‫ســوى مــا تقــدم ذكــره فبنــاء علــى مــا تقــدم وبعــد ســماع الدعــوى‬\n      ‫واإلجابــة ومبــا أن املدعــي العــام قــد ادعــى بــأن املدعــى عليــه قــد ســرق‬\n      ‫مــن جــاره ذهبــا وأجهــزة جــوال وحاســب آلــي عــن طريــق دخولــه مــن‬\n      ‫إحــدى نوافــذ بيتــه بعــد فــك مســاميرها وقــد صــادق املدعــى عليــه علــى‬\n      ‫ذلــك كلــه مــا عــدا أنــه هــو الــذي فــك املســامير فدفــع بأنهــا مفكوكــة‬\n      ‫مــن األصــل وأنــه دخــل البيــت مــن طريــق النافــذة بعــد رفــع الشــبك‬\n      ‫احلديــدي ولــم يقــدم املدعــي العــام بينــة موصلــة علــى دعــواه مــن أن‬\n      ‫املدعــى عليــه هــو الــذي فــك مســامير نافــذة جــاره وأمــا مــا جــاء يف تقريــر‬\n      ‫األدلــة اجلنائيــة مــن اتهــام املدعــى عليــه بأنــه هــو الــذي فــك املســامير‬\n      ‫فإنهــم اســتنتجوه مــن إقــرار املدعــى عليــه ولــم يــرد يف اإلقــرار مــا يفيــد‬\n      ‫ذلــك ومبــا أن املدعــي العــام قــد طلــب إقامــة حــد الســرقة علــى املدعــى‬\n      ‫عليــه وحيــث لــم تتوفــر كامــل شــروط إقامــة حــد الســرقة إذ اختــل فيهــا‬\n      ‫شــرط احلــرز واحلــرز معتبــر مبــا يتعــارف النــاس عليــه قــال ابــن قدامــة‬\n      ‫رحمــه اهلل‪( :‬احلــرز مــا عــد حــرزا يف العرف)[املغنــي ‪]427/12‬وقــال‬\n      ‫القــرايف رحمــه اهلل يف الذخيــرة‪( :‬ضابــط احلــرز مــا ال يعــد الواضــع فيــه‬\n      ‫مفرطــا)[‪ ]166/12‬وصاحــب احلــق اخلــاص يف هــذه القضيــة قــد حصــل‬\n      ‫منــه نــوع تفريــط يف حفــظ مالــه إذ لــم يحصــن بيتــه جيــدا فاختــل شــرط‬\n      ‫احلــرز ومبــا أن مــا أقــدم عليــه املدعــى عليــه جــرم عظيــم وفيــه إخــال‬\n      ‫باألمــن مــع أن املدعــى عليــه رجــل أمــن وممــن أوكل إليــه حفــظ األمــن‬\n      ‫وهــذا يقتضــي تشــديد العقوبــة يف حقــه ال ســيما وأن لــه ســوابق مماثلــة‬\n      ‫إضافــة إلــى أنــه قــد حصــل منــه انتهــاك حلرمــة بيــت جــاره وقــد قــال النبي‬\n\n\n‫‪337‬‬\n\f‫صلــى اهلل عليــه وســلم‪[ :‬واهلل ال يؤمــن واهلل ال يؤمــن واهلل ال يؤمــن]‬\n‫قيــل‪ :‬مــن يــا رســول اهلل؟ قال‪[:‬الــذي ال يأمــن جــاره بوائقــه]رواه البخــاري‬\n‫وقــال‪[:‬ال يدخــل اجلنــة مــن ال يأمــن جــاره بوائقــه]رواه مســلم فنفــي اإلميــان‬\n‫ودخــول اجلنــة عمــن فعــل مثــل هــذا الفعــل يــدل علــى عظــم ذنبــه ومبــا أن‬\n‫املدعــى عليــه قــد أظهــر النــدم والتوبــة على ما بدر منه وأعاد املســروقات‬\n‫لصاحبهــا فقــد قررنــا تخفيــف العقوبــة عنــه ولــكل مــا ســبق فقــد‬\n‫حكمنــا باإلجمــاع مبــا يلــي أوال صرفنــا النظــر عــن طلــب املدعــي العــام‬\n‫إقامــة حــد الســرقة علــى املدعــى عليــه ‪ ....‬لعــدم توفــر شــروط إقامــة احلــد‬\n‫كمــا ذكــر بعاليــه ثانيــا‪ :‬قررنــا تعزيــر املدعــى عليــه بســجنه ملــدة ثالث‬\n‫ســنوات حتتســب منهــا مــدة توقيفــه الســابقة علــى ذمــة هــذه القضيــة‬\n‫وجلــده ثالثمائــة جلــدة علــى دفعــات كل دفعــة خمســون جلــدة وبني كل‬\n‫دفعــة والتــي تليهــا خمســة عشــر يومــا وبــه حكمنــا وبعرضــه علــى‬\n‫الطرفــن قــرر كل واحــد منهمــا اعتراضــه علــى احلكــم وطلبــا رفعــه‬\n‫إلــى محكمــة االســتئناف بالئحــة اعتراضية فأفهمــا مبقتضى تعليمات‬\n‫االســتئناف وبــاهلل التوفيــق حــرر يف ‪1433/7/1‬ه ـ وصلــى اهلل علــى‬\n                                         ‫نبينا محمد وعلى آله وصحبه وسلم‪.‬‬\n‫احلمــد هلل وحــده أمــا بعــد ففــي يــوم األحــد املوافــق‪1434/01/18‬‬\n‫ه ـ افتتحــت اجللســة الســاعة التاســعة والربــع وقــد عــادت املعاملــة مــن‬\n‫محكمــة االســتئناف باملنطقــة الشــرقية مبوجــب خطــاب رئيســها رقــم‬\n‫‪ 331726723‬يف ‪1434/1/10‬ه ـ واملرفــق بــه قــرار الدائــرة اجلزائيــة‬\n‫اخلماســية األولــى رقــم ‪ 33480389‬يف ‪1433/12/27‬ه ـ ونــص احلاجــة‬\n‫منــه (وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة لوحــظ أنــه لــم يتــم إرفــاق الالئحــة االعتراضيــة للمدعــي‬\n\n\n                                                                                        ‫‪338‬‬\n\f      ‫العــام وال بــد مــن ذلــك فعلــى أصحــاب الفضيلــة مالحظــة مــا ذكــر‬\n      ‫وإكمــال مــا يلــزم ومــن ثــم إعــادة املعاملــة إلكمــال الزمهــا) انتهــى عليــه‬\n      ‫فنقــول جوابــا علــى ذلــك إن املدعــي العــام قــد اســتلم نســخة احلكــم‬\n      ‫يف‪1433/7/1‬ه ـ ومضــت املــدة ولــم يقــدم الئحتــه االعتراضيــة فلــذا‬\n      ‫ســقط حقــه يف االعتــراض وقــد ســقطت اإلشــارة إلــى ذلــك يف الضبــط‬\n      ‫يف وقتــه ســهوا علمــا أن فضيلــة املشــارك الثالــث الشــيخ ‪ ....‬قــد انتقــل‬\n      ‫إلــى محكمــة االســتئناف يف اجلــوف وأمرنــا بالتهميــش بذلــك علــى‬\n      ‫القــرار ثــم إعــادة كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق‬\n      ‫احلكــم بعــد اإلجــراء األخيــر وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/18‬ه ـ املتضمــن‬\n      ‫املصادقــة علــى احلكــم بعــد اإليضــاح األخيــر قاضــي اســتئناف د ‪......‬‬\n      ‫قاضــي اســتئناف ‪ ......‬قاضــي اســتئناف ‪ .......‬رئيــس اســتئناف ‪.........‬‬\n      ‫رئيــس الدائــرة ‪)........‬وحــرر لئــا يخفــى يف ‪1434/4/15‬ه ـ وصلــى اهلل‬\n                                                             ‫وســلم علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n      ‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة اخلبــر‬\n      ‫املســاعد برقــم ‪ 34/117393‬وتاريــخ ‪1434/1/24‬ه ـ واملقيــدة لــدى‬\n      ‫احملكمــة برقــم ‪/34/285161‬خ‪ 1‬وتاريــخ ‪1434/2/4‬ه ـ املرفــق بهــا‬\n      ‫القــرار الشــرعي ذو الرقــم ‪ 33323065‬والتاريــخ ‪1433/7/1‬ه ـ الصــادر‬\n      ‫مــن أصحــاب الفضيلــة القضــاة باحملكمــة الشــيخ‪ ......./‬والشــيخ‪......./‬‬\n      ‫والشــيخ‪ ......./‬اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد‪ ....../‬يف قضيــة‬\n      ‫ســرقة وقــد تضمــن القــرار حكــم أصحــاب الفضيلــة مبــا هــو مــدون‬\n\n\n‫‪339‬‬\n\f‫ومفصــل فيــه ‪ .‬وحيــث ســبق دراســة القــرار وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه أصحــاب‬\n‫الفضيلــة علــى قرارنــا رقــم ‪ 33480389‬وتاريــخ ‪1433/12/27‬ه ـ قررنــا‬\n‫املصادقــة علــى احلكــم بعــد اإليضــاح األخيــر‪ .‬واهلل املوفــق وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪ 1434/4/1‬هـ ـ ـ ـ ‪.‬‬\n\n\n\n\n                                                                                ‫‪340‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":331,"source_page_end":340,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c504a3eaa84da0f613a1ed0899e081f4329788909414bdd8adf0cedb8de08260","normalized_text_hash":"46a9699979cc5832a1b6d075c5658547a4bd653db80a1da0954ae0dbdffe4cc1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p331-33323065"},{"id":"6631547c-6c1d-5ca0-9500-1e03c31c862d","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -حدث -سرقة بعض محتويات سيارة -كسر زجاج سيارة- اشتراك يف سرقة -تخطيط للسرقة -انطباق بصمات -مطالبة بحد السرقة -اعتراف مصدق شرع ا -إنكار الدعوى -درء حد السرقة -رد دعوى -تعزير بالسجن واجللد.","document_number":"33388499","case_number":"33417918","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/21","year":"1434","subject":"سرقة -حدث -سرقة بعض محتويات سيارة -كسر زجاج سيارة- اشتراك يف سرقة -تخطيط للسرقة -انطباق بصمات -مطالبة بحد السرقة -اعتراف مصدق شرع ا -إنكار الدعوى -درء حد السرقة -رد دعوى -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"         ‫رقم الصك‪ 33388499:‬تاريخه ‪1433/8/21:‬هـ‬\n                          ‫رقم الدعوى ‪33417918:‬‬\n             ‫رقم قرار التصديق من محكمة االستئناف‬\n                    ‫‪ 3416470:‬تاريخه ‪1434/1/19:‬ه‬\n\n\n\n      ‫ســرقة‪ -‬حــدث‪ -‬ســرقة بعــض محتويــات ســيارة ‪ -‬كســر زجــاج ســيارة‪-‬‬\n      ‫اشــتراك يف ســرقة‪ -‬تخطيــط للســرقة ‪ -‬انطبــاق بصمــات‪ -‬مطالبــة‬\n      ‫بحــد الســرقة‪ -‬اعتــراف مصــدق شــرع ًا‪ -‬إنــكار الدعــوى ‪ -‬درء حــد‬\n                            ‫الســرقة‪ -‬رد دعــوى ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫قولــه صلــى اهلل عليــه وســلم ( إن دمائكــم وأموالكــم وأعراضكــم عليكــم‬\n                                                                         ‫حــرام )‪.‬‬\n\n\n\n\n      ‫دعــوى املدعــي العــام ضــد ثالثــة أشــخاص أحدهمــا عمــره ‪ 18‬عامــا‬\n      ‫والثانــي حــدث عمــره ‪ 17‬عامــا والثالــث حــدث عمــره ‪ 11‬عامــا إذ‬\n      ‫تشــاركوا يف التخطيــط وتكســير عــدد مــن الســيارات وســرقة مــا‬\n      ‫بداخلهــا مــن مبالــغ ماليــة وعينيــة وطلــب املدعــى العام إقامة حد الســرقة‬\n      ‫علــى املدعــى عليهمــا البالغــن وتعزيــر الثالــث بعقوبــة تناســب عمــره‬\n      ‫وإلــزام املدعــى عليــه الثانــي بإعــادة املبالــغ التــي ال يعلــم أصحابهــا إلــى‬\n      ‫بيــت املــال‪ ،‬مت القبــض علــى املدعــى عليهــم بعــد ورود بالغــات بســرقة‬\n      ‫عــدد مــن الســيارات وســرقة مــا بداخلهــا وبعــد البحــث والتحــري قبــض‬\n      ‫علــى املدعــى عليهــم وقــد اعتــرف أحــد املدعــى عليهــم حتقيق ـ ًا كمــا‬\n\n‫‪341‬‬\n\f‫انطبقــت بصمــات املدعــى عليهــم علــى بعــض البصمــات املرفوعــة مــن‬\n‫محــل اجلرميــة‪ ،‬أنكــر املدعــى عليهــم للدعــوى‪ ،‬وجــد اعتــراف للمدعــى‬\n‫عليــه الثانــي مصــدق شــرعاً‪ ،‬وجــود تقاريــر فنيــة ملضاهــاة بصمــات‬\n‫مرفوعــة مــن مســرح اجلرميــة لعــدد مــن الســرقات املثبتــة‪ ،‬انطبقــت‬\n‫بصمــات األول والثانــي‪ ،‬وجــدت شــهادات مدونــة يف ضبــط القضيــة‪،‬مت‬\n‫درء حــد الســرقة عنهما‪،‬حكمــت احملكمــة بتعزيــر املدعــى عليهمــا‬\n‫األول والثانــي بالســجن واجللــد‪ ،‬رد دعــوى املدعــي العــام بخصــوص‬\n          ‫احلــدث الثالــث‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلدينــا نحــن ‪ .....‬و ‪ ....‬و ‪ ......‬القضــاة باحملكمــة‬\n‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33417918‬وتاريــخ‬\n‫‪1433/6/22‬ه ـ واملقيــدة باحملكمــة برقــم ‪ 331169581‬وتاريــخ‬\n‫‪1433/6/22‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1433/07/23‬ه ـ أفتحــت‬\n‫اجللســة الســاعة ‪ 11 : 01‬وفيهــا حضــر املدعــي العــام ‪ ......‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬وادعــى قائــا بصفتــي مدعي ًا‬\n‫عامـ ًا بدائــرة االدعــاء العــام مبكــة املكرمــة ادعــي على كل مــن (‪)......‬‬\n‫البالــغ مــن العمر‪18‬عامــا بوركينــا فاســو اجلنســية مبوجــب إقامــة‬\n‫نظاميــة رقــم (‪ )....‬موقــوف بالســجن العــام مبكــة املكرمــة واحلــدث‬\n‫‪ .........‬البالــغ مــن العمر‪17‬عامــا مالــي اجلنســية مبوجــب رخصــة إقامــة‬\n‫والــده رقــم (‪ ).....‬موقــوف منــذ ‪1433/2/5‬هـ بــدار املالحظة االجتماعية‬\n‫بجــدة والغــام ‪ .......‬البالــغ مــن العمــر ‪11‬عامــا مالــي اجلنســية مبوجــب‬\n\n                                                                                     ‫‪342‬‬\n\f      ‫بطاقــة بديلــة رقــم‪ 2019‬بتاريــخ‪1433/1/ 19‬ه ـ موقــوف منــذ‬\n      ‫‪1433/2/5‬ه ـ بــدار املالحظــة ب‪ ....‬بأمــر قاضــي األحــداث حيث بتاريخ‬\n      ‫‪ 1431/9/19‬تبلــغ مركــز شــرطة ‪ ......‬عــن ســرقة ســيارة نــوع ‪ ....‬حتمــل‬\n      ‫اللوحــة ذات احلــروف واألرقــام (‪ ).... ...‬بعــد أن كســر اجلانــي زجــاج بــاب‬\n      ‫مســاعد الســائق وبتاريــخ ‪1431/10/29‬ه ـ تبلــغ مركــز شــرطة ‪ ...‬عــن‬\n      ‫ســرقة ســيارة نــوع ‪ .....‬حتمــل اللوحــة ذات احلــروف واألرقــام (‪).... ...‬‬\n      ‫وســرق منهــا جــوال أبــو كشــاف وثــاث بطائــق صــراف وبطاقــة أحــوال‬\n      ‫ورخصــة قيــادة وبتاريــخ ‪1432/4/17‬ه ـ ابلــغ ‪ ....../‬مركــز شــرطة ‪.....‬‬\n      ‫عــن تعــرض ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة ذات احلــروف واألرقــام (‪...‬‬\n      ‫‪ )....‬لكســر الزجــاج وكذلــك تبلــغ املركــز ذاتــه مــن‪ ....../‬عــن تعــرض‬\n      ‫ســيارته مــن نــوع ‪ .......‬حتمــل ذات الرقــم (‪ )....‬وقبــض علــى املدعــى عليــه‬\n      ‫الثانــي ‪ ....../‬داخــل الســيارة يفتــش بهــا وبتاريــخ ‪1432/11/8‬ه ـ ابلــغ‪/‬‬\n      ‫‪ ......‬مركــز شــرطة ‪......‬عــن تعــرض ســيارته مــن نــوع ‪ ......‬حتمــل اللوحــة‬\n      ‫ذات األرقــام واحلــروف (‪ ).... ...‬لكســر زجــاج الســائق وســرقة جهــاز أي‬\n      ‫بــاد وثالثمائــة ريــاال وبتاريــخ ‪1432/11/12‬ه ـ ‪ ،‬ابلــغ ‪ ....../‬عــن تعــرض‬\n      ‫ســيارته مــن نــوع ‪ .........‬حتمــل اللوحــة ذات احلــروف واألرقــام (‪) .... ...‬‬\n      ‫لكســر يف الزجــاج اخللفــي وســرقة ثــاث مائــة ريــال وابلــغ ‪ ......‬عــن‬\n      ‫تعــرض ســيارته مــن نــوع ‪ .....‬حتمــل اللوحــة ذات احلــروف واألرقــام(‪).... ...‬‬\n      ‫لكســر زجــاج املثلــث اخللفــي األميــن وســرقة كمبيــاالت رســمية‬\n      ‫وباالنتقــال واملعاينــة بتاريــخ ‪1432/9/19‬ه ـ ملعاينــة ســيارة مــن نــوع ‪.....‬‬\n      ‫حتمــل اللوحــة ذات احلــروف واألرقــام (‪ ).... ...‬اتضــح إن الزجــاج األمامــي‬\n      ‫األميــن للســائق تعــرض للكســر وجــرى رفــع اآلثــار وبتاريــخ‬\n      ‫‪1431/10/20‬ه ـ جــرى االنتقــال ومعاينــة ســيارة مــن نــوع ‪ ....‬حتمــل‬\n\n\n‫‪343‬‬\n\f‫اللوحــة ذات احلــروف واألرقــام (‪ )...‬واتضــح إنهــا تعرضــت لكســر‬\n‫الزجــاج األميــن األمامــي للســائق وجــرى رفــع البصمــات وبتاريــخ‬\n‫‪1432/4/17‬ه ـ جــرى معاينــة ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة ذات‬\n‫احلــروف واألرقــام (‪ ).... ...‬واتضــح إنهــا تعرضــت لكســر زجــاج بــاب‬\n‫الســائق وكذلــك جــرى معاينــة ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم‬\n‫(‪ ).... ...‬واتضــح أن زجــاج البــاب اخللفــي األميــن قــد تعــرض للكســر‬\n‫وبتاريــخ ‪1432/1/28‬ه ـ جــرى االنتقــال إلــى حــي ‪ ....‬بجــوار مســجد ‪.....‬‬\n‫ومعاينــة الســيارة نــوع ‪ .....‬تابــع لشــركة الكهربــاء رقــم اللوحــة (‪).... ...‬‬\n‫وقــد وجــد الزجــاج األمامــي للســائق مكســور ووجــد يف املوقــع نفســه‬\n‫ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم(‪ ).... ...‬وقــد كســر زجــاج املثلــث‬\n‫اخللفــي األيســر وبتاريــخ ‪1432/11/8‬ه ـ جــرى معاينــة ســيارة مــن نــوع‬\n‫‪ ......‬حتمــل اللوحــة ذات احلــروف واألرقــام (‪ ).... ...‬واتضــح أن زجــاج‬\n‫الســائق تعــرض للكســر وبتاريــخ ‪1432/11/14‬ه ـ جــرى معاينــة ســيارة‬\n‫مــن نــوع ‪ .....‬حتمــل اللوحــة ذات األرقــام واحلــروف(‪ ).... ...‬واتضــح إنهــا‬\n‫تعرضــت لكســر مثلــث الزجــاج اخللفــي األميــن وبتاريــخ ‪1433/1/18‬ه ـ‬\n‫قبــض علــى املدعــى عليــه األول ‪ ...../‬واملدعــى عليــه الثالــث ‪ ....../‬مــن‬\n‫قبــل الدوريــة األمنيــة يف موقــع ســرقة مــن داخــل ســيارة ‪ ....../‬وذكــرا‬\n‫إنهمــا يعرفــان مــن ســرق وجــرى االنتقــال برفقتهمــا إلــى حــي ‪ .....‬فارشــد‬\n‫علــى املدعــى عليــه الثانــي ‪ ......./‬وقبــض عليــه وبتفتيشــه وجــد معــه‬\n‫محفظــة صغيــرة ســوداء بداخلهــا هويــة وطنيــه باســم‪ ........./‬وكــرت‬\n‫عائلتــه ورخصتــه وبطاقــة الصــراف اآللــي اخلاصــة بــه ملصــرف ‪............‬‬\n‫وبســماع أقــوال‪ ....../‬صاحــب البطاقــة التــي ضبطــت مــع الثالــث أفــاد‬\n‫بأنــه أدى صــاة الظهــر مبســجد ‪ .....‬وعنــد خروجــه مــن املســجد وجــد‬\n\n\n                                                                                       ‫‪344‬‬\n\f      ‫ثالثــة أشــخاص بجــوار ســيارته وزجــاج بــاب الســائق مكســور فقبــض‬\n      ‫علــى اثنــن منهــم وهــرب الثالــث وقــد ســرق مــن الســيارة (‪ )2000‬ريــاال‬\n      ‫وهويتــه الوطنيــة وبطاقــة الصــراف اخلاصة به ملصــرف ‪ ............‬والبطاقة‬\n      ‫اخلاصــة لعملــه وباســتجواب املدعــى عليــه الثانــي احلــدث‪ ......./‬اعتــرف‬\n      ‫بأنــه يف وقــت صــاة الظهــر كان برفقــة املدعــى عليــه األول ‪...../‬‬\n      ‫واملدعــى عليــه الثالــث ‪ ....../‬عنــد مســجد ‪ ............‬فكســر األول ‪....../‬‬\n      ‫زجــاج بــاب الســائق بحجــر وفتــح البــاب واخــذ منهــا محفظــة ســوداء‬\n      ‫بداخلهــا (‪ )2000‬ألفــي ريــال فاخــذ األلفــن وأعطــاه احملفظــة وبهــا عــدد‬\n      ‫مــن البطاقــات وكان الثالــث ‪ ..... /‬يراقــب خــروج النــاس مــن صــاة‬\n      ‫الظهــر فأعطــاه إشــارة بانتهــاء الصــاة فهــرب وحضــر صاحــب الســيارة‬\n      ‫فقبــض علــى الثالــث‪ ...../‬وعلــى األول ‪ .....‬وهــرب هــو فقبــض عليــه مــن‬\n      ‫قبــل البحــث اجلنائــي يف عصــر اليــوم نفســه وأضــاف انــه ســبق أن ســرق‬\n      ‫(‪ )250‬مائتــن وخمســن ريــاال مــن إحــدى الســيارات و(‪ )150‬مــن ســيارة‬\n      ‫أخــرى ولفــة أســاك مــن عمــارة حتــت اإلنشــاء وانــه كذلــك كســر‬\n      ‫زجــاج إحــدى الســيارات لغــرض ســرقتها وقبــض عليــه مــن قبــل صاحبهــا‬\n      ‫وســلم لــدار املالحظــة فأطلقــوا ســراحه وباســتجواب املدعــى عليــه‬\n      ‫الثالث‪ .....‬ذكر بأنه قبض عليه بجوار مســجد ‪ ......‬الن معه شــخصني‬\n      ‫كســرا زجــاج ســيارة وســرق منهــا وهمــا األول‪ ......../‬والثانــي ‪......‬‬\n      ‫وأضــاف ان الثانــي‪ .... /‬هــو مــن كســر زجــاج الســيارة بحجــر ثــم ســرق‬\n      ‫احملفظــة ومبضاهــاة بصمــات املدعــى عليهــم علــى احلــوادث اجلنائيــة‬\n      ‫املقيــدة ضــد مجهــول ثبــت انطبــاق املدعــى عليــه األول ‪ ....../‬علــى‬\n      ‫حادثتــي ســرقة مــن داخــل ســيارتني األولــى بتاريخ‪1433/1/23‬ه ـ ورد‬\n      ‫التقريــر الفنــي رقــم ‪ 23‬لعــام ‪1433‬ه ـ مثبتــا انطبــاق بصمــات األول‪.....‬‬\n\n\n‫‪345‬‬\n\f‫علــى حادثــة ســرقة ســيارة مــن نــوع ‪ .....‬لوحــة رقــم (‪ ).... ...‬والثانيــة بتاريــخ‬\n‫‪1433/1/23‬ه ـ ورد التقريــر الفنــي رقــم ‪24‬لعــام ‪1433‬ه ـ مثبتــا انطباق‬\n‫بصمــات االول ‪....../‬علــى حــادث ســرقة ســيارة مــن نــوع ‪ ....‬لوحــة رقــم (‪...‬‬\n‫‪ )....‬وثبــت انطبــاق بصمــات الثانــي ‪ .....‬علــى اربــع حــوادث ســرقة مــن‬\n‫داخــل ســيارات علــى النحــو االتــي‪ :‬االولــى بتاريــخ ‪1432/11/16‬ه ـ ورد‬\n‫التقريــر الفنــي رقــم ‪ 419‬لعــام ‪1432‬ه ـ مثبتــا انطبــاق بصمــات الثانــي‬\n‫‪ ..../‬علــى حــادث ســرقة ســيارة مــن نــوع ‪ ......‬لوحــة رقــم (‪ ).... ...‬والثانيــة‬\n‫بتاريخ‪1432/11/18‬ه ـ ورد التقريــر الفنــي رقــم (‪ )420‬لعام‪1432‬ه ـ‬\n‫مثبتــا انطبــاق بصمــات الثانــي ‪.../‬علــى ســيارة مــن نــوع ‪ ......‬لوحــة رقــم(‪...‬‬\n‫‪ )....‬والثالثــة بتاريــخ ‪1432/9/6‬ه ـ ورد التقريــر الفنــي رقم(‪)332‬لعــام‬\n‫‪1432‬ه ـ مثبتــا انطبــاق بصمــات الثانــي ‪ .../‬علــى حادثــة ســرقة مــن نــوع‬\n‫ســيارة ‪ ....‬لوحــة رقــم (‪ ).... ...‬والرابعــة بتاريــخ ‪1432/9/6‬ه ـ ورد التقرير‬\n‫الفنــي رقــم (‪ )7‬لعــام ‪1432‬ه ـ مثبتــا انطبــاق بصمــات الثانــي ‪ .../‬علــى‬\n‫حادثــة ســرقة مــن ســيارة نــوع ‪ ....‬لوحــة رقــم (‪ ).... ...‬واســفر التحقيــق عــن‬\n‫توجيــه االتهــام للمدعــى عليهــم باالشــتراك يف التخطيــط وتكســير‬\n‫عــدد مــن الســيارات وســرقة مــا بداخلهــا مــن مبالــغ ماليــة وعينيــة وذلــك‬\n‫وفقــا لقــرار االتهــام رقــم (‪ /47‬لعام‪1433‬ه ـ واملؤيــد بقــرار جلنــة ادارة‬\n‫الهيئــة رقــم(‪/944‬م) لعام‪1433‬ه ـ لألدلــة والقرائــن التاليــة‪_1 :‬ماجــاء‬\n‫باعتــراف املدعــى عليــه الثانــي املــدون صفحــة (‪)6‬لفة(‪)41‬وصفحة(‪)15‬‬\n‫لفة(‪)33‬واملــدون صفحة(‪)13‬واملصــادق شــرعا ولفة(‪)105‬ولفــة(‪)98‬‬\n‫وصفحــة (‪)16،15،14‬مــن ملــف لفــة (‪-2)42‬ماجــاء يف محضــر القبــض‬\n‫علــى املدعــى عليــه الثانــي املرفــق لفة(‪)45‬ومحضــر الدوريــة بالقبــض‬\n‫علــى االول والثالــث واملرفــق لفــه(‪ -3)44‬مــا جــاء يف محاضــر االنتقــال‬\n\n\n                                                                                            ‫‪346‬‬\n\f      ‫واملعاينــة املدونــة بدفاتــر االســتدالل املرفقــة صفحــة (‪ )2‬ملــف (‪)1‬‬\n      ‫وصفحــة (‪ )2‬ملــف (‪ )10‬وصفحــة (‪ )2‬ملــف (‪ )32‬وصفحــة (‪)56‬‬\n      ‫وصفحــة (‪ )3‬ملــف (‪ )23‬صفحــة (‪ )3‬ملــف (‪ -4 )33‬التقاريــر الفنــي‬\n      ‫ملضاهــاة البصمــات املرفوعــة مــن مســرح اجلرميــة لعــدد مــن الســرقات‬\n      ‫املثبتــة النطبــاق بصمــات االول لســرقتني لفــة (‪ )18-8‬والثانــي ألربــع‬\n      ‫ســرقات املرفقــة لفــة (‪ -5)62-75-51-49-29‬مــا جــاء يف اقوال ‪......../‬‬\n      ‫مــن قبضــه علــى املدعــى عليهمــا االول والثالــث بجــوار ســيارته املتعرضــة‬\n      ‫للســرقة املــدون صفحــه (‪ )2‬لفــه (‪ -6 )42‬محضــر القبــض لفــه (‪-7)45‬‬\n      ‫تقاريــر الدوريــات األمنيــة لفة(‪-8)72-57-44-35-28-13‬تســلم‬\n      ‫املبلــغ‪ ......./‬للمســروقات صفحــة (‪ )14‬ملــف لفــه (‪ )33‬و (‪ )13‬ملــف لفــة‬\n      ‫(‪ )42‬وبالبحــث عــن ســوابقهم لــم يعثــر لهــم عــن ســوابق مســجلة وحيــث‬\n      ‫ان مــا قــام بــه املدعــى عليهــم فعــل محــرم ومعاقــب عليــه شــرعا لــذا‬\n      ‫اطلــب اثبــات ادانتهــم مبــا اســند اليهــم واحلكــم علــى االول والثانــي بحــد‬\n      ‫الســرقة الــوارد يف اآليــة الكرميــة رقم(‪)38‬مــن ســورة املائــدة واحلكــم‬\n      ‫علــى الغــام املدعــى عليــه الثالــث بعقوبــة تعزيريــه تناســب عمــره‬\n      ‫واحلكــم علــى الثانــي بإعــادة املبالــغ التــي ســرقها وال يعلــم اصحابهــا‬\n      ‫لصالــح بيــت املــال وقدرهــا (‪ )350‬ثالثــة مائــة وخمســون ريــاال وثمــن‬\n      ‫االســاك التــي ذكــر بانــه ســرقها مــن عمــارة حتــت االنشــاء (علمــا بــان‬\n      ‫احلــق اخلــاص مــازال قائمــا هــذه دعــواي وبعــرض دعــوى املدعــي العــام‬\n      ‫علــى املدعــى عليهــم أجابــوا بقولهــم مــا ذكــره املدعــي العــام يف دعــواه‬\n      ‫غيــر صحيــح جملــه وتفصيــا ونحــن لــم نقــم بســرقة أي ســيارة مــن التــي‬\n      ‫ذكرهــا املدعــي العــام ومت القبــض علينــا بــدون أي وجــه حــق هكــذا‬\n      ‫أجابــوا وبعــرض ذلــك علــى املدعــي العــام قــال الصحيــح مــا ذكرتــه يف‬\n\n\n‫‪347‬‬\n\f‫دعــواي وبينتــي اعتــراف املدعــى عليــه الثانــي املصــدق شــرعا وجــود‬\n‫بصمــات املدعــى عليــه االول والثانــي املذكــورة يف االدلــة والقرائــن‬\n‫وبالرجــوع الــى اعتــراف املدعــى عليــه الثانــي ‪ ....‬وجــد كمــا ذكــر‬\n‫املدعــي العــام كمــا وجــدت البصمــات املذكــورة وبعــرض االعتــراف‬\n‫علــى املدعــى عليــه الثانــي قــال انــه مت ضربــي واجبــاري علــى ان اوقــع‬\n‫وانــا عمــري ثالثــة عشــر عامــا تقريبــا وليــس كمــا ذكــره املدعــي العــام‬\n‫بــان عمــري ســبعة عشــر عامــا وبســؤال املدعــي العــام هــل لديــه بينــه قــال‬\n‫نعــم وقــد احضرتهــا واطلــب ســماع مــا لديهمــا وعليــه فقــد حضــر‪....‬‬\n‫ســعودي مبوجــب ســجل مدنــي رقــم (‪ ).....‬يف‪1393/7/1‬ه ـ ‪ ......‬ســعودي‬\n‫مبوجــب ســجل مدنــي رقــم (‪ ).....‬يف ‪1422/5/17‬ه ـ وبســؤالهم عــن‬\n‫الشــهادة التــي حضــرا ألدائهــا شــهد كل واحــد منهمــا مبفــرده قائــا‬\n‫اشــهد انــه يف شــهر محــرم مــن هــذا العــام جاءنــا بــاغ عــن طريــق‬\n‫العمليــات بوجــود ســرقة ســيارة يف حــي ‪ ......‬وبالذهــاب الــى موقع احلادث‬\n‫وجــد شــخص وســيارته مكســورة احــدى الزجاجــات وال نذكــر نــوع‬\n‫الســيارة واي زجــاج مكســور وبســؤاله مــن قــام بســرقتها اشــار الــى‬\n‫شــخص وهــو املدعــى عليــه االول وقــال هــذا ايضــا ويقصــد املدعــى عليــه‬\n‫الثالــث واخبرنــا املدعــى عليهمــا ان الــذي قــام بالســرقة هــو املدعــى‬\n‫عليــه الثانــي ‪ ...‬ومت طلــب البصمــات هكــذا شــهدا وبســؤال املدعــي‬\n‫العــام هــل لديــه مزيــد بينــه قــال بينتــي مــا جــاء يف اوراق املعاملــة مــن‬\n‫االدلــة والقرائــن فجــرى الرجــوع اليهــا فوجــدت كمــا ذكــر املدعــي‬\n‫العــام فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة وحيــث أنكــر املدعــى‬\n‫عليهــم مــا جــاء يف دعــوى املدعــي العــام ولضعــف األدلــة والقرائــن‬\n‫املقدمــة مــن املدعــي العــام يف حــق املدعــى عليــه الثالــث ولصغــر ســن‬\n\n\n                                                                                      ‫‪348‬‬\n\f      ‫املدعــى عليهــم والن امــوال املســلم محترمــة لقولــه صلــى اهلل عليــه وســلم‬\n      ‫(إن دمائكــم واموالكــم واعراضكــم عليكــم حــرام ) ولتوجه التهمه‬\n      ‫يف حــق املدعــى عليــه االول والثانــي لذلــك كلــه فلــم يثبــت لدينــا مــا‬\n      ‫يوجــب اقامــة حــد الســرقة علــى املدعــى عليهــم ودرانــا عنهــم احلــد‬\n      ‫وحكمنــا بتعزيرهــم وذلــك بســجن املدعــى عليــه االول ‪ .......‬ســتة اشــهر‬\n      ‫مــن تاريــخ ايقافــه وجلــده مائــة جلــده مفرقــة علــى دفعتــن يف كل دفعــه‬\n      ‫خمســون مــرة بــن كل مــرة والتــي تليهــا عشــرة ايــام وســجن املدعــى‬\n      ‫عليــه الثانــي ثمانيــة اشــهر مــن تاريــخ ايقافــه وجلــده مائــة جلــده مفرقــه‬\n      ‫علــى مرتــن يف كل مــرة خمســون جلــده بــن كل مــرة والتــي تليهــا‬\n      ‫عشــرة ايــام وحكمنــا بــرد دعــوى املدعــي العــام فيمــا يخــص املدعــى‬\n      ‫عليــه الثالــث وبعــرض احلكــم علــى املدعــى عليهــم قــرروا القناعــة‬\n      ‫وبعــرض احلكــم علــى املدعــي العــام قرر عدم القناعة وطلب االســتئناف‬\n      ‫واجيــب لطلبــه وافهــم بتعليمــات االعتــراض وبــاهلل التوفيــق وصلــى اهلل‬\n          ‫على سيدنا محمد وعلى اله وصحبه وسلم حرر يف ‪1433/7/23‬هـ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1433/11/21‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 12.30‬وبعــد رفــع كامــل اوراق املعاملــة‬\n      ‫الــى محكمــة االســتئناف عــادت وبرفقهــا القــرار رقــم ‪33439423‬‬\n      ‫يف‪1433/10/25‬ه ـ وهــذا نصــه بعــد املقدمــة وبدراســة احلكــم وصــورة‬\n      ‫ضبطــه والئحتــه االعتراضيــة تقــرر اعادتهــا ألصحــاب الفضيلــة حــكام‬\n      ‫القضيــة ملالحظــة أن العقوبــة قليلــة ســجنا وجلــدا يف حــق املدعــى عليهــم‬\n      ‫مبــا فيهــم الثالــث ملالحظــة ذلــك ‪ .‬وبــاهلل التوفيــق قاضــي اســتئناف‬\n      ‫د‪ ......‬ختــم وتوقيــع قاضــي اســتئناف ‪ ......‬ختــم وتوقيــع قاضــي اســتئناف‬\n      ‫‪ ......‬ختــم وتوقيــع قاضــي اســتئناف ‪ ......‬ختــم وتوقيــع رئيــس اســتئناف‬\n\n\n‫‪349‬‬\n\f‫‪ .....‬ختــم وتوقيــع عليــه جنيــب اصحــاب الفضيلــة وفقنــا اهلل واياهــم ان‬\n‫املدعــي العــام لــم يقــدم ادلــه او قرائــن توجــب زيــادة يف الســجن واجللــد‬\n‫علــى مــا حكمنــا بــه وامــا املدعــى عليــه الثالــث فســبب رد الدعــوى‬\n‫هــو عــدم وجــود مــا يدينــه عليــه فلــم يظهــر لدينــا ســوى مــا حكمنــا‬\n‫بــه وامرنــا برفــع كامــل االوراق املعاملــة الــى محكمــة االســتئناف‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n‫‪ 1433/11/21‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي‬\n‫بعــده ‪ ،‬وبعــد ‪ -:‬فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلماســية‬\n‫الثانيــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة‬\n‫برقــم ‪ 33/2029196‬وتاريــخ ‪1433/12/20‬ه ـ املرفــق بهــا القــرار رقــم‬\n‫‪ 33388499‬وتاريــخ ‪1433/8/21‬ه ـ الصــادر مــن أصحــاب الفضيلــة‬\n‫القضــاة باحملكمــة العامــة مبكــة املكرمــة الشــيخ‪ ...... /‬والشــيخ‪......‬‬\n‫والشــيخ ‪ .......‬املتضمــن دعــوى املدعــي العــام ضــد‪ ...... /‬بوركينــا‬\n‫فاســو اجلنســية ورفاقه‪،‬املتهمــن يف االشــتراك يف التخطيــط وتكســير‬\n‫عــدد مــن الســيارات وســرقة مــا بداخلهــا مــن مبالــغ ماليــة ‪ ،‬احملكــوم‬\n‫فيــه مبــا دون باطنــه‪ .‬املالحــظ عليــه بقــرار محكمــة االســتئناف رقــم‬\n‫‪ 33439423‬وتاريــخ ‪1433/10/25‬ه ـ وبدراســة احلكــم وصــورة ضبطه‬\n‫والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم بعــد‬\n‫اإليضــاح األخيــر‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                          ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                    ‫‪350‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":341,"source_page_end":350,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"34414c7edf6a46fb9b96fbcae634651304a3fd67753d5e97f2df64e34a45220a","normalized_text_hash":"456218419da8fca4d33d511e5455e41d3ab1a6bf10697ed4ac8ad188e8fc9d41","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p341-33388499"},{"id":"081704cc-ead8-57d3-8e12-cb0b9744e5f2","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة منزل -سرقة مجوهرات من داخل املنزل -سرقة من حرز -مقاومة الفرقة القابضة ومحاولة الهرب منها -مطالبة بإقامة حد السرقة -احلكم بإقامة حد السرقة -الرجوع عن احلكم بإقامة حد السرقة -رجوع املدعى عليه عن االعتراف على زعم ضغط احملقق وتأثير املرض النفسي -درء حد السرقة -التعزير بالسجن واجللد.","document_number":"33476192","case_number":"33423216","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باخلرج/املساعد ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/12/22","year":"1434","subject":"سرقة -سرقة منزل -سرقة مجوهرات من داخل املنزل -سرقة من حرز -مقاومة الفرقة القابضة ومحاولة الهرب منها -مطالبة بإقامة حد السرقة -احلكم بإقامة حد السرقة -الرجوع عن احلكم بإقامة حد السرقة -رجوع املدعى عليه عن االعتراف على زعم ضغط احملقق وتأثير املرض النفسي -درء حد السرقة -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 33476192:‬تاريخه ‪1434/12/22:‬هـ‬\n                         ‫رقم الدعوى ‪33423216:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34226366‬تاريخه‪1434/5/28 :‬ه‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة منــزل ‪ -‬ســرقة مجوهــرات مــن داخــل املنــزل ‪-‬ســرقة مــن‬\n      ‫حــرز ‪ -‬مقاومــة الفرقــة القابضــة ومحاولــة الهــرب منهــا ‪ -‬مطالبــة‬\n      ‫بإقامــة حــد الســرقة ‪ -‬احلكــم بإقامــة حــد الســرقة‪ -‬الرجــوع عــن احلكم‬\n      ‫بإقامــة حــد الســرقة‪ -‬رجــوع املدعــى عليــه عــن االعتــراف علــى زعــم‬\n      ‫ضغــط احملقــق وتأثيــر املــرض النفســي ‪ -‬درء حــد الســرقة‪ -‬التعزيــر‬\n                                                             ‫بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫‪-1‬قولــه تعالــى (والســارق والســارقة فاقطعــوا أيديهمــا جــزاء مبــا‬\n                                 ‫كســبا نــكا ًال مــن اهلل واهلل عزيــز حكيــم)‪.‬‬\n                                                    ‫‪-2‬احلدود تدرأ بالشبهات‪.‬‬\n\n\n\n      ‫دعــوى املدعــي العــام ضــد املدعــى عليه بســرقة مجموعة مــن املجوهرات‬\n      ‫مــن حرزهــا بعــد دخولــه إلــى أحــد املنــازل بالقفــز ومقاومــة الفرقــة‬\n      ‫القابضــة ومحاولــة الهــرب مــن الفرقــة‪ ،‬وطلــب املدعــى العــام إقامــة حــد‬\n      ‫الســرقة وتعزيــر املدعــى عليــه لقــاء مقاومتــه الفرقــة القابضــة ومحاولتــه‬\n      ‫الهــرب منهــا‪ ،‬مت القبــض علــى املدعــى عليــه بعد بالغ مفــاده تعرض أحد‬\n      ‫املنــازل لســرقة املجوهــرات املوجــودة بداخلــه‪ ،‬وبعــد البحــث والتحــري‬\n\n\n‫‪351‬‬\n\f‫ورد بــاغ مفــاده وجــود شــخص يف أســواق يحــاول بيــع بعــض املجوهــرات‬\n‫بــدون إثبــات وبعــد وصــول الدوريــات حــاول املدعى عليه الهــرب ومقاومة‬\n‫الفرقــة القابضــة إال أن الفرقــة متكنــت مــن القبــض عليــه وباســتجوابه‬\n‫أقــر بالســرقة املنســوبة إليــه‪ ،‬أقــر املدعــى عليــه بالدعــوى ثــم رجــع عــن‬\n‫اعترافــه املصــدق شــرعاً‪ ،‬تبــن وجــود ســوابق علــى املدعــى عليــه‪ ،‬صــدر‬\n‫احلكــم مــن ناظــري القضيــة بإقامــة حــد الســرقة لوجــود املــال املســروق‬\n‫واملــال محــرز يف بيــت مغلــق واملنــزل حــرز ملــا يف داخلــه واملــال املســروق‬\n‫بالــغ النصــاب واملدعــى عليــه عاقــل مكلــف مؤاخــذ بإقــراره‪ ،‬مت تقــدمي‬\n‫الالئحــة االعتراضيــة علــى احلكــم وذكــر املدعــى عليــه يف الئحتــه أنــه‬\n‫تراجــع عــن أقوالــه‪ ،‬أفــاد املدعــى عليــه أن إقــراره صــدر باإلكــراه مــن‬\n‫احملققــن وحتــت تأثيــر املــرض النفســي‪ ،‬مت الرجــوع عــن احلكــم بإقامة‬\n‫حــد الســرقة‪ ،‬تعزيــر املدعــى عليــه بالســجن واجللــد‪ ،‬تصديــق احلكــم‬\n                                                     ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدينا نحن القضاة ‪ ........‬والقاضي ‪ .......‬والقاضي‬\n‫‪ ......‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫باخلرج‪/‬املســاعد برقــم ‪ 33423216‬وتاريــخ ‪ 1433/06/24‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331187899‬وتاريــخ ‪ 1433/06/24‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1433/07/08‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعي‬\n‫العــام ‪ .....‬وأدعــى علــى احلاضــر معــه ‪ ........‬ســعودي مبوجــب الســجل‬\n‫املدنــي رقــم (‪ ).......‬قائــا ‪ :‬فقــد تقــدم املواطــن‪ ،....../‬ببــاغ لشــرطة‬\n‫محافظــة اخلرج‪/‬مخفــر شــرطة الناصفــة ‪ ،‬مفــاده بأنــه خــرج مــن منزلــه‬\n\n                                                                                         ‫‪352‬‬\n\f      ‫الواقــع مبحافظــة اخلــرج حــي ‪ ، ......‬يــوم األربعــاء املوافــق ‪1433/1/5‬ه ـ‬\n      ‫ـاء وبعــد عودتــه ملنزلــه وجــد نافــذة (فتحــة)‬     ‫الســاعة (‪ )2‬الثانيــة مسـ ً‬\n      ‫مكيــف املطبــخ مكســورة وقــد ســرق مــن غرفــة نومــه مجوهــرات‬\n      ‫مختلفــة األنــواع تقــدر قيمتهــا ب ــ(‪ )45000‬خمســة وأربعــن ألــف ريــال‬\n      ‫وأنــه ال يتهــم أحــد ًا بعينــه‪ ،‬وباالنتقــال ملنــزل املبلــغ ودخولــه اتضــح بــأن‬\n      ‫الدخــول حصــل عــن طريــق فتحــة املكيــف بعــد أن دفــع الســارق اللــوح‬\n      ‫املغلقــة بــه‪ ،‬وأن املســروقات ُأخــذت مــن درج تســريحة غرفــة النــوم‪.‬‬\n      ‫ويف يــوم األحــد املوافــق ‪1433/2/21‬ه ـ تلقــت العمليــات بالغ ـ ًا مفــاده‬\n      ‫وجــود شــخص مبجمــع أســواق ‪ ...‬مبدينــة الريــاض وبحوزتــه كميــة مــن‬\n      ‫الذهــب يحــاول بيعهــا دون إثبــات هويــة ‪ ،‬ممــا يوحــي ذلــك بســرقتها‪،‬‬\n      ‫وبوجــود فرقتــي (‪ )19‬و(‪ )20‬األمنيــة باملوقــع التقتــا باملبلــغ املواطــن‪.....‬‬\n      ‫والــذي أفــاد بــأن املدعــى عليــه حضــر لــه وبحوزتــه كميــة مــن الذهــب‬\n      ‫حــاول بيعهــا دون إثبــات هويــة وأنــه عــرض عليــه بيــع تلــك املجوهــرات‬\n      ‫دون إثبــات مقابــل (‪ )2000‬ريــال مــن قيمتهــا وأنــه منــذ صــاة املغــرب‬\n      ‫وهــو يحــاول بيــع املجوهــرات‪ .‬وبدخــول الفرقــة للمحــل شــاهدت املدعــى‬\n      ‫عليــه وبحوزتــه ذهــب وبطلــب إثباتــه حــاول الهــرب علــى األقــدام فيمــا‬\n      ‫قــاوم الفرقــة واعتــدى عليهــا فتــم القبــض عليــه ووجــد بحوزتــه مــن‬\n      ‫املجوهــرات الذهبيــة مــا وزنــه (‪ )86‬ســتة وثمانــون جرامـ ًا تقــدر قيمتهــا‬\n      ‫بــ(‪ )22700‬اثنــن وعشــرين ألف ـ ًا وســبعمائة ريــال‪ .‬وبتفتيــش ســيارته‬\n      ‫نــوع فــورد حتمــل اللوحــة رقــم (‪ ).... ...‬وجــد بهــا (‪ )2‬ســاعتان واحــدة‬\n      ‫رجاليــة والثانيــة نســائية قيمتهمــا تقــدر (‪ )2500‬ألفــن وخمســمائة ريــال‬\n      ‫وتعليقتــن ذهبيــة وفضيــة وخرصــان مــن الفضــة ‪ ،‬وجهــاز آيبــاد ‪ ،‬وقلــم‬\n                      ‫ماركــة ‪ ،‬وثالثــة أجهــزة نقالــة ‪ ،‬وبطاقــات صــراف آلــي‪.‬‬\n\n\n‫‪353‬‬\n\f‫وبســماع أقــوال ‪ ....... :‬أفــاد بأنــه ســمع مــن أصحــاب احملــات املجــاورة‬\n‫لــه وجــود شــخص يتنقــل بينهــا طلب ـ ًا يف بيــع مــا بحوزتــه مــن ذهــب دون‬\n‫إثبــات وأنــه طلــب مــن أصحــاب احملــات يف حالــة حضــوره لهــم توجيهــه‬\n‫حمللــه لوضــع كمــن لــه فحضــر إليــه ومعــه الذهــب واألملــاس وبطلــب‬\n‫إثباتــه أفــاد بعــدم وجــوده معــه وأن مــا بحوزتــه مــن ذهــب خــاص وعائــد‬\n‫لوالدتــه‪ ،‬وأضــاف (املبلــغ ) بــأن املدعــى عليــه قــدم لــه عمولــة وذلــك‬\n‫يف حالــة عــدم طلــب إثباتــه منــه وأنــه بعــد ذلــك أبلــغ اجلهــات األمنيــة‬\n‫وبحضورهــم وطلبهــم إثباتــه حــاول الهــرب وقاومهــم ورفــض امتثــال‬\n‫أمرهــم‪ .‬وباســتجواب املدعــى عليــه أقــر بأنــه يف يــوم ‪1433/1/5‬ه ـ‬\n‫ـاء دخــل منــزل املبلــغ ‪ ..... /‬الواقــع‬ ‫الســاعة (‪ )12‬الثانيــة عشــرة مسـ ً‬\n‫مبحافظــة اخلرج‪/‬حــي الــورود مــن فتحــة مكيــف املطبــخ وأنــه اجتــه‬\n‫لغرفــة النــوم وأخــذ مــن درج تســريحتها مجموعــة مــن املجوهــرات وخــرج‬\n‫مــن حيــث دخــل وصــدق اعترافــه شــرعاً‪ .‬وبعــرض املجوهــرات املســروقة‬\n‫علــى املبلــغ وزوجتــه أفــادا بأنهــا هــي مجوهراتهمــا إال أنهمــا فقــدا منهــا‬\n‫حلــق وخــوامت بهــا فصــوص املاســية وقــد تســلم صاحبهــا مــن املدعــى‬\n‫عليــه بــد ًال عنهــا (‪ )2000‬ريــال فيمــا قــرر بأنــه لــم يبــق لــه شــيء مفقــود‬\n‫مــن مجوهراتــه‪ .‬وقــد انتهــى التحقيــق معــه إلــى توجيــه االتهــام لــه بســرقة‬\n‫مجموعــة مــن املجوهــرات مــن حرزهــا بعــد دخولــه عــن طريــق القفــز إلــى‬\n‫أحــد املنــازل ومقاومتــه للفرقــة القابضــة ومحاولتــه الهــرب مــن الفرقــة‬\n‫وفــق قــرار االتهــام رقــم (‪ )132‬لعــام ‪1433‬ه ـ املراجــع مــن جلنــة إدارة هيئة‬\n‫التحقيــق واالدعــاء العــام بقرارهــا رقــم (‪/939‬ر) لعــام ‪1433‬ه ـ وذلــك‬\n                                                         ‫لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ .1‬إقــراره املصــدق شــرع ًا املــدون علــى الصفحــة رقــم (‪ )8‬مــن دفتــر‬\n\n\n                                                                                          ‫‪354‬‬\n\f                                                                      ‫التحقيــق لفــه (‪. )9‬‬\n                          ‫‪ .2‬محضر القبض املنوه عنه املرفق على اللفة رقم (‪. )3‬‬\n      ‫‪ .3‬محضــر االنتقــال واملعاينــة مــن ‪ .......‬املنــوه عنــه املــدون علــى الصفحــة‬\n                                         ‫رقــم (‪ )3‬مــن دفتــر التحقيــق لفــه رقــم (‪. )9‬‬\n      ‫‪ .4‬شــهادة املبلــغ ‪ .....‬عنهــا املدونــة علــى الصفحــة رقــم(‪ 1‬ـ ـ ‪ )3‬مــن دفتــر‬\n                                                                   ‫التحقيــق لفــة رقــم (‪)1‬‬\n      ‫‪ .5‬محضــر تعــرف صاحــب املســروقات عليهــا واســتالمها املنــوه عنــه‬\n      ‫املــدون علــى الصفحتــن رقــم (‪ ) 11 ، 5‬مــن دفتــر التحقيــق املرفــق علــى‬\n                                                                           ‫اللفــة رقــم (‪. )9‬‬\n      ‫وبالبحــث عــن مــا إذا كان لــه ســوابق ُعثــر لــه علــى ثــاث ســوابق األولــى‬\n      ‫دخــول منــازل لغــرض ســيء والثانيــة ســرقة أمــوال مقترنــة بســرقة ذهــب‬\n                                 ‫والتهديــد وحــرق منــزل والثالثــة ســرقة مســاكن‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه‪ -‬وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا وهــو ســرقة مــال محتــرم‬\n      ‫بالــغ النصــاب مــن حــرزه بعــد هتكــه ‪ ،‬وال شــبهة لــه فيــه ‪ ،‬وطالــب بــه‬\n       ‫صاحبــه أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه مبــا يلــي‪:‬‬\n           ‫‪ .1‬بحد السرقة الوارد يف اآلية الكرمية رقم(‪ )38‬من سورة املائدة ‪.‬‬\n      ‫‪ .2‬بعقوبــة تعزيريــة زاجــرة لــه ورادعــة لغيــره لقــاء مقاومتــه للفرقــة‬\n      ‫القابضــة ومحاولتــه الهــرب منها‪(.‬علم ـ ًا بــأن احلــق اخلــاص منت ـهٍ)‪ .‬وبــاهلل‬\n      ‫التوفيــق ‪ .‬ا ‪ -‬ه ـ وبســؤال املدعــى عليــه عــن دعــوى املدعــي العــام أجــاب‬\n      ‫بقولــة ‪ :‬انــه ومــن غيــر إرادة منــي وأنــا أســير علــى أقدامــي داخــل احلــي‬\n      ‫الــذي أســكنه مــع والــدي وزوجتــي دخلــت منــزل أحــد املواطنــن يف حــي‬\n      ‫الــورود يف محافظــة اخلــرج الســاعة الثانيــة عشــر ليــا وذلــك مــن غيــر‬\n\n\n‫‪355‬‬\n\f‫غــرض ومــن غيــر قصــد أي شــيء حيــث دخلــت عمــارة حتــت االنشــاء‬\n‫مجــاورة للمنــزل وقفــزت داخــل ســور منــزل املواطــن ووجــدت فتحــة‬\n‫مكيــف شــباك مفتوحــة فوجــدت مثــل الطاولــة الصغيــرة وصعــدت‬\n‫عليهــا ثــم دخلــت مــع فتحــة املكيــف داخــل املطبــخ ثــم جتولــت داخــل‬\n‫املنــزل حتــى وجــدت غرفــة نــوم مفتوحــة البــاب ووجــدت داخــل الــدرج‬\n‫(كمدينــة ) علبــة فيهــا عــدد مــن املجوهــرات عبــارة عــن ذهــب وســاعتني‬\n‫فأخذتهــا وعــدت مــن حيــث دخلــت أي مــن خــال الفتحــة التــي دخلــت‬\n‫معهــا وأخــذت املجوهــرات معــي وقمــت بدفنهــا قــرب منــزل والــدي‬\n‫وندمــت أشــد النــدم وهممــت بإعادتهــا لصاحــب املنــزل ولكنــي متــردد‬\n‫وخائــف ثــم تركتهــا يف مكانهــا وبعــد الســرقة بأســبوعني ‪ .‬والن لــي‬\n‫موعــد يف مستشــفى ( ‪ ) .......‬لألمــراض النفســية حيــث اتصلــت بــي‬\n‫املستشــفى وأخبرونــي باملوعــد وملعرفتــي ان املستشــفى يريــد مبلغــا مــن‬\n‫املــال بحثــت عــن أبــي آلخــذ منــه املــال فلــم أجــده فأخــذت الذهــب معــي‬\n‫للريــاض فحاولــت بيعــه فتــم القبــض علــي ومــا وجــد معــي يف ســوق ‪......‬‬\n‫مــن ذهــب هــو الذهــب الــذي ســرقته مــن املنــزل يف حــي الــورود ‪ .‬ومت‬\n‫ارجاعــه ملالكــه ولــم أقــاوم الفرقــة القابضــة وال أعلــم أنهــم رجــال أمــن‬\n‫ألنهــم يلبســون الثيــاب املدنيــة وذكــرت يف بدايــة التحقيــق أن الذهــب‬\n‫لوالدتــي وبعــد أن صليــت االســتخارة وعــدت الــى رشــدي اعترفــت‬\n‫أنــي ســارق للذهــب مــن املنــزل املذكــور وأنــا مريــض نفســي واعالــج‬\n‫عــن املــرض وصحيــح أنــه يوجــد علــي ســابقة دخــول منــزل لغــرض ســيئ‬\n‫قبــل زواجــي والســابقة الثانيــة متهــم فيهــا ولــم تثبــت التهمــة ومت احلكــم‬\n‫علــي بعشــر ســنوات أمضيــت منهــا خمــس ســنني وشــملني العفــو بحفــظ‬\n‫القــرآن وبعــد تســعة أشــهر مــن خروجــي مــن الســجن وقعــت يف هــذه‬\n\n\n                                                                                     ‫‪356‬‬\n\f      ‫القضيــة وال صحــة ملــا جــاء يف ذكــر الســوابق انــي حرقــت املنــزل ‪ .‬وأنــا‬\n      ‫تائــب هلل جــل وعــا ولــن أعــود لشــيء مــن املعاصــي ‪.‬هكــذا أجــاب ‪.‬‬\n      ‫وباالطــاع علــى أوراق املعاملــة وجــد مــن بينهــا صحيفــة الســوابق املبينــة‬\n      ‫أن للمدعــى عليــه ثــاث ســوابق وهــي مطابقــة للســوابق املذكــورة يف‬\n      ‫دعــوى املدعــي العــام أعــاه ولالطــاع علــى بقيــة أوراق املعاملــة والتأمــل‬\n      ‫رفعــت اجللســة وعليــه حصــل التوقيــع ‪ .‬احلمــد هلل وحــده وبعــد ففــي هــذا‬\n      ‫اليــوم الثالثــاء املوافــق ‪1433/11/21‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n      ‫املدعــي العــام وحضــر حلضــوره املدعــى عليــه ‪ ........‬وجــرى ســؤال هــل جد‬\n      ‫عنــده جديــد قــال ال جديــد عنــدي وجــرى االطــاع علــى أوراق املعاملــة‬\n      ‫ومــن بينهــا دفتــر التحقيــق املرفــق لفــة رقــم (‪ )1‬ص ‪ 1‬املتضمــن بــاغ يف‬\n      ‫يــوم األحــد ‪1433/11/21‬ه ـ عــن شــخص يريــد بيــع كميــة مــن الذهــب‬\n      ‫يف محــات بيــع الذهــب يف أســواق طيبــة ومــن غيــر اثبــات هويــة وذكــر‬\n      ‫أن الذهــب لوالدتــه فابلــغ الدوريــات االمنيــة وأنــه بعــد حضــور الدوريــة‬\n      ‫األمنيــة وطلبهــا اثباتــه قــام بالهــرب ورفــض االنصيــاع ‪ .‬وجــاء علــى اللفــة‬\n      ‫رقــم ‪ 3‬تقريــر حــادث علــى مطبوعــات قيــادة الدوريــات األمنيــة ويتضمــن‬\n      ‫أنــه مت القبــض علــى ‪ ..........‬ومعــه اثبــات هويتــه ومعــه مجوهــرات وزن‬\n      ‫‪ 86‬جرامــا مــن الذهــب ويوجــد يف ســيارته عــدد ســاعتني املــاس ‪ ..‬الــخ‬\n      ‫‪ .‬ومــن ضمــن أوراق املعاملــة دفتــر التحقيــق لفــة رقــم ‪ 9‬جــاء علــى ص‬\n      ‫‪ 8‬ويتضمــن اعتــراف املدعــى عليــه وهــذا نصــه ( نعــم أنــا ‪ .....‬ســعودي‬\n      ‫ســجل مدنــي رقــم (‪)......‬أقــر بطوعــي واختيــاري وبــدون اكــراه مــن‬\n      ‫أحــد أقــر بانــي يف يــوم االربعــاء املوافــق ‪1433/1/5‬ه ـ وعنــد الســاعة‬\n      ‫الثانيــة عشــر ليــا قمــت بدخــول منــزل املدعــو ‪ ............‬الواقــع بحــي ‪...‬‬\n      ‫عــن طريــق دريشــة مكيــف املطبــخ واجتهــت إلــى غرفــة النــوم وقمــت‬\n\n\n‫‪357‬‬\n\f‫بأخــذ مجموعــه مجوهــرات مــن درج التســريحة وخرجــت مــن نفــس‬\n‫املــكان الــذي دخلــت معــه ولــم أخــذ شــيئا آخــر غيــر ذلــك هــذا اقــرار‬\n‫منــي وعليــه جــرى التوقيــع ‪ .‬أ ـ ه ـ ‪ .‬ومصــادق عليــه شــرعا مبــا نصــه ‪:‬‬\n‫حضــر لدينــا املذكــور أعــاه وبتــاوة اقــراره عليــه املــدون ص ‪ 8‬مــن‬\n‫هــذا امللــف صــادق عليــه حرفيــا وأقــاد أن ســبب دخولــه للمنــزل هــي حالــة‬\n‫نفســية‪ .‬ومــن ضمــن أوراق املعاملــة االفــادة الطبيــة الصــادرة مــن مكتــب‬\n‫أ ‪ .‬د ‪ ............‬الطبيــة رقــم بــدون تاريــخ ‪1433/2/25 :‬ه ـ وجــاء نصهــا‪:‬‬\n‫املذكــور أعــاه راجعنــا يف مركــز ‪ .....‬ألول مــرة بتاريــخ ‪2011/6/22‬م‬\n‫حيــث كان يعانــي مــن اضطــراب وجدانــي ( ثنائــي القطــب ) وهــذه‬\n‫احلالــة تــؤدي الــى تدهــور شــخصية الفــرد ويكــون هنــاك طــرق شــاذة‬\n‫وغريبــة يف التفكيــر والســلوك واملشــاعر وميكــن أن يــرى مــن حولــه‬\n‫بصــورة غيــر ســوية وتهيمــن عليــه أفــكار غيــر واقعيــة وتبــدو أحيانــا‬\n‫تصرفاتــه متضاربــة ومتنافــرة ورمبــا ينقطــع عــن أهلــه ومعارفــة لدرجــة‬\n‫أن يبــدو عليــه وكانــه معــزول عــن الدنيــا وكانــت آخــر مراجعــة لــه‬\n‫بتاريــخ ‪2011/7/31‬م ‪ .‬ومــن ضمــن أوراق املعاملــة تقريــر بحث الســوابق‬\n‫املبــن وجــود عــدة ســوابق علــى املدعــى عليــه ومــن بينهــا الســابقة التــي‬\n‫حكــم فيهــا مبوجــب القــرار الصــادر برقــم ‪/11/4/24‬ض تاريــخ‬\n‫احلكــم ‪1427/6/27‬ه ـ ونــوع اجلرميــة ســرقة مســاكن كمــا جــرى‬\n‫االطــاع علــى صــورة القــرار املشــار إليــه يف صحيفــة الســوابق الصــادر‬\n‫مــن هــذه احملكمــة برقــم ‪/11/4/24‬ض يف ‪1427/6/27‬ه ـ واملتضمــن‬\n‫إقامــة دعــوى مــن املدعــي العــام ضــد املدعــى عليــه هنــا ‪ .....‬ويطالــب‬\n‫املدعــي العــام بإقامــة حــد احلرابــة علــى املدعــى عليــه التهــام املدعــى‬\n‫عليــه بدخــول املنــازل علــى ســبيل الغلبــة والقــوة والتهديــد بوجــود ســاح‬\n\n\n                                                                                    ‫‪358‬‬\n\f      ‫معــه ومعاونــون آخــرون وانتهــى حكــم أصحــاب الفضيلــة ( وحيــث لــم‬\n      ‫يثبــت مــا يوجــب إقامــة حــد احلرابــة علــى املدعــى عليــه فقــد صرفنــا‬\n      ‫النظــر عــن طلــب املدعــي العــام بإقامــة حــد احلرابــة وقــرر أصحــاب‬\n      ‫الفضيلــة تعزيــره بالســجن ســبع ســنني مــن تاريــخ توقيفــه وجلــده ألفــي‬\n      ‫جلــدة ) واحلكــم مصــادق عليــه مــن محكمــة االســتئناف بالقــرار رقــم‬\n      ‫‪/367‬خ‪/‬أ يف ‪1428/3/13‬ه ـ ثــم جــرى ســؤال املدعــى عليــه عمــا جــاء‬\n      ‫يف القــرار الســابق فقــال أننــي تائــب نــادم علــى مــا مضــى وأنــا ابــن اليــوم‬\n      ‫وســبب عودتــي للســرقة يف هــذه القضيــة أننــي لــم أشــعر بنفســي ومــا‬\n      ‫فعلتــه مــن غيــر إرادة منــي ‪ .‬فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي‬\n      ‫العــام وإلقــرار املدعــى عليــه أنــه دخــل أحــد العمائــر املجــاورة للمنــزل‬\n      ‫املســروق يف محافظــة اخلــرج ومــن ثــم قفــز داخــل ســور املنــزل املســروق‬\n      ‫وبحــث عــن مدخــل لداخــل املنــزل ووجــد فتحــة مكيــف وأحضــر مــا‬\n      ‫يرتفــع عليــه ليدخــل مــن خــال هــذه الفتحــة ودخــل داخــل املنــزل وجتــول‬\n      ‫يف البيــت املســروق ودخــل غرفــة النــوم وفتــح ( درج الكمدينــة) ووجــد‬\n      ‫فيــه علبــة فيهــا الذهــب والســاعتان فأخذهــا وخــرج مــن حيــث دخــل‬\n      ‫وأخفــى املســروقات ملــدة اســبوعني ثــم أخذهــا معــه ملدينــة الريــاض‬\n      ‫وذهــب لســوق الذهــب يف اســواق ‪ ........‬وعــرض الذهــب علــى أصحــاب‬\n      ‫احملــات وحــاول بيعــه وتتوجــه التهمــة عليــه مبقاومــة الفرقــة ولــو كان‬\n      ‫املدعــى عليــه مريــض مرضــا مســقط ًا لكمــال أهليتــه ملــا صــدرت منــه‬\n      ‫هــذه األفعــال وألن األصــل اســتصحاب حــال الصحــة عنــد املدعــى عليــه‬\n      ‫ولوجــود ســابقة علــى املدعــى عليــه مت احلكــم عليــه فيهــا بحكــم بليــغ‬\n      ‫ولــم يرتــدع‪ .‬وحيــث وجــد املــال املســروق بحــوزة املدعــى عليــه وألن املــال‬\n      ‫محــرز يف بيــت مغلــق عليــه وانتهــك املدعــى عليــه هــذا احلــرز بالتســلق‬\n\n\n‫‪359‬‬\n\f‫للســور اخلارجــي ومــن ثــم الدخــول داخــل املنــزل وألن املنــزل حــرز ملــا يف‬\n‫داخلــه وألن املــال املســروق مــال محتــرم وبالــغ للنصــاب واملدعــى عليــه‬\n‫عاقــل مكلــف مؤاخــذ بإقــراره وألن املدعــى عليــه بــاق علــى اقــراره وقــد‬\n‫صــدر منــه اإلقــرار وهــو بكامــل أهليتــه املعتبرة ولقوله تعالى( والســارق‬\n‫والســارقة فاقطعــوا أيديهمــا جــزاء ًا مبــا كســبا نــكاال مــن اهلل واهلل‬\n‫عزيــز حكيــم) لذلــك كلــه فقــد حكمنــا بإقامــة حــد الســرقة علــى‬\n‫املدعــى عليــه ‪ ............‬وذلــك بــأن تقطــع يــده اليمنــى مــن مفصــل الكــف‬\n‫مــادام بــاق علــى إقــراره ويكــون تعزيــره عــن تهمــة مقاومــة الفرقــة داخــل‬\n‫يف إقامــة احلــد عليــه وبــه حكمنــا وبعرضــه علــى املدعــى عليــه لــم يقنــع‬\n‫وطلــب رفعــه حملكمــة االســتئناف بالئحــة اعتراضيــة وجــرى إفهامــه‬\n‫أنــه يتــم طلبــه مــن الســجن ويســلم نســخة مــن القــرار خــال مــدة أقصاها‬\n‫ثالثــون يومــا مــن تاريخــه وأنــه إن لــم يتقــدم باالعتــراض يف تلــك املــدة‬\n‫يســقط حقــه يف االعتــراض ولــم يرغــب املدعــي العــام يف االعتــراض‬\n            ‫وصلــى وســلم علــى نبينــا محمــد ‪ .‬حــرر يف ‪1433/12/21‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده ففــي يــوم الســبت املوافــق‪ 1433/12/25‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــر املدعــى عليــه ‪ .......‬وجــرى تســليمه نســخة مــن‬\n‫القــرار وذلــك لتقــدمي الئحتــه االعتراضيــة خــال ثالثــن يومــا مــن تاريخه‬\n‫وإن لــم يتقــدم يف تلــك املــدة فإنــه يســقط حقــه يف االعتــراض ‪ ،‬ففــي يــوم‬\n‫الثالثــاء املوافــق ‪ 1434/3/3‬ه ـ افتتحــت اجللســة بنــاء علــى الالئحــة‬\n‫االعتراضيــة املقدمــة مــن املدعــى عليــه ‪ ....... /‬برقــم ‪34174980‬‬\n‫وتاريــخ ‪1434/1/20‬ه ـ وفيهــا حضــر املدعــى عليــه ‪ ............‬وجــاء علــى‬\n‫الصفحــة األخيــرة يف الئحتــه قولــه ( ومبــا أننــي قــد أخطــأت يف فهــم‬\n‫مــا عــرض علــي مــن أســئلة ســواء مــن احملقــق أو فضيلــة القضــاة لــذا‬\n\n\n                                                                                     ‫‪360‬‬\n\f      ‫فأننــي أتراجــع عــن كل مــا جــاء بأقوالــي ) ثــم جــرى ســؤال املدعــى عليه‬\n      ‫عــن مــا جــاء يف الئحتــه فقــال أننــي أقــرر رجوعــي عــن اعترافاتــي لــدى‬\n      ‫احملققــن ولديكــم وأنهــا قــد صــدرت منــي بنــاء علــى ضغــط احملقــق‬\n      ‫وتأثيــر املــرض النفســي علــي ومــن غيــر أدراك ‪ .‬لــذا فأنــه ال صحــة ملــا‬\n      ‫جــاء يف دعــوى املدعــي العــام أننــي دخلــت املنــزل وســرقت منــه الذهــب‬\n      ‫هكــذا قــرر ‪ .‬وبعرضــه علــى املدعــي العــام قــال الصحيــح مــا جــاء يف‬\n      ‫الدعــوى ويف إقــراره لــدى جهــة التحقيــق ولديكــم ‪ ،‬فســألناه البينــة‬\n      ‫فقــال ليــس لــدي بينــه ســوى إقــراره لــدى جهــات التحقيــق ولديكــم ‪،‬‬\n      ‫وبنــاء عليــه وحيــث رجــع املدعــى عليــه عــن إقــراره وذكــر أنــه مصــاب‬\n      ‫مبــرض نفســي وأن لهــا أثــر يف إقــراره وأنــه لــم يــدرك مــا أقــر بــه وألن‬\n      ‫احلــدود تــدرأ بالشــبهات لذلــك كلــه فقــد رجعنــا عــن مــا حكمنــا‬\n      ‫بــه مــن قطــع اليــد اليمنــى للمدعــى عليــه ولتوجــه التهمــة القويــة علــى‬\n      ‫املدعــى عليــه بإقــراره لــدى جهــات التحقيــق ولدينــا ولوجــود ســابقة مــن‬\n      ‫جنــس هــذه القضيــة قررنــا تعزيــر املدعــى عليــه بــأن يســجن ثمــان ســنني‬\n      ‫مــن تاريــخ القبــض عليــه وأن يجلــد ألــف جلــدة مفرقــة علــى عشــرين‬\n      ‫دفعــه كل دفعــه خمســن جلــدة بــن كل دفعــه وأخــرى خمســة أيــام ‪،‬‬\n      ‫وبــه حكمنــا وبعرضــه علــى املدعــى عليــه قنــع بــه وبعرضــه علــى املدعــي‬\n      ‫العــام طلــب رفعــه حملكمــة االســتئناف بالئحــة اعتراض وجــرى أفهامه‬\n      ‫أنــه يتــم تســليمة نســخة مــن احلكــم لتقــدمي الئحــة اعتــراض عليهــا يف‬\n      ‫مــدة أقصاهــا ثالثــون يومـ ًا ‪ ،‬واهلل املوفــق للصــواب ‪ .‬وصلــى اهلل وســلم‬\n                                      ‫علــى نبينــا محمــد ‪ .‬حــرر يف ‪ 1434/3/3‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فقــد‬\n      ‫اطلعنــا نحــن قضــاة الدائــرة اخلماســية األولــى مبحكمــة االســتئناف‬\n\n\n‫‪361‬‬\n\f‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة باخلــرج املكلــف الشــيخ‪ ........ /‬برقــم ‪ 331187899‬وتاريــخ‬\n‫‪1434/4/22‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلتــه والقضــاة‬\n‫املشــاركني لــه باحملكمــة الشــيخ‪ ...... /‬والشــيخ ‪ ..... /‬املســجل برقــم‬\n‫‪ 33476192‬وتاريــخ ‪1433/12/22‬ه ـ اخلــاص بدعــوى املدعــي العــام‬\n‫ضــد‪ ...... /‬يف قضيــة ســرقة ‪ ،‬وقــد تضمــن القــرار حكــم أصحــاب‬\n‫الفضيلــة علــى النحــو املفصــل فيــه ‪ ،‬وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة نقــرر باألكثريــة املصادقــة علــى احلكــم األخيــر مــع‬\n‫تنبيــه أصحــاب الفضيلــة إلــى مصادقــة رئيــس احملكمــة علــى صحــة‬\n‫أختــام وتواقيــع القضــاة قبــل بعــث املعاملــة جلهــة التنفيــذ والتوقيــع‬\n‫ال علــى الالئحــة االعتراضيــة مبــا يفيــد االطــاع عليهــا ‪ .‬واهلل‬\n                                                                   ‫مســتقب ً‬\n                                                                     ‫املوفــق ‪.‬‬\n\n\n\n\n                                                                                  ‫‪362‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":351,"source_page_end":362,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2bb84ff98e99b10366557988c0293840427c3b4220f1c42fc10acdc4d256a092","normalized_text_hash":"59989ddc9c243c6249847417b67428dccb97a211316ba23c87c4da8b178bd15c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p351-33476192"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
